XYPHER_UPLOADED_PHOTO_URI_4 = nil
XYPHER_UPLOADED_PHOTO_WARNED_4 = false
XYPHER_UPLOADED_PHOTO_URI_2 = nil
XYPHER_UPLOADED_PHOTO_URI_3 = nil
XYPHER_UPLOADED_PHOTO_WARNED_2 = false
XYPHER_UPLOADED_PHOTO_WARNED_3 = false
local XYPHER_UPLOADED_PHOTO_URI = nil
local XYPHER_UPLOADED_PHOTO_WARNED = false

function decodeXypherPhotoBase64(data)
    local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
    local map = {}
    for index = 1, #alphabet do
        map[alphabet:sub(index, index)] = index - 1
    end
    local clean = tostring(data or ""):gsub("[^A-Za-z0-9+/=]", "")
    local chunks = {}
    for index = 1, #clean, 4 do
        local c1, c2 = clean:sub(index, index), clean:sub(index + 1, index + 1)
        local c3, c4 = clean:sub(index + 2, index + 2), clean:sub(index + 3, index + 3)
        local a, b = map[c1], map[c2]
        if a ~= nil and b ~= nil then
            chunks[#chunks + 1] = string.char(a * 4 + math.floor(b / 16))
            local c, d = map[c3], map[c4]
            if c3 ~= "=" and c ~= nil then
                chunks[#chunks + 1] = string.char((b % 16) * 16 + math.floor(c / 4))
                if c4 ~= "=" and d ~= nil then
                    chunks[#chunks + 1] = string.char((c % 4) * 64 + d)
                end
            end
        end
    end
    return table.concat(chunks)
end

function ensureXypherUploadedPhotoAsset(photoOption)
    photoOption = photoOption or XYPHER_UPLOADED_PHOTO_OPTION
    local useFourth = photoOption == XYPHER_UPLOADED_PHOTO_OPTION_4
    local useThird = photoOption == XYPHER_UPLOADED_PHOTO_OPTION_3
    local useSecond = photoOption == XYPHER_UPLOADED_PHOTO_OPTION_2
    local photoFile = useFourth and XYPHER_UPLOADED_PHOTO_FILE_4 or (useThird and XYPHER_UPLOADED_PHOTO_FILE_3 or (useSecond and XYPHER_UPLOADED_PHOTO_FILE_2 or XYPHER_UPLOADED_PHOTO_FILE))
    local photoData = useFourth and XYPHER_UPLOADED_PHOTO_BASE64_4 or (useThird and XYPHER_UPLOADED_PHOTO_BASE64_3 or (useSecond and XYPHER_UPLOADED_PHOTO_BASE64_2 or XYPHER_UPLOADED_PHOTO_BASE64))
    local photoUri
    if useFourth then
        photoUri = XYPHER_UPLOADED_PHOTO_URI_4
    elseif useThird then
        photoUri = XYPHER_UPLOADED_PHOTO_URI_3
    elseif useSecond then
        photoUri = XYPHER_UPLOADED_PHOTO_URI_2
    else
        photoUri = XYPHER_UPLOADED_PHOTO_URI
    end
    if type(photoUri) == "string" and photoUri ~= "" then
        return photoUri
    end
    local assetLoader = getcustomasset or getsynasset
    if type(writefile) ~= "function" or type(assetLoader) ~= "function" then
        if useFourth then
            if not XYPHER_UPLOADED_PHOTO_WARNED_4 then
                XYPHER_UPLOADED_PHOTO_WARNED_4 = true
                warn("[XYPHER] Fourth local photo is unavailable in this executor; the remaining GUI will continue normally.")
            end
        elseif useThird then
            if not XYPHER_UPLOADED_PHOTO_WARNED_3 then
                XYPHER_UPLOADED_PHOTO_WARNED_3 = true
                warn("[XYPHER] Third local photo is unavailable in this executor; the remaining GUI will continue normally.")
            end
        elseif useSecond then
            if not XYPHER_UPLOADED_PHOTO_WARNED_2 then
                XYPHER_UPLOADED_PHOTO_WARNED_2 = true
                warn("[XYPHER] Second local photo is unavailable in this executor; the remaining GUI will continue normally.")
            end
        elseif not XYPHER_UPLOADED_PHOTO_WARNED then
            XYPHER_UPLOADED_PHOTO_WARNED = true
            warn("[XYPHER] Local photo background is unavailable in this executor; the remaining GUI will continue normally.")
        end
        return nil
    end

    local exists = false
    if type(isfile) == "function" then
        local okExists, result = pcall(isfile, photoFile)
        exists = okExists and result == true
    end
    if not exists then
        local bytes = decodeXypherPhotoBase64(photoData)
        if type(bytes) ~= "string" or #bytes < 1000 then return nil end
        local okWrite = pcall(writefile, photoFile, bytes)
        if not okWrite then return nil end
    end

    local okAsset, uri = pcall(assetLoader, photoFile)
    if okAsset and type(uri) == "string" and uri ~= "" then
        if useFourth then
            XYPHER_UPLOADED_PHOTO_URI_4 = uri
        elseif useThird then
            XYPHER_UPLOADED_PHOTO_URI_3 = uri
        elseif useSecond then
            XYPHER_UPLOADED_PHOTO_URI_2 = uri
        else
            XYPHER_UPLOADED_PHOTO_URI = uri
        end
        return uri
    end
    if useFourth then
        if not XYPHER_UPLOADED_PHOTO_WARNED_4 then
            XYPHER_UPLOADED_PHOTO_WARNED_4 = true
            warn("[XYPHER] Fourth embedded photo failed to load as a local image asset.")
        end
    elseif useThird then
        if not XYPHER_UPLOADED_PHOTO_WARNED_3 then
            XYPHER_UPLOADED_PHOTO_WARNED_3 = true
            warn("[XYPHER] Third embedded photo failed to load as a local image asset.")
        end
    elseif useSecond then
        if not XYPHER_UPLOADED_PHOTO_WARNED_2 then
            XYPHER_UPLOADED_PHOTO_WARNED_2 = true
            warn("[XYPHER] Second embedded photo failed to load as a local image asset.")
        end
    elseif not XYPHER_UPLOADED_PHOTO_WARNED then
        XYPHER_UPLOADED_PHOTO_WARNED = true
        warn("[XYPHER] Could not load embedded photo as a local image asset. Upload it to Roblox and use its asset ID if this executor does not support JPG custom assets.")
    end
    return nil
end

-- Embedded, low-resolution video loop (sampled at 5 FPS for mobile performance).
-- This uses executor local-image assets, not Roblox native MP4 playback.
XYPHER_VIDEO_BG_OPTION = "__XYPHER_VIDEO_BACKGROUND__"
XYPHER_VIDEO_FRAME_BASE64_DATA = [[




































































































]]
XYPHER_VIDEO_FRAME_DATA = {}
XYPHER_VIDEO_FRAME_URIS = {}
XYPHER_VIDEO_FRAME_WARNED = false

function initXypherVideoFrameData()
    XYPHER_VIDEO_FRAME_DATA = {}
    for frameData in tostring(XYPHER_VIDEO_FRAME_BASE64_DATA or ""):gmatch("[^\r\n]+") do
        XYPHER_VIDEO_FRAME_DATA[#XYPHER_VIDEO_FRAME_DATA + 1] = frameData
    end
end
initXypherVideoFrameData()

function ensureXypherVideoFrameAsset(frameIndex)
    frameIndex = math.floor(tonumber(frameIndex) or 1)
    if frameIndex < 1 then frameIndex = 1 end
    if frameIndex > #XYPHER_VIDEO_FRAME_DATA then frameIndex = #XYPHER_VIDEO_FRAME_DATA end
    if frameIndex < 1 then return nil end

    local cachedUri = XYPHER_VIDEO_FRAME_URIS[frameIndex]
    if type(cachedUri) == "string" and cachedUri ~= "" then return cachedUri end

    local assetLoader = getcustomasset or getsynasset
    if type(writefile) ~= "function" or type(assetLoader) ~= "function" then
        if not XYPHER_VIDEO_FRAME_WARNED then
            XYPHER_VIDEO_FRAME_WARNED = true
            warn("[XYPHER] Animated background needs writefile and getcustomasset/getsynasset support in the executor.")
        end
        return nil
    end

    local frameFile = string.format("Xypher_Video_Background_Crows_%03d.jpg", frameIndex)
    local exists = false
    if type(isfile) == "function" then
        local okExists, result = pcall(isfile, frameFile)
        exists = okExists and result == true
    end
    if not exists then
        local bytes = decodeXypherPhotoBase64(XYPHER_VIDEO_FRAME_DATA[frameIndex])
        if type(bytes) ~= "string" or #bytes < 300 then return nil end
        local okWrite = pcall(writefile, frameFile, bytes)
        if not okWrite then return nil end
    end

    local okAsset, uri = pcall(assetLoader, frameFile)
    if okAsset and type(uri) == "string" and uri ~= "" then
        XYPHER_VIDEO_FRAME_URIS[frameIndex] = uri
        return uri
    end
    if not XYPHER_VIDEO_FRAME_WARNED then
        XYPHER_VIDEO_FRAME_WARNED = true
        warn("[XYPHER] Could not load an animated-background frame as a local image asset.")
    end
    return nil
end

BACKGROUND_OPTIONS = {"139362780018712", "109527418380162", "88365163058110", "120478151076476", "73268250456333", "75307906931620", "102059683776532", "104029051875501", "113387354275344", "123753481590047", "124872550975665", XYPHER_UPLOADED_PHOTO_OPTION, XYPHER_UPLOADED_PHOTO_OPTION_2, XYPHER_UPLOADED_PHOTO_OPTION_3, XYPHER_UPLOADED_PHOTO_OPTION_4, XYPHER_VIDEO_BG_OPTION}
DEFAULT_BACKGROUND_ID = BACKGROUND_OPTIONS[1]

-- Background image loader. The full-screen photo is fitted to the exact panel bounds
-- (the panel itself owns the rounded clipping), so it cannot spill past the GUI edges.
-- A generation token prevents a slow previous image from overriding the latest selection.
local XYPHER_GUI_BG_LOAD_TOKEN = 0
function applyXypherGuiBackground(target, assetId, transparency)
    if not target or not target.Parent then return false end
    local id = tostring(assetId or "")
    local isVideoBackground = id == XYPHER_VIDEO_BG_OPTION
    local isEmbeddedPhoto = id == XYPHER_UPLOADED_PHOTO_OPTION or id == XYPHER_UPLOADED_PHOTO_OPTION_2 or id == XYPHER_UPLOADED_PHOTO_OPTION_3 or id == XYPHER_UPLOADED_PHOTO_OPTION_4
    local embeddedUri = isEmbeddedPhoto and ensureXypherUploadedPhotoAsset(id) or nil
    if isVideoBackground then
        if #XYPHER_VIDEO_FRAME_DATA < 1 then return false end
    elseif isEmbeddedPhoto then
        if not embeddedUri then return false end
    elseif not id:match("^%d+$") then
        return false
    end

    XYPHER_GUI_BG_LOAD_TOKEN += 1
    local token = XYPHER_GUI_BG_LOAD_TOKEN
    target.AnchorPoint = Vector2.new(0, 0)
    target.Position = UDim2.fromScale(0, 0)
    target.Size = UDim2.fromScale(1, 1)
    target.BackgroundTransparency = 1
    target.BorderSizePixel = 0
    target.ClipsDescendants = true
    target.ImageTransparency = math.clamp(tonumber(transparency) or 0.2, 0, 1)
    target.ImageColor3 = Color3.fromRGB(255, 255, 255)
    target.ScaleType = Enum.ScaleType.Stretch

    if isVideoBackground then
        local firstUri = ensureXypherVideoFrameAsset(1)
        if not firstUri then
            target.Image = ""
            return false
        end
        target.Image = firstUri
        task.spawn(function()
            local frameIndex = 1
            while token == XYPHER_GUI_BG_LOAD_TOKEN and target.Parent do
                task.wait(0.20)
                if token ~= XYPHER_GUI_BG_LOAD_TOKEN or not target.Parent then break end

                -- Pause playback while any parent GUI object is hidden to save mobile resources.
                local canRender = true
                local ancestor = target.Parent
                while ancestor and ancestor ~= pgui do
                    if ancestor:IsA("GuiObject") and not ancestor.Visible then
                        canRender = false
                        break
                    end
                    ancestor = ancestor.Parent
                end
                if canRender then
                    frameIndex = frameIndex + 1
                    if frameIndex > #XYPHER_VIDEO_FRAME_DATA then frameIndex = 1 end
                    local frameUri = ensureXypherVideoFrameAsset(frameIndex)
                    if frameUri and token == XYPHER_GUI_BG_LOAD_TOKEN and target.Parent then
                        target.Image = frameUri
                    end
                end
            end
        end)
        return true
    end

    if isEmbeddedPhoto then
        target.Image = embeddedUri
    else
        target.Image = "rbxthumb://type=Asset&id=" .. id .. "&w=768&h=432"
    end

    task.spawn(function()
        local function waitForImage(seconds)
            local deadline = os.clock() + seconds
            while os.clock() < deadline do
                if token ~= XYPHER_GUI_BG_LOAD_TOKEN or not target.Parent then return false, true end
                local ok, loaded = pcall(function() return target.IsLoaded end)
                if ok and loaded then return true, false end
                task.wait(0.1)
            end
            return false, false
        end

        local loaded, cancelled = waitForImage(2.5)
        if cancelled or loaded then return end
        if isEmbeddedPhoto then
            warn("[XYPHER] Embedded photo did not load. Check whether the executor supports local JPG image assets.")
            return
        end

        if token ~= XYPHER_GUI_BG_LOAD_TOKEN or not target.Parent then return end
        target.Image = "rbxassetid://" .. id
        loaded, cancelled = waitForImage(3.0)
        if cancelled or loaded then return end

        if token == XYPHER_GUI_BG_LOAD_TOKEN and target.Parent then
            target.Image = "rbxthumb://type=Asset&id=" .. id .. "&w=420&h=420"
        end
    end)
    return true
end
