STEAL_PHOTO_OPTIONS = {"78298853435931", "121659514207976", "77936305493257", "130500802179710", "133931613501338", "133368341832498", "120701547731015", "102059683776532", "104029051875501", XYPHER_UPLOADED_PHOTO_OPTION, XYPHER_UPLOADED_PHOTO_OPTION_2, XYPHER_UPLOADED_PHOTO_OPTION_3, XYPHER_UPLOADED_PHOTO_OPTION_4}

-- Intro dependencies must exist before showIntro() is called.
-- Keep every XYPHER/gameplay overlay hidden until showIntro() finishes (or is skipped).
local XYPHER_STARTUP_INTRO_COMPLETE = false
-- The previous merge referenced pgui/makeVISIONRedrumSound without defining them,
-- which caused the intro coroutine to fail immediately.
pgui = LP and LP:WaitForChild("PlayerGui", 20) or nil

local VISION_REDRUM_URL = "https://file.garden/algLafWA1jk8WMfK/redrum_spotdown.org%202.mp3"
local VISION_REDRUM_FILE = "vision_redrum.mp3"
local _visionRedrumAsset = nil

function getVISIONRedrumAsset()
    if _visionRedrumAsset then return _visionRedrumAsset end

    local assetLoader = getcustomasset or getsynasset
    if type(assetLoader) ~= "function" or type(writefile) ~= "function" then
        return nil, "custom asset functions unavailable"
    end

    local exists = false
    if type(isfile) == "function" then
        local okExists, result = pcall(isfile, VISION_REDRUM_FILE)
        exists = okExists and result == true
    end

    if not exists then
        local okDownload, data = pcall(function()
            return game:HttpGet(VISION_REDRUM_URL)
        end)
        if not okDownload or type(data) ~= "string" or #data < 256 then
            return nil, "could not download intro music"
        end
        local okWrite = pcall(writefile, VISION_REDRUM_FILE, data)
        if not okWrite then
            return nil, "could not save intro music"
        end
    end

    local okAsset, asset = pcall(assetLoader, VISION_REDRUM_FILE)
    if not okAsset or type(asset) ~= "string" or asset == "" then
        return nil, "could not create intro music asset"
    end

    _visionRedrumAsset = asset
    return asset
end

function makeVISIONRedrumSound(startAt, name)
    local asset = getVISIONRedrumAsset()
    if not asset then
        return nil
    end

    local sound = Instance.new("Sound")
    sound.Name = name or "VISIONRedrum"
    sound.SoundId = asset
    sound.Volume = 1
    sound.Looped = false
    sound.Parent = game:GetService("SoundService")

    local startPosition = math.max(0, tonumber(startAt) or 0)
    pcall(function() sound.TimePosition = startPosition end)

    task.spawn(function()
        local deadline = tick() + 8
        while sound.Parent and not sound.IsLoaded and tick() < deadline do
            task.wait(0.05)
        end
        if sound.Parent then
            pcall(function()
                sound.TimePosition = startPosition
                sound:Play()
            end)
        end
    end)

    return sound
end


-- Strong, clearly visible Halloween flicker for VISION branding and Discord.
-- Smooth breathing glow with a short, unmistakable light-flicker burst.
function applyVisionHalloweenBlink(guiObject)
    if not guiObject then return end

    local canApply = true
    pcall(function()
        if guiObject:GetAttribute("VisionHalloweenBlinkActive") then
            canApply = false
        else
            guiObject:SetAttribute("VisionHalloweenBlinkActive", true)
        end
    end)
    if not canApply then return end

    task.spawn(function()
        local isImage = guiObject:IsA("ImageLabel") or guiObject:IsA("ImageButton")
        local isText = guiObject:IsA("TextLabel") or guiObject:IsA("TextButton")
        local gradient = guiObject:FindFirstChildOfClass("UIGradient")
        local stroke = guiObject:FindFirstChildOfClass("UIStroke")
        local startedAt = os.clock()
        local orange = Color3.fromRGB(128, 128, 128)
        local amber = Color3.fromRGB(218, 218, 218)
        local hotAmber = Color3.fromRGB(241, 241, 241)
        local deepOrange = Color3.fromRGB(39, 39, 39)

        while guiObject.Parent do
            local elapsed = os.clock() - startedAt
            local pulse = (math.sin(elapsed * 5.4) + 1) * 0.5
            local cycle = elapsed % 3.0

            -- Three hard on/off flashes every cycle make the flicker obvious on phone.
            if cycle > 2.18 then
                local flickerStep = math.floor((cycle - 2.18) * 12)
                pulse = (flickerStep % 2 == 0) and 1 or 0.025
            end

            local glowColor = deepOrange:Lerp(amber, pulse)
            if pulse > 0.82 then glowColor = amber:Lerp(hotAmber, (pulse - 0.82) / 0.18) end
            pcall(function()
                if isImage then
                    guiObject.ImageColor3 = glowColor
                    guiObject.ImageTransparency = 0.01 + (1 - pulse) * 0.34
                elseif isText then
                    guiObject.TextColor3 = glowColor
                    guiObject.TextTransparency = 0.015 + (1 - pulse) * 0.34
                    -- Keep a dark edge so the orange lettering stays readable during flashes.
                    guiObject.TextStrokeColor3 = deepOrange
                    guiObject.TextStrokeTransparency = 0.02 + (1 - pulse) * 0.24
                end

                if stroke then
                    stroke.Color = glowColor
                    stroke.Thickness = 1.6 + pulse * 1.8
                    stroke.Transparency = 0.04 + (1 - pulse) * 0.48
                end

                if gradient then
                    gradient.Color = ColorSequence.new({
                        ColorSequenceKeypoint.new(0, deepOrange:Lerp(orange, pulse)),
                        ColorSequenceKeypoint.new(0.5, orange:Lerp(hotAmber, pulse)),
                        ColorSequenceKeypoint.new(1, Color3.fromRGB(24, 24, 24):Lerp(amber, pulse)),
                    })
                end
            end)
            task.wait(0.08)
        end

        pcall(function() guiObject:SetAttribute("VisionHalloweenBlinkActive", nil) end)
    end)
end

-- Decorative Halloween helpers. These objects are intentionally non-interactive
-- so they never intercept mouse/touch input from Vision controls.
function addHalloweenGlyph(parent, name, glyph, position, size, zIndex, color, driftX, driftY)
    local label = Instance.new("TextLabel")
    label.Name = name
    label.Position = position
    label.Size = size
    label.BackgroundTransparency = 1
    label.BorderSizePixel = 0
    label.Text = glyph
    label.TextColor3 = color or Color3.fromRGB(156, 156, 156)
    label.TextTransparency = 0.04
    label.TextStrokeColor3 = Color3.fromRGB(28, 28, 28)
    label.TextStrokeTransparency = 0.28
    label.Font = Enum.Font.GothamBlack
    label.TextScaled = true
    label.ZIndex = zIndex or 5
    label.Active = false
    label.Selectable = false
    label.Parent = parent

    local constraint = Instance.new("UITextSizeConstraint")
    constraint.MinTextSize = 8
    constraint.MaxTextSize = math.max(11, math.floor(math.min(size.X.Offset, size.Y.Offset) * 1.2))
    constraint.Parent = label

    local dx = tonumber(driftX) or 1.5
    local dy = tonumber(driftY) or 2
    local base = position
    local bright = Color3.fromRGB(201, 201, 201)
    local tw = TS_G:Create(label, TweenInfo.new(1.3, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut, -1, true), {
        Position = UDim2.new(base.X.Scale, base.X.Offset + dx, base.Y.Scale, base.Y.Offset + dy),
        Rotation = 7,
        TextColor3 = bright,
        TextTransparency = 0.015,
    })
    tw:Play()
    return label
end

-- Detailed bat emblem: layered silhouette/shadow, silk-like wing trails, and tiny
-- amber glints. All parts are non-interactive and move together as one compact group.
function addHalloweenBatDetail(parent, name, position, size, zIndex, color, driftX, driftY)
    local root = Instance.new("Frame")
    root.Name = name .. "DetailRoot"
    root.Position = position
    root.Size = size
    root.BackgroundTransparency = 1
    root.BorderSizePixel = 0
    root.ZIndex = zIndex or 5
    root.Active = false
    root.Selectable = false
    root.Parent = parent

    local shadow = Instance.new("TextLabel")
    shadow.Name = "BatShadow"
    shadow.Position = UDim2.fromOffset(1, 2)
    shadow.Size = UDim2.new(1, 0, 1, 0)
    shadow.BackgroundTransparency = 1
    shadow.BorderSizePixel = 0
    shadow.Text = "🦇"
    shadow.TextColor3 = Color3.fromRGB(16, 16, 16)
    shadow.TextTransparency = 0.08
    shadow.TextStrokeColor3 = Color3.fromRGB(11, 11, 11)
    shadow.TextStrokeTransparency = 0.04
    shadow.Font = Enum.Font.GothamBlack
    shadow.TextScaled = true
    shadow.ZIndex = (zIndex or 5)
    shadow.Active = false
    shadow.Selectable = false
    shadow.Parent = root

    local bat = Instance.new("TextLabel")
    bat.Name = "BatSilhouette"
    bat.Size = UDim2.new(1, 0, 1, 0)
    bat.BackgroundTransparency = 1
    bat.BorderSizePixel = 0
    bat.Text = "🦇"
    bat.TextColor3 = color or Color3.fromRGB(160, 160, 160)
    bat.TextTransparency = 0.025
    bat.TextStrokeColor3 = Color3.fromRGB(32, 32, 32)
    bat.TextStrokeTransparency = 0.08
    bat.Font = Enum.Font.GothamBlack
    bat.TextScaled = true
    bat.ZIndex = (zIndex or 5) + 1
    bat.Active = false
    bat.Selectable = false
    bat.Parent = root
    local batGradient = Instance.new("UIGradient")
    batGradient.Rotation = 90
    batGradient.Color = ColorSequence.new({
        ColorSequenceKeypoint.new(0, Color3.fromRGB(208, 208, 208)),
        ColorSequenceKeypoint.new(0.48, color or Color3.fromRGB(160, 160, 160)),
        ColorSequenceKeypoint.new(1, Color3.fromRGB(54, 54, 54)),
    })
    batGradient.Parent = bat

    -- Fine wing trails frame the glyph instead of adding large cluttering stickers.
    local function wingTrail(xScale, yScale, widthScale, rotation, transparency)
        local trail = Instance.new("Frame")
        trail.Name = "WingRimDetail"
        trail.AnchorPoint = Vector2.new(0.5, 0.5)
        trail.Position = UDim2.new(xScale, 0, yScale, 0)
        trail.Size = UDim2.new(widthScale, 0, 0, math.max(1, math.floor(size.Y.Offset * 0.055)))
        trail.Rotation = rotation
        trail.BackgroundColor3 = Color3.fromRGB(190, 190, 190)
        trail.BackgroundTransparency = transparency or 0.35
        trail.BorderSizePixel = 0
        trail.ZIndex = zIndex or 5
        trail.Active = false
        trail.Selectable = false
        trail.Parent = root
        return trail
    end
    wingTrail(0.17, 0.68, 0.24, -22, 0.44)
    wingTrail(0.81, 0.68, 0.24, 22, 0.44)

    if size.X.Offset >= 20 then
        for i, spark in ipairs({
            {x = 0.08, y = 0.11, text = "✦"},
            {x = 0.82, y = 0.04, text = "·"},
        }) do
            local glint = Instance.new("TextLabel")
            glint.Name = "BatGlint" .. tostring(i)
            glint.Position = UDim2.new(spark.x, 0, spark.y, 0)
            glint.Size = UDim2.fromOffset(math.max(5, math.floor(size.X.Offset * 0.22)), math.max(5, math.floor(size.Y.Offset * 0.34)))
            glint.BackgroundTransparency = 1
            glint.Text = spark.text
            glint.TextColor3 = Color3.fromRGB(221, 221, 221)
            glint.TextStrokeColor3 = Color3.fromRGB(61, 61, 61)
            glint.TextStrokeTransparency = 0.18
            glint.Font = Enum.Font.GothamBold
            glint.TextScaled = true
            glint.ZIndex = (zIndex or 5) + 2
            glint.Active = false
            glint.Selectable = false
            glint.Parent = root
        end
    end

    local dx, dy = tonumber(driftX) or 1.5, tonumber(driftY) or 1.5
    local base = position
    local drift = TS_G:Create(root, TweenInfo.new(1.55, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut, -1, true), {
        Position = UDim2.new(base.X.Scale, base.X.Offset + dx, base.Y.Scale, base.Y.Offset + dy),
        Rotation = 4,
    })
    drift:Play()
    return root
end

function addHalloweenSpider(parent, name, x, y, width, height, zIndex, threadLength)
    threadLength = threadLength or 12
    zIndex = zIndex or 5

    -- The silk is anchored to a fixed point above the spider. Its length/angle
    -- follows the body every frame, avoiding the old disconnected stiff-string look.
    local anchorX = x + width * 0.5
    local anchorY = math.max(0, y - threadLength)

    local threadGlow = Instance.new("Frame")
    threadGlow.Name = name .. "ThreadGlow"
    threadGlow.AnchorPoint = Vector2.new(0.5, 0)
    threadGlow.Position = UDim2.fromOffset(anchorX, anchorY)
    threadGlow.Size = UDim2.fromOffset(3, threadLength + height * 0.55)
    threadGlow.BackgroundColor3 = Color3.fromRGB(147, 147, 147)
    threadGlow.BackgroundTransparency = 0.82
    threadGlow.BorderSizePixel = 0
    threadGlow.ZIndex = math.max(1, zIndex - 2)
    threadGlow.Active = false
    threadGlow.Selectable = false
    threadGlow.Parent = parent

    local thread = Instance.new("Frame")
    thread.Name = name .. "Thread"
    thread.AnchorPoint = Vector2.new(0.5, 0)
    thread.Position = UDim2.fromOffset(anchorX, anchorY)
    thread.Size = UDim2.fromOffset(1, threadLength + height * 0.55)
    thread.BackgroundColor3 = Color3.fromRGB(210, 210, 210)
    thread.BackgroundTransparency = 0.08
    thread.BorderSizePixel = 0
    thread.ZIndex = math.max(1, zIndex - 1)
    thread.Active = false
    thread.Selectable = false
    thread.Parent = parent

    local root = Instance.new("Frame")
    root.Name = name .. "DetailedBody"
    root.Position = UDim2.fromOffset(x, y)
    root.Size = UDim2.fromOffset(width, height)
    root.BackgroundTransparency = 1
    root.BorderSizePixel = 0
    root.ZIndex = zIndex
    root.Active = false
    root.Selectable = false
    root.Parent = parent

    local legParts = {}
    local knees = {}
    local function drawLine(x1, y1, x2, y2, thickness, color, transparency, suffix, layer)
        local dx, dy = x2 - x1, y2 - y1
        local length = math.sqrt(dx * dx + dy * dy)
        if length < 0.5 then return nil end
        local piece = Instance.new("Frame")
        piece.Name = suffix or "SpiderLeg"
        piece.AnchorPoint = Vector2.new(0.5, 0.5)
        piece.Position = UDim2.fromOffset((x1 + x2) * 0.5, (y1 + y2) * 0.5)
        piece.Size = UDim2.fromOffset(length, thickness)
        piece.Rotation = math.deg(math.atan2(dy, dx))
        piece.BackgroundColor3 = color
        piece.BackgroundTransparency = transparency or 0.12
        piece.BorderSizePixel = 0
        piece.ZIndex = layer or zIndex
        piece.Active = false
        piece.Selectable = false
        piece.Parent = root
        return piece
    end

    -- Eight two-part legs. The very slight alternating motion is individually
    -- tweened with offset phases, rather than rotating the entire spider rigidly.
    local ox, oy = width * 0.5, height * 0.52
    local legEnds = {
        {width * 0.17, height * 0.10, -1}, {width * 0.025, height * 0.29, -1},
        {width * 0.02, height * 0.69, -1}, {width * 0.19, height * 0.94, -1},
        {width * 0.83, height * 0.10, 1}, {width * 0.975, height * 0.29, 1},
        {width * 0.98, height * 0.69, 1}, {width * 0.81, height * 0.94, 1},
    }
    local microMove = math.clamp(math.min(width, height) * 0.035, 0.25, 0.75)
    for i, item in ipairs(legEnds) do
        local ex, ey, side = item[1], item[2], item[3]
        local kx = ox + (ex - ox) * 0.54
        local ky = oy + (ey - oy) * 0.54 + (i % 2 == 0 and 0.45 or -0.45)
        local baseLeg = drawLine(ox, oy, kx, ky, 1.15, Color3.fromRGB(23, 23, 23), 0.035, "SpiderLegBase" .. i, zIndex)
        local outerLeg = drawLine(kx, ky, ex, ey, 1.05, Color3.fromRGB(171, 171, 171), 0.08, "SpiderLegJoint" .. i, zIndex)
        local knee = Instance.new("Frame")
        knee.Name = "SpiderKnee" .. i
        knee.AnchorPoint = Vector2.new(0.5, 0.5)
        knee.Position = UDim2.fromOffset(kx, ky)
        knee.Size = UDim2.fromOffset(math.max(2, width * 0.105), math.max(2, width * 0.105))
        knee.BackgroundColor3 = Color3.fromRGB(209, 209, 209)
        knee.BorderSizePixel = 0
        knee.ZIndex = zIndex + 1
        knee.Active = false
        knee.Selectable = false
        knee.Parent = root
        Instance.new("UICorner", knee).CornerRadius = UDim.new(1, 0)
        if baseLeg and outerLeg then
            legParts[#legParts + 1] = {
                first = baseLeg, second = outerLeg, knee = knee, side = side,
                firstRotation = baseLeg.Rotation, secondRotation = outerLeg.Rotation,
                firstPosition = baseLeg.Position, secondPosition = outerLeg.Position,
                kneePosition = knee.Position, index = i,
                baseX = ox, baseY = oy, endX = ex, endY = ey,
                firstThickness = 1.15, secondThickness = 1.05,
            }
            knees[#knees + 1] = knee
        end
    end

    local abdomen = Instance.new("Frame")
    abdomen.Name = "SpiderAbdomen"
    abdomen.AnchorPoint = Vector2.new(0.5, 0.5)
    abdomen.Position = UDim2.new(0.5, 0, 0.61, 0)
    abdomen.Size = UDim2.new(0.45, 0, 0.45, 0)
    abdomen.BackgroundColor3 = Color3.fromRGB(19, 19, 19)
    abdomen.BorderSizePixel = 0
    abdomen.ZIndex = zIndex + 2
    abdomen.Active = false
    abdomen.Selectable = false
    abdomen.Parent = root
    Instance.new("UICorner", abdomen).CornerRadius = UDim.new(1, 0)
    local abdomenStroke = Instance.new("UIStroke", abdomen)
    abdomenStroke.Color = Color3.fromRGB(161, 161, 161)
    abdomenStroke.Thickness = 1
    abdomenStroke.Transparency = 0.08
    local abdomenGradient = Instance.new("UIGradient", abdomen)
    abdomenGradient.Rotation = 90
    abdomenGradient.Color = ColorSequence.new({
        ColorSequenceKeypoint.new(0, Color3.fromRGB(178, 178, 178)),
        ColorSequenceKeypoint.new(0.48, Color3.fromRGB(54, 54, 54)),
        ColorSequenceKeypoint.new(1, Color3.fromRGB(12, 12, 12)),
    })

    local head = Instance.new("Frame")
    head.Name = "SpiderHead"
    head.AnchorPoint = Vector2.new(0.5, 0.5)
    head.Position = UDim2.new(0.5, 0, 0.30, 0)
    head.Size = UDim2.new(0.31, 0, 0.29, 0)
    head.BackgroundColor3 = Color3.fromRGB(12, 12, 12)
    head.BorderSizePixel = 0
    head.ZIndex = zIndex + 3
    head.Active = false
    head.Selectable = false
    head.Parent = root
    Instance.new("UICorner", head).CornerRadius = UDim.new(1, 0)
    local headStroke = Instance.new("UIStroke", head)
    headStroke.Color = Color3.fromRGB(150, 150, 150)
    headStroke.Thickness = 0.85
    headStroke.Transparency = 0.08

    -- Four tiny warm eyes read clearly at mobile size without turning the spider
    -- into a bright emoji-like sticker.
    local eyePositions = {0.27, 0.42, 0.58, 0.73}
    for i, eyeX in ipairs(eyePositions) do
        local eye = Instance.new("Frame")
        eye.Name = "SpiderEye" .. i
        eye.AnchorPoint = Vector2.new(0.5, 0.5)
        eye.Position = UDim2.new(eyeX, 0, 0.30, 0)
        local eyeScale = (i == 2 or i == 3) and 0.075 or 0.058
        local eyeSize = math.max(1.1, width * eyeScale)
        eye.Size = UDim2.fromOffset(eyeSize, math.max(1.1, height * 0.065))
        eye.BackgroundColor3 = (i == 2 or i == 3) and Color3.fromRGB(236, 236, 236) or Color3.fromRGB(185, 185, 185)
        eye.BorderSizePixel = 0
        eye.ZIndex = zIndex + 4
        eye.Active = false
        eye.Selectable = false
        eye.Parent = root
        Instance.new("UICorner", eye).CornerRadius = UDim.new(1, 0)
    end

    local abdomenMark = Instance.new("Frame")
    abdomenMark.Name = "SpiderAbdomenMark"
    abdomenMark.AnchorPoint = Vector2.new(0.5, 0.5)
    abdomenMark.Position = UDim2.new(0.5, 0, 0.60, 0)
    abdomenMark.Size = UDim2.new(0.10, 0, 0.22, 0)
    abdomenMark.BackgroundColor3 = Color3.fromRGB(187, 187, 187)
    abdomenMark.BackgroundTransparency = 0.06
    abdomenMark.BorderSizePixel = 0
    abdomenMark.ZIndex = zIndex + 3
    abdomenMark.Active = false
    abdomenMark.Selectable = false
    abdomenMark.Parent = root
    Instance.new("UICorner", abdomenMark).CornerRadius = UDim.new(1, 0)

    -- One coordinated heartbeat animation replaces disconnected tweens. The
    -- knees remain attached to both leg segments, while the body swings gently
    -- and each leg follows a slightly different phase for organic movement.
    local bornAt = os.clock()
    local bobY = math.clamp(height * 0.13, 0.9, 3.2)
    local swingX = math.clamp(width * 0.075, 0.45, 1.7)

    local function placeSegment(piece, x1, y1, x2, y2, thickness)
        if not piece or not piece.Parent then return end
        local dx, dy = x2 - x1, y2 - y1
        local length = math.max(0.5, math.sqrt(dx * dx + dy * dy))
        piece.Position = UDim2.fromOffset((x1 + x2) * 0.5, (y1 + y2) * 0.5)
        piece.Size = UDim2.fromOffset(length, thickness)
        piece.Rotation = math.deg(math.atan2(dy, dx))
    end

    local threadConnection
    local updateAccumulator = 0
    local animationStep = 1 / 30 -- UI decoration does not need to update at full frame rate.
    threadConnection = RunService.Heartbeat:Connect(function(dt)
        if not root.Parent or not thread.Parent or not threadGlow.Parent then
            if threadConnection then threadConnection:Disconnect() end
            return
        end
        updateAccumulator += dt
        if updateAccumulator < animationStep then return end
        updateAccumulator %= animationStep

        local t = os.clock() - bornAt
        -- Low-frequency sway + secondary bob, no abrupt direction changes.
        local bodySway = math.sin(t * 1.18 + 0.24)
        local bodyBob = math.sin(t * 2.05 + 0.6)
        root.Position = UDim2.fromOffset(x + bodySway * swingX, y + bodyBob * bobY)
        root.Rotation = math.sin(t * 1.06 + 0.18) * 3.2

        for _, leg in ipairs(legParts) do
            local i = leg.index
            local reach = math.sin(t * 2.8 + i * 0.83)
            local lift = math.cos(t * 2.35 + i * 1.07)
            local ex = leg.endX + leg.side * reach * microMove * 1.25
            local ey = leg.endY + lift * microMove * 0.9
            -- A tiny knee flex creates a two-joint step rather than a rigid twitch.
            local kx = leg.baseX + (ex - leg.baseX) * 0.54
            local ky = leg.baseY + (ey - leg.baseY) * 0.54 + math.sin(t * 3.1 + i * 0.71) * microMove * 0.42
            placeSegment(leg.first, leg.baseX, leg.baseY, kx, ky, leg.firstThickness)
            placeSegment(leg.second, kx, ky, ex, ey, leg.secondThickness)
            if leg.knee and leg.knee.Parent then
                leg.knee.Position = UDim2.fromOffset(kx, ky)
            end
        end

        -- The silk pivots from its fixed ceiling anchor and continuously follows
        -- the spider's body, keeping the thread visually attached during the swing.
        local dx = root.Position.X.Offset - x
        local dy = root.Position.Y.Offset - y
        local threadHeight = math.max(2, threadLength + height * 0.52 + dy)
        local lean = math.deg(math.atan2(dx, math.max(1, threadHeight)))
        thread.Size = UDim2.fromOffset(1, threadHeight)
        threadGlow.Size = UDim2.fromOffset(3, threadHeight + 1)
        thread.Rotation = lean
        threadGlow.Rotation = lean
        local silkPulse = (math.sin(t * 1.45) + 1) * 0.5
        thread.BackgroundTransparency = 0.075 + silkPulse * 0.045
        threadGlow.BackgroundTransparency = 0.84 - silkPulse * 0.09
    end)

    -- A quiet abdomen pulse and soft silk shimmer add life without rapid flicker.
    task.spawn(function()
        while root.Parent and abdomen.Parent do
            local pulse = TS_G:Create(abdomenStroke, TweenInfo.new(0.9, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut), {
                Transparency = 0.42,
            })
            pulse:Play()
            pulse.Completed:Wait()
            if not root.Parent then break end
            local settle = TS_G:Create(abdomenStroke, TweenInfo.new(1.05, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut), {
                Transparency = 0.08,
            })
            settle:Play()
            settle.Completed:Wait()
        end
    end)

    return root, thread
end

-- Draw a refined corner cobweb: evenly spaced radial silk strands crossed by
-- curved, nested bands. The old version used crossing polygonal lines, which
-- made the web look like a rough grid at small sizes.
function addHalloweenSpiderWeb(parent, name, position, size, zIndex, transparency, orientation)
    size = math.max(12, tonumber(size) or 32)
    zIndex = zIndex or 1
    local root = Instance.new("Frame")
    root.Name = name
    root.Position = position
    root.Size = UDim2.fromOffset(size, size)
    root.BackgroundTransparency = 1
    root.BorderSizePixel = 0
    root.ZIndex = zIndex
    root.Active = false
    root.Selectable = false
    root.ClipsDescendants = true
    root.Parent = parent

    local webColor = Color3.fromRGB(155, 155, 155)
    local silkHighlight = Color3.fromRGB(206, 206, 206)
    local alpha = math.clamp(tonumber(transparency) or 0.46, 0.14, 0.82)
    local orientationIndex = (tonumber(orientation) or 0) % 4
    local function transform(px, py)
        if orientationIndex == 1 then return size - px, py end
        if orientationIndex == 2 then return size - px, size - py end
        if orientationIndex == 3 then return px, size - py end
        return px, py
    end
    local lineCounter = 0
    local function line(x1, y1, x2, y2, thickness, transparencyValue, color, nameSuffix)
        x1, y1 = transform(x1, y1)
        x2, y2 = transform(x2, y2)
        local dx, dy = x2 - x1, y2 - y1
        local length = math.sqrt(dx * dx + dy * dy)
        if length < 1 then return nil end
        lineCounter = lineCounter + 1
        local piece = Instance.new("Frame")
        piece.Name = nameSuffix or ("SilkStrand" .. tostring(lineCounter))
        piece.AnchorPoint = Vector2.new(0.5, 0.5)
        piece.Position = UDim2.fromOffset((x1 + x2) * 0.5, (y1 + y2) * 0.5)
        piece.Size = UDim2.fromOffset(length, thickness or 1)
        piece.Rotation = math.deg(math.atan2(dy, dx))
        piece.BackgroundColor3 = color or webColor
        piece.BackgroundTransparency = transparencyValue or alpha
        piece.BorderSizePixel = 0
        piece.ZIndex = zIndex + 1
        piece.Active = false
        piece.Selectable = false
        piece.Parent = root
        return piece
    end

    -- Mobile-friendly web: fewer spokes/bands keep the Halloween detail crisp without hundreds of UI parts.
    local spokeCount = 5
    local spokePoints = {}
    for i = 0, spokeCount - 1 do
        local theta = (math.pi * 0.5) * (i / (spokeCount - 1))
        local ct, st = math.cos(theta), math.sin(theta)
        local edgeDistance = size / math.max(ct, st)
        local ex, ey = edgeDistance * ct, edgeDistance * st
        spokePoints[#spokePoints + 1] = {theta = theta, distance = edgeDistance, x = ex, y = ey}
        -- The first and last strands catch a little more light like real silk.
        line(0, 0, ex, ey, (i == 1 or i == spokeCount - 2) and 1.35 or 1.05,
            (i == 1 or i == spokeCount - 2) and math.max(0.12, alpha - 0.12) or alpha,
            webColor, "RadialSilk" .. tostring(i + 1))
    end

    -- Each cross-thread follows a shallow Bezier bow instead of a straight
    -- polygon chord. This makes the web read as taut silk rather than a grid.
    local ringFractions = {0.28, 0.58, 0.86}
    local curveSteps = 2
    for ringIndex, fraction in ipairs(ringFractions) do
        local pts = {}
        for _, spoke in ipairs(spokePoints) do
            local radius = spoke.distance * fraction
            pts[#pts + 1] = {x = radius * math.cos(spoke.theta), y = radius * math.sin(spoke.theta)}
        end
        for i = 1, #pts - 1 do
            local a, b = pts[i], pts[i + 1]
            local bendScale = 1.035 + (ringIndex / #ringFractions) * 0.015
            local cx, cy = ((a.x + b.x) * 0.5) * bendScale, ((a.y + b.y) * 0.5) * bendScale
            local prevX, prevY = a.x, a.y
            local outerBand = ringIndex == #ringFractions
            local emphasized = (i == 2 or i == 4) and ringIndex % 2 == 1
            for segment = 1, curveSteps do
                local t = segment / curveSteps
                local inv = 1 - t
                local px = inv * inv * a.x + 2 * inv * t * cx + t * t * b.x
                local py = inv * inv * a.y + 2 * inv * t * cy + t * t * b.y
                line(prevX, prevY, px, py,
                    outerBand and 1.2 or 0.9,
                    emphasized and math.max(0.10, alpha - 0.19) or (alpha + (ringIndex % 2) * 0.045),
                    emphasized and silkHighlight or webColor,
                    "CurvedSilkBand" .. tostring(ringIndex) .. "Segment" .. tostring(i) .. "Piece" .. tostring(segment))
                prevX, prevY = px, py
            end
        end
    end

    -- Fine golden beads are placed on true spoke/band intersections, not on
    -- the square's arbitrary corners; this makes the pattern read as a web.
    local outerFraction = 0.78
    for _, spokeIndex in ipairs({1, 3, 5}) do
        local spoke = spokePoints[spokeIndex]
        local radius = spoke.distance * outerFraction
        local px, py = radius * math.cos(spoke.theta), radius * math.sin(spoke.theta)
        px, py = transform(px, py)
        local bead = Instance.new("Frame")
        bead.Name = "SilkAmberKnot" .. tostring(spokeIndex)
        bead.AnchorPoint = Vector2.new(0.5, 0.5)
        bead.Position = UDim2.fromOffset(px, py)
        local beadSize = math.max(2, math.floor(size * 0.06))
        bead.Size = UDim2.fromOffset(beadSize, beadSize)
        bead.BackgroundColor3 = silkHighlight
        bead.BackgroundTransparency = math.min(0.32, alpha * 0.45)
        bead.BorderSizePixel = 0
        bead.ZIndex = zIndex + 2
        bead.Active = false
        bead.Selectable = false
        bead.Parent = root
        Instance.new("UICorner", bead).CornerRadius = UDim.new(1, 0)
    end

    -- Tiny corner anchor where all of the silk originates.
    local anchorGlow = Instance.new("Frame")
    anchorGlow.Name = "SilkAnchorGlow"
    anchorGlow.AnchorPoint = Vector2.new(0.5, 0.5)
    local ax, ay = transform(0, 0)
    anchorGlow.Position = UDim2.fromOffset(ax, ay)
    anchorGlow.Size = UDim2.fromOffset(math.max(3, size * 0.10), math.max(3, size * 0.10))
    anchorGlow.BackgroundColor3 = Color3.fromRGB(178, 178, 178)
    anchorGlow.BackgroundTransparency = 0.28
    anchorGlow.BorderSizePixel = 0
    anchorGlow.ZIndex = zIndex + 3
    anchorGlow.Active = false
    anchorGlow.Selectable = false
    anchorGlow.Parent = root
    Instance.new("UICorner", anchorGlow).CornerRadius = UDim.new(1, 0)

    local anchorPulse = TS_G:Create(anchorGlow, TweenInfo.new(1.35, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut, -1, true), {
        BackgroundTransparency = 0.58,
        Size = UDim2.fromOffset(math.max(2, size * 0.07), math.max(2, size * 0.07)),
    })
    anchorPulse:Play()

    -- A single slow silk glint gives each web depth without cluttering the UI.
    local glint = Instance.new("TextLabel")
    glint.Name = "SilkGlint"
    glint.AnchorPoint = Vector2.new(0.5, 0.5)
    glint.Position = UDim2.fromOffset(size * 0.70, size * 0.70)
    glint.Size = UDim2.fromOffset(math.max(5, size * 0.16), math.max(5, size * 0.16))
    glint.BackgroundTransparency = 1
    glint.BorderSizePixel = 0
    glint.Text = "✦"
    glint.TextColor3 = silkHighlight
    glint.TextTransparency = 0.28
    glint.TextStrokeColor3 = Color3.fromRGB(50, 50, 50)
    glint.TextStrokeTransparency = 0.42
    glint.Font = Enum.Font.GothamBold
    glint.TextScaled = true
    glint.ZIndex = zIndex + 4
    glint.Active = false
    glint.Selectable = false
    glint.Parent = root
    glint.Rotation = -8
    return root
end

-- XYPHER HUB INTRO — replaced with intro_xypher_hub_starborn_FIXED.lua.
-- Kept as a function so the existing startup sequence and visibility callback still work.
local function showIntro(onFinished)
    local Players = game:GetService("Players")
    local HttpService = game:GetService("HttpService")
    local LP = Players.LocalPlayer
    if not LP then
        LP = Players.PlayerAdded:Wait()
    end

    do
        -- ============ INTRO XYPHER HUB (intro Fira/Rival Hub dipindahkan persis; intro lama Nanz sudah dihapus) ============
        -- layar 1: "Adaptt ontop?"  ->  layar 2: "NO!"  ->  layar 3: "XYPHER HUB" + link discord
        local skipIntroNow = false
        local introThemeKey = nil
        pcall(function()
            local fileName = "MVP_" .. tostring(LP.UserId) .. ".json"
            if type(isfile) == "function" and type(readfile) == "function" and isfile(fileName) then
                local data = HttpService:JSONDecode(readfile(fileName))
                if type(data) == "table" and data.skipIntro == true then skipIntroNow = true end
                if type(data) == "table" and type(data.themeColor) == "string" then introThemeKey = data.themeColor end
            end
        end)
        local okIntro, errIntro = pcall(function()
            if skipIntroNow then return end
            local TweenService = game:GetService("TweenService")
            local CoreGui = game:GetService("CoreGui")
            local SoundService = game:GetService("SoundService")
            local UserInputService = game:GetService("UserInputService")
            local Players = game:GetService("Players")

            -- Muat Starborn dengan cara yang sama seperti file font kedua, tetapi
            -- validasi ulang TTF dan tulis ulang JSON setiap eksekusi supaya tidak
            -- memakai file/cache lama yang membuat font diam-diam kembali ke default.
            local INTRO_FONT = nil
            local INTRO_FONT_ERROR = nil
            do
                local envSyn = (type(syn) == "table") and syn or nil
                local assetFn = (type(getcustomasset) == "function" and getcustomasset)
                    or (type(getsynasset) == "function" and getsynasset)
                    or (envSyn and type(envSyn.getcustomasset) == "function" and envSyn.getcustomasset)
                    or (envSyn and type(envSyn.getsynasset) == "function" and envSyn.getsynasset)

                local fontFile = "starborn.ttf"
                local configFile = "starborn.json"
                local fontUrl = "https://files.catbox.moe/pwgdui.ttf"

                local function validFontData(data)
                    if type(data) ~= "string" or #data < 1000 then
                        return false
                    end
                    local signature = data:sub(1, 4)
                    return signature == "\0\1\0\0"
                        or signature == "OTTO"
                        or signature == "true"
                        or signature == "ttcf"
                end

                local ok, result = pcall(function()
                    if not assetFn then
                        error("executor tidak menyediakan getcustomasset/getsynasset")
                    end
                    if type(writefile) ~= "function" then
                        error("executor tidak menyediakan writefile")
                    end

                    local cachedFont = nil
                    if type(isfile) == "function" and type(readfile) == "function" then
                        local existsOk, exists = pcall(isfile, fontFile)
                        if existsOk and exists then
                            local readOk, bytes = pcall(readfile, fontFile)
                            if readOk and validFontData(bytes) then
                                cachedFont = bytes
                            end
                        end
                    end

                    if not cachedFont then
                        local downloadOk, bytes = pcall(game.HttpGet, game, fontUrl)
                        if not downloadOk or not validFontData(bytes) then
                            error("unduhan starborn.ttf gagal atau file yang diterima bukan TTF yang valid")
                        end
                        local writeOk, writeErr = pcall(writefile, fontFile, bytes)
                        if not writeOk then
                            error("gagal menulis starborn.ttf: " .. tostring(writeErr))
                        end
                        if type(readfile) == "function" then
                            local verifyOk, verifyBytes = pcall(readfile, fontFile)
                            if not verifyOk or not validFontData(verifyBytes) then
                                error("starborn.ttf gagal diverifikasi setelah disimpan")
                            end
                        end
                    end

                    -- Selalu buat ulang config agar assetId tidak tertinggal dari cache lama.
                    local assetOk, fontAsset = pcall(assetFn, fontFile)
                    if not assetOk or type(fontAsset) ~= "string" or fontAsset == "" then
                        error("getcustomasset gagal membuat asset untuk starborn.ttf: " .. tostring(fontAsset))
                    end

                    local config = HttpService:JSONEncode({
                        name = "Starborn",
                        faces = {{
                            name = "Regular",
                            weight = 400,
                            style = "normal",
                            assetId = fontAsset,
                        }}
                    })
                    local configWriteOk, configWriteErr = pcall(writefile, configFile, config)
                    if not configWriteOk then
                        error("gagal menulis starborn.json: " .. tostring(configWriteErr))
                    end

                    local configAssetOk, configAsset = pcall(assetFn, configFile)
                    if not configAssetOk or type(configAsset) ~= "string" or configAsset == "" then
                        error("getcustomasset gagal membuat asset untuk starborn.json: " .. tostring(configAsset))
                    end

                    local fontOk, loadedFont = pcall(function()
                        return Font.new(configAsset)
                    end)
                    if not fontOk or not loadedFont then
                        error("Font.new gagal memuat Starborn: " .. tostring(loadedFont))
                    end

                    -- Uji bahwa FontFace benar-benar dapat dipasang sebelum intro dibuat.
                    local probe = Instance.new("TextLabel")
                    local assignOk, assignErr = pcall(function()
                        probe.FontFace = loadedFont
                    end)
                    probe:Destroy()
                    if not assignOk then
                        error("FontFace menolak font Starborn: " .. tostring(assignErr))
                    end
                    return loadedFont
                end)

                if ok then
                    INTRO_FONT = result
                    print("[XYPHER HUB] Font Starborn berhasil dimuat dan siap dipakai pada intro.")
                else
                    INTRO_FONT_ERROR = tostring(result)
                    warn("[XYPHER HUB] Starborn gagal dimuat: " .. INTRO_FONT_ERROR)
                end
            end

            local function applyIntroFont(textObject, fallbackFont)
                -- Font lama hanya menjadi fallback jika executor benar-benar gagal
                -- memuat custom asset. Saat Starborn tersedia, FontFace dipasang terakhir.
                textObject.Font = fallbackFont
                if INTRO_FONT then
                    local ok, err = pcall(function()
                        textObject.FontFace = INTRO_FONT
                    end)
                    if not ok then
                        warn("[XYPHER HUB] Gagal memasang Starborn pada " .. textObject.Name .. ": " .. tostring(err))
                    end
                end
            end

            local function forceStarbornOnText(object)
                if not INTRO_FONT or not object then return end
                if object:IsA("TextLabel") or object:IsA("TextButton") or object:IsA("TextBox") then
                    local ok, err = pcall(function()
                        object.FontFace = INTRO_FONT
                    end)
                    if not ok then
                        warn("[XYPHER HUB] Gagal memaksa Starborn pada " .. object.Name .. ": " .. tostring(err))
                    end
                end
            end

            local HOLD_TO_SKIP = 1
            local INTRO_DURATION = 6.35
            local SONG_URL = "https://files.catbox.moe/4inuat.mp3"
            local SONG_FILE = "M4LWARE_Intro_Song1.mp3"

            -- ===== tema monokrom: hitam, abu-abu perak, dan putih =====
            -- Warna intro dikunci ke hitam-putih agar config tema lama tidak mengubah tampilannya.
