do
-- Starborn font toggle: applies Starborn to script UI and game UI text,
-- including text with strokes, while retaining original fonts for restoration.
local XYPHER_STARborn_URL = "https://files.catbox.moe/pwgdui.ttf"
local XYPHER_STARborn_FACE = nil
local XYPHER_STARborn_ORIGINALS = setmetatable({}, { __mode = "k" })
local XYPHER_STARborn_OBJECT_CONNECTIONS = setmetatable({}, { __mode = "k" })
local XYPHER_STARborn_REAPPLY_QUEUED = setmetatable({}, { __mode = "k" })
local XYPHER_STARborn_ROOT_CONNECTIONS = {}
local XYPHER_STARborn_TOKEN = 0

local function getXypherCustomAssetFunction()
    local assetFn = nil
    if type(getcustomasset) == "function" then
        assetFn = getcustomasset
    elseif type(getsynasset) == "function" then
        assetFn = getsynasset
    end

    -- A few executors expose asset helpers only through syn/getgenv.
    if not assetFn and type(syn) == "table" then
        if type(syn.getcustomasset) == "function" then
            assetFn = syn.getcustomasset
        elseif type(syn.getsynasset) == "function" then
            assetFn = syn.getsynasset
        end
    end
    if not assetFn and type(getgenv) == "function" then
        local envOk, env = pcall(getgenv)
        if envOk and type(env) == "table" then
            if type(env.getcustomasset) == "function" then
                assetFn = env.getcustomasset
            elseif type(env.getsynasset) == "function" then
                assetFn = env.getsynasset
            end
        end
    end
    return assetFn
end

local function isValidXypherTTF(data)
    if type(data) ~= "string" or #data < 1000 then return false end
    local signature = data:sub(1, 4)
    return signature == "\0\1\0\0"
        or signature == "OTTO"
        or signature == "true"
        or signature == "ttcf"
end

local function loadXypherStarbornFont()
    if XYPHER_STARborn_FACE then return XYPHER_STARborn_FACE end

    local assetFn = getXypherCustomAssetFunction()
    if not assetFn then
        warn("[XYPHER] Font Starborn tidak dapat dimuat: executor tidak menyediakan getcustomasset/getsynasset.")
        return nil
    end
    if type(writefile) ~= "function" then
        warn("[XYPHER] Font Starborn tidak dapat dimuat: executor tidak menyediakan writefile.")
        return nil
    end

    local fontPath = "starborn.ttf"
    local jsonPath = "starborn.json"
    local fontData = safeReadfile(fontPath)
    if not isValidXypherTTF(fontData) then
        local downloadOk, downloaded = pcall(function()
            return game:HttpGet(XYPHER_STARborn_URL)
        end)
        if not downloadOk or not isValidXypherTTF(downloaded) then
            warn("[XYPHER] Unduhan Starborn gagal atau file yang diterima bukan font TTF/OTF yang valid.")
            return nil
        end
        local writeOk, writeErr = pcall(writefile, fontPath, downloaded)
        if not writeOk then
            warn("[XYPHER] Gagal menyimpan starborn.ttf: " .. tostring(writeErr))
            return nil
        end
        -- Some executors have writefile but expose readfile inconsistently.
        -- Verify saved bytes when possible; otherwise the validated download is safe to use.
        local savedFontData = safeReadfile(fontPath)
        fontData = savedFontData or downloaded
        if not isValidXypherTTF(fontData) then
            warn("[XYPHER] Verifikasi starborn.ttf gagal setelah file disimpan.")
            return nil
        end
    end

    -- Refresh the asset URI each run so starborn.json cannot retain a stale URI.
    local assetOk, fontAsset = pcall(assetFn, fontPath)
    if not assetOk or type(fontAsset) ~= "string" or fontAsset == "" then
        warn("[XYPHER] Executor gagal membuat asset untuk starborn.ttf: " .. tostring(fontAsset))
        return nil
    end

    local encodeOk, config = pcall(function()
        return HS:JSONEncode({
            name = "Starborn",
            faces = {{
                name = "Regular",
                weight = 400,
                style = "normal",
                assetId = fontAsset,
            }},
        })
    end)
    if not encodeOk or type(config) ~= "string" then
        warn("[XYPHER] Gagal membuat konfigurasi font Starborn: " .. tostring(config))
        return nil
    end
    local configWriteOk, configWriteErr = pcall(writefile, jsonPath, config)
    if not configWriteOk then
        warn("[XYPHER] Gagal menyimpan starborn.json: " .. tostring(configWriteErr))
        return nil
    end

    local jsonAssetOk, jsonAsset = pcall(assetFn, jsonPath)
    if not jsonAssetOk or type(jsonAsset) ~= "string" or jsonAsset == "" then
        warn("[XYPHER] Executor gagal membuat asset untuk starborn.json: " .. tostring(jsonAsset))
        return nil
    end

    local fontOk, face = pcall(function() return Font.new(jsonAsset) end)
    if not fontOk or not face then
        warn("[XYPHER] Font.new gagal memuat Starborn: " .. tostring(face))
        return nil
    end
    local probe = Instance.new("TextLabel")
    local assignOk, assignErr = pcall(function() probe.FontFace = face end)
    probe:Destroy()
    if not assignOk then
        warn("[XYPHER] FontFace menolak font Starborn: " .. tostring(assignErr))
        return nil
    end

    XYPHER_STARborn_FACE = face
    return face
end

local function isXypherStarbornTarget(obj)
    if not obj then return false end
    local ok, shouldUse = pcall(function()
        if not (obj:IsA("TextLabel") or obj:IsA("TextButton") or obj:IsA("TextBox")) then
            return false
        end
        -- IMPORTANT: do not filter TextStrokeTransparency. Stroked game text
        -- must also receive Starborn; the stroke itself remains unchanged.
        local fontString = tostring(obj.FontFace)
        if fontString:find("BuilderIcons", 1, true) then return false end
        return true
    end)
    return ok and shouldUse == true
end

local function bindXypherStarbornFontGuard(obj)
    if XYPHER_STARborn_OBJECT_CONNECTIONS[obj] then return end
    local ok, connection = pcall(function()
        return obj:GetPropertyChangedSignal("FontFace"):Connect(function()
            if not S.starbornFontEnabled or not obj.Parent then return end
            local readOk, currentFace = pcall(function() return obj.FontFace end)
            if not readOk or currentFace == XYPHER_STARborn_FACE then return end
            if XYPHER_STARborn_REAPPLY_QUEUED[obj] then return end
            XYPHER_STARborn_REAPPLY_QUEUED[obj] = true
            task.defer(function()
                XYPHER_STARborn_REAPPLY_QUEUED[obj] = nil
                if not S.starbornFontEnabled or not obj.Parent then return end
                pcall(function()
                    if obj.FontFace ~= XYPHER_STARborn_FACE then
                        obj.FontFace = XYPHER_STARborn_FACE
                    end
                end)
            end)
        end)
    end)
    if ok and connection then
        XYPHER_STARborn_OBJECT_CONNECTIONS[obj] = connection
    end
end

local function applyXypherStarbornToObject(obj)
    if not S.starbornFontEnabled or not isXypherStarbornTarget(obj) then return end

    if XYPHER_STARborn_ORIGINALS[obj] == nil then
        local ok, originalFace = pcall(function() return obj.FontFace end)
        if not ok or originalFace == nil then return end
        XYPHER_STARborn_ORIGINALS[obj] = originalFace
    end

    bindXypherStarbornFontGuard(obj)
    pcall(function()
        if obj.FontFace ~= XYPHER_STARborn_FACE then
            obj.FontFace = XYPHER_STARborn_FACE
        end
    end)
end

local function getXypherStarbornRoots()
    local roots = { game }
    -- Some executors place their custom UI outside the DataModel. Include it
    -- when available so the scan covers both the game and executor UI.
    if type(gethui) == "function" then
        local ok, root = pcall(gethui)
        if ok and root and root ~= game then
            local isInGame = false
            pcall(function() isInGame = root:IsDescendantOf(game) end)
            if not isInGame then
                roots[#roots + 1] = root
            end
        end
    end
    return roots
end

local function disconnectXypherStarbornGuards()
    for obj, connection in pairs(XYPHER_STARborn_OBJECT_CONNECTIONS) do
        pcall(function() connection:Disconnect() end)
        XYPHER_STARborn_OBJECT_CONNECTIONS[obj] = nil
        XYPHER_STARborn_REAPPLY_QUEUED[obj] = nil
    end
end

local function setXypherStarbornFontEnabled(enabled)
    enabled = enabled == true
    if enabled == S.starbornFontEnabled then return true end

    if enabled then
        local face = loadXypherStarbornFont()
        if not face then return false end

        XYPHER_STARborn_TOKEN += 1
        local token = XYPHER_STARborn_TOKEN
        S.starbornFontEnabled = true
        if type(S.setStarbornFontVisual) == "function" then
            pcall(S.setStarbornFontVisual, true)
        end

        for _, connection in ipairs(XYPHER_STARborn_ROOT_CONNECTIONS) do
            pcall(function() connection:Disconnect() end)
        end
        table.clear(XYPHER_STARborn_ROOT_CONNECTIONS)

        local roots = getXypherStarbornRoots()
        for _, root in ipairs(roots) do
            local ok, connection = pcall(function()
                return root.DescendantAdded:Connect(function(obj)
                    if not S.starbornFontEnabled then return end
                    task.defer(function()
                        if S.starbornFontEnabled then
                            applyXypherStarbornToObject(obj)
                        end
                    end)
                end)
            end)
            if ok and connection then
                XYPHER_STARborn_ROOT_CONNECTIONS[#XYPHER_STARborn_ROOT_CONNECTIONS + 1] = connection
            end
        end

        -- Walk all current descendants in batches to avoid a large one-frame hitch.
        task.spawn(function()
            local seen = setmetatable({}, { __mode = "k" })
            for _, root in ipairs(roots) do
                if token ~= XYPHER_STARborn_TOKEN or not S.starbornFontEnabled then return end
                local ok, descendants = pcall(function() return root:GetDescendants() end)
                if ok and type(descendants) == "table" then
                    for index, obj in ipairs(descendants) do
                        if token ~= XYPHER_STARborn_TOKEN or not S.starbornFontEnabled then return end
                        if not seen[obj] then
                            seen[obj] = true
                            applyXypherStarbornToObject(obj)
                        end
                        if index % 250 == 0 then task.wait() end
                    end
                end
            end
        end)
        return true
    end

    S.starbornFontEnabled = false
    if type(S.setStarbornFontVisual) == "function" then
        pcall(S.setStarbornFontVisual, false)
    end
    XYPHER_STARborn_TOKEN += 1
    for _, connection in ipairs(XYPHER_STARborn_ROOT_CONNECTIONS) do
        pcall(function() connection:Disconnect() end)
    end
    table.clear(XYPHER_STARborn_ROOT_CONNECTIONS)
    disconnectXypherStarbornGuards()

    for obj, originalFace in pairs(XYPHER_STARborn_ORIGINALS) do
        if obj then
            pcall(function() obj.FontFace = originalFace end)
        end
        XYPHER_STARborn_ORIGINALS[obj] = nil
    end
    return true
end

S._setStarbornFontEnabled = setXypherStarbornFontEnabled
end


-- Apply the selected image to each floating mobile button's background layer.
-- Images use full brightness; only a very light shade remains for text contrast.
function setStealPhotoImage(assetId)
    S._stealPhotoLoadToken = (S._stealPhotoLoadToken or 0) + 1
    local loadToken = S._stealPhotoLoadToken
    local targets = S.mobileButtonBackgroundImages or {}
    local rawId = type(assetId) == "string" and assetId or ""
    local isEmbeddedPhoto = rawId == XYPHER_UPLOADED_PHOTO_OPTION or rawId == XYPHER_UPLOADED_PHOTO_OPTION_2 or rawId == XYPHER_UPLOADED_PHOTO_OPTION_3 or rawId == XYPHER_UPLOADED_PHOTO_OPTION_4
    local validId = (rawId:match("^%d+$") and rawId) or (isEmbeddedPhoto and rawId or nil)
    local embeddedUri = isEmbeddedPhoto and ensureXypherUploadedPhotoAsset(rawId) or nil
    if isEmbeddedPhoto and not embeddedUri then validId = nil end

    if not validId then
        for _, target in ipairs(targets) do
            pcall(function()
                if target.image and target.image.Parent then
                    target.image.Image = ""
                    target.image.Visible = false
                end
                if target.shade and target.shade.Parent then
                    target.shade.Visible = false
                end
            end)
        end
        return
    end

    -- The IDs in this menu are image/decal asset IDs, so try the direct asset
    -- URI first (it renders the actual image rather than a catalog thumbnail).
    -- Fall back to rbxthumb for assets that do not resolve directly.
    local directUri = isEmbeddedPhoto and embeddedUri or ("rbxassetid://" .. validId)
    local thumbnailUri = not isEmbeddedPhoto and ("rbxthumb://type=Asset&id=" .. validId .. "&w=420&h=420") or nil
    local firstImage = nil
    for _, target in ipairs(targets) do
        pcall(function()
            local image = target.image
            if image and image.Parent then
                image.Image = directUri
                image.ImageTransparency = 0
                image.Visible = true
                image.ZIndex = 12
                firstImage = firstImage or image
            end
            if target.shade and target.shade.Parent then
                target.shade.Visible = true
            end
        end)
    end

    -- Never block GUI creation while waiting for an image. If direct asset loading
    -- fails, switch all buttons to a thumbnail URI after a short bounded wait.
    task.spawn(function()
        local loaded = false
        local deadline = os.clock() + 2.5
        while os.clock() < deadline do
            if loadToken ~= S._stealPhotoLoadToken then return end
            if firstImage and firstImage.Parent then
                local ok, isLoaded = pcall(function() return firstImage.IsLoaded end)
                if ok and isLoaded then
                    loaded = true
                    break
                end
            else
                return
            end
            task.wait(0.1)
        end
        if loaded or loadToken ~= S._stealPhotoLoadToken then return end
        if isEmbeddedPhoto then
            warn("[XYPHER] Embedded mobile-button photo did not load. Check local JPG image support in the executor.")
            return
        end
        for _, target in ipairs(S.mobileButtonBackgroundImages or {}) do
            pcall(function()
                if target.image and target.image.Parent then
                    target.image.Image = thumbnailUri
                    target.image.Visible = true
                end
            end)
        end
    end)
end

-- ===== PLAYER ESP (VX7 COMPOSITE: BOX + HIGHLIGHT + SPEED CARD) =====
PLAYER_ESP_COLOR = Color3.fromRGB(151, 151, 151) -- Halloween orange ESP
PLAYER_ESP_FILL_TRANSPARENCY = 0.7
PLAYER_ESP_OUTLINE_TRANSPARENCY = 0.3
PLAYER_ESP_BIND_NAME = "Vision_VX7_PlayerESP"

function ensurePlayerESPGui()
    local cache = S.espPlayerCache
    if cache.screenGui and cache.screenGui.Parent then return cache.screenGui end
    local playerGui = LP:FindFirstChildOfClass("PlayerGui") or LP:WaitForChild("PlayerGui")
    local screenGui = Instance.new("ScreenGui")
    screenGui.Name = "Vision_VX7_PlayerESP"
    screenGui.ResetOnSpawn = false
    screenGui.DisplayOrder = 998
    screenGui.IgnoreGuiInset = true
    screenGui.ZIndexBehavior = Enum.ZIndexBehavior.Global
    screenGui.Parent = playerGui
    cache.screenGui = screenGui
    return screenGui
end

function removeESPHighlight(playerData)
    if playerData and playerData.highlight then
        pcall(function() playerData.highlight:Destroy() end)
        playerData.highlight = nil
    end
end

function disconnectESPConnection(playerData, name)
    local connection = playerData and playerData[name]
    if connection then
        pcall(function() connection:Disconnect() end)
        playerData[name] = nil
    end
end

function removeESPForPlayer(player)
    local cache = S.espPlayerCache
    local data = cache and cache.players[player]
    if not data then return end
    disconnectESPConnection(data, "charConn")
    disconnectESPConnection(data, "charRemovingConn")
    removeESPHighlight(data)
    for _, key in ipairs({"box", "infoFrame"}) do
        if data[key] then pcall(function() data[key]:Destroy() end); data[key] = nil end
    end
    data.speedLabel = nil
    data.nameLabel = nil
    cache.players[player] = nil
end

function clearESP()
    local cache = S.espPlayerCache
    if not cache then return end
    local players = {}
    for player in pairs(cache.players) do table.insert(players, player) end
    for _, player in ipairs(players) do removeESPForPlayer(player) end
end

function createESPBox(parent)
    local box = Instance.new("Frame")
    box.Name = "VX7_ESPBox2D"
    box.BackgroundColor3 = PLAYER_ESP_COLOR
    box.BackgroundTransparency = 0.75
    box.BorderSizePixel = 0
    box.Visible = false
    box.ZIndex = 2
    box.Parent = parent
    local stroke = Instance.new("UIStroke")
    stroke.Color = PLAYER_ESP_COLOR
    stroke.Thickness = 1.5
    stroke.Transparency = 0
    stroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
    stroke.Parent = box
    return box
end

function createESPInfoCard(parent, player)
    local root = Instance.new("Frame")
    root.Name = "VX7_EI_" .. tostring(player.UserId)
    root.Size = UDim2.fromOffset(174, 59)
    root.AnchorPoint = Vector2.new(0.5, 1)
    root.BackgroundTransparency = 1
    root.BorderSizePixel = 0
    root.Visible = false
    root.Parent = parent

    local avatarBack = Instance.new("Frame")
    avatarBack.Size = UDim2.fromOffset(34, 34)
    avatarBack.Position = UDim2.fromOffset(8, 3)
    avatarBack.BackgroundColor3 = Color3.fromRGB(33, 33, 33)
    avatarBack.BorderSizePixel = 0
    avatarBack.Parent = root
    Instance.new("UICorner", avatarBack).CornerRadius = UDim.new(1, 0)

    local avatar = Instance.new("ImageLabel")
    avatar.Name = "Avatar"
    avatar.Size = UDim2.new(1, -4, 1, -4)
    avatar.Position = UDim2.fromOffset(2, 2)
    avatar.BackgroundTransparency = 1
    avatar.ScaleType = Enum.ScaleType.Crop
    avatar.Parent = avatarBack
    Instance.new("UICorner", avatar).CornerRadius = UDim.new(1, 0)
    task.spawn(function()
        local ok, image = pcall(function()
            return Players:GetUserThumbnailAsync(player.UserId, Enum.ThumbnailType.HeadShot, Enum.ThumbnailSize.Size48x48)
        end)
        if ok and image and avatar.Parent then avatar.Image = image end
    end)

    local speed = Instance.new("TextLabel")
    speed.Name = "Speed"
    speed.Size = UDim2.new(1, 0, 0, 40)
    speed.Position = UDim2.new(0, 0, 0, 0)
    speed.BackgroundTransparency = 1
    speed.Text = "0.0"
    speed.TextColor3 = PLAYER_ESP_COLOR
    speed.Font = Enum.Font.GothamBlack
    speed.TextSize = 30
    speed.TextXAlignment = Enum.TextXAlignment.Center
    speed.TextYAlignment = Enum.TextYAlignment.Center
    speed.TextStrokeTransparency = 0
    speed.TextStrokeColor3 = Color3.fromRGB(20, 20, 20)
    speed.Parent = root

    local displayName = Instance.new("TextLabel")
    displayName.Name = "DisplayName"
    displayName.Size = UDim2.new(1, 0, 0, 17)
    displayName.Position = UDim2.new(0, 0, 0, 40)
    displayName.BackgroundTransparency = 1
    displayName.Text = player.DisplayName
    displayName.TextColor3 = PLAYER_ESP_COLOR
    displayName.Font = Enum.Font.GothamBold
    displayName.TextSize = 10
    displayName.TextXAlignment = Enum.TextXAlignment.Center
    displayName.TextStrokeTransparency = 0
    displayName.TextStrokeColor3 = Color3.fromRGB(20, 20, 20)
    displayName.Parent = root
    return root, speed, displayName
end

function setPlayerESPCharacter(playerData, character)
    removeESPHighlight(playerData)
    if not S.espEnabled or not character or not character.Parent then return end
    local highlight = Instance.new("Highlight")
    highlight.Name = "VX7_ESPPlayer"
    highlight.Adornee = character
    highlight.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
    highlight.FillTransparency = PLAYER_ESP_FILL_TRANSPARENCY
    highlight.OutlineTransparency = PLAYER_ESP_OUTLINE_TRANSPARENCY
    highlight.FillColor = PLAYER_ESP_COLOR
    highlight.OutlineColor = PLAYER_ESP_COLOR
    pcall(function() highlight:SetAttribute("VX7ESP", true) end)
    highlight.Parent = character
    playerData.highlight = highlight
end

function watchESPPlayer(player)
    if not player or player == LP then return end
    removeESPForPlayer(player)
    local cache = S.espPlayerCache
    local data = {lastSpeedText = nil}
    cache.players[player] = data
    local screenGui = ensurePlayerESPGui()
    data.box = createESPBox(screenGui)
    data.infoFrame, data.speedLabel, data.nameLabel = createESPInfoCard(screenGui, player)
    setPlayerESPCharacter(data, player.Character)

    data.charConn = player.CharacterAdded:Connect(function(character)
        task.delay(0.1, function()
            if S.espEnabled and cache.players[player] == data then
                setPlayerESPCharacter(data, character)
            end
        end)
    end)
    data.charRemovingConn = player.CharacterRemoving:Connect(function(character)
        if data.highlight and data.highlight.Adornee == character then removeESPHighlight(data) end
        if data.box then data.box.Visible = false end
        if data.infoFrame then data.infoFrame.Visible = false end
    end)
end

function updateESP(deltaTime)
    if not S.espEnabled then return end
    local cache = S.espPlayerCache
    local currentCamera = workspace.CurrentCamera
    if not currentCamera then return end
    cache.infoAccumulator = (cache.infoAccumulator or 0) + (deltaTime or 1 / 60)
    local updateInfo = cache.infoAccumulator >= 1 / 30
    if updateInfo then cache.infoAccumulator = 0 end

    for player, data in pairs(cache.players) do
        local character = player.Character
        local humanoid = character and character:FindFirstChildOfClass("Humanoid")
        local root = character and character:FindFirstChild("HumanoidRootPart")
        local head = character and character:FindFirstChild("Head")
        if character and humanoid and humanoid.Health > 0 and root then
            local headPos = (head and head.Position or root.Position + Vector3.new(0, 1, 0)) + Vector3.new(0, 1.6, 0)
            local footPos = root.Position - Vector3.new(0, 3, 0)
            local topScreen, topOnScreen = currentCamera:WorldToViewportPoint(headPos)
            local bottomScreen, bottomOnScreen = currentCamera:WorldToViewportPoint(footPos)
            if data.box and topOnScreen and bottomOnScreen and topScreen.Z > 0 and bottomScreen.Z > 0 then
                local height = math.abs(bottomScreen.Y - topScreen.Y)
                local width = height * 0.55
                if height == height and width == width and height > 0 then
                    data.box.Size = UDim2.fromOffset(width, height)
                    data.box.Position = UDim2.fromOffset((topScreen.X + bottomScreen.X) * 0.5 - width * 0.5, math.min(topScreen.Y, bottomScreen.Y))
                    data.box.Visible = true
                else
                    data.box.Visible = false
                end
            elseif data.box then
                data.box.Visible = false
            end

            if updateInfo and data.infoFrame and data.speedLabel then
                local cardPos, onScreen = currentCamera:WorldToViewportPoint(root.Position + Vector3.new(0, 3.45, 0))
                if onScreen and cardPos.Z > 0 then
                    data.infoFrame.Position = UDim2.fromOffset(cardPos.X, cardPos.Y)
                    data.infoFrame.Visible = true
                    local velocity = root.AssemblyLinearVelocity
                    local speedText = tostring(math.floor(Vector3.new(velocity.X, 0, velocity.Z).Magnitude * 10 + 0.5) / 10)
                    if data.lastSpeedText ~= speedText then
                        data.lastSpeedText = speedText
                        data.speedLabel.Text = speedText
                    end
                    data.speedLabel.TextColor3 = PLAYER_ESP_COLOR
                else
                    data.infoFrame.Visible = false
                end
            end
            local highlight = data.highlight
            if (not highlight or not highlight.Parent or highlight.Adornee ~= character) and S.espEnabled then
                setPlayerESPCharacter(data, character)
            elseif highlight then
                if highlight.FillColor ~= PLAYER_ESP_COLOR then highlight.FillColor = PLAYER_ESP_COLOR end
                if highlight.OutlineColor ~= PLAYER_ESP_COLOR then highlight.OutlineColor = PLAYER_ESP_COLOR end
            end
        else
            if data.box then data.box.Visible = false end
            if data.infoFrame then data.infoFrame.Visible = false end
            if data.highlight then removeESPHighlight(data) end
        end
    end
end

function stopESPLoop()
    S.espEnabled = false
    local cache = S.espPlayerCache
    if not cache then return end
    for _, name in ipairs({"addConn", "remConn", "renderConn"}) do
        local connection = cache[name]
        if connection then pcall(function() connection:Disconnect() end); cache[name] = nil end
    end
    if cache.renderBound then
        pcall(function() RunService:UnbindFromRenderStep(PLAYER_ESP_BIND_NAME) end)
        cache.renderBound = false
    end
    clearESP()
    if cache.screenGui then
        pcall(function() cache.screenGui:Destroy() end)
        cache.screenGui = nil
    end
    cache.infoAccumulator = 0
end

function startESPLoop()
    stopESPLoop()
    S.espEnabled = true
    local cache = S.espPlayerCache
    ensurePlayerESPGui()
    for _, player in ipairs(Players:GetPlayers()) do watchESPPlayer(player) end
    cache.addConn = Players.PlayerAdded:Connect(watchESPPlayer)
    cache.remConn = Players.PlayerRemoving:Connect(removeESPForPlayer)
    local bindOk = pcall(function()
        RunService:BindToRenderStep(PLAYER_ESP_BIND_NAME, Enum.RenderPriority.Camera.Value + 2, updateESP)
    end)
    if bindOk then
        cache.renderBound = true
    else
        cache.renderConn = RunService.RenderStepped:Connect(updateESP)
    end
end

function toggleESP(on)
    if on then startESPLoop() else stopESPLoop() end
end

SWING_COOLDOWN = 0.25
AUTO_BAT_SPEED, AUTO_BAT_VERT_SPEED, AUTO_BAT_DIST, AUTO_BAT_HEIGHT, AUTO_BAT_V_OFF, AUTO_BAT_TURN_SPEED, AUTO_BAT_MAX_TURN_RATE =
    58, 52, 0.15, 0.35, 0.65, 285, 28

