AntiRagdollV2 = {
    Enabled = false,
    Connection = nil,
    ResetCooldown = 0,
}

local function startAntiRagdollV2()
    if AntiRagdollV2.Connection then return end
    AntiRagdollV2.Enabled = true
    AntiRagdollV2.Connection = RunService.Heartbeat:Connect(function()
        if not AntiRagdollV2.Enabled or not S.antiRagdollEnabled then return end
        local character = LP.Character
        if not character then return end
        local humanoid = character:FindFirstChildOfClass("Humanoid")
        local root = character:FindFirstChild("HumanoidRootPart")
        if not humanoid or not root then return end
        if humanoid.Health <= 0 or humanoid:GetState() == Enum.HumanoidStateType.Dead then return end

        local state = humanoid:GetState()
        local now = tick()
        if state == Enum.HumanoidStateType.Physics
            or state == Enum.HumanoidStateType.Ragdoll
            or state == Enum.HumanoidStateType.FallingDown then
            if now - AntiRagdollV2.ResetCooldown > 0.15 then
                AntiRagdollV2.ResetCooldown = now
                -- Disparar el contador antes de que V2 cambie el estado a GettingUp.
                if triggerBatCounter then triggerBatCounter(character) end
                pcall(function()
                    if humanoid:GetState() == Enum.HumanoidStateType.GettingUp then return end
                    if humanoid.Health <= 0 or humanoid:GetState() == Enum.HumanoidStateType.Dead then return end
                    humanoid:ChangeState(Enum.HumanoidStateType.GettingUp)
                    root.Velocity = Vector3.zero
                    root.RotVelocity = Vector3.zero
                    root.AssemblyLinearVelocity = Vector3.zero
                    root.AssemblyAngularVelocity = Vector3.zero
                    for _, obj in ipairs(character:GetDescendants()) do
                        if obj:IsA("Motor6D") then obj.Enabled = true end
                        if obj:IsA("Constraint") then obj.Enabled = true end
                    end
                    local camera = workspace.CurrentCamera
                    if camera then camera.CameraSubject = humanoid end
                    local playerScripts = LP:FindFirstChild("PlayerScripts")
                    local playerModule = playerScripts and playerScripts:FindFirstChild("PlayerModule")
                    local controlModule = playerModule and playerModule:FindFirstChild("ControlModule")
                    if controlModule then
                        local controls = require(controlModule)
                        if controls and controls.Enable then controls:Enable() end
                    end
                    humanoid.AutoRotate = true
                    humanoid.PlatformStand = false
                    humanoid.Sit = false
                end)
            end
        end
    end)
end

local function stopAntiRagdollV2()
    AntiRagdollV2.Enabled = false
    if AntiRagdollV2.Connection then
        AntiRagdollV2.Connection:Disconnect()
        AntiRagdollV2.Connection = nil
    end
    AntiRagdollV2.ResetCooldown = 0
end

startAntiRagdoll = function()
    startAntiRagdollV2()
end

stopAntiRagdoll = function()
    stopAntiRagdollV2()
end

local function toggleAntiRag(on)
    S.antiRagdollEnabled = (on == true)
    if S.antiRagdollEnabled then startAntiRagdoll() else stopAntiRagdoll() end
end

savedAnimate = nil

local function startUnwalk()
    local c = LP.Character
    if not c then return end
    local hum = c:FindFirstChildOfClass("Humanoid")
    if hum then
        for _, t in ipairs(hum:GetPlayingAnimationTracks()) do
            t:Stop()
        end
    end
    local anim = c:FindFirstChild("Animate")
    if anim then
        if not savedAnimate then
            savedAnimate = anim:Clone()
        end
        anim:Destroy()
    end
    S.unwalkEnabled = true
end

local function stopUnwalk()
    if not S.unwalkEnabled then return end
    S.unwalkEnabled = false
    local c = LP.Character
    if c and savedAnimate then
        local existing = c:FindFirstChild("Animate")
        if existing and existing ~= savedAnimate then existing:Destroy() end
        savedAnimate.Parent = c
        savedAnimate.Disabled = false
        savedAnimate = nil
    end
end

POS = S.AP

function stopAutoLeft()
    if S.alConn then S.alConn:Disconnect(); S.alConn = nil end
    S.alPhase = 1
    local c = LP.Character
    if c then
        local hum = c:FindFirstChildOfClass("Humanoid")
        if hum then hum:Move(Vector3.zero, false) end
    end
    if S.autoLeftSetVisual then S.autoLeftSetVisual(false) end
end

function stopAutoRight()
    if S.arConn then S.arConn:Disconnect(); S.arConn = nil end
    S.arPhase = 1
    local c = LP.Character
    if c then
        local hum = c:FindFirstChildOfClass("Humanoid")
        if hum then hum:Move(Vector3.zero, false) end
    end
    if S.autoRightSetVisual then S.autoRightSetVisual(false) end
end

function startAutoLeft()
    if S.alConn then S.alConn:Disconnect() end
    S.alPhase = 1
    S.alConn = RunService.Heartbeat:Connect(function()
        if not S.autoLeftEnabled or S._youtResetInProgress then return end
        local c = LP.Character; if not c then return end
        local root = c:FindFirstChild("HumanoidRootPart")
        local hum = c:FindFirstChildOfClass("Humanoid")
        if not root or not hum or hum.Health <= 0 then return end
        if isSpeedRagdollState(hum) then
            hum:Move(Vector3.zero, false)
            return
        end
        local spd = S.getAutoPathSpeed()
        if S.alPhase == 1 then
            local tgt = Vector3.new(POS.L1.X, root.Position.Y, POS.L1.Z)
            if (tgt - root.Position).Magnitude < 1 then
                S.alPhase = 2
                local d = POS.L2 - root.Position
                local mv = Vector3.new(d.X, 0, d.Z).Unit
                hum:Move(mv, false)
                root.Velocity = Vector3.new(mv.X * spd, root.Velocity.Y, mv.Z * spd)
                return
            end
            local d = POS.L1 - root.Position
            local mv = Vector3.new(d.X, 0, d.Z).Unit
            hum:Move(mv, false)
            root.Velocity = Vector3.new(mv.X * spd, root.Velocity.Y, mv.Z * spd)
        elseif S.alPhase == 2 then
            local tgt = Vector3.new(POS.L2.X, root.Position.Y, POS.L2.Z)
            if (tgt - root.Position).Magnitude < 1 then
                hum:Move(Vector3.zero, false)
                root.Velocity = Vector3.zero
                S.autoLeftEnabled = false
                if S.alConn then S.alConn:Disconnect(); S.alConn = nil end
                S.alPhase = 1
                if S.autoLeftSetVisual then S.autoLeftSetVisual(false) end
                if S._setPButtonActive and S._btnAAL then
                    S._setPButtonActive(S._btnAAL, S._bsAAL, S._l1AAL, S._l2AAL, false)
                end
                task.defer(S.startMovement)
                return
            end
            local d = POS.L2 - root.Position
            local mv = Vector3.new(d.X, 0, d.Z).Unit
            hum:Move(mv, false)
            root.Velocity = Vector3.new(mv.X * spd, root.Velocity.Y, mv.Z * spd)
        end
    end)
end

function startAutoRight()
    if S.arConn then S.arConn:Disconnect() end
    S.arPhase = 1
    S.arConn = RunService.Heartbeat:Connect(function()
        if not S.autoRightEnabled or S._youtResetInProgress then return end
        local c = LP.Character; if not c then return end
        local root = c:FindFirstChild("HumanoidRootPart")
        local hum = c:FindFirstChildOfClass("Humanoid")
        if not root or not hum or hum.Health <= 0 then return end
        if isSpeedRagdollState(hum) then
            hum:Move(Vector3.zero, false)
            return
        end
        local spd = S.getAutoPathSpeed()
        if S.arPhase == 1 then
            local tgt = Vector3.new(POS.R1.X, root.Position.Y, POS.R1.Z)
            if (tgt - root.Position).Magnitude < 1 then
                S.arPhase = 2
                local d = POS.R2 - root.Position
                local mv = Vector3.new(d.X, 0, d.Z).Unit
                hum:Move(mv, false)
                root.Velocity = Vector3.new(mv.X * spd, root.Velocity.Y, mv.Z * spd)
                return
            end
            local d = POS.R1 - root.Position
            local mv = Vector3.new(d.X, 0, d.Z).Unit
            hum:Move(mv, false)
            root.Velocity = Vector3.new(mv.X * spd, root.Velocity.Y, mv.Z * spd)
        elseif S.arPhase == 2 then
            local tgt = Vector3.new(POS.R2.X, root.Position.Y, POS.R2.Z)
            if (tgt - root.Position).Magnitude < 1 then
                hum:Move(Vector3.zero, false)
                root.Velocity = Vector3.zero
                S.autoRightEnabled = false
                if S.arConn then S.arConn:Disconnect(); S.arConn = nil end
                S.arPhase = 1
                if S.autoRightSetVisual then S.autoRightSetVisual(false) end
                if S._setPButtonActive and S._btnAAR then
                    S._setPButtonActive(S._btnAAR, S._bsAAR, S._l1AAR, S._l2AAR, false)
                end
                task.defer(S.startMovement)
                return
            end
            local d = POS.R2 - root.Position
            local mv = Vector3.new(d.X, 0, d.Z).Unit
            hum:Move(mv, false)
            root.Velocity = Vector3.new(mv.X * spd, root.Velocity.Y, mv.Z * spd)
        end
    end)
end

-- Auto Path must never keep steering a new character after any reset/respawn.
LP.CharacterRemoving:Connect(function()
    S.autoLeftEnabled = false
    S.autoRightEnabled = false
    pcall(stopAutoLeft)
    pcall(stopAutoRight)
    if S._setPButtonActive and S._btnAAL then
        pcall(S._setPButtonActive, S._btnAAL, S._bsAAL, S._l1AAL, S._l2AAL, false)
    end
    if S._setPButtonActive and S._btnAAR then
        pcall(S._setPButtonActive, S._btnAAR, S._bsAAR, S._l1AAR, S._l2AAR, false)
    end
    if S.stopMovement then pcall(S.stopMovement) end
end)

-- ==================== NORMAL BAT AIMBOT (replaced with extracted VXYRO / LINX V1) ====================
-- Source logic ported from Aimbot_Normal_Logic_Extracted.lua.
-- Vision UI/state/wiring stays intact; only the aimbot core is replaced.

local _IS_MOBILE = false
pcall(function()
    _IS_MOBILE = game:GetService("UserInputService").TouchEnabled
        and not game:GetService("UserInputService").KeyboardEnabled
end)

local _linxAimbotSpeed = 58
local _linxLaggerAimbotSpeed = 40
local _linxAutoSwingEnabled = true
local _linxAimbotTarget = nil
local _closestCache, _closestCacheAt = nil, 0
_batAimPreviousAutoRotate = nil

local function _linxGetAimbotSpeed()
    return _linxAimbotSpeed
end

local function findAimbotBat(character)
    if not character then return nil end

    local function isBatTool(item)
        if not item or not item:IsA("Tool") then return false end
        local name = string.lower(item.Name)
        return name:find("bat", 1, true) ~= nil or name:find("slap", 1, true) ~= nil
    end

    for _, item in ipairs(character:GetChildren()) do
        if isBatTool(item) then return item end
    end

    local backpack = LP:FindFirstChild("Backpack") or LP:FindFirstChildOfClass("Backpack")
    if backpack then
        for _, item in ipairs(backpack:GetChildren()) do
            if isBatTool(item) then return item end
        end
    end

    return nil
end

local function getClosestAliveRoot()
    local now = os.clock()
    local ttl = _IS_MOBILE and 0.07 or 0.025

    if _closestCache and (now - _closestCacheAt) < ttl then
        if _closestCache.Parent then
            return _closestCache
        end
    end

    local root = LP.Character and LP.Character:FindFirstChild("HumanoidRootPart")
    if not root then return nil end

    local closest, minDist = nil, math.huge
    for _, plr in ipairs(Players:GetPlayers()) do
        if plr ~= LP and plr.Character then
            local targetRoot = plr.Character:FindFirstChild("HumanoidRootPart")
            local hum = plr.Character:FindFirstChildOfClass("Humanoid")
            if targetRoot and hum and hum.Health > 0 then
                local d = (targetRoot.Position - root.Position).Magnitude
                if d < minDist then
                    minDist = d
                    closest = targetRoot
                end
            end
        end
    end

    _closestCache, _closestCacheAt = closest, now
    return closest
end

S.resetAutoBatMotion = function()
    local character = LP.Character
    local root = character and character:FindFirstChild("HumanoidRootPart")
    local humanoid = character and character:FindFirstChildOfClass("Humanoid")

    if root then
        pcall(function()
            root.AssemblyAngularVelocity = Vector3.zero
            root.AssemblyLinearVelocity = Vector3.zero
        end)
    end

    if humanoid then
        pcall(function() humanoid.AutoRotate = true end)
    end

    _batAimPreviousAutoRotate = nil
end

local function disableAutoBat()
    if S.batAimbotConn then
        pcall(function() S.batAimbotConn:Disconnect() end)
        S.batAimbotConn = nil
    end

    S.batAimbotEnabled = false
    S.autoBatEquippedThisRun = false
    S._autoBatTarget = nil
    _linxAimbotTarget = nil
    _closestCache = nil
    _closestCacheAt = 0
    S.resetAutoBatMotion()
end

function startBatAimbot()
    if type(_G.StopAntiBatBypass) == "function" and type(_G.GetAntiBatBypassState) == "function" and _G.GetAntiBatBypassState() then
        pcall(_G.StopAntiBatBypass)
        if S.antiBatAimbotSetVisual then pcall(S.antiBatAimbotSetVisual, false) end
    end
    if S.batAimbotConn then
        pcall(function() S.batAimbotConn:Disconnect() end)
        S.batAimbotConn = nil
    end

    -- Keep Vision's existing exclusivity: TP BAT has priority.
    if S.tpBatEnabled then
        return false
    end

    local char0 = LP.Character
    local hum0 = char0 and char0:FindFirstChildOfClass("Humanoid")
    if hum0 then hum0.AutoRotate = false end

    S.batAimbotEnabled = true
    S.autoBatEquippedThisRun = false
    _linxAimbotTarget = nil
    _closestCache = nil
    _closestCacheAt = 0

    S.batAimbotConn = RunService.RenderStepped:Connect(function()
        if not S.batAimbotEnabled or S.tpBatEnabled then return end

        local char = LP.Character
        if not char then return end

        local root = char:FindFirstChild("HumanoidRootPart")
        local hum = char:FindFirstChildOfClass("Humanoid")
        if not root or not hum or hum.Health <= 0 then return end

        if hum.AutoRotate then
            hum.AutoRotate = false
        end

        local bat = findAimbotBat(char)
        if bat and bat.Parent ~= char then
            pcall(function() hum:EquipTool(bat) end)
        end

        local target = getClosestAliveRoot()
        if not target or not target.Parent then
            _linxAimbotTarget = nil
            root.AssemblyAngularVelocity = Vector3.zero
            if _linxAutoSwingEnabled and bat then
                pcall(function() bat:Activate() end)
            end
            return
        end
        _linxAimbotTarget = target
        S._autoBatTarget = target

        local targetVel = target.AssemblyLinearVelocity
        pcall(function()
            if (not targetVel or targetVel.Magnitude < 0.01) and target.Velocity then
                targetVel = target.Velocity
            end
        end)
        if typeof(targetVel) ~= "Vector3" then
            targetVel = Vector3.zero
        end

        local myPos = root.Position
        local targetPos = target.Position

        local predictPos = targetPos + targetVel * 0.14 + target.CFrame.LookVector * 0.3
        local direction = predictPos - myPos
        local flat = Vector3.new(direction.X, 0, direction.Z)
        local flatDir = (flat.Magnitude > 0.01) and flat.Unit or Vector3.zero

        local chaseSpeed = _linxGetAimbotSpeed()
        local desiredHeight = targetPos.Y + 3.7
        local yVel = (desiredHeight - myPos.Y) * 19.5 + targetVel.Y * 0.8

        if hum.FloorMaterial ~= Enum.Material.Air then
            yVel = math.max(yVel, 13)
        end
        yVel = math.clamp(yVel, -70, 110)

        local desiredVel = Vector3.new(
            flatDir.X * chaseSpeed,
            yVel,
            flatDir.Z * chaseSpeed
        )

        root.AssemblyLinearVelocity = root.AssemblyLinearVelocity:Lerp(desiredVel, 0.8)
        pcall(function() root.Velocity = root.AssemblyLinearVelocity end)

        local speed3 = targetVel.Magnitude
        local predictTime = math.clamp(speed3 / 150, 0.05, 0.2)
        local predictedPos = targetPos + targetVel * predictTime

        if (predictedPos - myPos).Magnitude > 0.1 then
            local goalCF = CFrame.lookAt(myPos, predictedPos)
            local diffCF = root.CFrame:Inverse() * goalCF
            local rx, ry, rz = diffCF:ToEulerAnglesXYZ()
            rx = math.clamp(rx, -2.5, 2.5)
            ry = math.clamp(ry, -2.5, 2.5)
            rz = math.clamp(rz, -2.5, 2.5)
            root.AssemblyAngularVelocity = root.CFrame:VectorToWorldSpace(
                Vector3.new(rx * 42, ry * 42, rz * 42)
            )
        else
            root.AssemblyAngularVelocity = Vector3.zero
        end

        if _linxAutoSwingEnabled and bat then
            pcall(function() bat:Activate() end)
        end
    end)

    return true
end

function stopBatAimbot()
    disableAutoBat()
end

-- ==================== ANTI BAT AIMBOT LOGIC (ported from extracted file) ====================
-- Core movement / target / swing behavior is kept from the supplied
-- Anti_Bat_Aimbot_Logic_Extracted.lua. Only the Vision UI/state hooks are added.

local antiBatBypassEnabled = false
local aimbotSpeedValue = 55

_G.AceAntiBypassAimbot = _G.AceAntiBypassAimbot or {
    conn = nil,
    swingCooldown = false,
    prevAutoRotate = nil,
}

_G.AceAntiBypassSlapList = _G.AceAntiBypassSlapList or {
    "Bat","Slap","Iron Slap","Gold Slap","Diamond Slap","Emerald Slap",
    "Ruby Slap","Dark Matter Slap","Flame Slap","Nuclear Slap",
    "Galaxy Slap","Glitched Slap"
}

-- Prevent an old connection from surviving a script re-execute.
if _G.AceAntiBypassAimbot.conn then
    pcall(function() _G.AceAntiBypassAimbot.conn:Disconnect() end)
    _G.AceAntiBypassAimbot.conn = nil
end

function _G.AceAntiBypassFindBat()
    local char = LP.Character
    if not char then return nil end

    for _, name in ipairs(_G.AceAntiBypassSlapList) do
        local t = char:FindFirstChild(name)
        if t and t:IsA("Tool") then return t end
    end

    local bp = LP:FindFirstChildOfClass("Backpack")
    if bp then
        for _, name in ipairs(_G.AceAntiBypassSlapList) do
            local t = bp:FindFirstChild(name)
            if t and t:IsA("Tool") then
                local hum = char:FindFirstChildOfClass("Humanoid")
                if hum then pcall(function() hum:EquipTool(t) end) end
                return t
            end
        end
    end

    for _, ch in ipairs(char:GetChildren()) do
        if ch:IsA("Tool") then
            local n = ch.Name:lower()
            if n:find("bat", 1, true) or n:find("slap", 1, true) then
                return ch
            end
        end
    end

    return nil
end

function _G.AceAntiBypassTrySwing()
    if _G.AceAntiBypassAimbot.swingCooldown then return end
    _G.AceAntiBypassAimbot.swingCooldown = true

    pcall(function()
        local char = LP.Character
        if not char then return end

        local tool = char:FindFirstChildOfClass("Tool") or _G.AceAntiBypassFindBat()
        if tool then
            if tool.Parent ~= char then
                local hum = char:FindFirstChildOfClass("Humanoid")
                if hum then pcall(function() hum:EquipTool(tool) end) end
            end
            pcall(function() tool:Activate() end)
        end
    end)

    task.delay(0.35, function()
        if _G.AceAntiBypassAimbot then
            _G.AceAntiBypassAimbot.swingCooldown = false
        end
    end)
end

function _G.AceAntiBypassGetClosest()
    local root = LP.Character and LP.Character:FindFirstChild("HumanoidRootPart")
    if not root then return nil, math.huge end

    local closest, minDist = nil, math.huge
    for _, plr in ipairs(Players:GetPlayers()) do
        if plr ~= LP and plr.Character then
            local tRoot = plr.Character:FindFirstChild("HumanoidRootPart")
            local hum = plr.Character:FindFirstChildOfClass("Humanoid")
            if tRoot and hum and hum.Health > 0 then
                local dist = (tRoot.Position - root.Position).Magnitude
                if dist < minDist then
                    minDist = dist
                    closest = tRoot
                end
            end
        end
    end

    return closest, minDist
end

local function startAntiBatBypass()
    if _G.AceAntiBypassAimbot.conn then
        pcall(function() _G.AceAntiBypassAimbot.conn:Disconnect() end)
        _G.AceAntiBypassAimbot.conn = nil
    end

    local hum0 = LP.Character and LP.Character:FindFirstChildOfClass("Humanoid")
    if hum0 then
        if _G.AceAntiBypassAimbot.prevAutoRotate == nil then
            _G.AceAntiBypassAimbot.prevAutoRotate = hum0.AutoRotate
        end
        hum0.AutoRotate = false
    end

    antiBatBypassEnabled = true
    S.antiBatAimbotEnabled = true

    _G.AceAntiBypassAimbot.conn = RunService.Heartbeat:Connect(function()
        if not antiBatBypassEnabled then return end

        local char = LP.Character
        if not char then return end

        local root = char:FindFirstChild("HumanoidRootPart")
        local hum = char:FindFirstChildOfClass("Humanoid")
        if not root or not hum then return end

        if not char:FindFirstChildOfClass("Tool") then
            local bat = _G.AceAntiBypassFindBat()
            if bat then pcall(function() hum:EquipTool(bat) end) end
        end

        local targetRoot = _G.AceAntiBypassGetClosest()
        if not targetRoot then
            root.AssemblyLinearVelocity = root.AssemblyLinearVelocity * 0.9
            if root.AssemblyLinearVelocity.Magnitude < 1 then
                root.AssemblyLinearVelocity = Vector3.zero
            end
            return
        end

        local targetVel = targetRoot.AssemblyLinearVelocity
        local moveDir = targetVel.Magnitude > 0.1
            and targetVel.Unit
            or targetRoot.CFrame.LookVector

        local offset = moveDir * 1.0 + Vector3.new(0, 1.5, 0)
        local desiredPos = targetRoot.Position + offset
        local toTarget = desiredPos - root.Position

        if toTarget.Magnitude > 0.5 then
            local moveVec = toTarget.Unit * aimbotSpeedValue
            root.AssemblyLinearVelocity = Vector3.new(moveVec.X, moveVec.Y, moveVec.Z)
        else
            root.AssemblyLinearVelocity = root.AssemblyLinearVelocity * 0.95
            if root.AssemblyLinearVelocity.Magnitude < 1 then
                root.AssemblyLinearVelocity = Vector3.zero
            end
        end

        local distToTarget = (root.Position - targetRoot.Position).Magnitude
        if distToTarget <= 4.5 then
            _G.AceAntiBypassTrySwing()
        end
    end)

    return true
end

local function stopAntiBatBypass()
    antiBatBypassEnabled = false
    S.antiBatAimbotEnabled = false

    if _G.AceAntiBypassAimbot.conn then
        pcall(function() _G.AceAntiBypassAimbot.conn:Disconnect() end)
        _G.AceAntiBypassAimbot.conn = nil
    end

    _G.AceAntiBypassAimbot.swingCooldown = false

    local char = LP.Character
    local root = char and char:FindFirstChild("HumanoidRootPart")
    if root then
        root.AssemblyLinearVelocity = Vector3.zero
        root.AssemblyAngularVelocity = Vector3.zero
    end

    local hum = char and char:FindFirstChildOfClass("Humanoid")
    if hum then
        hum.AutoRotate = (_G.AceAntiBypassAimbot.prevAutoRotate == nil)
            and true
            or _G.AceAntiBypassAimbot.prevAutoRotate
        hum.PlatformStand = false
        pcall(function() hum:ChangeState(Enum.HumanoidStateType.GettingUp) end)
    end

    _G.AceAntiBypassAimbot.prevAutoRotate = nil
    return true
end

local _antiBatToggleDebounce = 0
local function toggleAntiBatBypass()
    local now = tick()
    if _antiBatToggleDebounce > 0 and _antiBatToggleDebounce + 0.15 > now then
        return antiBatBypassEnabled == true
    end
    _antiBatToggleDebounce = now

    antiBatBypassEnabled = not antiBatBypassEnabled
    if antiBatBypassEnabled then
        local ok, result = pcall(startAntiBatBypass)
        if not ok or result == false then
            antiBatBypassEnabled = false
            S.antiBatAimbotEnabled = false
            return false
        end
    else
        stopAntiBatBypass()
    end

    if S.antiBatAimbotSetVisual then
        pcall(S.antiBatAimbotSetVisual, antiBatBypassEnabled)
    end
    return antiBatBypassEnabled == true
end

_G.StartAntiBatBypass = startAntiBatBypass
_G.StopAntiBatBypass = stopAntiBatBypass
_G.ToggleAntiBatBypass = toggleAntiBatBypass
_G.GetAntiBatBypassState = function()
    return antiBatBypassEnabled == true
end
_G.SetAntiBatBypassSpeed = function(speed)
    aimbotSpeedValue = tonumber(speed) or 55
    _G.AceAntiBypassAimbotSpeed = aimbotSpeedValue
end
_G.AceAntiBypassAimbotSpeed = aimbotSpeedValue

-- ==================== TP BAT LOGIC (ported from MVP TP BAT) ====================
-- The original Vision TP BAT implementation is replaced here by the MVP TP BAT
-- movement/targeting/hit flow while keeping Vision's existing UI/wiring intact.

local tpBatHitCooldown = false
local TP_BAT_HIT_DELAY = 0.075 -- MVP default behavior (batSpeed 40)
local TP_BAT_MAX_DISTANCE = 100

local function isTpBatTool(tool)
    if not tool or not tool:IsA("Tool") then return false end
    local name = string.lower(tool.Name)
    return name == "bat"
        or name:find("bat", 1, true) ~= nil
        or name:find("slap", 1, true) ~= nil
end

local function getTpBatToolMVP()
    local character = LP.Character
    if not character then return nil end

    local humanoid = character:FindFirstChildOfClass("Humanoid")

    -- Already equipped.
    for _, child in ipairs(character:GetChildren()) do
        if isTpBatTool(child) then
            return child
        end
    end

    -- Backpack -> equip.
    local backpack = LP:FindFirstChildOfClass("Backpack") or LP:FindFirstChild("Backpack")
    if backpack then
        for _, child in ipairs(backpack:GetChildren()) do
            if isTpBatTool(child) then
                if humanoid then
                    pcall(function() humanoid:EquipTool(child) end)
                else
                    pcall(function() child.Parent = character end)
                end
                return child
            end
        end
    end

    return nil
end

-- MVP hit flow: Activate + every RemoteEvent in the bat, then the first RemoteEvent.
local function tryTpBatHitMVP()
    if tpBatHitCooldown then return end
    tpBatHitCooldown = true

    pcall(function()
        local bat = getTpBatToolMVP()
        if not bat then return end

        pcall(function() bat:Activate() end)

        for _, descendant in ipairs(bat:GetDescendants()) do
            if descendant:IsA("RemoteEvent") then
                pcall(function() descendant:FireServer() end)
            end
        end

        local event = bat:FindFirstChildWhichIsA("RemoteEvent")
        if event then
            pcall(function() event:FireServer() end)
        end
    end)

    task.delay(TP_BAT_HIT_DELAY, function()
        tpBatHitCooldown = false
    end)
end

local function getTpBatClosestMVP(root)
    if not root or not root.Parent then
        return nil, math.huge
    end

    local best, bestDistance = nil, math.huge

    for _, player in ipairs(Players:GetPlayers()) do
        if player ~= LP and player.Character then
            local humanoid = player.Character:FindFirstChildOfClass("Humanoid")
            local targetRoot = player.Character:FindFirstChild("HumanoidRootPart")

            if humanoid and humanoid.Health > 0 and targetRoot and targetRoot.Parent then
                local distance = (root.Position - targetRoot.Position).Magnitude
                if distance < bestDistance then
                    bestDistance = distance
                    best = player
                end
            end
        end
    end

    return best, bestDistance
end

local function tpBatMVPHeartbeat()
    if not S.tpBatEnabled then return end

    local character = LP.Character
    if not character then return end

    local root = character:FindFirstChild("HumanoidRootPart")
    local humanoid = character:FindFirstChildOfClass("Humanoid")
    if not root or not humanoid or humanoid.Health <= 0 then return end

    -- MVP logic: stop currently playing character animations while TP BAT is active.
    local animator = humanoid:FindFirstChildOfClass("Animator")
    if animator then
        pcall(function()
            for _, track in ipairs(animator:GetPlayingAnimationTracks()) do
                track:Stop()
            end
        end)
    end

    local bat = getTpBatToolMVP()
    if bat and bat.Parent ~= character then
        pcall(function() humanoid:EquipTool(bat) end)
    end

    local target, distance = getTpBatClosestMVP(root)
    if not target or distance > TP_BAT_MAX_DISTANCE then return end

    local targetRoot = target.Character and target.Character:FindFirstChild("HumanoidRootPart")
    if not targetRoot then return end

    -- Preserve the MVP hidden root replication step when the executor exposes it.
    if type(sethiddenproperty) == "function" then
        pcall(function()
            sethiddenproperty(root, "PhysicsRepRootPart", targetRoot)
        end)
    end

    local targetPos = targetRoot.Position + Vector3.new(0, 0.9, 0)

    if distance > 4 then
        root.CFrame = CFrame.new(targetPos, targetRoot.Position)
    elseif distance > 1.5 then
        root.CFrame = CFrame.new(root.Position:Lerp(targetPos, 0.55), targetRoot.Position)
    else
        root.CFrame = CFrame.new(targetPos, targetRoot.Position)
    end

    pcall(function()
        root.AssemblyAngularVelocity = Vector3.zero
    end)

    -- MVP camera behavior: follow the target while TP BAT is active.
    local camera = workspace.CurrentCamera
    if camera then
        camera.CFrame = CFrame.new(camera.CFrame.Position, targetRoot.Position + Vector3.new(0, 0.5, 0))
    end

    -- MVP V1 behavior: hit automatically on the heartbeat loop.
    tryTpBatHitMVP()
end

-- ==================== TP BAT ZERO MODE (V2) ====================
-- Integrated from TP_Bat_V1_Zero_Logic.lua and controlled by Vision's existing
-- TP BAT button/keybind. Only one mode is active at a time.
local TP_BAT_MODE_VISION = "V1"
local TP_BAT_MODE_ZERO = "V2"
local TP_BAT_MODE_ORBIT = "V3"
if S.tpBatMode ~= TP_BAT_MODE_ZERO and S.tpBatMode ~= TP_BAT_MODE_ORBIT then
    S.tpBatMode = TP_BAT_MODE_VISION
end

local zeroTpBatConfig = {
    range = 250,
    tpOffset = Vector3.new(0, 0, 0),
    loopDelay = 0.08,
    smartRotation = true,
    resetVelocity = true,
    predictMovement = true,
    predictionFactor = 0.15,
    healthCheck = true,
    teamCheck = false,
    behindTarget = false,
    behindDistance = 4,
    antiFling = true,
    sideOffset = 2.5,
}
local zeroTpBatRuntime = {
    enabled = false,
    thread = nil,
    hitCooldown = false,
    hrp = nil,
    humanoid = nil,
}

local function updateZeroTpBatCharacter()
    local character = LP.Character
    if not character then
        zeroTpBatRuntime.hrp = nil
        zeroTpBatRuntime.humanoid = nil
        return
    end
    zeroTpBatRuntime.hrp = character:FindFirstChild("HumanoidRootPart")
    zeroTpBatRuntime.humanoid = character:FindFirstChildOfClass("Humanoid")
end

local function getZeroTpBatTool()
    local character = LP.Character
    if not character then return nil end

    local tool = character:FindFirstChild("Bat")
    if tool and tool:IsA("Tool") then return tool end
    for _, child in ipairs(character:GetChildren()) do
        if child:IsA("Tool") then
            local name = string.lower(child.Name)
            if name:find("bat", 1, true) or name:find("slap", 1, true) then
                return child
            end
        end
    end

    local backpack = LP:FindFirstChild("Backpack") or LP:FindFirstChildOfClass("Backpack")
    if backpack then
        tool = backpack:FindFirstChild("Bat")
        if tool and tool:IsA("Tool") then
            pcall(function()
                local humanoid = character:FindFirstChildOfClass("Humanoid")
                if humanoid then humanoid:EquipTool(tool) end
            end)
            return tool
        end
        for _, child in ipairs(backpack:GetChildren()) do
            if child:IsA("Tool") then
                local name = string.lower(child.Name)
                if name:find("bat", 1, true) or name:find("slap", 1, true) then
                    pcall(function() child.Parent = character end)
                    return child
                end
            end
        end
    end
    return nil
end

local function tryZeroTpBatHit()
    if zeroTpBatRuntime.hitCooldown then return end
    zeroTpBatRuntime.hitCooldown = true
    pcall(function()
        local bat = getZeroTpBatTool()
        if bat then
            pcall(function() bat:Activate() end)
            local remoteEvent = bat:FindFirstChildWhichIsA("RemoteEvent")
            if remoteEvent then pcall(function() remoteEvent:FireServer() end) end
        end
    end)
    task.delay(0.08, function() zeroTpBatRuntime.hitCooldown = false end)
end

local function isValidZeroTpBatTarget(player)
    if player == LP or not player.Character then return false end
    local humanoid = player.Character:FindFirstChildOfClass("Humanoid")
    if not humanoid then return false end
    if zeroTpBatConfig.healthCheck and humanoid.Health <= 0 then return false end
    if zeroTpBatConfig.teamCheck and player.Team == LP.Team and player.Team ~= nil then return false end
    local root = player.Character:FindFirstChild("HumanoidRootPart")
    if not root then return false end
    return true, root, humanoid
end

local function findNearestZeroTpBatTarget()
    local myRoot = zeroTpBatRuntime.hrp or (LP.Character and LP.Character:FindFirstChild("HumanoidRootPart"))
    if not myRoot then return nil end
    local nearest, shortest = nil, tonumber(zeroTpBatConfig.range) or 250
    for _, player in ipairs(Players:GetPlayers()) do
        local valid, root = isValidZeroTpBatTarget(player)
        if valid then
            local distance = (root.Position - myRoot.Position).Magnitude
            if distance < shortest then shortest, nearest = distance, root end
        end
    end
    return nearest
end

local function teleportZeroTpBatToTarget(targetRoot)
    if not targetRoot or not targetRoot.Parent then return end
    local myRoot = zeroTpBatRuntime.hrp or (LP.Character and LP.Character:FindFirstChild("HumanoidRootPart"))
    local myHumanoid = zeroTpBatRuntime.humanoid or (LP.Character and LP.Character:FindFirstChildOfClass("Humanoid"))
    if not myRoot then return end

    local targetPosition = targetRoot.Position
    if zeroTpBatConfig.predictMovement then
        targetPosition = targetPosition + targetRoot.AssemblyLinearVelocity * zeroTpBatConfig.predictionFactor
    end

    local finalPosition
    if zeroTpBatConfig.behindTarget then
        local delta = targetPosition - myRoot.Position
        local direction = delta.Magnitude > 0.001 and delta.Unit or Vector3.new(0, 0, 1)
        finalPosition = targetPosition - direction * zeroTpBatConfig.behindDistance + Vector3.new(0, 2, 0)
    elseif (tonumber(zeroTpBatConfig.sideOffset) or 0) > 0 then
        local direction = myRoot.Position - targetPosition
        direction = Vector3.new(direction.X, 0, direction.Z)
        if direction.Magnitude < 0.1 then
            direction = Vector3.new(1, 0, 0)
        else
            direction = direction.Unit
        end
        finalPosition = targetPosition + direction * zeroTpBatConfig.sideOffset
    else
        finalPosition = targetPosition + zeroTpBatConfig.tpOffset
    end

    if zeroTpBatConfig.smartRotation then
        myRoot.CFrame = CFrame.new(finalPosition, targetPosition)
    else
        myRoot.CFrame = CFrame.new(finalPosition)
    end

    if zeroTpBatConfig.resetVelocity then
        pcall(function()
            myRoot.Velocity = Vector3.zero
            myRoot.AssemblyLinearVelocity = Vector3.zero
            myRoot.RotVelocity = Vector3.zero
            myRoot.AssemblyAngularVelocity = Vector3.zero
        end)
    end
    if zeroTpBatConfig.antiFling and myHumanoid then
        pcall(function()
            myHumanoid.PlatformStand = false
            myHumanoid.Sit = false
        end)
    end
end

local function stopZeroTpBat()
    local wasActive = zeroTpBatRuntime.enabled or zeroTpBatRuntime.thread ~= nil
    zeroTpBatRuntime.enabled = false
    local thread = zeroTpBatRuntime.thread
    zeroTpBatRuntime.thread = nil
    if thread then pcall(function() task.cancel(thread) end) end
    zeroTpBatRuntime.hitCooldown = false
    if wasActive then
        local character = LP.Character
        local root = character and character:FindFirstChild("HumanoidRootPart")
        if root then
            pcall(function()
                root.AssemblyAngularVelocity = Vector3.zero
                root.AssemblyLinearVelocity = Vector3.zero
            end)
        end
        local humanoid = character and character:FindFirstChildOfClass("Humanoid")
        if humanoid then pcall(function() humanoid.AutoRotate = true end) end
    end
    updateZeroTpBatCharacter()
end

local function startZeroTpBat()
    if zeroTpBatRuntime.enabled then return true end
    zeroTpBatRuntime.enabled = true
    updateZeroTpBatCharacter()
    zeroTpBatRuntime.thread = task.spawn(function()
        while zeroTpBatRuntime.enabled and S.tpBatEnabled and S.tpBatMode == TP_BAT_MODE_ZERO do
            updateZeroTpBatCharacter()
            local target = findNearestZeroTpBatTarget()
            if target then
                teleportZeroTpBatToTarget(target)
                tryZeroTpBatHit()
            end
            task.wait(math.max(0.02, tonumber(zeroTpBatConfig.loopDelay) or 0.08))
        end
        zeroTpBatRuntime.enabled = false
        zeroTpBatRuntime.thread = nil
    end)
    return true
end

-- ==================== TP BAT MODE V3 (orbit logic from TP_Bat_V2_Logic.lua) ====================
-- Adapted to SC Vision's existing TP Bat selector/toggle. No standalone GUI is created.
local orbitTpBatConfig = {
    orbitRadius = 3.5,
    orbitHeight = 0.5,
    orbitSpeed = 1.5,
    swingCooldown = 0.08,
    resetVelocity = true,
    equipTool = true,
}
local orbitTpBatRuntime = {
    enabled = false,
    connection = nil,
    angle = 0,
    toolCooldown = false,
}

local function findOrbitTpBatTool()
    local character = LP.Character
    if not character then return nil end

    for _, child in ipairs(character:GetChildren()) do
        if child:IsA("Tool") then
            local name = string.lower(child.Name)
            if name:find("bat", 1, true) or name:find("tp", 1, true) then
                return child
            end
        end
    end

    local backpack = LP:FindFirstChild("Backpack") or LP:FindFirstChildOfClass("Backpack")
    if backpack then
        for _, child in ipairs(backpack:GetChildren()) do
            if child:IsA("Tool") then
                local name = string.lower(child.Name)
                if name:find("bat", 1, true) or name:find("tp", 1, true) then
                    return child
                end
            end
        end
    end
    return nil
end

local function findNearestOrbitTpBatTarget(myRoot)
    if not myRoot then return nil end
    local closestDistance, chosenRoot = math.huge, nil
    for _, player in ipairs(Players:GetPlayers()) do
        if player ~= LP and player.Character then
            local targetCharacter = player.Character
            local targetRoot = targetCharacter:FindFirstChild("HumanoidRootPart")
            local targetHumanoid = targetCharacter:FindFirstChildOfClass("Humanoid")
            if targetRoot and targetHumanoid and targetHumanoid.Health > 0 then
                local distance = (targetRoot.Position - myRoot.Position).Magnitude
                if distance < closestDistance then
                    closestDistance, chosenRoot = distance, targetRoot
                end
            end
        end
    end
    return chosenRoot
end

local function activateOrbitTpBatTool(tool)
    if orbitTpBatRuntime.toolCooldown or not tool or not tool.Parent then return end
    orbitTpBatRuntime.toolCooldown = true
    pcall(function() tool:Activate() end)
    task.delay(math.max(0.03, tonumber(orbitTpBatConfig.swingCooldown) or 0.08), function()
        orbitTpBatRuntime.toolCooldown = false
    end)
end

local function orbitTpBatHeartbeat(deltaTime)
    if not orbitTpBatRuntime.enabled or not S.tpBatEnabled or S.tpBatMode ~= TP_BAT_MODE_ORBIT then
        return
    end
    local character = LP.Character
    if not character then return end
    local root = character:FindFirstChild("HumanoidRootPart")
    local humanoid = character:FindFirstChildOfClass("Humanoid")
    if not root or not humanoid or humanoid.Health <= 0 then return end

    local tool = character:FindFirstChildOfClass("Tool") or findOrbitTpBatTool()
    if tool and orbitTpBatConfig.equipTool and tool.Parent ~= character then
        pcall(function() humanoid:EquipTool(tool) end)
    end

    local targetRoot = findNearestOrbitTpBatTarget(root)
    if not targetRoot or not targetRoot.Parent then return end

    orbitTpBatRuntime.angle = orbitTpBatRuntime.angle + (tonumber(orbitTpBatConfig.orbitSpeed) or 1.5) * (deltaTime or 0)
    if orbitTpBatRuntime.angle > math.pi * 2 then
        orbitTpBatRuntime.angle = orbitTpBatRuntime.angle - math.pi * 2
    end

    local targetPosition = targetRoot.Position
    local radius = math.max(0, tonumber(orbitTpBatConfig.orbitRadius) or 3.5)
    local height = tonumber(orbitTpBatConfig.orbitHeight) or 0.5
    local orbitPosition = Vector3.new(
        targetPosition.X + math.cos(orbitTpBatRuntime.angle) * radius,
        targetPosition.Y + height,
        targetPosition.Z + math.sin(orbitTpBatRuntime.angle) * radius
    )
    local lookAt = Vector3.new(targetPosition.X, orbitPosition.Y, targetPosition.Z)

    pcall(function()
        root.CFrame = CFrame.lookAt(orbitPosition, lookAt)
        if orbitTpBatConfig.resetVelocity then
            root.AssemblyLinearVelocity = Vector3.zero
            root.AssemblyAngularVelocity = Vector3.zero
        end
        root.CFrame = CFrame.lookAt(
            root.Position,
            Vector3.new(targetPosition.X, root.Position.Y, targetPosition.Z)
        )
    end)

    if tool then activateOrbitTpBatTool(tool) end
end

local function stopOrbitTpBat()
    orbitTpBatRuntime.enabled = false
    if orbitTpBatRuntime.connection then
        pcall(function() orbitTpBatRuntime.connection:Disconnect() end)
        orbitTpBatRuntime.connection = nil
    end
    orbitTpBatRuntime.toolCooldown = false
    orbitTpBatRuntime.angle = 0
    local character = LP.Character
    local root = character and character:FindFirstChild("HumanoidRootPart")
    if root and orbitTpBatConfig.resetVelocity then
        pcall(function()
            root.AssemblyLinearVelocity = Vector3.zero
            root.AssemblyAngularVelocity = Vector3.zero
        end)
    end
end

local function startOrbitTpBat()
    if orbitTpBatRuntime.enabled and orbitTpBatRuntime.connection then return true end
    if orbitTpBatRuntime.connection then
        pcall(function() orbitTpBatRuntime.connection:Disconnect() end)
        orbitTpBatRuntime.connection = nil
    end
    orbitTpBatRuntime.enabled = true
    orbitTpBatRuntime.angle = 0
    orbitTpBatRuntime.toolCooldown = false
    orbitTpBatRuntime.connection = RunService.Heartbeat:Connect(orbitTpBatHeartbeat)
    return true
end

local function setTpBat(state)
    local enabled = state == true
    S.tpBatEnabled = enabled
    S.batTpEnabled = enabled
    S._smartBatTpDriving = enabled

    -- Stop/disconnect every prior mode before starting the selected one.
    if S.tpBatConn then
        pcall(function() S.tpBatConn:Disconnect() end)
        S.tpBatConn = nil
    end
    stopZeroTpBat()
    stopOrbitTpBat()

    if enabled then
        if S.tpBatMode == TP_BAT_MODE_ZERO then
            startZeroTpBat()
        elseif S.tpBatMode == TP_BAT_MODE_ORBIT then
            startOrbitTpBat()
        else
            S.tpBatMode = TP_BAT_MODE_VISION
            if S.tpBatModeSelectorLabel then S.tpBatModeSelectorLabel.Text = S.tpBatMode end
            S.tpBatConn = RunService.Heartbeat:Connect(tpBatMVPHeartbeat)
        end
    else
        tpBatHitCooldown = false

        -- Return replication ownership to the local player when the feature is off.
        local character = LP.Character
        local root = character and character:FindFirstChild("HumanoidRootPart")
        if root and type(root.SetNetworkOwner) == "function" then
            pcall(function() root:SetNetworkOwner(LP) end)
        end
    end
end

LP.CharacterAdded:Connect(function(character)
    if S.tpBatEnabled then
        -- The MVP heartbeat logic reacquires the new character automatically.
        task.wait(0.1)
    end
end)

setBatAimbot = function(state)
    state = state == true
    if state and S.tpBatEnabled then
        return false
    end
    if S.batAimbotEnabled == state then return true end
    S.batAimbotEnabled = state
    if state then
        local started = startBatAimbot()
        if started == false then
            S.batAimbotEnabled = false
            return false
        end
    else
        stopBatAimbot()
    end
    if S.batAimbotSetVisual then S.batAimbotSetVisual(state) end
    if S._setPButtonActive and S._btnBAT then
        S._setPButtonActive(S._btnBAT, S._bsBAT, S._l1BAT, S._l2BAT, state)
    end
    S.restartMovement()
    saveConfig()
end

BAT_COUNTER_SLAP_LIST = {
    "Bat", "Slap", "Iron Slap", "Gold Slap", "Diamond Slap",
    "Emerald Slap", "Ruby Slap", "Dark Matter Slap", "Flame Slap",
    "Nuclear Slap", "Galaxy Slap", "Glitched Slap",
}

local function findBatForCounter()
    local character = LP.Character
    if not character then return nil end
    local backpack = LP:FindFirstChildOfClass("Backpack")
    for _, name in ipairs(BAT_COUNTER_SLAP_LIST) do
        local tool = character:FindFirstChild(name) or (backpack and backpack:FindFirstChild(name))
        if tool then return tool end
    end
    for _, child in ipairs(character:GetChildren()) do
        if child:IsA("Tool") and (child.Name:lower():find("bat") or child.Name:lower():find("slap")) then
            return child
        end
    end
    if backpack then
        for _, child in ipairs(backpack:GetChildren()) do
            if child:IsA("Tool") and (child.Name:lower():find("bat") or child.Name:lower():find("slap")) then
                return child
            end
        end
    end
    return nil
end

local function swingBatForCounter(bat, character)
    if not bat or not character then return end
    local humanoid = character:FindFirstChildOfClass("Humanoid")
    if bat.Parent ~= character and humanoid then
        pcall(function() humanoid:EquipTool(bat) end)
        task.wait(0.05)
    end
    local remote = bat:FindFirstChildOfClass("RemoteEvent") or bat:FindFirstChildOfClass("RemoteFunction")
    if remote and remote:IsA("RemoteEvent") then
        pcall(function() remote:FireServer() end)
        task.wait(0.1)
        pcall(function() remote:FireServer() end)
    else
        pcall(function() bat:Activate() end)
        task.wait(0.1)
        pcall(function() bat:Activate() end)
    end
end

triggerBatCounter = function(character)
    if not S.batCounterEnabled or S.batCounterDebounce then return end
    character = character or LP.Character
    if not character then return end
    S.batCounterDebounce = true
    -- Clean integra estos hooks con body-lock; se usan solo si están disponibles.
    if type(_suppressBodyLock) == "function" then pcall(_suppressBodyLock) end
    task.spawn(function()
        task.wait(0.15)
        local ok, err = pcall(function()
            local bat = findBatForCounter()
            if bat then swingBatForCounter(bat, character) end
        end)
        if not ok then warn("[Vision] Bat Counter error: " .. tostring(err)) end
        task.wait(0.3)
        S.batCounterDebounce = false
        if type(_unsuppressBodyLock) == "function" then pcall(_unsuppressBodyLock, true) end
    end)
end

stopBatCounter = function()
    if S.batCounterConn then
        S.batCounterConn:Disconnect()
        S.batCounterConn = nil
    end
    S.batCounterDebounce = false
end

startBatCounter = function()
    if S.batCounterConn then return end
    S.batCounterConn = RunService.Heartbeat:Connect(function()
        if not S.batCounterEnabled or S.batCounterDebounce then return end
        local character = LP.Character
        if not character then return end
        local humanoid = character:FindFirstChildOfClass("Humanoid")
        if not humanoid then return end
        local state = humanoid:GetState()
        if state == Enum.HumanoidStateType.Physics
            or state == Enum.HumanoidStateType.Ragdoll
            or state == Enum.HumanoidStateType.FallingDown then
            triggerBatCounter(character)
        end
    end)
end

-- Bat Counter V2 imported logic (independent toggle, reuses Vision TP BAT adapter).
local startBatCounterV2, stopBatCounterV2
S.batCounterV2Enabled = S.batCounterV2Enabled == true
S.batCounterV2Debounce = false
S.batCounterV2Conn = nil
S.batCounterV2HitCooldown = false
local BAT_COUNTER_V2_SWING_CD = 0.08
S.setBatCounterV2Visual = nil

S._batCounterV2OriginalTpState = false
S._batCounterV2SuppressCount = 0
S._lastBatCounterV2Time = 0
S._batCounterV2Cooldown = 0.01

local function isPlayerRagdolledV2(player)
    if not player or not player.Character then return false end
    local hum = player.Character:FindFirstChildOfClass("Humanoid")
    if not hum then return false end
    local state = hum:GetState()
    return state == Enum.HumanoidStateType.Physics or state == Enum.HumanoidStateType.Ragdoll or state == Enum.HumanoidStateType.FallingDown
end

local function hasAnimalEquippedV2(player)
    if not player or not player.Character then return false end
    for _, child in ipairs(player.Character:GetChildren()) do
        if child:IsA("Tool") then
            if child:FindFirstChild("Handle") or child.Name:find("Animal") or child.Name:find("Pet") then return true end
        end
    end
    return false
end

local function getAttackingPlayerWithAnimalV2()
    local myChar = LP.Character
    if not myChar then return nil end
    local myRoot = myChar:FindFirstChild("HumanoidRootPart")
    if not myRoot then return nil end
    local closest, minDist = nil, math.huge
    for _, plr in ipairs(Players:GetPlayers()) do
        if plr ~= LP and plr.Character then
            if not hasAnimalEquippedV2(plr) then continue end
            local tRoot = plr.Character:FindFirstChild("HumanoidRootPart")
            local hum = plr.Character:FindFirstChildOfClass("Humanoid")
            if tRoot and hum and hum.Health > 0 then
                local dist = (tRoot.Position - myRoot.Position).Magnitude
                if dist < 12 and dist < minDist then
                    minDist = dist; closest = plr
                end
            end
        end
    end
    return closest
end

local function getBatV2Counter()
    local char = LP.Character
    if not char then return nil end
    for _, child in ipairs(char:GetChildren()) do
        if child:IsA("Tool") then
            local name = child.Name:lower()
            if name:find("bat") or name:find("slap") or name:find("sword") or name:find("knife") then return child end
        end
    end
    local bp = LP:FindFirstChild("Backpack")
    if bp then
        for _, child in ipairs(bp:GetChildren()) do
            if child:IsA("Tool") then
                local name = child.Name:lower()
                if name:find("bat") or name:find("slap") or name:find("sword") or name:find("knife") then
                    child.Parent = char
                    return child
                end
            end
        end
    end
    if bp then
        for _, child in ipairs(bp:GetChildren()) do
            if child:IsA("Tool") then child.Parent = char; return child end
        end
    end
    return nil
end

local function tryHitBatCounterV2()
    if S.batCounterV2HitCooldown then return end
    S.batCounterV2HitCooldown = true
    pcall(function()
        local bat = getBatV2Counter()
        if bat then
            bat:Activate()
            local ev = bat:FindFirstChildWhichIsA("RemoteEvent")
            if ev then ev:FireServer() end
        end
    end)
    task.delay(BAT_COUNTER_V2_SWING_CD, function() S.batCounterV2HitCooldown = false end)
end

local function executeBatCounterV2()
    local now = tick()
    if now - (S._lastBatCounterV2Time or 0) < (S._batCounterV2Cooldown or 0.01) then return end
    if S.batCounterV2Debounce then return end
    S.batCounterV2Debounce = true
    S._lastBatCounterV2Time = now
    local attacker = getAttackingPlayerWithAnimalV2()
    if not attacker then S.batCounterV2Debounce = false; return end
    if isPlayerRagdolledV2(attacker) then S.batCounterV2Debounce = false; return end
    if not hasAnimalEquippedV2(attacker) then S.batCounterV2Debounce = false; return end
    S._batCounterV2OriginalTpState = S.tpBatEnabled
    local tpWasEnabled = S.tpBatEnabled
    if not tpWasEnabled then
        setTpBat(true)
        if S.tpBatSetVisual then S.tpBatSetVisual(true) end
    end
    local function doCounterHit()
        local char = LP.Character
        if not char then return end
        local hrp = char:FindFirstChild("HumanoidRootPart")
        if not hrp then return end
        local attChar = attacker.Character
        if not attChar then return end
        local attRoot = attChar:FindFirstChild("HumanoidRootPart")
        if not attRoot then return end
        if not hasAnimalEquippedV2(attacker) then S.batCounterV2Debounce = false; return end
        if sethiddenproperty then sethiddenproperty(hrp, "PhysicsRepRootPart", attRoot) end
        local targetPos = attRoot.Position + Vector3.new(0, 0.9, 0)
        if (hrp.Position - targetPos).Magnitude > 8 then hrp.CFrame = CFrame.new(targetPos) end
        tryHitBatCounterV2()
        task.delay(0.05, function() tryHitBatCounterV2() end)
        task.delay(0.1, function() tryHitBatCounterV2() end)
    end
    doCounterHit()
    task.delay(0.2, function()
        if not S._batCounterV2OriginalTpState and S.tpBatEnabled then
            setTpBat(false)
            if S.tpBatSetVisual then S.tpBatSetVisual(false) end
        end
        S.batCounterV2Debounce = false
    end)
end

stopBatCounterV2 = function()
    if S.batCounterV2Conn then
        S.batCounterV2Conn:Disconnect()
        S.batCounterV2Conn = nil
    end
    S.batCounterV2Debounce = false
    S.batCounterV2HitCooldown = false
end

startBatCounterV2 = function()
    if S.batCounterV2Conn then return end
    S.batCounterV2Conn = RunService.Heartbeat:Connect(function()
        if not S.batCounterV2Enabled then return end
        if S.batCounterV2Debounce then return end
        local character = LP.Character
        if not character then return end
        local humanoid = character:FindFirstChildOfClass("Humanoid")
        if not humanoid or humanoid.Health <= 0 then return end
        local state = humanoid:GetState()
        local isBeingAttacked = state == Enum.HumanoidStateType.Physics or
                               state == Enum.HumanoidStateType.Ragdoll or
                               state == Enum.HumanoidStateType.FallingDown or
                               state == Enum.HumanoidStateType.GettingUp
        if isBeingAttacked then
            local attacker = getAttackingPlayerWithAnimalV2()
            if attacker then
                if not isPlayerRagdolledV2(attacker) then
                    if hasAnimalEquippedV2(attacker) then
                        executeBatCounterV2()
                    end
                end
            end
        end
    end)
end


medusaWatchedCharacter = nil
medusaLastErrorWarn = 0

local function findMedusa(character)
    local c = character or LP.Character
    if not c then return nil end
    local function isMedusaTool(tool)
        if not tool or not tool:IsA("Tool") then return false end
        local name = tool.Name:lower()
        return name:find("medusa") or name:find("head") or name:find("stone")
    end
    for _, tool in ipairs(c:GetChildren()) do
        if isMedusaTool(tool) then return tool end
    end
    local backpack = LP:FindFirstChildOfClass("Backpack") or LP:FindFirstChild("Backpack")
    if backpack then
        for _, tool in ipairs(backpack:GetChildren()) do
            if isMedusaTool(tool) then return tool end
        end
    end
    return nil
end

local function useMedusaCounter()
    if not S.medusaCounterEnabled or S.medusaDebounce then return end
    local now = tick()
    if now - (S.medusaLastUsed or 0) < S.MEDUSA_COOLDOWN then return end
    local character = LP.Character
    local humanoid = character and character:FindFirstChildOfClass("Humanoid")
    if not character or not humanoid or humanoid.Health <= 0 then return end

    S.medusaDebounce = true
    local ok, activated = pcall(function()
        local medusa = findMedusa(character)
        if not medusa then return false end
        if medusa.Parent ~= character then
            local equipOk = pcall(function() humanoid:EquipTool(medusa) end)
            if not equipOk then return false end
        end
        if not medusa.Parent then return false end
        local activateOk = pcall(function() medusa:Activate() end)
        if not activateOk then return false end
        return true
    end)
    S.medusaDebounce = false
    if ok and activated then
        S.medusaLastUsed = tick()
    elseif not ok and tick() - medusaLastErrorWarn >= 3 then
        medusaLastErrorWarn = tick()
        warn("[Vision] Medusa Counter error: " .. tostring(activated))
    end
end

local function onAnchorChanged(part)
    if not part or not part:IsA("BasePart") then return nil end
    return part:GetPropertyChangedSignal("Anchored"):Connect(function()
        if not S.medusaCounterEnabled or not part.Parent then return end
        if part.Anchored and part.Transparency == 1 then
            useMedusaCounter()
        end
    end)
end

local function stopMedusaCounter()
    for _, connection in ipairs(S.medusaConns) do
        if connection then pcall(function() connection:Disconnect() end) end
    end
    S.medusaConns = {}
    medusaWatchedCharacter = nil
end

local function setupMedusaCounter(character)
    stopMedusaCounter()
    if not character or not S.medusaCounterEnabled or character ~= LP.Character then return end
    medusaWatchedCharacter = character
    local watchedParts = {}
    local function watchPart(part)
        if not S.medusaCounterEnabled or medusaWatchedCharacter ~= character then return end
        if not part or not part:IsA("BasePart") or watchedParts[part] then return end
        watchedParts[part] = true
        local ok, connection = pcall(onAnchorChanged, part)
        if ok and connection then table.insert(S.medusaConns, connection) end
    end
    for _, part in ipairs(character:GetDescendants()) do
        watchPart(part)
    end
    table.insert(S.medusaConns, character.DescendantAdded:Connect(watchPart))
end

LP.CharacterRemoving:Connect(function(character)
    if medusaWatchedCharacter == character then stopMedusaCounter() end
end)

local function applyFPSBoost()
    safeSetfpscap(999999999)
    removeCharacterAccessories()
    local function pO(v)
        pcall(function()
            if v:IsA("Model") then
                v.LevelOfDetail = Enum.ModelLevelOfDetail.Disabled
                v.ModelStreamingMode = Enum.ModelStreamingMode.Nonatomic
            elseif v:IsA("MeshPart") then
                v.CastShadow = false; v.DoubleSided = false
                v.RenderFidelity = Enum.RenderFidelity.Performance
            elseif v:IsA("BasePart") then
                v.CastShadow = false; v.Material = Enum.Material.Plastic; v.Reflectance = 0
            elseif v:IsA("Decal") or v:IsA("Texture") then
                v.Transparency = 1
            elseif v:IsA("SpecialMesh") then
                v.TextureId = ""
            elseif v:IsA("Fire") or v:IsA("SpotLight") or v:IsA("Smoke")
                or v:IsA("Sparkles") or v:IsA("ParticleEmitter")
                or v:IsA("Trail") or v:IsA("Beam") then
                v.Enabled = false
            elseif v:IsA("SurfaceAppearance") or v:IsA("MaterialVariant") then
                v:Destroy()
            elseif v:IsA("Attachment") then
                v.Visible = false
            end
        end)
    end
    for _, v in pairs(workspace:GetDescendants()) do pO(v) end
    pcall(function()
        local L = Lighting
        for _, v in pairs(L:GetDescendants()) do
            pcall(function()
                if v:IsA("Sky") or v:IsA("Atmosphere") or v:IsA("BloomEffect")
                    or v:IsA("BlurEffect") or v:IsA("SunRaysEffect")
                    or v:IsA("DepthOfFieldEffect") or v:IsA("Clouds")
                    or v:IsA("PostEffect") or v:IsA("ColorCorrectionEffect") then
                    v:Destroy()
                end
            end)
        end
        safeSethiddenproperty(L, "Technology", Enum.Technology.Legacy)
        L.GlobalShadows = false; L.FogEnd = 9e9; L.Brightness = 0
        local ter = workspace:FindFirstChildOfClass("Terrain")
        if ter then
            safeSethiddenproperty(ter, "Decoration", false)
            ter.WaterReflectance = 0; ter.WaterTransparency = 0.7
            ter.WaterWaveSize = 0; ter.WaterWaveSpeed = 0
        end
    end)
    workspace.DescendantAdded:Connect(function(v)
        if S.fpsBoostEnabled then task.spawn(pO, v) end
    end)
end

local function stopFPSBoost()
    S.fpsBoostEnabled = false
    restoreAccessories()
end

local function runTPFloor()
    pcall(function() executeTPDown() end)
end

getconnections = getconnections or get_signal_cons or getconnects or (syn and syn.get_signal_cons)

local function isMyPlotByName(plotName)
    local plots = workspace:FindFirstChild("Plots")
    if not plots then return false end
    local plot = plots:FindFirstChild(plotName)
    if not plot then return false end
    local sign = plot:FindFirstChild("PlotSign")
    if sign then
        local yb = sign:FindFirstChild("YourBase")
        if yb and yb:IsA("BillboardGui") then
            return yb.Enabled == true
        end
    end
    return false
end

local function sanitizeStealRadius(value, fallback)
    local raw = tostring(value or ""):gsub(",", ".")
    local n = tonumber(raw)
    if not n or n ~= n or n <= 0 or n == math.huge or n == -math.huge then
        return fallback or 61
    end
    return n
end

local function setStealRadius(value, fallback)
    S.Steal.StealRadius = sanitizeStealRadius(value, fallback or S.Steal.StealRadius)
    return S.Steal.StealRadius
end
local function sanitizeStealDuration(value, fallback)
    local raw = tostring(value or ""):gsub(",", ".")
    local number = tonumber(raw)
    if not number or number ~= number or number == math.huge or number == -math.huge then
        return fallback or 1.3
    end
    return math.clamp(number, 0.05, 2)
end
local function setStealDuration(value, fallback)
    S.Steal.StealDuration = sanitizeStealDuration(value, fallback or S.Steal.StealDuration)
    return S.Steal.StealDuration
end

autoGrabSetDelayRadius = 9
autoGrabStopTime = 0.96
autoGrabStopEnabled = true
_plotsCache = nil
_plotsCacheTime = 0

local function getPlotsRoot()
    local now = tick()
    if _plotsCache and now - _plotsCacheTime < 2 and _plotsCache.Parent then
        return _plotsCache
    end
    _plotsCache = workspace:FindFirstChild("Plots")
    _plotsCacheTime = now
    return _plotsCache
end

local function applyStealRadiusToPrompt(prompt)
    if not prompt then return end
    pcall(function()
        prompt.MaxActivationDistance = math.max(prompt.MaxActivationDistance or 0, setStealRadius(S.Steal.StealRadius, 61))
    end)
end

local function findNearestPrompt()
    local char = LP.Character
    if not char then return nil, nil end
    local root = char:FindFirstChild("HumanoidRootPart")
    if not root then return nil, nil end
    local plotsRoot = getPlotsRoot()
    if not plotsRoot then return nil, nil end

    local nearestPrompt, nearestDist, nearestName = nil, math.huge, nil
    local rpos = root.Position
    local radius = setStealRadius(S.Steal.StealRadius, 61)
    for _, plot in ipairs(plotsRoot:GetChildren()) do
        if isMyPlotByName(plot.Name) then continue end
        local pods = plot:FindFirstChild("AnimalPodiums")
        if not pods then continue end
        for _, pod in ipairs(pods:GetChildren()) do
            pcall(function()
                local base = pod:FindFirstChild("Base")
                local spawn = base and base:FindFirstChild("Spawn")
                if spawn then
                    local sp = spawn.Position
                    local dx, dy, dz = sp.X - rpos.X, sp.Y - rpos.Y, sp.Z - rpos.Z
                    local dist = math.sqrt(dx * dx + dy * dy + dz * dz)
                    if dist < nearestDist and dist <= radius then
                        local att = spawn:FindFirstChild("PromptAttachment")
                        if att then
                            for _, child in ipairs(att:GetChildren()) do
                                if child:IsA("ProximityPrompt") and tostring(child.ActionText or ""):find("Steal") then
                                    applyStealRadiusToPrompt(child)
                                    nearestPrompt, nearestDist, nearestName = child, dist, pod.Name
                                    break
                                end
                            end
                        end
                    end
                end
            end)
        end
    end
    return nearestPrompt, nearestName
end

local function updateStealHudStatus()
    local status = S.stealHudStatus
    if not status or not status.Parent then return end

    local enabled = S.Steal and S.Steal.AutoStealEnabled == true
    local stealing = S.Steal and S.Steal.isStealing == true
    local palette = S.activeThemePalette
    if not enabled then
        status.Text = "OFF"
        status.TextColor3 = Color3.fromRGB(160, 160, 160)
        if type(S._stopStealDetectAnimation) == "function" then
            pcall(S._stopStealDetectAnimation)
        end
    elseif stealing then
        status.Text = "STEALING"
        status.TextColor3 = palette and palette.bright or Color3.fromRGB(245, 242, 255)
        if type(S._stopStealDetectAnimation) == "function" then
            pcall(S._stopStealDetectAnimation)
        end
    else
        -- Auto Steal is enabled and searching for a target: show DETECT.
        status.Text = "DETECT"
        status.TextColor3 = palette and palette.accent or Color3.fromRGB(188, 83, 255)
    end
end

local function resetCleanStealProgress()
    if S.progressFill then S.progressFill.Size = UDim2.new(0, 0, 1, 0) end
    if S.progressPct then S.progressPct.Text = "0%" end
end

local function executeSteal(prompt, podName)
    if S.Steal.isStealing or not prompt then return end

    if math.random(30) == 1 then
        for cachedPrompt in pairs(S.Steal.Data) do
            if not cachedPrompt.Parent then S.Steal.Data[cachedPrompt] = nil end
        end
    end

    if not S.Steal.Data[prompt] then
        S.Steal.Data[prompt] = {hold = {}, trigger = {}, ready = true}
        pcall(function()
            if getconnections then
                for _, c in ipairs(getconnections(prompt.PromptButtonHoldBegan)) do
                    if c.Function then table.insert(S.Steal.Data[prompt].hold, c.Function) end
                end
                for _, c in ipairs(getconnections(prompt.Triggered)) do
                    if c.Function then table.insert(S.Steal.Data[prompt].trigger, c.Function) end
                end
            end
        end)
    end

    local data = S.Steal.Data[prompt]
    if not data.ready then return end
    data.ready = false
    S.Steal.isStealing = true
    updateStealHudStatus()
    S.Steal.stealStartTime = tick()
    resetCleanStealProgress()

    task.spawn(function()
        for _, fn in ipairs(data.hold) do task.spawn(fn) end

        local startTime = tick()
        local duration = setStealDuration(S.Steal.StealDuration, 1.3)
        local promptFired = false
        local stopProgress = 0

        if autoGrabStopEnabled then
            while S.Steal.isStealing and S.Steal.AutoStealEnabled do
                local elapsed = tick() - startTime
                if elapsed >= autoGrabStopTime then break end
                local progress = math.clamp(elapsed / duration, 0, 1)
                if S.progressFill then S.progressFill.Size = UDim2.new(progress, 0, 1, 0) end
                if S.progressPct then S.progressPct.Text = math.floor(progress * 100) .. "%" end
                if not prompt.Parent or not prompt.Parent.Parent then break end
                local char = LP.Character
                local hrp = char and char:FindFirstChild("HumanoidRootPart")
                if hrp and (hrp.Position - prompt.Parent.Parent.Position).Magnitude > S.Steal.StealRadius then break end
                task.wait()
            end

            stopProgress = math.clamp(autoGrabStopTime / duration, 0, 1)
            if S.progressFill then S.progressFill.Size = UDim2.new(stopProgress, 0, 1, 0) end
            if S.progressPct then S.progressPct.Text = math.floor(stopProgress * 100) .. "%" end

            local phase2Timeout = math.max(2.99 - autoGrabStopTime - math.max(duration - autoGrabStopTime, 0), 0.05)
            local phase2Start = tick()
            while S.Steal.isStealing and S.Steal.AutoStealEnabled do
                if tick() - phase2Start >= phase2Timeout then
                    resetCleanStealProgress()
                    data.ready = true
                    S.Steal.isStealing = false
                    updateStealHudStatus()
                    task.wait()
                    local newPrompt, newName = findNearestPrompt()
                    if newPrompt then executeSteal(newPrompt, newName) end
                    return
                end
                if not prompt.Parent or not prompt.Parent.Parent then
                    resetCleanStealProgress()
                    data.ready = true
                    S.Steal.isStealing = false
                    updateStealHudStatus()
                    return
                end
                local char = LP.Character
                local hrp = char and char:FindFirstChild("HumanoidRootPart")
                if hrp then
                    local dist = (hrp.Position - prompt.Parent.Parent.Position).Magnitude
                    if dist <= autoGrabSetDelayRadius then
                        break
                    elseif dist > S.Steal.StealRadius then
                        resetCleanStealProgress()
                        data.ready = true
                        S.Steal.isStealing = false
                        updateStealHudStatus()
                        return
                    end
                end
                task.wait()
            end

            if S.Steal.isStealing and S.Steal.AutoStealEnabled then
                local fillStart = tick()
                local fillDuration = math.max(duration - autoGrabStopTime, 0.05)
                while true do
                    local fp = math.clamp((tick() - fillStart) / fillDuration, 0, 1)
                    local totalProgress = stopProgress + fp * (1 - stopProgress)
                    if S.progressFill then S.progressFill.Size = UDim2.new(totalProgress, 0, 1, 0) end
                    if S.progressPct then S.progressPct.Text = math.floor(totalProgress * 100) .. "%" end
                    if fp >= 1 and not promptFired then
                        promptFired = true
                        pcall(function()
                            for _, fn in ipairs(data.trigger) do task.spawn(fn) end
                            local remote = ReplicatedStorage:FindFirstChild("StealAnimal")
                            if remote and podName then remote:FireServer(podName) end
                            if prompt then prompt:Fire() end
                        end)
                        break
                    end
                    task.wait()
                end
            end
        else
            while S.Steal.isStealing and S.Steal.AutoStealEnabled do
                local elapsed = tick() - startTime
                local progress = math.clamp(elapsed / duration, 0, 1)
                if S.progressFill then S.progressFill.Size = UDim2.new(progress, 0, 1, 0) end
                if S.progressPct then S.progressPct.Text = math.floor(progress * 100) .. "%" end
                if not prompt.Parent or not prompt.Parent.Parent then break end
                local char = LP.Character
                local hrp = char and char:FindFirstChild("HumanoidRootPart")
                if hrp and (hrp.Position - prompt.Parent.Parent.Position).Magnitude > S.Steal.StealRadius then break end
                if elapsed >= duration and not promptFired then
                    promptFired = true
                    pcall(function()
                        for _, fn in ipairs(data.trigger) do task.spawn(fn) end
                        local remote = ReplicatedStorage:FindFirstChild("StealAnimal")
                        if remote and podName then remote:FireServer(podName) end
                        if prompt then prompt:Fire() end
                    end)
                    break
                end
                task.wait()
            end
        end

        resetCleanStealProgress()
        data.ready = true
        S.Steal.isStealing = false
        updateStealHudStatus()
    end)
end

local function startAutoSteal()
    if S.Conns.autoSteal then
        S.stealActive = true
        S.Steal.AutoStealEnabled = true
        updateStealHudStatus()
        return
    end
    S.stealActive = true
    S.Steal.AutoStealEnabled = true
    updateStealHudStatus()
    S.Conns.autoSteal = RunService.Heartbeat:Connect(function()
        if not S.Steal.AutoStealEnabled or S.Steal.isStealing then return end
        local prompt, podName = findNearestPrompt()
        if prompt then executeSteal(prompt, podName) end
    end)
end

local function stopAutoSteal()
    if S.Conns.autoSteal then S.Conns.autoSteal:Disconnect(); S.Conns.autoSteal = nil end
    S.stealActive = false
    S.Steal.AutoStealEnabled = false
    updateStealHudStatus()
    if S.Conns.progress then S.Conns.progress:Disconnect(); S.Conns.progress = nil end
    S.Steal.isStealing = false
    S.Steal.stealStartTime = nil
    resetCleanStealProgress()
end

-- Removed an unused always-on noclip sweep; it was scanning every other character every 0.15s.

RunService.RenderStepped:Connect(function()
    S._fpsCount = S._fpsCount + 1
    local now = tick()
    if now - S._lastFpsTime >= 1 then
        S.currentFPS = math.floor(S._fpsCount/(now - S._lastFpsTime))
        S._fpsCount = 0
        S._lastFpsTime = now
    end
end)

updateFloatingButtons = function()
    if not S._setPButtonActive then return end
    local fb = S._floatingButtons
    if fb.lagger then updateLaggerButtonVisual() end
    if fb.carry then S._setPButtonActive(fb.carry, fb.strokeCarry, fb.l1Carry, fb.l2Carry, S.speedMode) end
    if fb.autoLeft then S._setPButtonActive(fb.autoLeft, fb.strokeAutoLeft, fb.l1AutoLeft, fb.l2AutoLeft, S.autoLeftEnabled) end
    if fb.autoRight then S._setPButtonActive(fb.autoRight, fb.strokeAutoRight, fb.l1AutoRight, fb.l2AutoRight, S.autoRightEnabled) end
    if fb.bat then S._setPButtonActive(fb.bat, fb.strokeBat, fb.l1Bat, fb.l2Bat, S.batAimbotEnabled) end
    if fb.antiBat then S._setPButtonActive(fb.antiBat, nil, nil, nil, S.antiBatAimbotEnabled) end
end

local function setUILock(enabled)
    S.lockUIEnabled = enabled == true
    if S.lockUIEnabled then S._floatingPanelDragging = false end
    -- Lock bloquea únicamente el arrastre; las acciones siguen funcionando.
    if S.mainMenuFrame then S.mainMenuFrame.Active = true end
    if S.miniToggleButton then S.miniToggleButton.Active = true end
    -- El contenedor es solo visual; nunca debe capturar toques detrás.
    if S.floatingPanelFrame then S.floatingPanelFrame.Active = false end
end

local function makeDraggable(frame, isFloatingPanel, dragTarget, onMove)
    local dragging, dragStart, startPos = false, nil, nil
    local moved = false
    local target = dragTarget or frame
    frame.Active = true
    frame.InputBegan:Connect(function(inp)
        if S.lockUIEnabled then return end
        if inp.UserInputType == Enum.UserInputType.MouseButton1 or inp.UserInputType == Enum.UserInputType.Touch then
            dragging = true
            moved = false
            if isFloatingPanel then S._floatingPanelDragging = false end
            dragStart = inp.Position
            startPos = target.Position
        end
    end)
    UIS.InputChanged:Connect(function(inp)
        if S.lockUIEnabled or not dragging then return end
        if inp.UserInputType == Enum.UserInputType.MouseMovement or inp.UserInputType == Enum.UserInputType.Touch then
            local delta = inp.Position - dragStart
            if delta.Magnitude > 2 then
                moved = true
                local newX = startPos.X.Offset + delta.X
                local newY = startPos.Y.Offset + delta.Y
                target.Position = UDim2.new(startPos.X.Scale, newX, startPos.Y.Scale, newY)
                if onMove then pcall(onMove, target) end
                if isFloatingPanel then S._floatingPanelDragging = true end
            end
        end
    end)
    UIS.InputEnded:Connect(function(inp)
        if inp.UserInputType == Enum.UserInputType.MouseButton1 or inp.UserInputType == Enum.UserInputType.Touch then
            if isFloatingPanel and moved then saveConfig() end
            dragging = false
            moved = false
            if isFloatingPanel then
                task.delay(0.12, function()
                    S._floatingPanelDragging = false
                end)
            end
        end
    end)
end

