-- ── Palette (Premium Glassmorphism) ──────────────────────────────────────
-- Neon base palette: near-black violet surfaces with a vivid electric-violet accent.
-- Theme buttons below replace these colors with their own coordinated neon palette.
C_BG       = Color3.fromRGB(4, 4, 12)
C_HEADER   = Color3.fromRGB(8, 5, 19)
C_CARD     = Color3.fromRGB(12, 8, 26)
C_CARD_HOV = Color3.fromRGB(30, 12, 51)
C_BORDER   = Color3.fromRGB(103, 45, 156)
C_HIGHLIGHT      = Color3.fromRGB(190, 55, 255)
C_SHADE  = Color3.fromRGB(83, 23, 151)
C_HIGHLIGHT_BRIGHT = Color3.fromRGB(245, 222, 255)
C_WHITE    = Color3.fromRGB(250, 247, 255)
C_GREY     = Color3.fromRGB(181, 170, 205)
C_DIM      = Color3.fromRGB(46, 25, 72)
C_ACCENT   = Color3.fromRGB(177, 42, 255)
C_SEPARATOR_GRAY = Color3.fromRGB(98, 51, 145)
C_CARD_ACTIVE_BG = Color3.fromRGB(31, 12, 54)

PANEL_W  = 1100
PANEL_H  = 620
HEADER_H = 72
TABBAR_H = 34

-- ── Scrolling page factory ────────────────────────────────────────────────
local function buildGui_createScrollingPages(parent)
    local pages = {}
    for _, n in ipairs({"Speed","Main","Move","Config","Keybinds"}) do
        local sf = Instance.new("ScrollingFrame", parent)
        sf.Size = UDim2.new(1,0,1,0)
        sf.BackgroundTransparency = 1
        sf.BorderSizePixel = 0
        sf.ScrollBarThickness = 3
        sf.ScrollBarImageColor3 = C_HIGHLIGHT
        sf.Visible = false
        sf.AutomaticCanvasSize = Enum.AutomaticSize.Y
        sf.CanvasSize = UDim2.new(0,0,0,0)
        pcall(function() sf.ElasticBehavior = Enum.ElasticBehavior.Always end)
        pcall(function() sf.ScrollingDirection = Enum.ScrollingDirection.Y end)
        local ll = Instance.new("UIListLayout", sf)
        ll.SortOrder = Enum.SortOrder.LayoutOrder
        ll.Padding = UDim.new(0,4)
        ll.FillDirection = Enum.FillDirection.Vertical
        local pp = Instance.new("UIPadding", sf)
        pp.PaddingLeft  = UDim.new(0,10)
        pp.PaddingRight = UDim.new(0,10)
        pp.PaddingTop   = UDim.new(0,8)
        pp.PaddingBottom= UDim.new(0,18)
        pages[n] = sf
    end
    return pages
end

rowCounts = {Speed=0, Main=0, Move=0, Config=0, Keybinds=0}

-- ── Card row ──────────────────────────────────────────────────────────────
local function mkCard(pg, pages, h)
    rowCounts[pg] = rowCounts[pg] + 1
    local f = Instance.new("Frame", pages[pg])
    f.Size = UDim2.new(1,0,0,h or 38)
    f.BackgroundColor3 = C_CARD
    f.BackgroundTransparency = 0.15
    f.BorderSizePixel = 0
    f.LayoutOrder = rowCounts[pg]
    Instance.new("UICorner", f).CornerRadius = UDim.new(0,12)
    local stroke = Instance.new("UIStroke", f)
    stroke.Color = C_BORDER; stroke.Thickness = 1; stroke.Transparency = 0.3
    -- Subtle inner glow gradient
    local cardGrad = Instance.new("UIGradient", f)
    cardGrad.Color = ColorSequence.new({
        ColorSequenceKeypoint.new(0, Color3.fromRGB(20, 20, 20)),
        ColorSequenceKeypoint.new(0.5, Color3.fromRGB(10, 10, 10)),
        ColorSequenceKeypoint.new(1, Color3.fromRGB(14, 14, 14)),
    })
    cardGrad.Rotation = 135
    return f
end

-- ── Section divider ───────────────────────────────────────────────────────
local function mkSection(pg, pages, text)
    rowCounts[pg] = rowCounts[pg] + 1
    local f = Instance.new("Frame", pages[pg])
    f.Name = "Section_" .. tostring(text):gsub("[^%w]+", "_")
    f:SetAttribute("XypherSectionTitle", text)
    f.Size = UDim2.new(1,0,0,20)
    f.BackgroundTransparency = 1
    f.BorderSizePixel = 0
    f.LayoutOrder = rowCounts[pg]
    local lbl = Instance.new("TextLabel", f)
    lbl.Size = UDim2.new(1,-10,1,0)
    lbl.Position = UDim2.new(0,10,0,0)
    lbl.BackgroundTransparency = 1
    lbl.Text = text:upper()
    lbl.TextColor3 = C_HIGHLIGHT
    lbl.Font = Enum.Font.GothamBold
    lbl.TextSize = 9
    lbl.TextXAlignment = Enum.TextXAlignment.Left
    local line = Instance.new("Frame", f)
    line.Size = UDim2.new(1,-10,0,1)
    line.Position = UDim2.new(0,10,1,-1)
    line.BackgroundColor3 = C_SEPARATOR_GRAY
    line.BackgroundTransparency = 0.72
    line.BorderSizePixel = 0
end

-- ── Toggle row ────────────────────────────────────────────────────────────
-- Lightweight, fail-safe Halloween cobweb accent for toggle rows.
-- This decoration is deliberately isolated from GUI construction so any
-- decorative failure can never prevent the Vision interface from appearing.
local toggleWebCounter = 0
local function addToggleHalloweenWeb(card)
    if not card or not card.Parent or card:FindFirstChild("HalloweenToggleCobweb") then return end
    local ok = pcall(function()
        toggleWebCounter += 1
        local size = math.random(16, 20)
        local x = math.random(164, 181)
        local y = math.random(7, 11)
        local orientation = math.random(0, 3)
        local alpha = math.random(50, 66) / 100

        local root = Instance.new("Frame")
        root.Name = "HalloweenToggleCobweb"
        root.Position = UDim2.fromOffset(x, y)
        root.Size = UDim2.fromOffset(size, size)
        root.BackgroundTransparency = 1
        root.BorderSizePixel = 0
        root.ZIndex = 2
        root.Active = false
        root.Selectable = false
        root.ClipsDescendants = true
        root.Parent = card

        local strand = Color3.fromRGB(150, 150, 150)
        local highlight = Color3.fromRGB(202, 202, 202)
        local function transform(px, py)
            if orientation == 1 then return size - px, py end
            if orientation == 2 then return size - px, size - py end
            if orientation == 3 then return px, size - py end
            return px, py
        end
        local function webLine(x1, y1, x2, y2, thick, color, transparency, name)
            x1, y1 = transform(x1, y1)
            x2, y2 = transform(x2, y2)
            local dx, dy = x2 - x1, y2 - y1
            local length = math.sqrt(dx * dx + dy * dy)
            if length < 1 then return end
            local f = Instance.new("Frame")
            f.Name = name
            f.AnchorPoint = Vector2.new(0.5, 0.5)
            f.Position = UDim2.fromOffset((x1 + x2) * 0.5, (y1 + y2) * 0.5)
            f.Size = UDim2.fromOffset(length, thick)
            f.Rotation = math.deg(math.atan2(dy, dx))
            f.BackgroundColor3 = color
            f.BackgroundTransparency = transparency
            f.BorderSizePixel = 0
            f.ZIndex = 3
            f.Active = false
            f.Selectable = false
            f.Parent = root
        end

        -- Small corner-web silhouette: 3 rays + 2 curved-looking cross bands (7 lines total).
        local edgePoints = {
            {x = size, y = 0},
            {x = size, y = size},
            {x = 0, y = size},
        }
        for i, point in ipairs(edgePoints) do
            webLine(0, 0, point.x, point.y, i == 2 and 1.0 or 0.8, strand, alpha, "ToggleRadialSilk" .. tostring(i))
        end
        for ringIndex, fraction in ipairs({0.42, 0.76}) do
            local p1 = {x = edgePoints[1].x * fraction, y = edgePoints[1].y * fraction}
            local p2 = {x = edgePoints[2].x * fraction, y = edgePoints[2].y * fraction}
            local p3 = {x = edgePoints[3].x * fraction, y = edgePoints[3].y * fraction}
            local color = ringIndex == 2 and highlight or strand
            local transparency = math.min(0.82, alpha + 0.08)
            webLine(p1.x, p1.y, p2.x, p2.y, ringIndex == 2 and 0.9 or 0.75, color, transparency, "ToggleCrossSilk" .. tostring(ringIndex) .. "A")
            webLine(p2.x, p2.y, p3.x, p3.y, ringIndex == 2 and 0.9 or 0.75, color, transparency, "ToggleCrossSilk" .. tostring(ringIndex) .. "B")
        end
        local knot = Instance.new("Frame")
        knot.Name = "ToggleSilkKnot"
        knot.AnchorPoint = Vector2.new(0.5, 0.5)
        local kx, ky = transform(0, 0)
        knot.Position = UDim2.fromOffset(kx, ky)
        knot.Size = UDim2.fromOffset(2, 2)
        knot.BackgroundColor3 = highlight
        knot.BackgroundTransparency = 0.2
        knot.BorderSizePixel = 0
        knot.ZIndex = 4
        knot.Active = false
        knot.Selectable = false
        knot.Parent = root
        Instance.new("UICorner", knot).CornerRadius = UDim.new(1, 0)
    end)
    return ok
end

local toggleWebQueue = {}
local toggleWebQueueHead, toggleWebQueueTail = 1, 0
local toggleWebWorkerRunning = false
local function queueToggleHalloweenWeb(card)
    if not card or not card.Parent then return end
    toggleWebQueueTail += 1
    toggleWebQueue[toggleWebQueueTail] = card
    if toggleWebWorkerRunning then return end
    toggleWebWorkerRunning = true
    task.spawn(function()
        local batch = 0
        while toggleWebQueueHead <= toggleWebQueueTail do
            local target = toggleWebQueue[toggleWebQueueHead]
            toggleWebQueue[toggleWebQueueHead] = nil
            toggleWebQueueHead += 1
            if target and target.Parent then pcall(addToggleHalloweenWeb, target) end
            batch += 1
            if batch >= 4 then
                batch = 0
                task.wait()
            end
        end
        toggleWebQueue = {}
        toggleWebQueueHead, toggleWebQueueTail = 1, 0
        toggleWebWorkerRunning = false
    end)
end

local function mkToggle(pg, pages, label, defKey, defOn, onToggle, onKeyChanged, previewImageId)
    -- Consistent row height and control spacing make touch targets easier to use.
    local card = mkCard(pg, pages, 42)
    card.Name = "ToggleRow_" .. tostring(label):gsub("[^%w]+", "_")
    local isCrosshairToggle = tostring(label):lower():find("crosshair", 1, true) ~= nil
    -- Crosshair controls need a solid surface so ON/OFF state is easy to see.
    -- Keep the existing glass style for other toggles to avoid changing the whole UI.
    card.BackgroundTransparency = isCrosshairToggle and 0.12 or 0.70
    local cardStroke = card:FindFirstChildOfClass("UIStroke")
    local hasPreview = type(previewImageId) == "string" and (previewImageId:match("^%d+$") ~= nil or (previewImageId == XYPHER_UPLOADED_PHOTO_OPTION or previewImageId == XYPHER_UPLOADED_PHOTO_OPTION_2 or previewImageId == XYPHER_UPLOADED_PHOTO_OPTION_3 or previewImageId == XYPHER_UPLOADED_PHOTO_OPTION_4))
    local switchRightInset = defKey and 70 or 14
    local switchWidth = 42
    local previewWidth = 38
    local labelRightReserve = switchRightInset + switchWidth + 10
    if hasPreview then labelRightReserve = labelRightReserve + previewWidth + 8 end

    -- Draw the decorative web after the row is created; it must never block
    -- creation of the actual toggle or the rest of the Vision GUI.
    -- Keep feature cards clean and reference-matched; no decorative layer may cover controls.

    local lbl = Instance.new("TextLabel", card)
    lbl.Name = "ToggleLabel"
    lbl.Size = UDim2.new(1, -(12 + labelRightReserve), 1, 0)
    lbl.Position = UDim2.new(0,12,0,0)
    lbl.BackgroundTransparency = 1
    lbl.Text = tostring(label)
    -- Boost toggle-label contrast and readability across dark/glass backgrounds.
    -- Use an opaque white label, a black outline, and a heavier font so the text
    -- remains readable even when the row is translucent or a theme is changed.
    lbl.TextTransparency = 0
    lbl.TextColor3 = Color3.fromRGB(255, 255, 255)
    lbl.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
    lbl.TextStrokeTransparency = 0.16
    lbl.Font = Enum.Font.GothamBlack
    lbl.TextSize = 13
    lbl.TextScaled = false
    lbl.TextWrapped = false
    lbl.TextXAlignment = Enum.TextXAlignment.Left
    lbl.TextYAlignment = Enum.TextYAlignment.Center
    lbl.ZIndex = 6
    local toggleLabelSize = Instance.new("UITextSizeConstraint")
    toggleLabelSize.Name = "ToggleLabelSizeConstraint"
    toggleLabelSize.MinTextSize = 10
    toggleLabelSize.MaxTextSize = 13
    toggleLabelSize.Parent = lbl
    pcall(function() lbl.TextTruncate = Enum.TextTruncate.AtEnd end)

    -- Optional non-interactive thumbnail preview for mobile-button Background rows.
    -- It is placed between the label and switch, above the transparent click area.
    if hasPreview then
        local previewFrame = Instance.new("Frame")
        previewFrame.Name = "BackgroundPreviewFrame"
        previewFrame.AnchorPoint = Vector2.new(1, 0.5)
        previewFrame.Position = UDim2.new(1, -(switchRightInset + switchWidth + 8), 0.5, 0)
        previewFrame.Size = UDim2.fromOffset(previewWidth, 24)
        previewFrame.BackgroundColor3 = Color3.fromRGB(8, 8, 8)
        previewFrame.BackgroundTransparency = 0.05
        previewFrame.BorderSizePixel = 0
        previewFrame.ClipsDescendants = true
        previewFrame.Active = false
        previewFrame.Selectable = false
        previewFrame.ZIndex = 10
        previewFrame.Visible = true
        previewFrame.Parent = card
        Instance.new("UICorner", previewFrame).CornerRadius = UDim.new(0, 6)

        local previewStroke = Instance.new("UIStroke")
        previewStroke.Name = "PreviewNeonBorder"
        previewStroke.Color = Color3.fromRGB(157, 157, 157)
        previewStroke.Thickness = 1
        previewStroke.Transparency = 0.22
        previewStroke.Parent = previewFrame

        local previewImage = Instance.new("ImageLabel")
        previewImage.Name = "BackgroundPreviewImage"
        previewImage.Size = UDim2.new(1, -2, 1, -2)
        previewImage.Position = UDim2.fromOffset(1, 1)
        previewImage.BackgroundTransparency = 1
        previewImage.BorderSizePixel = 0
        if previewImageId == XYPHER_UPLOADED_PHOTO_OPTION or previewImageId == XYPHER_UPLOADED_PHOTO_OPTION_2 or previewImageId == XYPHER_UPLOADED_PHOTO_OPTION_3 or previewImageId == XYPHER_UPLOADED_PHOTO_OPTION_4 then
            previewImage.Image = ensureXypherUploadedPhotoAsset(previewImageId) or ""
        else
            previewImage.Image = "rbxthumb://type=Asset&id=" .. previewImageId .. "&w=150&h=100"
        end
        previewImage.ImageTransparency = 0
        previewImage.ScaleType = Enum.ScaleType.Crop
        previewImage.Active = false
        previewImage.Selectable = false
        previewImage.ZIndex = 11
        previewImage.Visible = true
        previewImage.Parent = previewFrame
        Instance.new("UICorner", previewImage).CornerRadius = UDim.new(0, 5)

        -- Resolve thumbnails asynchronously with fallbacks; never block UI creation.
        -- Some image assets resolve through rbxthumb, while others require rbxassetid.
        task.spawn(function()
            if previewImageId == XYPHER_UPLOADED_PHOTO_OPTION or previewImageId == XYPHER_UPLOADED_PHOTO_OPTION_2 or previewImageId == XYPHER_UPLOADED_PHOTO_OPTION_3 or previewImageId == XYPHER_UPLOADED_PHOTO_OPTION_4 then
                local localUri = ensureXypherUploadedPhotoAsset(previewImageId)
                if localUri and previewImage.Parent then previewImage.Image = localUri end
                return
            end
            local thumbnailUri = "rbxthumb://type=Asset&id=" .. previewImageId .. "&w=150&h=100"
            local directUri = "rbxassetid://" .. previewImageId
            local largeThumbnailUri = "rbxthumb://type=Asset&id=" .. previewImageId .. "&w=420&h=420"
            local function waitLoaded(timeout)
                local deadline = os.clock() + timeout
                while os.clock() < deadline and previewImage.Parent do
                    local okLoaded, isLoaded = pcall(function() return previewImage.IsLoaded end)
                    if okLoaded and isLoaded then return true end
                    task.wait(0.1)
                end
                return false
            end
            if waitLoaded(2.0) then return end
            if not previewImage.Parent then return end
            pcall(function() previewImage.Image = directUri end)
            if waitLoaded(2.0) then return end
            if not previewImage.Parent then return end
            pcall(function() previewImage.Image = largeThumbnailUri end)
            waitLoaded(1.5)
        end)
    end

    local keyBtn = nil
    if defKey then
        keyBtn = Instance.new("TextButton", card)
        keyBtn.Name = "ToggleKeybind"
        keyBtn.AnchorPoint = Vector2.new(1, 0.5)
        keyBtn.Size = UDim2.fromOffset(48, 26)
        keyBtn.Position = UDim2.new(1, -8, 0.5, 0)
        keyBtn.BackgroundColor3 = Color3.fromRGB(0, 0, 0)
        keyBtn.BackgroundTransparency = 0
        keyBtn.BorderSizePixel = 0
        keyBtn.ZIndex = 10
        keyBtn.Text = (defKey or Enum.KeyCode.Unknown).Name
        keyBtn.TextTransparency = 0
        keyBtn.TextColor3 = C_GREY
        keyBtn.Font = Enum.Font.GothamBold; keyBtn.TextSize = 9
        Instance.new("UICorner", keyBtn).CornerRadius = UDim.new(0,8)
        local ks = Instance.new("UIStroke", keyBtn)
        ks.Color = Color3.fromRGB(35, 35, 35)
        ks.Thickness = 1
        ks.Transparency = 0.52
        ks.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
        local listening = false
        keyBtn.MouseButton1Click:Connect(function()
            if listening then return end; listening = true
            local prev = keyBtn.Text; keyBtn.Text = "···"; keyBtn.TextColor3 = C_HIGHLIGHT
            local conn
            conn = UIS.InputBegan:Connect(function(inp)
                if inp.UserInputType == Enum.UserInputType.Keyboard or inp.UserInputType == Enum.UserInputType.Gamepad1 then
                    if inp.KeyCode ~= Enum.KeyCode.Escape then
                        keyBtn.Text = inp.KeyCode.Name; keyBtn.TextColor3 = C_GREY
                        if onKeyChanged then onKeyChanged(inp.KeyCode, inp.UserInputType == Enum.UserInputType.Gamepad1) end
                    else keyBtn.Text = prev; keyBtn.TextColor3 = C_GREY end
                    listening = false; conn:Disconnect()
                end
            end)
        end)
    end

    -- Refined Halloween accent shared by every toggle row.
    local activeAccent = Instance.new("Frame", card)
    activeAccent.Name = "HalloweenToggleAccent"
    activeAccent.AnchorPoint = Vector2.new(0, 0.5)
    activeAccent.Position = UDim2.new(0, 0, 0.5, 0)
    activeAccent.Size = UDim2.new(0, 3, 0, 13)
    activeAccent.BackgroundColor3 = C_HIGHLIGHT
    activeAccent.BackgroundTransparency = 0.78
    activeAccent.BorderSizePixel = 0
    activeAccent.ZIndex = 4
    activeAccent.Active = false
    activeAccent.Selectable = false
    Instance.new("UICorner", activeAccent).CornerRadius = UDim.new(1, 0)
    local activeAccentGradient = Instance.new("UIGradient", activeAccent)
    activeAccentGradient.Rotation = 90
    activeAccentGradient.Color = ColorSequence.new({
        ColorSequenceKeypoint.new(0, C_HIGHLIGHT_BRIGHT),
        ColorSequenceKeypoint.new(0.5, C_HIGHLIGHT),
        ColorSequenceKeypoint.new(1, C_SHADE),
    })

    -- Toggle premium: dark when OFF, neon accent when ON.
    local pillBg = Instance.new("Frame", card)
    pillBg.Name = "ToggleTrack"
    pillBg.Size = UDim2.fromOffset(switchWidth, 24)
    pillBg.AnchorPoint = Vector2.new(1, 0.5)
    pillBg.Position = UDim2.new(1, -switchRightInset, 0.5, 0)
    pillBg.BackgroundColor3 = Color3.fromRGB(9, 9, 9)
    pillBg.BackgroundTransparency = 0
    pillBg.BorderSizePixel = 0
    pillBg.ZIndex = 6
    pillBg.ClipsDescendants = false
    Instance.new("UICorner", pillBg).CornerRadius = UDim.new(1,0)
    local pillStroke = Instance.new("UIStroke", pillBg)
    pillStroke.Name = "TrackStroke"
    pillStroke.Color = Color3.fromRGB(151, 151, 151)
    pillStroke.Thickness = 0.8
    pillStroke.Transparency = 0.62
    local pillGradient = Instance.new("UIGradient", pillBg)
    pillGradient.Name = "TrackGradient"
    pillGradient.Rotation = 90
    pillGradient.Enabled = true
    pillGradient.Color = ColorSequence.new({
        ColorSequenceKeypoint.new(0, Color3.fromRGB(30, 30, 30)),
        ColorSequenceKeypoint.new(0.55, Color3.fromRGB(15, 15, 15)),
        ColorSequenceKeypoint.new(1, Color3.fromRGB(7, 7, 7)),
    })
    local dotBack = Instance.new("Frame", pillBg)
    dotBack.Name = "DotBack"
    dotBack.AnchorPoint = Vector2.new(0.5,0.5)
    dotBack.Position = UDim2.new(0.5,0,0.5,1)
    dotBack.Size = UDim2.fromOffset(16, 16)
    dotBack.BackgroundColor3 = Color3.fromRGB(0, 0, 0)
    dotBack.BackgroundTransparency = isCrosshairToggle and 0.28 or 0.55
    dotBack.BorderSizePixel = 0
    dotBack.ZIndex = 6
    Instance.new("UICorner", dotBack).CornerRadius = UDim.new(1,0)
    local dot = Instance.new("Frame", pillBg)
    dot.Name = "Knob"
    dot.AnchorPoint = Vector2.new(0.5,0.5)
    dot.Position = UDim2.new(0.5,0,0.5,0)
    dot.Size = UDim2.fromOffset(14, 14)
    dot.BackgroundColor3 = Color3.fromRGB(93, 93, 93)
    dot.BorderSizePixel = 0
    dot.ZIndex = 7
    Instance.new("UICorner", dot).CornerRadius = UDim.new(1,0)
    local dotGradient = Instance.new("UIGradient", dot)
    dotGradient.Name = "VisionDotGradient"
    dotGradient.Rotation = 90
    dotGradient.Color = ColorSequence.new({
        ColorSequenceKeypoint.new(0, Color3.fromRGB(235, 235, 235)),
        ColorSequenceKeypoint.new(0.5, Color3.fromRGB(128, 128, 128)),
        ColorSequenceKeypoint.new(1, Color3.fromRGB(49, 49, 49)),
    })
    local dotGloss = Instance.new("Frame", dot)
    dotGloss.Name = "VisionOrangeGloss"
    dotGloss.Size = UDim2.new(0.46,0,0.24,0)
    dotGloss.Position = UDim2.new(0.22,0,0.11,0)
    dotGloss.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
    dotGloss.BackgroundTransparency = 0.62
    dotGloss.BorderSizePixel = 0
    dotGloss.ZIndex = 8
    Instance.new("UICorner", dotGloss).CornerRadius = UDim.new(1,0)
    local dotScale = Instance.new("UIScale", dot)
    dotScale.Scale = 1

    local isOn = defOn or false
    local function setV(on)
        isOn = on
        local fadeInfo = TweenInfo.new(0.22,Enum.EasingStyle.Quad,Enum.EasingDirection.Out)
        local dotColor = on and C_HIGHLIGHT or (isCrosshairToggle and Color3.fromRGB(155, 155, 155) or Color3.fromRGB(93, 93, 93))
        local dotSequence = on and ColorSequence.new({
            ColorSequenceKeypoint.new(0, C_HIGHLIGHT_BRIGHT),
            ColorSequenceKeypoint.new(0.46, C_HIGHLIGHT),
            ColorSequenceKeypoint.new(1, C_SHADE),
        }) or (isCrosshairToggle and ColorSequence.new({
            ColorSequenceKeypoint.new(0, Color3.fromRGB(250, 250, 250)),
            ColorSequenceKeypoint.new(0.5, Color3.fromRGB(180, 180, 180)),
            ColorSequenceKeypoint.new(1, Color3.fromRGB(105, 105, 105)),
        }) or ColorSequence.new({
            ColorSequenceKeypoint.new(0, Color3.fromRGB(235, 235, 235)),
            ColorSequenceKeypoint.new(0.5, Color3.fromRGB(128, 128, 128)),
            ColorSequenceKeypoint.new(1, Color3.fromRGB(49, 49, 49)),
        }))
        TS_G:Create(dot, fadeInfo, {BackgroundColor3 = dotColor}):Play()
        dotGradient.Color = dotSequence
        TS_G:Create(dotScale, TweenInfo.new(0.28,Enum.EasingStyle.Back,Enum.EasingDirection.Out), {
            Scale = on and 1.08 or 0.92,
        }):Play()
        task.delay(0.02, function()
            if dotScale and dotScale.Parent then
                TS_G:Create(dotScale, TweenInfo.new(0.28,Enum.EasingStyle.Back,Enum.EasingDirection.Out), {Scale = 1}):Play()
            end
        end)
        dotGloss.BackgroundTransparency = on and 0.44 or 0.62

        -- Keep the activation switch itself fully opaque; transparency applies to
        -- the row surface only, never to the control the player must tap.
        pillBg.BackgroundTransparency = 0
        pillGradient.Enabled = true
        pillGradient.Color = on and ColorSequence.new({
            ColorSequenceKeypoint.new(0, C_HIGHLIGHT_BRIGHT),
            ColorSequenceKeypoint.new(0.42, C_HIGHLIGHT),
            ColorSequenceKeypoint.new(1, Color3.fromRGB(8, 5, 18)),
        }) or ColorSequence.new({
            ColorSequenceKeypoint.new(0, Color3.fromRGB(33, 33, 33)),
            ColorSequenceKeypoint.new(0.55, Color3.fromRGB(16, 16, 16)),
            ColorSequenceKeypoint.new(1, Color3.fromRGB(7, 7, 7)),
        })
        pillStroke.Color = on and C_HIGHLIGHT or C_DIM
        TS_G:Create(pillStroke, fadeInfo, {
            Thickness = on and (isCrosshairToggle and 1.6 or 1.25) or (isCrosshairToggle and 1.05 or 0.6),
            Transparency = on and (isCrosshairToggle and 0.06 or 0.18) or (isCrosshairToggle and 0.24 or 0.58),
        }):Play()
        TS_G:Create(activeAccent, fadeInfo, {
            BackgroundTransparency = on and 0.03 or 0.78,
            Size = on and UDim2.new(0, 3, 0, 28) or UDim2.new(0, 3, 0, 15),
        }):Play()
        card.BackgroundColor3 = on and C_CARD_ACTIVE_BG or C_CARD
        if cardStroke then
            TS_G:Create(cardStroke, fadeInfo, {
                Color = on and (isCrosshairToggle and C_HIGHLIGHT or C_SEPARATOR_GRAY) or C_BORDER,
                Transparency = on and (isCrosshairToggle and 0.10 or 0.42) or (isCrosshairToggle and 0.12 or 0.3),
                Thickness = on and (isCrosshairToggle and 1.5 or 1.15) or 1,
            }):Play()
        end
    end

    local clickArea = Instance.new("TextButton", card)
    clickArea.Name = "ToggleClickArea"
    clickArea.Size = UDim2.new(1,0,1,0)
    clickArea.BackgroundTransparency = 1
    clickArea.Text = ""
    clickArea.AutoButtonColor = false
    clickArea.Active = true
    clickArea.ClipsDescendants = true
    clickArea.ZIndex = 5

    -- Touch/click feedback: a small accent ripple expands and fades inside the row.
    -- It is non-interactive and clipped to the toggle card so it cannot cover nearby controls.
    local function playToggleClickRipple(inputObject)
        pcall(function()
            if not clickArea.Parent then return end
            local size = clickArea.AbsoluteSize
            local px, py = size.X * 0.5, size.Y * 0.5
            if inputObject and inputObject.Position then
                local origin = clickArea.AbsolutePosition
                px = math.clamp(inputObject.Position.X - origin.X, 0, size.X)
                py = math.clamp(inputObject.Position.Y - origin.Y, 0, size.Y)
            end
            local diameter = math.clamp(math.min(size.X, 46), 28, 46)
            local ripple = Instance.new("Frame")
            ripple.Name = "ToggleClickRipple"
            ripple.AnchorPoint = Vector2.new(0.5, 0.5)
            ripple.Position = UDim2.fromOffset(px, py)
            ripple.Size = UDim2.fromOffset(0, 0)
            ripple.BackgroundColor3 = C_HIGHLIGHT_BRIGHT
            ripple.BackgroundTransparency = 0.72
            ripple.BorderSizePixel = 0
            ripple.Active = false
            ripple.Selectable = false
            ripple.ZIndex = 8
            ripple.Parent = clickArea
            Instance.new("UICorner", ripple).CornerRadius = UDim.new(1, 0)
            local rippleStroke = Instance.new("UIStroke")
            rippleStroke.Color = C_HIGHLIGHT
            rippleStroke.Thickness = 1.1
            rippleStroke.Transparency = 0.32
            rippleStroke.Parent = ripple

            local expandTween = TS_G:Create(ripple, TweenInfo.new(0.30, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
                Size = UDim2.fromOffset(diameter, diameter),
                BackgroundTransparency = 1,
            })
            local fadeStrokeTween = TS_G:Create(rippleStroke, TweenInfo.new(0.30, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
                Transparency = 1,
                Thickness = 0.5,
            })
            expandTween:Play()
            fadeStrokeTween:Play()
            expandTween.Completed:Connect(function()
                if ripple and ripple.Parent then ripple:Destroy() end
            end)
        end)
    end

    clickArea.Activated:Connect(function(inputObject)
        playToggleClickRipple(inputObject)
        isOn = not isOn
        setV(isOn)
        if onToggle then onToggle(isOn) end
    end)
    clickArea.MouseEnter:Connect(function()
        TS_G:Create(card, TweenInfo.new(0.12), {BackgroundColor3 = C_CARD_HOV}):Play()
    end)
    clickArea.MouseLeave:Connect(function()
        TS_G:Create(card, TweenInfo.new(0.15), {
            BackgroundColor3 = isOn and C_CARD_ACTIVE_BG or C_CARD
        }):Play()
    end)

    setV(isOn)
    return setV, keyBtn, card
end

-- ── Number input row ──────────────────────────────────────────────────────
local function mkInput(pg, pages, label, default, onChange)
    local card = mkCard(pg, pages, 36)
    local lbl = Instance.new("TextLabel", card)
    lbl.Size = UDim2.new(0.55,-8,1,0); lbl.Position = UDim2.new(0,12,0,0)
    lbl.BackgroundTransparency = 1; lbl.Text = label
    lbl.TextColor3 = C_WHITE; lbl.Font = Enum.Font.GothamBold
    lbl.TextSize = 11; lbl.TextXAlignment = Enum.TextXAlignment.Left
    local box = Instance.new("TextBox", card)
    box.Size = UDim2.new(0,66,0,26); box.Position = UDim2.new(1,-74,0.5,-13)
    box.BackgroundColor3 = Color3.fromRGB(18, 18, 18); box.BorderSizePixel = 0
    box.Text = tostring(default); box.TextColor3 = C_WHITE
    box.Font = Enum.Font.GothamBlack; box.TextSize = 11
    box.ClearTextOnFocus = false; box.MultiLine = false
    pcall(function() box.ReturnKeyType = Enum.ReturnKeyType.Done end)
    Instance.new("UICorner", box).CornerRadius = UDim.new(0,8)
    local boxStroke = Instance.new("UIStroke", box)
    boxStroke.Color = C_BORDER; boxStroke.Thickness = 0.8
    local lastVal = tostring(default); local isFocused = false
    box.Focused:Connect(function()
        isFocused = true
        TS_G:Create(boxStroke, TweenInfo.new(0.15), {Color = C_HIGHLIGHT}):Play()
    end)
    local function applyVal()
        if not isFocused then return end
        isFocused = false
        TS_G:Create(boxStroke, TweenInfo.new(0.15), {Color = C_BORDER}):Play()
        local n = tonumber(box.Text)
        if n then lastVal = tostring(n); box.Text = lastVal; onChange(n)
        else box.Text = lastVal end
        pcall(function() box:ReleaseFocus(false) end)
    end
    box.FocusLost:Connect(function()
        if isFocused then
            isFocused = false
            TS_G:Create(boxStroke, TweenInfo.new(0.15), {Color = C_BORDER}):Play()
            local n = tonumber(box.Text)
            if n then lastVal = tostring(n); box.Text = lastVal; onChange(n)
            else box.Text = lastVal end
        end
    end)
    pcall(function() box.ReturnPressedFromOnScreenKeyboard:Connect(applyVal) end)
    UIS.TouchTap:Connect(function(positions)
        if not isFocused then return end
        pcall(function()
            local abs = box.AbsolutePosition; local sz = box.AbsoluteSize; local tp = positions[1]
            if tp and not (tp.X>=abs.X and tp.X<=abs.X+sz.X and tp.Y>=abs.Y and tp.Y<=abs.Y+sz.Y) then
                applyVal()
            end
        end)
    end)
    return box
end

-- ── Action / keybind row ──────────────────────────────────────────────────
local function mkActionRow(pg, pages, labelText, keyEntry, onRun)
    local card = mkCard(pg, pages, 36)
    local lbl = Instance.new("TextLabel", card)
    lbl.Size = UDim2.new(0,180,1,0); lbl.Position = UDim2.new(0,12,0,0)
    lbl.BackgroundTransparency = 1; lbl.Text = labelText
    lbl.TextColor3 = C_WHITE; lbl.Font = Enum.Font.GothamBold; lbl.TextSize = 11
    lbl.TextXAlignment = Enum.TextXAlignment.Left

    -- Toda la fila ejecuta la acción al tocarla; el botón de tecla sigue permitiendo reasignarla.
    if onRun then
        local actionTap = Instance.new("TextButton", card)
        actionTap.Name = "ActionTapArea"
        actionTap.Size = UDim2.new(1, 0, 1, 0)
        actionTap.BackgroundTransparency = 1
        actionTap.Text = ""
        actionTap.AutoButtonColor = false
        actionTap.Active = true
        actionTap.ZIndex = 2
        actionTap.Activated:Connect(function()
            task.spawn(onRun)
        end)
    end

    if keyEntry then
        local keyBtn = Instance.new("TextButton", card)
        keyBtn.Size = UDim2.new(0,52,0,24); keyBtn.Position = UDim2.new(1,-62,0.5,-12)
        keyBtn.BackgroundColor3 = Color3.fromRGB(18, 18, 18); keyBtn.BorderSizePixel = 0; keyBtn.ZIndex = 10
        keyBtn.Text = (keyEntry.kb or keyEntry.gp or Enum.KeyCode.Unknown).Name
        keyBtn.TextColor3 = C_GREY; keyBtn.Font = Enum.Font.GothamBold; keyBtn.TextSize = 9
        Instance.new("UICorner", keyBtn).CornerRadius = UDim.new(0,7)
        local ks = Instance.new("UIStroke", keyBtn); ks.Color = C_BORDER; ks.Thickness = 0.8
        local listening = false
        keyBtn.MouseButton1Click:Connect(function()
            if listening then return end; listening = true
            local prev = keyBtn.Text; keyBtn.Text = "···"; keyBtn.TextColor3 = C_HIGHLIGHT
            local conn
            conn = UIS.InputBegan:Connect(function(inp)
                if inp.UserInputType == Enum.UserInputType.Keyboard or inp.UserInputType == Enum.UserInputType.Gamepad1 then
                    if inp.KeyCode ~= Enum.KeyCode.Escape then
                        keyBtn.Text = inp.KeyCode.Name; keyBtn.TextColor3 = C_GREY
                        if inp.UserInputType == Enum.UserInputType.Gamepad1 then
                            keyEntry.gp = inp.KeyCode; keyEntry.kb = nil
                        else keyEntry.kb = inp.KeyCode; keyEntry.gp = nil end
                        saveConfig()
                    else keyBtn.Text = prev; keyBtn.TextColor3 = C_GREY end
                    listening = false; conn:Disconnect()
                end
            end)
        end)
    end
    return function(newLabel)
        if lbl and lbl.Parent then lbl.Text = newLabel end
    end
end

-- ── Mini toggle (minimised button) ────────────────────────────────────────
local function buildGui_createMiniToggle(gui, showGuiFn)
    -- Independent launcher. The direct fallback below is intentional: it can
    -- reopen the stored dashboard even if the original show callback is stale.
    local btn = Instance.new("TextButton")
    btn.Name = "OpenGuiButton"
    btn.Size = UDim2.fromOffset(104, 34)
    btn.Position = UDim2.new(0, 18, 0, 70)
    btn.BackgroundColor3 = Color3.fromRGB(11, 7, 20)
    btn.BackgroundTransparency = 0.02
    btn.BorderSizePixel = 0
    btn.Text = "XYPHER"
    btn.TextColor3 = C_WHITE
    btn.Font = Enum.Font.GothamBlack
    btn.TextSize = 11
    btn.TextScaled = false
    btn.TextXAlignment = Enum.TextXAlignment.Center
    btn.TextYAlignment = Enum.TextYAlignment.Center
    btn.AutoButtonColor = false
    btn.ZIndex = 10
    btn.Visible = true
    btn.Active = true
    btn.Selectable = true
    btn.Parent = gui
    Instance.new("UICorner", btn).CornerRadius = UDim.new(0, 10)
    local ms = Instance.new("UIStroke", btn)
    ms.Color = C_HIGHLIGHT
    ms.Thickness = 1.35
    ms.Transparency = 0.12
    local grad = Instance.new("UIGradient", btn)
    grad.Rotation = 12
    grad.Color = ColorSequence.new({
        ColorSequenceKeypoint.new(0, Color3.fromRGB(42, 36, 67)),
        ColorSequenceKeypoint.new(0.52, Color3.fromRGB(16, 17, 26)),
        ColorSequenceKeypoint.new(1, Color3.fromRGB(48, 38, 71)),
    })
    local titleConstraint = Instance.new("UITextSizeConstraint", btn)
    titleConstraint.MinTextSize = 10
    titleConstraint.MaxTextSize = 13

    local lastActivation = -math.huge
    local function activateMiniOnce()
        local now = os.clock()
        if now - lastActivation < 0.30 then return end
        lastActivation = now

        -- While the interface is still being built, remember the request but
        -- also attempt a direct reopen if the main root has already been created.
        if not S._xypherBuildReady then S._xypherOpenPending = true end

        -- First use the normal transition. The old implementation always ran the
        -- fallback afterward, resetting Scale/Position immediately and cancelling
        -- the visible entrance animation even when showGuiFn had worked correctly.
        local callbackWasRun = type(showGuiFn) == "function"
        local callbackOk, callbackErr = pcall(function()
            if callbackWasRun then showGuiFn() end
        end)
        if not callbackOk then
            warn("[XYPHER] Open GUI transition error: " .. tostring(callbackErr))
        end

        local opened = false
        local root = S.mainMenuFrame
        local screenGui = nil
        if root and root.Parent then
            screenGui = root:FindFirstAncestorOfClass("ScreenGui")
        end

        -- A successful callback owns the animation. Do not reset its scale or
        -- position; only confirm that the real GUI remains enabled and visible.
        if callbackWasRun and callbackOk and root and root.Parent and root.Visible then
            if screenGui and not screenGui.Enabled then screenGui.Enabled = true end
            opened = true
        end

        if not opened then
            if not (root and root.Parent) then
                -- Recover the root from either host if an executor left a stale state ref.
                pcall(function()
                    local core = game:GetService("CoreGui")
                    local pg = LP and LP:FindFirstChildOfClass("PlayerGui")
                    local hosts = {core, pg}
                    for _, host in ipairs(hosts) do
                        if host then
                            local screen = host:FindFirstChild("Vision")
                            local candidate = screen and screen:FindFirstChild("Outer")
                            if candidate and candidate:IsA("GuiObject") and candidate.Parent then
                                root = candidate
                                S.mainMenuFrame = candidate
                                gui = screen
                                screenGui = screen
                                break
                            end
                        end
                    end
                end)
            end
            if root and root.Parent then
                local fallbackOk, fallbackErr = pcall(function()
                    root.AnchorPoint = Vector2.new(0.5, 0.5)
                    root.Size = UDim2.fromOffset(PANEL_W, PANEL_H)
                    local targetPosition = UDim2.fromScale(0.5, 0.5)
                    root.Position = UDim2.new(0.5, 0, 0.5, 30)
                    root.Visible = true

                    local scaleObj = S.mainGuiScaleObj
                    if not (scaleObj and scaleObj.Parent) then
                        scaleObj = root:FindFirstChildWhichIsA("UIScale", true)
                        if scaleObj then S.mainGuiScaleObj = scaleObj end
                    end
                    if scaleObj and scaleObj.Parent then
                        local camera = workspace.CurrentCamera
                        local viewport = camera and camera.ViewportSize or Vector2.new(PANEL_W, PANEL_H)
                        local fit = math.min(1, (viewport.X - 16) / PANEL_W, (viewport.Y - 20) / PANEL_H)
                        if S.IS_TOUCH_DEVICE then fit = math.min(fit, S.phoneGuiScale or 0.72) end
                        local targetScale = math.max(0.24, fit * 0.82)
                        scaleObj.Scale = math.max(0.14, targetScale * 0.58)
                        if S.menuTween then pcall(function() S.menuTween:Cancel() end) end
                        S.menuTween = TS_G:Create(scaleObj, TweenInfo.new(0.42, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {Scale = targetScale})
                        S.menuTween:Play()
                    end
                    if root.Parent and root.Parent:IsA("ScreenGui") then root.Parent.Enabled = true end
                    if screenGui and screenGui:IsA("ScreenGui") then screenGui.Enabled = true end
                    TS_G:Create(root, TweenInfo.new(0.42, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), {Position = targetPosition}):Play()
                    if S._xypherLauncherGui then S._xypherLauncherGui.Enabled = true end
                end)
                opened = fallbackOk
                if not fallbackOk then
                    warn("[XYPHER] Open GUI fallback error: " .. tostring(fallbackErr))
                end
            end
        end

        if opened then
            btn.Visible = false
            S._xypherOpenPending = false
            if type(S._xypherSetGameplayOverlaysVisible) == "function" then
                pcall(S._xypherSetGameplayOverlaysVisible, false)
            end
        else
            -- Do not vanish if the target root is unavailable; leave the user
            -- an actionable launcher rather than a dead end.
            btn.Visible = true
        end
    end

    btn.Activated:Connect(activateMiniOnce)
    btn.MouseButton1Click:Connect(activateMiniOnce)
    btn.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1
            or input.UserInputType == Enum.UserInputType.Touch then
            activateMiniOnce()
        end
    end)
    return btn
end

-- ── Kroblox (ported from Ace Duels) ────────────────────────────────────────
_G._VisionKrobloxMode = _G._VisionKrobloxMode or "Off"
VISION_KROBLOX_ASSETS = {
    ["Left Leg"] = {
        id = "rbxassetid://139607673", targetBodyPart = "LeftUpperLeg",
        partsToHide = {"LeftUpperLeg", "LeftLowerLeg", "LeftFoot"},
        scale = Vector3.new(1, 1, 1), audio = "rbxassetid://87998522263554",
        offset = CFrame.new(0, 0, 0) * CFrame.Angles(1.2, 0, 0),
    },
    ["Right Leg"] = {
        id = "rbxassetid://139607718", targetBodyPart = "RightUpperLeg",
        partsToHide = {"RightUpperLeg", "RightLowerLeg", "RightFoot"},
        scale = Vector3.new(1, 1, 1), audio = "rbxassetid://135315310485417",
        offset = CFrame.new(0, 0, 0) * CFrame.Angles(0, 1.2, 0),
    },
}
local function clearVisionKroblox()
    local character = LP.Character
    if not character then return end
    for _, name in ipairs({"Korblox_LeftLeg", "Korblox_RightLeg", "VisionKroblox_LeftLeg", "VisionKroblox_RightLeg"}) do
        local object = character:FindFirstChild(name)
        if object then pcall(function() object:Destroy() end) end
    end
    for _, name in ipairs({"LeftUpperLeg", "LeftLowerLeg", "LeftFoot", "RightUpperLeg", "RightLowerLeg", "RightFoot"}) do
        local part = character:FindFirstChild(name)
        if part and part:IsA("BasePart") then
            part.Transparency = 0
            part.LocalTransparencyModifier = 0
        end
    end
end

local function attachVisionKroblox(whichLeg)
    local data = VISION_KROBLOX_ASSETS[whichLeg]
    local character = LP.Character
    if not data or not character then return false end
    local target = character:FindFirstChild(data.targetBodyPart)
    if not target then return false end
    local old = character:FindFirstChild("Korblox_" .. whichLeg:gsub("%s+", ""))
    if old then old:Destroy() end
    for _, name in ipairs(data.partsToHide) do
        local part = character:FindFirstChild(name)
        if part and part:IsA("BasePart") then part.Transparency = 1 end
    end
    local ok, objects = pcall(function() return game:GetObjects(data.id) end)
    if not ok or not objects or #objects == 0 then return false end
    local object = objects[1]
    object.Name = "Korblox_" .. whichLeg:gsub("%s+", "")
    local meshPart = object:IsA("BasePart") and object or object:FindFirstChildWhichIsA("BasePart", true)
    if not meshPart then pcall(function() object:Destroy() end); return false end
    meshPart.Size = meshPart.Size * data.scale
    meshPart.CanCollide = false
    meshPart.CanTouch = false
    meshPart.CanQuery = false
    meshPart.Massless = true
    meshPart.CFrame = target.CFrame * data.offset
    local weld = Instance.new("WeldConstraint")
    weld.Part0 = target
    weld.Part1 = meshPart
    weld.Parent = meshPart
    object.Parent = character
    return true
end

_G._VisionApplyKroblox = function(mode)
    mode = ({Off=true, Left=true, Right=true, Both=true})[mode] and mode or "Off"
    clearVisionKroblox()
    S.krobloxMode = mode
    _G._VisionKrobloxMode = mode
    if mode == "Left" or mode == "Both" then pcall(attachVisionKroblox, "Left Leg") end
    if mode == "Right" or mode == "Both" then pcall(attachVisionKroblox, "Right Leg") end
end

LP.CharacterAdded:Connect(function()
    task.wait(0.6)
    if _G._VisionKrobloxMode ~= "Off" then
        pcall(_G._VisionApplyKroblox, _G._VisionKrobloxMode)
    end
end)

-- ── Tab content builders ──────────────────────────────────────────────────
local function buildSpeedTab(pages)
    mkSection("Speed", pages, "Speed Values")
    S.normalBox  = mkInput("Speed", pages, "Normal Speed",   S.NS, function(v)
        if v>0 and v<=500 then S.NS=v; S.applySpeedVelocityNow(); S.restartMovement(); saveConfig() end end)
    S.carryBox   = mkInput("Speed", pages, "Carry Speed",    S.CS, function(v)
        if v>0 and v<=500 then S.CS=v; S.applySpeedVelocityNow(); S.restartMovement(); saveConfig() end end)
    S.laggerBox  = mkInput("Speed", pages, "Lagger Normal Speed", S.LS, function(v)
        if v>0 and v<=500 then S.LS=v; S.applySpeedVelocityNow(); S.restartMovement(); saveConfig() end end)
    S.laggerCarryBox = mkInput("Speed", pages, "Lagger Carry Speed", S.LCS, function(v)
        if v>0 and v<=500 then S.LCS=v; S.applySpeedVelocityNow(); S.restartMovement(); saveConfig() end end)
    mkSection("Speed", pages, "Modes")
    S.speedClk, _ = mkToggle("Speed", pages, "Carry Mode", S.KB.SpeedToggle.kb, S.speedMode, function(on)
        if on and S.laggerMode~=0 then S.laggerMode=0; if S.setLaggerVisual then S.setLaggerVisual(false) end; updateLaggerButtonVisual() end
        S.speedMode = on
        if on then S.setCarrySpeedMode() else S.setNormalSpeedMode() end
        S.restartMovement(); updateFloatingButtons(); saveConfig()
    end, function(k,isGp)
        if isGp then S.KB.SpeedToggle.gp=k; S.KB.SpeedToggle.kb=nil
        else S.KB.SpeedToggle.kb=k; S.KB.SpeedToggle.gp=nil end; saveConfig()
    end)
    S.setLaggerVisual, _ = mkToggle("Speed", pages, "Lagger Mode", S.KB.LaggerToggle.kb, S.laggerMode ~= 0, function(on)
        if on then
            if S.speedClk then S.speedClk(false) end
            S.setLaggerNormalMode()
        else
            S.setLaggerOffMode()
        end
        updateLaggerButtonVisual(); S.restartMovement(); updateFloatingButtons(); saveConfig()
    end, function(k,isGp)
        if isGp then S.KB.LaggerToggle.gp=k; S.KB.LaggerToggle.kb=nil
        else S.KB.LaggerToggle.kb=k; S.KB.LaggerToggle.gp=nil end; saveConfig()
    end)
end

-- ==================== VISION BAT SKINS ====================
do
-- Ported from Zurich: Epic Katana and Bloody Katana, including their slash sounds.
VisionBatSkin = {}
VISION_BAT_SKINS = {
    {name = "Off"},
    {
        name = "Epic Katana",
        id = "rbxassetid://14052995337",
        soundId = "rbxassetid://111808555599832",
        c0 = CFrame.new(0, 0, 1.6) * CFrame.Angles(0, 0, math.rad(-90)),
    },
    {
        name = "Bloody Katana",
        id = "rbxassetid://126653333198410",
        soundId = "rbxassetid://111808555599832",
        c0 = CFrame.new(0, 0, 2) * CFrame.Angles(math.rad(90), 0, 0),
    },
}
VisionBatSkin.cache = {}
VisionBatSkin.originals = setmetatable({}, {__mode = "k"})
VisionBatSkin.soundConnections = setmetatable({}, {__mode = "k"})
VisionBatSkin.watched = setmetatable({}, {__mode = "k"})

function VisionBatSkin.visionLoadBatSkin(id)
    if VisionBatSkin.cache[id] then return VisionBatSkin.cache[id] end
    local ok, objects = pcall(function() return game:GetObjects(id) end)
    if not ok or type(objects) ~= "table" or #objects == 0 then return nil end
    VisionBatSkin.cache[id] = objects[1]
    return objects[1]
end

function VisionBatSkin.visionIsBat(tool)
    return tool and tool:IsA("Tool") and tool.Name:lower() == "bat"
end

function VisionBatSkin.visionSetBatSlashSound(tool, soundId)
    if not tool then return end
    for _, sound in ipairs(tool:GetDescendants()) do
        if sound:IsA("Sound") and sound.Name == "Slash" then
            local original = sound:GetAttribute("VisionOriginalSlashSound")
            if soundId then
                if original == nil then sound:SetAttribute("VisionOriginalSlashSound", sound.SoundId) end
                sound.SoundId = soundId
            elseif original ~= nil then
                sound.SoundId = original
                sound:SetAttribute("VisionOriginalSlashSound", nil)
            end
        end
    end
end

function VisionBatSkin.visionRestoreBatSkin(tool, clearOriginal)
    if not VisionBatSkin.visionIsBat(tool) then return end
    local handle = tool:FindFirstChild("Handle")
    local original = VisionBatSkin.originals[tool]
    if handle then
        -- En Off no debe quedar visible ningún modelo, weld o parte de la skin.
        for _, child in ipairs(handle:GetChildren()) do
            if not child:IsA("Sound") then
                pcall(function() child:Destroy() end)
            end
        end
    end
    if handle and original then
        handle.Transparency = original.transparency
        handle.CanCollide = original.canCollide
        handle.CanTouch = original.canTouch
        handle.CanQuery = original.canQuery
        handle.Size = original.size
    elseif handle then
        handle.Transparency = 0
    end
    if original and original.grip then tool.Grip = original.grip end
    VisionBatSkin.visionSetBatSlashSound(tool, nil)
    local soundConnection = VisionBatSkin.soundConnections[tool]
    if clearOriginal ~= false and soundConnection then
        pcall(function() soundConnection:Disconnect() end)
        VisionBatSkin.soundConnections[tool] = nil
    end
    if clearOriginal ~= false then VisionBatSkin.originals[tool] = nil end
end

function VisionBatSkin.visionPrepareBatSkin(tool, entry)
    if not VisionBatSkin.visionIsBat(tool) or not entry or not entry.id then return end
    local toolHandle = tool:FindFirstChild("Handle")
    if not toolHandle then return end

    if not VisionBatSkin.originals[tool] then
        VisionBatSkin.originals[tool] = {
            grip = tool.Grip,
            transparency = toolHandle.Transparency,
            canCollide = toolHandle.CanCollide,
            canTouch = toolHandle.CanTouch,
            canQuery = toolHandle.CanQuery,
            size = toolHandle.Size,
        }
    end

    VisionBatSkin.visionRestoreBatSkin(tool, false)
    for _, child in ipairs(toolHandle:GetChildren()) do
        if not child:IsA("Sound") then pcall(function() child:Destroy() end) end
    end

    local katanaRoot = VisionBatSkin.visionLoadBatSkin(entry.id)
    if not katanaRoot then return end
    local modelClone = katanaRoot:Clone()
    modelClone.Name = "VisionBatSkinModel"
    modelClone.Parent = toolHandle

    local function makeKinematic(inst)
        if inst:IsA("BasePart") then
            inst.Anchored = false
            inst.CanCollide = false
            inst.Massless = true
        end
        for _, child in ipairs(inst:GetChildren()) do makeKinematic(child) end
    end
    makeKinematic(modelClone)

    local primaryPart = modelClone:IsA("BasePart") and modelClone or modelClone.PrimaryPart
    if not primaryPart then
        for _, inst in ipairs(modelClone:GetDescendants()) do
            if inst:IsA("BasePart") then primaryPart = inst; break end
        end
    end
    if not primaryPart then pcall(function() modelClone:Destroy() end); return end

    local weld = Instance.new("Weld")
    weld.Part0 = toolHandle
    weld.Part1 = primaryPart
    weld.C0 = entry.c0
    weld.Parent = toolHandle

    toolHandle.Transparency = 1
    toolHandle.CanCollide = false
    toolHandle.Size = Vector3.new(0.3, 1, 0.3)
    tool.GripForward = Vector3.new(0, -1, 0)
    tool.GripRight   = Vector3.new(1,  0, 0)
    tool.GripUp      = Vector3.new(0,  0, 1)
    tool.GripPos     = Vector3.new(0,  0, 0)

    local previousSoundConnection = VisionBatSkin.soundConnections[tool]
    if previousSoundConnection then
        pcall(function() previousSoundConnection:Disconnect() end)
        VisionBatSkin.soundConnections[tool] = nil
    end
    VisionBatSkin.visionSetBatSlashSound(tool, entry.soundId)
    VisionBatSkin.soundConnections[tool] = tool.DescendantAdded:Connect(function(obj)
        if S.batSkinMode == entry.name and obj:IsA("Sound") and obj.Name == "Slash" then
            if obj:GetAttribute("VisionOriginalSlashSound") == nil then
                obj:SetAttribute("VisionOriginalSlashSound", obj.SoundId)
            end
            obj.SoundId = entry.soundId
        end
    end)
end

function VisionBatSkin.visionApplyBatSkin(tool)
    if not VisionBatSkin.visionIsBat(tool) then return end
    if S.batSkinMode == "Off" then
        VisionBatSkin.visionRestoreBatSkin(tool)
        return
    end
    local entry
    for _, candidate in ipairs(VISION_BAT_SKINS) do
        if candidate.name == S.batSkinMode then entry = candidate; break end
    end
    if entry then VisionBatSkin.visionPrepareBatSkin(tool, entry) end
end

function VisionBatSkin.visionScanBatSkins(parent)
    if not parent then return end
    for _, child in ipairs(parent:GetChildren()) do
        if VisionBatSkin.visionIsBat(child) then task.spawn(VisionBatSkin.visionApplyBatSkin, child) end
    end
end

function VisionBatSkin.visionWatchBatSkinContainer(parent)
    if not parent or VisionBatSkin.watched[parent] then return end
    VisionBatSkin.watched[parent] = true
    table.insert(S.batSkinConnections, parent.ChildAdded:Connect(function(child)
        task.wait(0.1)
        if VisionBatSkin.visionIsBat(child) then VisionBatSkin.visionApplyBatSkin(child) end
    end))
    VisionBatSkin.visionScanBatSkins(parent)
end

function VisionBatSkin.visionWatchBatSkinCharacter(character)
    VisionBatSkin.visionWatchBatSkinContainer(character)
    VisionBatSkin.visionWatchBatSkinContainer(LP:FindFirstChildOfClass("Backpack"))
    if S.batSkinMode ~= "Off" then
        task.delay(0.35, function()
            if LP.Character == character then
                VisionBatSkin.visionScanBatSkins(character)
                VisionBatSkin.visionScanBatSkins(LP:FindFirstChildOfClass("Backpack"))
            end
        end)
    end
end

function VisionBatSkin.visionSetBatSkin(mode, shouldSave)
    local valid = false
    for _, entry in ipairs(VISION_BAT_SKINS) do
        if entry.name == mode then valid = true; break end
    end
    S.batSkinMode = valid and mode or "Off"
    VisionBatSkin.visionScanBatSkins(LP.Character)
    VisionBatSkin.visionScanBatSkins(LP:FindFirstChildOfClass("Backpack"))
    if S.batSkinSelectorLabel then S.batSkinSelectorLabel.Text = S.batSkinMode end
    if shouldSave then saveConfig() end
end

function VisionBatSkin.visionCycleBatSkin(direction)
    local index = 1
    for i, entry in ipairs(VISION_BAT_SKINS) do
        if entry.name == S.batSkinMode then index = i; break end
    end
    index = index + (direction or 1)
    if index < 1 then index = #VISION_BAT_SKINS end
    if index > #VISION_BAT_SKINS then index = 1 end
    VisionBatSkin.visionSetBatSkin(VISION_BAT_SKINS[index].name, true)
end

S.setBatSkin = VisionBatSkin.visionSetBatSkin
S.cycleBatSkin = VisionBatSkin.visionCycleBatSkin

LP.CharacterAdded:Connect(function(character)
    task.wait(0.2)
    VisionBatSkin.visionWatchBatSkinCharacter(character)
end)
LP.ChildAdded:Connect(function(child)
    if child:IsA("Backpack") then VisionBatSkin.visionWatchBatSkinContainer(child) end
end)
VisionBatSkin.visionWatchBatSkinCharacter(LP.Character)
end

