do
VisionDisplaySkin = {}
VISION_SKIN_ORDER = {"Off", "PURPLE", "BLUE", "RED", "BLACK", "GREEN", "WHITE"}
VISION_SKIN_SETS = {
    PURPLE = {hats="1744060292,439945661,1125510,1029025", hair="", headless=true, korblox="Right", accessories={1744060292,439945661,1125510,1029025,11748356,8465506143,11444217173}, clothing={7424637509,7689651773}, color=Color3.fromRGB(145,88,255)},
    BLUE = {hats="74891470", hair="16630147,6346833550,6594911228,6594919952,6823338112,7097747842", headless=true, korblox="Right", accessories={74891470,16630147,6346833550,6594911228,6594919952,6823338112,7097747842}, clothing={18423061209,18423154566}, color=Color3.fromRGB(55,145,255)},
    RED = {hats="215718515,439945661", hair="7183785281", headless=true, korblox="Right", accessories={215718515,439945661,7183785281}, clothing={15998365201,7689651773}, color=Color3.fromRGB(235,62,72)},
    BLACK = {hats="10159600649,439946249,17798262442,92482095662016", hair="139101716417676", headless=true, korblox="Right", accessories={10159600649,439946249,17798262442,92482095662016,139101716417676,12490213797}, clothing={18766106994,13925390578}, color=Color3.fromRGB(24,24,30)},
    GREEN = {hats="553970961,1744060292", hair="93268856876777", headless=true, korblox="Right", accessories={553970961,1744060292,93268856876777}, clothing={9478068776,6348682339}, color=Color3.fromRGB(62,210,112)},
    WHITE = {hats="74891470,215718515,439945661,1016143686,1744060292,10159600649,89012651581593,88365652378427", hair="126447390530523", headless=true, korblox="Right", accessories={74891470,215718515,439945661,1016143686,1744060292,10159600649,89012651581593,126447390530523}, clothing={88032876921227,108259950755140}, color=Color3.fromRGB(238,238,244)},
}
VISION_ASSET_PROPERTIES = {
    [1744060292]="HatAccessory", [439945661]="HatAccessory", [1125510]="HatAccessory", [1029025]="HatAccessory", [8465506143]="HatAccessory", [74891470]="HatAccessory", [215718515]="HatAccessory", [10159600649]="HatAccessory", [439946249]="HatAccessory", [17798262442]="HatAccessory", [92482095662016]="HatAccessory", [553970961]="HatAccessory", [1016143686]="HatAccessory", [89012651581593]="HatAccessory", [88365652378427]="HatAccessory",
    [16630147]="HairAccessory", [6346833550]="HairAccessory", [6594911228]="HairAccessory", [6594919952]="HairAccessory", [6823338112]="HairAccessory", [7097747842]="HairAccessory", [7183785281]="HairAccessory", [139101716417676]="HairAccessory", [93268856876777]="HairAccessory", [126447390530523]="HairAccessory",
    [11748356]="FaceAccessory", [12490213797]="FaceAccessory", [11444217173]="NeckAccessory",
    [7424637509]="Shirt", [18423061209]="Shirt", [15998365201]="Shirt", [18766106994]="Shirt", [9478068776]="Shirt", [88032876921227]="Shirt",
    [7689651773]="Pants", [18423154566]="Pants", [13925390578]="Pants", [6348682339]="Pants", [108259950755140]="Pants",
}
VisionOriginalDescriptions = setmetatable({}, {__mode="k"})
VisionOriginalOutfits = setmetatable({}, {__mode="k"})
VisionDisplaySkin._assetCache = {}
VisionDisplaySkin._applying = false
VisionDisplaySkin._pendingToken = nil

function VisionDisplaySkin.assetInSet(id, setData)
    id=tonumber(id); if not id or not setData then return false end
    for _,v in ipairs(setData.accessories or {}) do if id==v then return true end end
    for _,v in ipairs(setData.clothing or {}) do if id==v then return true end end
    return false
end
function VisionDisplaySkin.appendDescriptionAsset(description, id)
    local property=VISION_ASSET_PROPERTIES[tonumber(id)]
    if not property then return end
    if property=="Shirt" or property=="Pants" then description[property]=tonumber(id); return end
    local old=tostring(description[property] or "")
    if not old:find(tostring(id),1,true) then description[property]=(old=="" and tostring(id) or old..","..tostring(id)) end
end
function VisionDisplaySkin.buildDescription(setName, character)
    local setData=VISION_SKIN_SETS[setName]; if not setData then return nil end
    local humanoid=character and character:FindFirstChildOfClass("Humanoid"); if not humanoid then return nil end
    local description
    pcall(function() description=humanoid:GetAppliedDescription():Clone() end)
    if not description then pcall(function() description=Players:GetHumanoidDescriptionFromUserId(LP.UserId) end) end
    if not description then description=Instance.new("HumanoidDescription") end
    for _,property in ipairs({"HatAccessory","HairAccessory","FaceAccessory","NeckAccessory","ShouldersAccessory","FrontAccessory","BackAccessory","WaistAccessory","ShirtAccessory","PantsAccessory","JacketAccessory","SweaterAccessory","ShortsAccessory","TShirtAccessory","DressSkirtAccessory"}) do pcall(function() description[property]="" end) end
    pcall(function() description.Shirt=0; description.Pants=0; description.GraphicTShirt=0; description.HatAccessory=setData.hats or ""; description.HairAccessory=setData.hair or "" end)
    for _,id in ipairs(setData.accessories or {}) do VisionDisplaySkin.appendDescriptionAsset(description,id) end
    for _,id in ipairs(setData.clothing or {}) do VisionDisplaySkin.appendDescriptionAsset(description,id) end
    return description
end
function VisionDisplaySkin.applyDescription(humanoid, description)
    if not humanoid or not description then return false end

    -- Use a single description application. Trying several ApplyDescription
    -- variants in sequence can force multiple avatar rebuilds in one frame.
    local copy
    local ok = pcall(function() copy = description:Clone() end)
    if not ok or not copy then return false end

    local applied = false
    pcall(function()
        local method = humanoid.ApplyDescription
        if type(method) == "function" then
            method(humanoid, copy)
            applied = true
        end
    end)

    pcall(function() copy:Destroy() end)
    return applied
end
function VisionDisplaySkin.captureOriginalOutfit(character)
    if VisionOriginalOutfits[character] then return end
    local saved={}
    for _,child in ipairs(character:GetChildren()) do
        if child:IsA("Accessory") or child:IsA("Accoutrement") or child:IsA("Shirt") or child:IsA("Pants") or child:IsA("ShirtGraphic") then
            local ok,clone=pcall(function() return child:Clone() end)
            if ok and clone then saved[#saved+1]=clone end
        end
    end
    VisionOriginalOutfits[character]=saved
end
function VisionDisplaySkin.restoreOriginalOutfit(character)
    local saved=VisionOriginalOutfits[character]
    if not saved then return end
    for _,child in ipairs(character:GetChildren()) do
        if child:IsA("Accessory") or child:IsA("Accoutrement") or child:IsA("Shirt") or child:IsA("Pants") or child:IsA("ShirtGraphic") then pcall(function() child:Destroy() end) end
    end
    local humanoid=character:FindFirstChildOfClass("Humanoid")
    for _,clone in ipairs(saved) do
        local copy=clone:Clone()
        if copy:IsA("Accessory") and humanoid then VisionDisplaySkin.attachAccessory(character,humanoid,copy) else copy.Parent=character end
    end
end

function VisionDisplaySkin.clearMarked(character)
    for _,child in ipairs(character:GetChildren()) do
        if child:GetAttribute("VisionCompleteSkin") then pcall(function() child:Destroy() end) end
    end
end
function VisionDisplaySkin.markAndColor(character, setData)
    for _,child in ipairs(character:GetChildren()) do
        if child:IsA("Accessory") or child:IsA("Accoutrement") or child:IsA("Shirt") or child:IsA("Pants") or child:IsA("ShirtGraphic") then
            local id
            pcall(function() id=tonumber(child.SourceAssetId) end)
            if VisionDisplaySkin.assetInSet(id,setData) then child:SetAttribute("VisionCompleteSkin",true) end
        end
    end
    for _,descendant in ipairs(character:GetDescendants()) do
        if descendant:IsA("BasePart") then
            local parent=descendant
            while parent and parent~=character do
                if parent:GetAttribute("VisionCompleteSkin") then descendant.Color=setData.color; break end
                parent=parent.Parent
            end
        end
    end
end
function VisionDisplaySkin.setHeadless(character, enabled)
    local head=character and character:FindFirstChild("Head"); if not head then return end
    local transparency=enabled and 1 or 0; head.Transparency=transparency; head.LocalTransparencyModifier=transparency
    for _,child in ipairs(head:GetChildren()) do if child:IsA("Decal") or child:IsA("Texture") then child.Transparency=transparency end end
end
function VisionDisplaySkin.attachAccessory(character, humanoid, accessory)
    local handle=accessory:FindFirstChild("Handle",true)
    pcall(function() humanoid:AddAccessory(accessory) end)
    if not accessory.Parent then accessory.Parent=character end
    if not handle or not handle:IsA("BasePart") then return accessory.Parent==character end
    local handleAttachment=handle:FindFirstChildWhichIsA("Attachment")
    if not handleAttachment then return accessory.Parent==character end
    local targetAttachment
    for _,descendant in ipairs(character:GetDescendants()) do
        if descendant:IsA("Attachment") and descendant.Name==handleAttachment.Name and not descendant:IsDescendantOf(accessory) then targetAttachment=descendant; break end
    end
    if targetAttachment and targetAttachment.Parent:IsA("BasePart") then
        handle.Anchored=false; handle.CanCollide=false; handle.CanTouch=false; handle.CanQuery=false; handle.Massless=true
        handle.CFrame=targetAttachment.Parent.CFrame*targetAttachment.CFrame*handleAttachment.CFrame:Inverse()
        if not handle:FindFirstChild("VisionAccessoryWeld") then
            local weld=Instance.new("WeldConstraint"); weld.Name="VisionAccessoryWeld"; weld.Part0=targetAttachment.Parent; weld.Part1=handle; weld.Parent=handle
        end
    end
    return accessory.Parent==character
end
function VisionDisplaySkin.hasAsset(character, assetId)
    assetId=tonumber(assetId)
    for _,child in ipairs(character:GetChildren()) do
        local sourceId
        pcall(function() sourceId=tonumber(child.SourceAssetId) end)
        if assetId and assetId>0 then
            if sourceId==assetId or tonumber(child:GetAttribute("VisionSkinAssetId"))==assetId then return true end
        end
    end
    return false
end
function VisionDisplaySkin.addAsset(character, humanoid, assetId)
    assetId = tonumber(assetId)
    if not assetId or assetId <= 0 or VisionDisplaySkin.hasAsset(character, assetId) then return true end

    -- Cache the source template so changing skins repeatedly does not reload
    -- the same Roblox asset every time. Only the cached template is cloned.
    local cached = VisionDisplaySkin._assetCache[assetId]
    if not cached then
        local ok, objects = pcall(function()
            return game:GetObjects("rbxassetid://" .. tostring(assetId))
        end)
        if ok and type(objects) == "table" and #objects > 0 then
            cached = objects[1]
        else
            local loaded
            pcall(function() loaded = game:GetService("InsertService"):LoadAsset(assetId) end)
            cached = loaded
        end
        if cached then
            local okClone, template = pcall(function() return cached:Clone() end)
            if okClone and template then
                VisionDisplaySkin._assetCache[assetId] = template
            end
            pcall(function() cached:Destroy() end)
            cached = VisionDisplaySkin._assetCache[assetId]
        end
    end

    if not cached then return false end

    local candidates = {}
    if cached:IsA("Accessory") or cached:IsA("Shirt") or cached:IsA("Pants") or cached:IsA("ShirtGraphic") then
        candidates[1] = cached
    else
        for _, descendant in ipairs(cached:GetDescendants()) do
            if descendant:IsA("Accessory") or descendant:IsA("Shirt") or descendant:IsA("Pants") or descendant:IsA("ShirtGraphic") then
                candidates[#candidates + 1] = descendant
            end
        end
    end

    local added = false
    for _, source in ipairs(candidates) do
        local okClone, clone = pcall(function() return source:Clone() end)
        if okClone and clone then
            clone:SetAttribute("VisionCompleteSkin", true)
            clone:SetAttribute("VisionSkinAssetId", assetId)
            if clone:IsA("Accessory") then
                if VisionDisplaySkin.attachAccessory(character, humanoid, clone) then added = true end
            else
                for _, old in ipairs(character:GetChildren()) do
                    if old.ClassName == clone.ClassName and old:GetAttribute("VisionCompleteSkin") then
                        pcall(function() old:Destroy() end)
                    end
                end
                clone.Parent = character
                added = true
            end
        end
    end
    return added
end

function VisionDisplaySkin.applyAccessories(character, humanoid, description, setData)
    local source
    pcall(function() source=Players:CreateHumanoidModelFromDescriptionAsync(description,Enum.HumanoidRigType.R15) end)
    if not source then pcall(function() source=Players:CreateHumanoidModelFromDescription(description,Enum.HumanoidRigType.R15) end) end
    if not source then return end
    for _,child in ipairs(source:GetChildren()) do
        if child:IsA("Accessory") or child:IsA("Shirt") or child:IsA("Pants") or child:IsA("ShirtGraphic") then
            if child:IsA("Accessory") then
                local sourceId; pcall(function() sourceId=tonumber(child.SourceAssetId) end)
                if not VisionDisplaySkin.hasAsset(character,sourceId) then
                    local clone=child:Clone(); clone:SetAttribute("VisionCompleteSkin",true); clone:SetAttribute("VisionSkinAssetId",sourceId)
                    VisionDisplaySkin.attachAccessory(character,humanoid,clone)
                end
            else
                for _,current in ipairs(character:GetChildren()) do if current.ClassName==child.ClassName then pcall(function() current:Destroy() end) end end
                local clone=child:Clone(); clone:SetAttribute("VisionCompleteSkin",true); clone.Parent=character
            end
        end
    end
    source:Destroy(); VisionDisplaySkin.markAndColor(character,setData)
end

function VisionDisplaySkin.apply(token)
    token = token or S._skinApplyToken
    if VisionDisplaySkin._applying then
        VisionDisplaySkin._pendingToken = token
        return
    end

    local character = LP.Character
    local setName = S.displaySkin
    if token ~= S._skinApplyToken or not character or setName == "Off" or not S.customSkinEnabled then return end

    local humanoid = character:FindFirstChildOfClass("Humanoid")
    local setData = VISION_SKIN_SETS[setName]
    if not humanoid or not setData then return end

    VisionDisplaySkin._applying = true
    VisionDisplaySkin._pendingToken = nil

    local ok, err = pcall(function()
        if not VisionOriginalDescriptions[character] then
            pcall(function() VisionOriginalDescriptions[character] = humanoid:GetAppliedDescription():Clone() end)
        end
        VisionDisplaySkin.captureOriginalOutfit(character)

        -- Replace only the visible outfit parts. This avoids forcing Roblox to
        -- rebuild the whole humanoid with ApplyDescription on every skin switch.
        VisionDisplaySkin.clearMarked(character)
        for _, child in ipairs(character:GetChildren()) do
            if child:IsA("Accessory") or child:IsA("Accoutrement")
                or child:IsA("Shirt") or child:IsA("Pants") or child:IsA("ShirtGraphic") then
                pcall(function() child:Destroy() end)
            end
        end
        if token ~= S._skinApplyToken then return end

        -- Add only the requested assets once. hasAsset() prevents duplicates.
        for _, id in ipairs(setData.accessories or {}) do
            if token ~= S._skinApplyToken then return end
            VisionDisplaySkin.addAsset(character, humanoid, id)
        end
        for _, id in ipairs(setData.clothing or {}) do
            if token ~= S._skinApplyToken then return end
            VisionDisplaySkin.addAsset(character, humanoid, id)
        end

        VisionDisplaySkin.markAndColor(character, setData)
        VisionDisplaySkin.setHeadless(character, setData.headless == true)
        if type(_G._VisionApplyKroblox) == "function" and token == S._skinApplyToken then
            pcall(_G._VisionApplyKroblox, setData.korblox or "Off")
        end
    end)

    VisionDisplaySkin._applying = false
    if not ok then warn("[Vision] Custom avatar apply error: " .. tostring(err)) end

    local pending = VisionDisplaySkin._pendingToken
    VisionDisplaySkin._pendingToken = nil
    if pending and pending == S._skinApplyToken and S.customSkinEnabled and S.displaySkin ~= "Off" then
        task.defer(function() VisionDisplaySkin.apply(pending) end)
    end
end

function VisionDisplaySkin.off()
    local character = LP.Character
    if not character then return end
    local humanoid = character:FindFirstChildOfClass("Humanoid")

    -- Invalidate running apply jobs before restoring the original avatar.
    S._skinApplyToken = S._skinApplyToken + 1
    VisionDisplaySkin._pendingToken = nil

    VisionDisplaySkin.clearMarked(character)
    local restoredByDescription = false
    if humanoid and VisionOriginalDescriptions[character] then
        local original = VisionOriginalDescriptions[character]:Clone()
        restoredByDescription = VisionDisplaySkin.applyDescription(humanoid, original)
        pcall(function() original:Destroy() end)
    end
    -- Only use the manual outfit restore if the description restore failed;
    -- doing both can duplicate accessories and create a visible hitch.
    if not restoredByDescription then
        VisionDisplaySkin.restoreOriginalOutfit(character)
    end
    VisionDisplaySkin.setHeadless(character, false)
    if type(_G._VisionApplyKroblox) == "function" then pcall(_G._VisionApplyKroblox, "Off") end
end
function VisionDisplaySkin.setSkin(name,save)
    S._skinApplyToken = S._skinApplyToken + 1
    local myToken = S._skinApplyToken
    local valid = false
    for _,v in ipairs(VISION_SKIN_ORDER) do if v == name then valid = true end end
    S.displaySkin = valid and name or "Off"
    if S.displaySkin == "Off" then
        S.customSkinEnabled = false
        VisionDisplaySkin.off()
    else
        S.customSkinEnabled = true
        task.spawn(function() VisionDisplaySkin.apply(myToken) end)
    end
    if S.displaySkinSelectorLabel then S.displaySkinSelectorLabel.Text = S.displaySkin end
    if S.customSkinVisual then S.customSkinVisual(S.customSkinEnabled) end
    if save then saveConfig() end
end
function VisionDisplaySkin.cycleSkin(direction)
    local index=1; for i,v in ipairs(VISION_SKIN_ORDER) do if v==S.displaySkin then index=i end end
    index=index+(direction or 1); if index<1 then index=#VISION_SKIN_ORDER end; if index>#VISION_SKIN_ORDER then index=1 end
    VisionDisplaySkin.setSkin(VISION_SKIN_ORDER[index],true)
end
function VisionDisplaySkin.setCustom(on)
    S._skinApplyToken=S._skinApplyToken+1
    local myToken=S._skinApplyToken
    S.customSkinEnabled=on==true
    if S.customSkinEnabled then if S.displaySkin=="Off" then S.displaySkin="PURPLE" end; task.spawn(function() VisionDisplaySkin.apply(myToken) end) else VisionDisplaySkin.off() end
    if S.customSkinVisual then S.customSkinVisual(S.customSkinEnabled) end
    if S.displaySkinSelectorLabel then S.displaySkinSelectorLabel.Text=S.displaySkin end
    saveConfig()
end
S.setDisplaySkin=VisionDisplaySkin.setSkin; S.cycleDisplaySkin=VisionDisplaySkin.cycleSkin; S.setCustomSkin=VisionDisplaySkin.setCustom
S.applyDisplaySkin=function(token) return VisionDisplaySkin.apply(token) end
LP.CharacterAdded:Connect(function(character)
    VisionOriginalDescriptions[character] = nil
    VisionOriginalOutfits[character] = nil
    if S.customSkinEnabled and S.displaySkin ~= "Off" then
        local token = S._skinApplyToken
        task.defer(function()
            if LP.Character == character and S.customSkinEnabled and S.displaySkin ~= "Off" and token == S._skinApplyToken then
                VisionDisplaySkin.apply(token)
            end
        end)
    end
end)
end

-- ============================================================
-- SC Vision Nuke Optimizer integration
-- Imported from Nuke_Optimizer_Logic.lua. Disabled by default.
-- Avatar protection patch: all player characters and marked custom-avatar trees are excluded.
-- Private globals are namespaced to avoid collisions with other hubs.
-- ============================================================
-- Clean up an older execution of this same integrated module first.
if type(_G.__SCVisionNukeStop) == "function" then
    pcall(_G.__SCVisionNukeStop)
end
_G.__SCVisionNukeOn = false
_G.__SCVisionNukeConns = {}
_G.__SCVisionNukeThreads = {}

(function()
-- Nuke Optimizer — logic-only extraction from Zero Hub.
-- Source basis: Zero_hub_mobile_button_background_final.lua
-- The original UI/toggle is not included.
--
-- Usage:
--   _G.__SCVisionNukeStart()  -- enable optimizer
--   _G.__SCVisionNukeStop()   -- disable optimizer
--   _G.__SCVisionNukeToggle(true/false)
--
-- Optional Minecraft texture integration uses globals/hooks when available.
-- This module is disabled by default and does not auto-start.

-- ============================================================
-- NUKE OPTIMIZER INTEGRATION
-- Added as a GUI-controlled feature; disabled by default.
-- ============================================================
-- Nuke Optimizer - extracted from Vasper_v3.5_AntiE01_AutoSteal_SEMI_CHECKED_FIXED.lua
-- Standalone extraction.
-- Toggle:
--   _G.__SCVisionNukeStart()  -> ON
--   _G.__SCVisionNukeStop()   -> OFF
--
-- Compatible with the original Minecraft-texture preservation hooks when
-- those functions/state exist. Otherwise it safely falls back to normal
-- optimization behavior.

local Players = game:GetService("Players")
local RunService = game:GetService("RunService") -- retained from source integration
local LP = Players.LocalPlayer

-- Standalone replacement for the original script's local settings table.
-- Set _G.__SCVisionNukeSettings.avaPresetEnabled = true when an Ava Preset is active.
local NukeSettings = _G.__SCVisionNukeSettings or { avaPresetEnabled = false }
_G.__SCVisionNukeSettings = NukeSettings

_G.__SCVisionNukeOn = _G.__SCVisionNukeOn or false
_G.__SCVisionNukeConns = _G.__SCVisionNukeConns or {}
_G.__SCVisionNukeThreads = _G.__SCVisionNukeThreads or {}

-- Minimal state fallback so this extracted module can run by itself.
local NukeState = _G.VasperNukeState or {}
NukeState.minecraftTextureEnabled = NukeState.minecraftTextureEnabled == true
_G.VasperNukeState = NukeState

local function IsMinecraftTextureObject(obj)
    if _G.IsMinecraftTextureObject then
        local ok, result = pcall(_G.IsMinecraftTextureObject, obj)
        if ok then return result end
    end
    return obj and type(obj.Name) == "string"
        and obj.Name:sub(1, #"__MC_V5__") == "__MC_V5__"
end

local function IsMinecraftLightingObject(obj)
    if _G.IsMinecraftLightingObject then
        local ok, result = pcall(_G.IsMinecraftLightingObject, obj)
        if ok then return result end
    end
    return obj and (obj.Name == "__MC_V5_Sky" or obj.Name == "__MC_V5_Atmos")
end

local function RefreshMinecraftAfterNuke()
    if not NukeState.minecraftTextureEnabled then return end
    local create = _G.minecraftCreateSkyAndAtmosphere or minecraftCreateSkyAndAtmosphere
    local repair = _G.integrityRepair or integrityRepair
    local scanFn = _G.scan or scan

    task.spawn(function()
        for _ = 1, 5 do
            if not NukeState.minecraftTextureEnabled then return end
            pcall(function()
                if create then create() end
            end)
            pcall(function()
                if repair then repair() end
            end)
            pcall(function()
                if scanFn then scanFn() end
            end)
            task.wait(0.22)
        end
    end)
end

_G.__SCVisionNukeStart = function()
        if _G.__SCVisionNukeOn then
            RefreshMinecraftAfterNuke()
            return
        end
        _G.__SCVisionNukeOn=true
        local Lighting=game:GetService("Lighting")
        local MaterialService=game:GetService("MaterialService")
        local XMin,XMax=-560,-240
        local ClothingClasses={"Shirt","Pants","ShirtGraphic","Accessory","Hat","HairAccessory","FaceAccessory","NeckAccessory","ShoulderAccessory","FrontAccessory","BackAccessory","WaistAccessory"}
        local BASE_NAMES={"baseplate","spawnlocation","spawn location","spawn"}

        -- Objects created by Vyxro's Avatar Changer must survive Nuke Optimizer.
        -- Use an attribute marker so normal game accessories/clothes can still
        -- be optimized away. Descendants inherit protection via ancestor lookup.
        -- AVA PRESET / AVATAR CHANGER PROTECTION
        -- The preset uses _VxyroAvaPreset, while the Avatar Changer uses
        -- _VyxroAvatarChanger. Both markers must survive the nuke pass.
        local function IsVyxroAvatarObject(obj)
            local cur = obj
            while cur and cur ~= workspace do
                local marked = false
                pcall(function()
                    marked = cur:GetAttribute("_VyxroAvatarChanger") == true
                        or cur:GetAttribute("_VxyroAvaPreset") == true
                end)
                if marked then return true end
                cur = cur.Parent
            end
            return false
        end

        -- When Ava Preset is enabled, never optimize the local
        -- character through the global workspace scan. This is intentionally
        -- stronger than marker-only protection because HumanoidDescription
        -- may create Shirt/Pants/Accessory instances before the preset
        -- marker can be attached, which otherwise creates a race with Nuke.
        local function IsLocalAvaPresetObject(obj)
            if not obj or not LP.Character then return false end
            if NukeSettings.avaPresetEnabled ~= true then return false end
            local ok, inside = pcall(function() return obj:IsDescendantOf(LP.Character) end)
            return ok and inside == true
        end

        local function IsVyxroProtectedLighting(obj)
            if not obj then return false end
            if obj.Name == "VyxroMotionBlur" then return true end
            if type(obj.Name) == "string" and obj.Name:sub(1,10) == "VyxroVivid" then return true end
            local marked = false
            pcall(function() marked = obj:GetAttribute("_VyxroImportedVivid") == true end)
            return marked
        end

        -- Hard protection for every player's full character tree. This includes
        -- custom avatar bodies, accessories, clothing, face decals, mesh textures,
        -- and any descendants which are added while Nuke Optimizer is running.
        local function IsCharacterPart(obj)
            if not obj then return false end
            for _,plr in ipairs(Players:GetPlayers()) do
                local character = plr.Character
                if character then
                    if obj == character then return true end
                    local ok, inside = pcall(function()
                        return obj:IsDescendantOf(character)
                    end)
                    if ok and inside == true then return true end
                end
            end
            -- Covers avatar/custom-character models during the brief respawn window
            -- before Player.Character is assigned, plus character models spawned by
            -- avatar changers. Marked Avatar Changer trees are also protected below.
            local cur = obj
            while cur and cur ~= workspace do
                local isCharacterModel = false
                pcall(function()
                    isCharacterModel = cur:IsA("Model")
                        and cur:FindFirstChildOfClass("Humanoid") ~= nil
                end)
                if isCharacterModel then return true end
                cur = cur.Parent
            end
            return false
        end

        local function SafeDestroy(obj)
            if IsCharacterPart(obj) then return end
            if IsLocalAvaPresetObject(obj) then return end
            if IsVyxroAvatarObject(obj) or IsVyxroProtectedLighting(obj) then return end
            if IsMinecraftTextureObject(obj) or IsMinecraftLightingObject(obj) then return end
            if obj.Name=="Overhead" then return end
            pcall(function() obj:Destroy() end)
        end
        local function IsClothing(obj)
            for _,c in ipairs(ClothingClasses) do if obj:IsA(c) then return true end end
            return false
        end
        local function IsOutOfRange(obj)
            if obj:IsA("BasePart") then local x=obj.Position.X; return x<XMin or x>XMax end
            return false
        end
        local function IsBase(obj)
            if not obj:IsA("BasePart") then return false end
            local nl=obj.Name:lower()
            for _,n in ipairs(BASE_NAMES) do if nl:find(n,1,true) then return true end end
            return false
        end
        local function IsInBase(obj)
            local p=obj.Parent
            while p and p~=workspace do
                if IsBase(p) then return true end
                p=p.Parent
            end
            return false
        end
        local function MakeTransparent(obj)
            if IsCharacterPart(obj) then return end
            if IsMinecraftTextureObject(obj) then return end
            pcall(function()
                if IsBase(obj) and not IsCharacterPart(obj) then
                    obj.Transparency=1; obj.CastShadow=false
                end
            end)
        end
        local function StripObject(obj)
            if IsCharacterPart(obj) then return end
            if IsVyxroAvatarObject(obj) or IsVyxroProtectedLighting(obj) then return end
            if IsMinecraftTextureObject(obj) or IsMinecraftLightingObject(obj) then return end
            pcall(function()
                if obj:IsA("Texture") or obj:IsA("Decal") or obj:IsA("SpecialMesh") then
                    SafeDestroy(obj)
                elseif obj:IsA("ParticleEmitter") or obj:IsA("Trail") or obj:IsA("Beam") or obj:IsA("Smoke") or obj:IsA("Fire") or obj:IsA("Sparkles") then
                    pcall(function() obj.Enabled=false end)
                    SafeDestroy(obj)
                elseif obj:IsA("SurfaceAppearance") then
                    SafeDestroy(obj)
                elseif obj:IsA("BasePart") then
                    obj.CastShadow=false
                    -- Minecraft Texture owns the visual material/color behavior while active.
                    if not NukeState.minecraftTextureEnabled then
                        obj.Material=Enum.Material.Plastic
                        obj.MaterialVariant=""
                        obj.Reflectance=0
                    end
                end
            end)
        end
        local function CleanObject(obj)
            if IsCharacterPart(obj) then return end
            if IsVyxroAvatarObject(obj) or IsVyxroProtectedLighting(obj) then return end
            if IsMinecraftTextureObject(obj) or IsMinecraftLightingObject(obj) then return end
            pcall(function()
                if obj:IsA("SurfaceAppearance") then
                    -- Do not fight active Minecraft Texture on MeshParts.
                    if NukeState.minecraftTextureEnabled then return end
                    SafeDestroy(obj)
                elseif obj:IsA("Decal") or obj:IsA("Texture") then
                    if not (obj.Name=="face" and obj.Parent and obj.Parent.Name=="Head") then SafeDestroy(obj) end
                elseif obj:IsA("SpecialMesh") then
                    obj.TextureId=""
                elseif obj:IsA("ParticleEmitter") or obj:IsA("Trail") or obj:IsA("Beam") then
                    SafeDestroy(obj)
                elseif obj:IsA("PointLight") or obj:IsA("SpotLight") or obj:IsA("SurfaceLight") then
                    SafeDestroy(obj)
                elseif obj:IsA("Fire") or obj:IsA("Smoke") or obj:IsA("Sparkles") or obj:IsA("Explosion") then
                    SafeDestroy(obj)
                elseif obj:IsA("Animation") or obj:IsA("AnimationController") then
                    SafeDestroy(obj)
                elseif obj:IsA("BasePart") then
                    obj.CastShadow=false
                    if not NukeState.minecraftTextureEnabled then
                        obj.Material=Enum.Material.Plastic
                        obj.MaterialVariant=""
                        obj.Reflectance=0
                    end
                end
            end)
        end
        local function ApplyGreySky()
            pcall(function()
                if NukeState.minecraftTextureEnabled then
                    minecraftCreateSkyAndAtmosphere()
                    return
                end
                for _,obj in ipairs(Lighting:GetChildren()) do
                    if obj:IsA("Sky") then obj:Destroy() end
                end
                local sky=Instance.new("Sky")
                sky.SkyboxBk=""; sky.SkyboxDn=""; sky.SkyboxFt=""; sky.SkyboxLf=""; sky.SkyboxRt=""; sky.SkyboxUp=""
                sky.CelestialBodiesShown=false
                sky.Name="_VezyNukeSky"
                sky.Parent=Lighting
            end)
        end
        local function OptimizeLighting()
            Lighting.GlobalShadows=false
            Lighting.FogEnd=9e9
            Lighting.FogStart=9e9
            Lighting.EnvironmentDiffuseScale=0
            Lighting.EnvironmentSpecularScale=0
            Lighting.Brightness=1.5
            Lighting.Ambient=Color3.fromRGB(60, 60, 60)
            for _,v in ipairs(Lighting:GetChildren()) do
                local preserve = (NukeState.minecraftTextureEnabled and IsMinecraftLightingObject(v)) or IsVyxroProtectedLighting(v)
                if not preserve and (v:IsA("BloomEffect") or v:IsA("BlurEffect") or v:IsA("ColorCorrectionEffect") or v:IsA("SunRaysEffect") or v:IsA("DepthOfFieldEffect") or v:IsA("Atmosphere") or v:IsA("Clouds")) then
                    v:Destroy()
                end
            end
            ApplyGreySky()
        end
        local function ApplyTerrain()
            pcall(function() local T=workspace.Terrain; T.Decoration=false; T.WaterWaveSize=0; T.WaterWaveSpeed=0; T.WaterReflectance=0; T.WaterTransparency=1 end)
        end
        local function OptimizeCharacter(char)
            if not char then return end
            -- Do not optimize player characters at all: avatars and custom appearances
            -- must remain intact, regardless of whether their preset marker has loaded.
            if IsCharacterPart(char) then return end
            -- Local Ava Preset character is completely excluded from Nuke.
            if char == LP.Character and NukeSettings.avaPresetEnabled == true then return end
            if IsVyxroAvatarObject(char) then return end
            task.spawn(function()
                task.wait(0.3)
                if not _G.__SCVisionNukeOn then return end
                for _,obj in ipairs(char:GetDescendants()) do
                    if IsVyxroAvatarObject(obj) then
                    elseif IsMinecraftTextureObject(obj) then
                    elseif IsClothing(obj) then SafeDestroy(obj)
                    else CleanObject(obj) end
                end
                RefreshMinecraftAfterNuke()
            end)
        end
        pcall(function() settings().Rendering.QualityLevel=Enum.QualityLevel.Level01; settings().Rendering.MeshPartDetailLevel=Enum.MeshPartDetailLevel.Level01 end)
        pcall(function() if setfpscap then setfpscap(999) end end)

        table.insert(_G.__SCVisionNukeThreads,task.spawn(function()
            if not game:IsLoaded() then game.Loaded:Wait() end
            OptimizeLighting(); ApplyTerrain()
            if NukeState.minecraftTextureEnabled then pcall(minecraftCreateSkyAndAtmosphere) end
            for _,obj in ipairs(workspace:GetDescendants()) do
                if not _G.__SCVisionNukeOn then return end
                -- IMPORTANT: check local preset protection BEFORE IsClothing.
                -- Otherwise Shirt/Pants/Accessory are destroyed by the generic
                -- clothing branch before character protection can run.
                if IsCharacterPart(obj) or IsLocalAvaPresetObject(obj) or IsVyxroAvatarObject(obj) then
                elseif IsMinecraftTextureObject(obj) or IsMinecraftLightingObject(obj) then
                elseif IsBase(obj) then MakeTransparent(obj)
                elseif IsClothing(obj) then SafeDestroy(obj)
                elseif IsInBase(obj) then
                elseif IsOutOfRange(obj) then SafeDestroy(obj)
                else CleanObject(obj); StripObject(obj) end
            end
            if NukeState.minecraftTextureEnabled then RefreshMinecraftAfterNuke() end
        end))

        table.insert(_G.__SCVisionNukeConns,workspace.DescendantAdded:Connect(function(obj)
            if not _G.__SCVisionNukeOn then return end
            task.defer(function()
                if not _G.__SCVisionNukeOn then return end
                if IsCharacterPart(obj) then return end
                if IsLocalAvaPresetObject(obj) then return end
                if IsVyxroAvatarObject(obj) or IsVyxroProtectedLighting(obj) then return end
                if NukeSettings.avaPresetEnabled == true and LP.Character and obj:IsDescendantOf(LP.Character) then return end
                if IsMinecraftTextureObject(obj) or IsMinecraftLightingObject(obj) then return end
                if IsBase(obj) then MakeTransparent(obj); return end
                if IsClothing(obj) then SafeDestroy(obj)
                elseif IsInBase(obj) then
                elseif IsCharacterPart(obj) then
                elseif IsOutOfRange(obj) then SafeDestroy(obj)
                else CleanObject(obj); StripObject(obj) end
            end)
        end))

        table.insert(_G.__SCVisionNukeConns,Lighting.DescendantAdded:Connect(function(obj)
            if not _G.__SCVisionNukeOn then return end
            if IsVyxroProtectedLighting(obj) then return end
            if NukeState.minecraftTextureEnabled and IsMinecraftLightingObject(obj) then return end
            if obj:IsA("Atmosphere") or obj:IsA("Clouds") or obj:IsA("PostEffect") then SafeDestroy(obj) end
        end))

        table.insert(_G.__SCVisionNukeConns,MaterialService.DescendantAdded:Connect(function(obj)
            if not _G.__SCVisionNukeOn then return end
            SafeDestroy(obj)
        end))

        for _,plr in ipairs(Players:GetPlayers()) do
            OptimizeCharacter(plr.Character)
            table.insert(_G.__SCVisionNukeConns,plr.CharacterAdded:Connect(OptimizeCharacter))
        end
        table.insert(_G.__SCVisionNukeConns,Players.PlayerAdded:Connect(function(plr)
            table.insert(_G.__SCVisionNukeConns,plr.CharacterAdded:Connect(OptimizeCharacter))
        end))
        table.insert(_G.__SCVisionNukeThreads,task.spawn(function()
            while _G.__SCVisionNukeOn do
                task.wait(15)
                pcall(function() collectgarbage("collect") end)
                if NukeState.minecraftTextureEnabled then RefreshMinecraftAfterNuke() end
            end
        end))
        RefreshMinecraftAfterNuke()
    end
    
_G.__SCVisionNukeStop = function()
    _G.__SCVisionNukeOn = false

    for _, c in ipairs(_G.__SCVisionNukeConns) do
        pcall(function() c:Disconnect() end)
    end
    _G.__SCVisionNukeConns = {}
    _G.__SCVisionNukeThreads = {}
end

-- Optional convenience toggle.
_G.__SCVisionNukeToggle = function(enabled)
    if enabled then
        _G.__SCVisionNukeStart()
    else
        _G.__SCVisionNukeStop()
    end
end
end)()

S.startNukeOptimizer = function()
    local startFn = _G.__SCVisionNukeStart
    if type(startFn) == "function" then
        return startFn()
    end
end
S.stopNukeOptimizer = function()
    local stopFn = _G.__SCVisionNukeStop
    if type(stopFn) == "function" then
        return stopFn()
    end
end

