        local modeOptions = {TP_BAT_MODE_VISION, TP_BAT_MODE_ZERO, TP_BAT_MODE_ORBIT}
        local function changeTpBatMode(direction)
            local index = 1
            for i, mode in ipairs(modeOptions) do
                if mode == S.tpBatMode then index = i; break end
            end
            index = index + direction
