        local function setVisualOnly(n)
            n = math.clamp(tonumber(n) or 1.0, 0.50, 2.00)
            n = math.floor(n * 100 + 0.5) / 100
            local ratio = (n - 0.50) / 1.50
            valueLabel.Text = string.format("%.2f", n)
            box.Text = string.format("%.2f", n)
            fill.Size = UDim2.new(ratio, 0, 1, 0)
            knob.Position = UDim2.new(ratio, 0, 0.5, 0)
        end

        local function applyValue(n, persist)
            n = math.clamp(tonumber(n) or (S.mobileButtonScale or 1.0), 0.50, 2.00)
            n = math.floor(n * 100 + 0.5) / 100
            -- Set state and update actual buttons.
            S.mobileButtonScale = n
            if type(S.setMobileButtonScale) == "function" then
                pcall(S.setMobileButtonScale, n)
            end
            setVisualOnly(n)
            if persist then saveConfig() end
        end

        apply.MouseButton1Click:Connect(function()
            applyValue(tonumber(box.Text), true)
        end)
        box.FocusLost:Connect(function(enterPressed)
            -- On mobile, tapping the keyboard's Done may close the box without
            -- firing a MouseButton1Click, so both paths apply the same value.
            applyValue(tonumber(box.Text), true)
        end)

        local function ratioFromInput(input)
            local width = math.max(track.AbsoluteSize.X, 1)
            local x = input.Position.X - track.AbsolutePosition.X
            return math.clamp(x / width, 0, 1)
        end
        local dragging = false
        local function setFromRatio(ratio)
            local n = 0.50 + math.clamp(ratio, 0, 1) * 1.50
            applyValue(n, false)
        end
        local function beginSlider(input)
            dragging = true
            setFromRatio(ratioFromInput(input))
        end
        track.InputBegan:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.Touch or input.UserInputType == Enum.UserInputType.MouseButton1 then
                beginSlider(input)
            end
        end)
        knob.InputBegan:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.Touch or input.UserInputType == Enum.UserInputType.MouseButton1 then
                beginSlider(input)
            end
        end)
        UIS.InputChanged:Connect(function(input)
            if dragging and (input.UserInputType == Enum.UserInputType.Touch or input.UserInputType == Enum.UserInputType.MouseMovement) then
                setFromRatio(ratioFromInput(input))
            end
        end)
        UIS.InputEnded:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.Touch or input.UserInputType == Enum.UserInputType.MouseButton1 then
                if dragging then
                    dragging = false
                    saveConfig()
                end
            end
        end)

        S.mobileButtonScaleBox = box
        S.mobileButtonScaleSetVisual = setVisualOnly
        S.mobileButtonScaleApply = function(value)
            applyValue(value, true)
        end
        setVisualOnly(S.mobileButtonScale or 1.0)
    end

    -- A separate adjustable scale for the XYPHER Steal Bar HUD.
    -- It is intentionally set below 1.00 by default because the previous HUD
    -- filled too much of the mobile screen; users can still choose 0.50-2.00.
