        track.Position = UDim2.new(0, 154, 0, 40)
        track.BackgroundColor3 = Color3.fromRGB(33, 33, 33)
        track.BorderSizePixel = 0
        track.ZIndex = 6
        Instance.new("UICorner", track).CornerRadius = UDim.new(1, 0)

        local fill = Instance.new("Frame", track)
        fill.Name = "Fill"
        fill.Size = UDim2.fromScale((S.stealHudScale - 0.50) / 1.50, 1)
        fill.BackgroundColor3 = C_HIGHLIGHT
        fill.BorderSizePixel = 0
        fill.ZIndex = 7
        Instance.new("UICorner", fill).CornerRadius = UDim.new(1, 0)

        local knob = Instance.new("TextButton", track)
        knob.Name = "Knob"
        knob.Size = UDim2.fromOffset(18, 18)
        knob.AnchorPoint = Vector2.new(0.5, 0.5)
        knob.Position = UDim2.new((S.stealHudScale - 0.50) / 1.50, 0, 0.5, 0)
        knob.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
        knob.BorderSizePixel = 0
        knob.Text = ""
        knob.AutoButtonColor = false
        knob.ZIndex = 9
        Instance.new("UICorner", knob).CornerRadius = UDim.new(1, 0)
        local knobStroke = Instance.new("UIStroke", knob)
        knobStroke.Color = C_HIGHLIGHT
        knobStroke.Thickness = 1

        local function setVisualOnly(n)
            n = math.clamp(tonumber(n) or 0.55, 0.50, 2.00)
            n = math.floor(n * 100 + 0.5) / 100
            local ratio = (n - 0.50) / 1.50
            valueLabel.Text = string.format("%.2f", n)
            box.Text = string.format("%.2f", n)
            fill.Size = UDim2.new(ratio, 0, 1, 0)
            knob.Position = UDim2.new(ratio, 0, 0.5, 0)
        end

        local function applyValue(n, persist)
            n = math.clamp(tonumber(n) or (S.stealHudScale or 0.55), 0.50, 2.00)
            n = math.floor(n * 100 + 0.5) / 100
            S.stealHudScale = n
            setVisualOnly(n)
            if type(S.applyStealHudScale) == "function" then
                pcall(S.applyStealHudScale, n, persist ~= false)
            elseif persist ~= false then
                saveConfig()
            end
        end

        apply.MouseButton1Click:Connect(function()
            applyValue(tonumber(box.Text), true)
        end)
        box.FocusLost:Connect(function()
            applyValue(tonumber(box.Text), true)
        end)

        local function ratioFromInput(input)
            local width = math.max(track.AbsoluteSize.X, 1)
            local x = input.Position.X - track.AbsolutePosition.X
            return math.clamp(x / width, 0, 1)
        end
        local dragging = false
        local function setFromRatio(ratio)
            local n = 0.50 + math.clamp(ratio, 0, 1) * 1.50
