            end
        end)
        knob.InputBegan:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.Touch or input.UserInputType == Enum.UserInputType.MouseButton1 then
                dragging = true
                setFromRatio(ratioFromInput(input))
            end
        end)
        UIS.InputChanged:Connect(function(input)
            if dragging and (input.UserInputType == Enum.UserInputType.Touch or input.UserInputType == Enum.UserInputType.MouseMovement) then
                setFromRatio(ratioFromInput(input))
            end
        end)
        UIS.InputEnded:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.Touch or input.UserInputType == Enum.UserInputType.MouseButton1 then
                if dragging then
                    dragging = false
                    saveConfig()
                end
            end
        end)

        S.stealHudScaleBox = box
        S.stealHudScaleSetVisual = setVisualOnly
        S.stealHudScaleApply = function(value)
            applyValue(value, true)
        end
        setVisualOnly(S.stealHudScale or 0.55)
    end

    S.setStretchVisual, _ = mkToggle("Main", pages, "Stretch Rez", nil, S.stretchEnabled, function(on)
        if on then enableStretch() else disableStretch() end
        S.stretchEnabled = on
        saveConfig()
    end, nil)
    do
        local card = mkCard("Main", pages, 40)
        local label = Instance.new("TextLabel", card)
        label.Size = UDim2.new(0, 118, 1, 0)
        label.Position = UDim2.new(0, 12, 0, 0)
