        label.Font = Enum.Font.GothamBold
        label.TextSize = 11
        label.TextXAlignment = Enum.TextXAlignment.Left
        local selector = Instance.new("Frame", card)
        selector.Size = UDim2.new(0, 142, 1, 0)
        selector.Position = UDim2.new(1, -152, 0, 0)
        selector.BackgroundTransparency = 1
        local function makeSkyButton(text, x)
            local button = Instance.new("TextButton", selector)
            button.Size = UDim2.new(0, 22, 0, 24)
            button.Position = UDim2.new(0, x, 0.5, -12)
            button.BackgroundTransparency = 1
            button.BorderSizePixel = 0
            button.Text = text
            button.TextColor3 = C_WHITE
            button.Font = Enum.Font.GothamBold
            button.TextSize = 13
            button.AutoButtonColor = false
            button.ZIndex = 10
            return button
        end
        local left = makeSkyButton("<", 0)
        S.skySelectorLabel = Instance.new("TextLabel", selector)
        S.skySelectorLabel.Size = UDim2.new(0, 90, 0, 24)
        S.skySelectorLabel.Position = UDim2.new(0, 26, 0.5, -12)
        S.skySelectorLabel.BackgroundTransparency = 1
        S.skySelectorLabel.Text = S.skyTheme
        S.skySelectorLabel.TextColor3 = C_WHITE
        S.skySelectorLabel.Font = Enum.Font.GothamBold
        S.skySelectorLabel.TextSize = 10
        S.skySelectorLabel.TextXAlignment = Enum.TextXAlignment.Center
        S.skySelectorLabel.TextTruncate = Enum.TextTruncate.AtEnd
        S.skySelectorLabel.ZIndex = 9
        local right = makeSkyButton(">", 120)
        local function changeSky(direction)
            local index = 1
            for i, name in ipairs(SKY_PRESETS_LIST) do
                if name == S.skyTheme then index = i; break end
            end
            index = index + direction
            if index < 1 then index = #SKY_PRESETS_LIST end
            if index > #SKY_PRESETS_LIST then index = 1 end
            local name = SKY_PRESETS_LIST[index]
            pcall(applyCustomSky, name)
            S.skyTheme = name
            S.skySelectorLabel.Text = name
            saveConfig()
        end
        left.MouseButton1Click:Connect(function() changeSky(-1) end)
        right.MouseButton1Click:Connect(function() changeSky(1) end)
    end
    mkSection("Main", pages, "Character / Performance")
    do
        local card = mkCard("Main", pages, 40)
        local title = Instance.new("TextLabel", card)
        title.Size = UDim2.new(0, 100, 1, 0)
        title.Position = UDim2.new(0, 12, 0, 0)
        title.BackgroundTransparency = 1
        title.Text = "Anim Pack"
        title.TextColor3 = C_WHITE
        title.Font = Enum.Font.GothamBold
        title.TextSize = 11
        title.TextXAlignment = Enum.TextXAlignment.Left
        local selector = Instance.new("Frame", card)
        selector.Size = UDim2.new(0, 142, 1, 0)
        selector.Position = UDim2.new(1, -152, 0, 0)
        selector.BackgroundTransparency = 1
        local function makeAnimButton(text, x)
            local button = Instance.new("TextButton", selector)
            button.Size = UDim2.new(0, 22, 0, 24)
            button.Position = UDim2.new(0, x, 0.5, -12)
            button.BackgroundTransparency = 1
            button.BorderSizePixel = 0
            button.Text = text
            button.TextColor3 = C_WHITE
            button.Font = Enum.Font.GothamBold
            button.TextSize = 13
            button.AutoButtonColor = false
            button.ZIndex = 10
            return button
        end
        local left = makeAnimButton("<", 0)
        S.animSelectorLabel = Instance.new("TextLabel", selector)
        S.animSelectorLabel.Size = UDim2.new(0, 90, 0, 24)
        S.animSelectorLabel.Position = UDim2.new(0, 26, 0.5, -12)
        S.animSelectorLabel.BackgroundTransparency = 1
        S.animSelectorLabel.Text = S.currentAnimPack
        S.animSelectorLabel.TextColor3 = C_WHITE
        S.animSelectorLabel.Font = Enum.Font.GothamBold
        S.animSelectorLabel.TextSize = 10
        S.animSelectorLabel.TextXAlignment = Enum.TextXAlignment.Center
        S.animSelectorLabel.TextTruncate = Enum.TextTruncate.AtEnd
        S.animSelectorLabel.ZIndex = 9
        local right = makeAnimButton(">", 120)
        local function changeAnimPack(direction)
            local index = 1
            for i, entry in ipairs(YF.ANIM_PACK_ORDER) do
                if entry[2] == S.currentAnimPack then index = i; break end
            end
            index = index + direction
            if index < 1 then index = #YF.ANIM_PACK_ORDER end
            if index > #YF.ANIM_PACK_ORDER then index = 1 end
            local packName = YF.ANIM_PACK_ORDER[index][2]
            if packName == "Off" then YF.stopAnimPack() else YF.startAnimPack(packName) end
            if S.animSelectorLabel then S.animSelectorLabel.Text = packName end
            saveConfig()
        end
        left.MouseButton1Click:Connect(function() changeAnimPack(-1) end)
        right.MouseButton1Click:Connect(function() changeAnimPack(1) end)
    end
    S.setAntiLagVisual, _ = mkToggle("Main", pages, "Anti Lag", nil, S.antiLagEnabled, function(on)
        if on then YF.enableAntiLag() else YF.disableAntiLag() end
        saveConfig()
    end, nil)
    mkSection("Main", pages, "Utility")
    S.setUnwalkVisual, _ = mkToggle("Main", pages, "Unwalk", nil, S.unwalkEnabled, function(on)
        if on then startUnwalk() else stopUnwalk() end; saveConfig()
    end, nil)
    S.setAntiRagVisual, _ = mkToggle("Main", pages, "Anti Ragdoll", nil, S.antiRagdollEnabled, function(on)
        toggleAntiRag(on); saveConfig()
    end, nil)
    S.ragdollStealSetVisual, _ = mkToggle("Main", pages, "Ragdoll Steal", nil, S.ragdollStealEnabled == true, function(on)
        S.ragdollStealEnabled = on == true
        local fn = _G.__VisionRagdollStealSet
        if type(fn) == "function" then pcall(fn, S.ragdollStealEnabled) end
        saveConfig()
    end, nil)
    mkSection("Main", pages, "Actions")
    mkActionRow("Main", pages, "Instant Reset", S.KB.InstaReset, function()
        if _G.InstaReset and _G.InstaReset.Trigger then _G.InstaReset.Trigger() end
    end)
end

local function buildMoveTab(pages)
    mkSection("Move", pages, "Auto Path")
    local setALVis, _ = mkToggle("Move", pages, "Auto Left", S.KB.AutoLeft.kb, false, function(on)
        S.autoLeftEnabled=on
        if on then
            if S.autoRightEnabled then S.autoRightEnabled=false; stopAutoRight(); if S.autoRightSetVisual then S.autoRightSetVisual(false) end end
            if S.batAimbotEnabled then setBatAimbot(false) end
            startAutoLeft()
        else stopAutoLeft() end
        if S.autoLeftSetVisual then S.autoLeftSetVisual(on) end
        S.restartMovement(); updateFloatingButtons(); saveConfig()
    end, function(k,isGp)
        if isGp then S.KB.AutoLeft.gp=k; S.KB.AutoLeft.kb=nil
        else S.KB.AutoLeft.kb=k; S.KB.AutoLeft.gp=nil end; saveConfig()
    end)
    S.autoLeftSetVisual = setALVis
    local setARVis, _ = mkToggle("Move", pages, "Auto Right", S.KB.AutoRight.kb, false, function(on)
        S.autoRightEnabled=on
        if on then
            if S.autoLeftEnabled then S.autoLeftEnabled=false; stopAutoLeft(); if S.autoLeftSetVisual then S.autoLeftSetVisual(false) end end
            if S.batAimbotEnabled then setBatAimbot(false) end
            startAutoRight()
        else stopAutoRight() end
        if S.autoRightSetVisual then S.autoRightSetVisual(on) end
        S.restartMovement(); updateFloatingButtons(); saveConfig()
    end, function(k,isGp)
        if isGp then S.KB.AutoRight.gp=k; S.KB.AutoRight.kb=nil
        else S.KB.AutoRight.kb=k; S.KB.AutoRight.gp=nil end; saveConfig()
    end)
    S.autoRightSetVisual = setARVis
    mkSection("Move", pages, "Steal")
    local setStealVis, _ = mkToggle("Move", pages, "Auto Steal", nil, S.stealActive, function(on)
        S.stealActive = on
        if on then startAutoSteal() else stopAutoSteal() end
        saveConfig()
    end, nil)
    S.setInstaGrab = setStealVis
    S.radInput = mkInput("Move", pages, "Steal Radius", S.Steal.StealRadius, function(v)
        if v>=1 and v<=300 then S.Steal.StealRadius=math.floor(v) end; saveConfig()
    end)
    S.stealDurationBox = mkInput("Move", pages, "Steal Duration", S.Steal.StealDuration, function(v)
        if tonumber(v) then setStealDuration(v); saveConfig() end
    end)
    mkSection("Move", pages, "Actions")
    mkActionRow("Move", pages, "Drop Brainrot", S.KB.DropBrainrot, runDropBrainrot)
    mkActionRow("Move", pages, "TP Down",       S.KB.TPFlor,       runTPFloor)
end

local function buildKeybindsTab(pages)
    mkSection("Keybinds", pages, "Keybind")
    mkActionRow("Keybinds", pages, "Hide GUI",       S.KB.GuiHide,      nil)
    mkActionRow("Keybinds", pages, "Carry Mode",     S.KB.SpeedToggle,  function() S.toggleCarryMode(); S.restartMovement(); updateFloatingButtons(); saveConfig() end)
    mkActionRow("Keybinds", pages, "Lagger Mode",    S.KB.LaggerToggle, function() S.toggleLaggerMode(); S.restartMovement(); updateFloatingButtons(); saveConfig() end)
    mkActionRow("Keybinds", pages, "Bat Aimbot",     S.KB.AutoBat,      function() setBatAimbot(not S.batAimbotEnabled) end)
    mkActionRow("Keybinds", pages, "TP Bat",         S.KB.TpBat,        function()
        local enabled = not S.tpBatEnabled
        setTpBat(enabled)
        if S.tpBatSetVisual then S.tpBatSetVisual(enabled) end
        saveConfig()
    end)
    mkActionRow("Keybinds", pages, "Auto Left",      S.KB.AutoLeft,     function()
        S.autoLeftEnabled=not S.autoLeftEnabled
        if S.autoLeftEnabled then if S.autoRightEnabled then S.autoRightEnabled=false; stopAutoRight(); if S.autoRightSetVisual then S.autoRightSetVisual(false) end end; startAutoLeft() else stopAutoLeft() end
        if S.autoLeftSetVisual then S.autoLeftSetVisual(S.autoLeftEnabled) end; updateFloatingButtons(); saveConfig()
    end)
    mkActionRow("Keybinds", pages, "Auto Right",     S.KB.AutoRight,    function()
        S.autoRightEnabled=not S.autoRightEnabled
        if S.autoRightEnabled then if S.autoLeftEnabled then S.autoLeftEnabled=false; stopAutoLeft(); if S.autoLeftSetVisual then S.autoLeftSetVisual(false) end end; startAutoRight() else stopAutoRight() end
        if S.autoRightSetVisual then S.autoRightSetVisual(S.autoRightEnabled) end; updateFloatingButtons(); saveConfig()
    end)
    mkActionRow("Keybinds", pages, "Drop Brainrot",  S.KB.DropBrainrot, runDropBrainrot)
    mkActionRow("Keybinds", pages, "TP Down",        S.KB.TPFlor,       runTPFloor)
    mkActionRow("Keybinds", pages, "Instant Reset", S.KB.InstaReset, function()
        if _G.InstaReset and _G.InstaReset.Trigger then _G.InstaReset.Trigger() end
    end)
end

local function resetConfigToDefaults()
    if type(S.stopNukeOptimizer) == "function" then pcall(S.stopNukeOptimizer) end
    S.nukeOptimizerEnabled = false
    pcall(stopAutoSteal)
    pcall(stopBatCounter)
    pcall(stopBatCounterV2)
    pcall(stopMedusaCounter)
    pcall(stopUnwalk)
    pcall(stopHoldJump)
    pcall(stopAutoLeft)
    pcall(stopAutoRight)
    pcall(stopBatAimbot)
    pcall(stopAntiBatBypass)
    pcall(setTpBat, false)
    pcall(stopAntiRagdoll)
    S.ragdollStealEnabled = false
    S.shinyGraphicsEnabled = false
    pcall(function() if type(_G.__VisionRagdollStealSet) == "function" then _G.__VisionRagdollStealSet(false) end end)
    pcall(function() if type(_G.__VisionShinySet) == "function" then _G.__VisionShinySet(false) end end)
    pcall(stopFPSBoost)
    pcall(YF.stopAntiFling)
    pcall(YF.stopBodyLock)
    pcall(YF.disableAntiLag)
    pcall(YF.stopAnimPack)
    pcall(disableStretch)
    pcall(disableVividGraphics)
    pcall(toggleESP, false)

    S.NS, S.CS, S.LS, S.LCS = 70, 45, 22, 22
    S.speedMode, S.laggerMode = false, 0
    S.antiRagdollEnabled = false
    S.medusaCounterEnabled = false
    S.unwalkEnabled = false
    S.autoLeftEnabled, S.autoRightEnabled = false, false
    S.batAimbotEnabled, S.batCounterEnabled = false, false
    S.batCounterV2Enabled = false
    S.tpBatMode = TP_BAT_MODE_VISION
    if S.tpBatModeSelectorLabel then S.tpBatModeSelectorLabel.Text = S.tpBatMode end
    S.antiBatAimbotEnabled = false
    S.fpsBoostEnabled = false
    S.stealActive = false
    S.espEnabled = false
    S.antiFlingEnabled = false
    S.bodyLockEnabled, S.bodyLockRange = false, 20
    S.antiLagEnabled = false
    S.vividGraphicsEnabled = false
    S.stretchEnabled, S.stretchFOV = false, 120
    S.skyTheme, S.krobloxMode = "Off", "Off"
    if S.setBatSkin then pcall(S.setBatSkin, "Off", false) end
    S.batSkinMode = "Off"
    if S.setDisplaySkin then pcall(S.setDisplaySkin, "Off", false) else S.displaySkin="Off"; S.customSkinEnabled=false end
    S.currentAnimPack = "Off"
    S.hideOpiumButtonsEnabled = false
    S.lockUIEnabled = false
    pcall(setUILock, false)
    if S.setLockUI_Visual2 then
        pcall(S.setLockUI_Visual2, false)
    end
    S.Steal.StealRadius, S.Steal.StealDuration = 61, 1.3
    S.tpDownHeightTrigger = 20
    local function resetKey(name, kb, gp)
        if S.KB[name] then S.KB[name].kb, S.KB[name].gp = kb, gp end
    end
    resetKey("DropBrainrot", Enum.KeyCode.X, Enum.KeyCode.ButtonR2)
    resetKey("AutoLeft", Enum.KeyCode.Z, Enum.KeyCode.DPadLeft)
    resetKey("AutoRight", Enum.KeyCode.C, Enum.KeyCode.DPadRight)
    resetKey("AutoBat", Enum.KeyCode.E, Enum.KeyCode.ButtonY)
    resetKey("TpBat", Enum.KeyCode.V, nil)
    resetKey("TPFlor", Enum.KeyCode.F, Enum.KeyCode.ButtonA)
    resetKey("GuiHide", Enum.KeyCode.LeftControl, Enum.KeyCode.ButtonSelect)
    resetKey("SpeedToggle", Enum.KeyCode.Q, Enum.KeyCode.DPadUp)
    resetKey("LaggerToggle", Enum.KeyCode.R, Enum.KeyCode.DPadDown)
    resetKey("InstaReset", Enum.KeyCode.H, nil)
    S.backgroundAssetId = DEFAULT_BACKGROUND_ID
    S.stealPhotoAssetId = nil
    setStealPhotoImage(nil)
    for _, setter in pairs(S.stealPhotoToggleSetters or {}) do
        if type(setter) == "function" then pcall(setter, false) end
    end
    S.openBackgroundOptions = true
    if type(S.setBackgroundOptionsVisible) == "function" then
        pcall(S.setBackgroundOptionsVisible, true)
    end
    if S.setOpenBackgroundVisual then pcall(S.setOpenBackgroundVisual, true) end
    S.mobileButtonPositions = {}
    S.floatingFreeButtonPositions = {}

    pcall(applyCustomSky, "Off")
    pcall(_G._VisionApplyKroblox, "Off")
    if S.displaySkinSelectorLabel then S.displaySkinSelectorLabel.Text="Off" end
    if S.customSkinVisual then S.customSkinVisual(false) end
    pcall(setUILock, false)
    if S.floatingPanelGui then S.floatingPanelGui.Enabled = true end
    pcall(function()
        local pg = LP:FindFirstChild("PlayerGui")
        local old = pg and pg:FindFirstChild("OpiumGGV5_2")
        if old then old.Enabled = true end
    end)
    if S.backgroundImage then
        applyXypherGuiBackground(S.backgroundImage, S.backgroundAssetId or DEFAULT_BACKGROUND_ID, 0.20)
    end
    if S.speedClk then S.speedClk(false) end
    if S.setLaggerVisual then S.setLaggerVisual(false) end
    if S.setAntiRagVisual then S.setAntiRagVisual(false) end
    if S.ragdollStealSetVisual then S.ragdollStealSetVisual(false) end
    if S.shinyGraphicsSetVisual then S.shinyGraphicsSetVisual(false) end
    if S.mobileButtonLargeVisual then S.mobileButtonLargeVisual(false) end
    if S.mobileButtonSmallVisual then S.mobileButtonSmallVisual(false) end
    pcall(S.setMobileButtonScale, 1.0)
    if S.setFpsVisual then S.setFpsVisual(false) end
    if S.setNukeOptimizerVisual then pcall(S.setNukeOptimizerVisual, false) end
    if S.setBatCounterVisual then S.setBatCounterVisual(false) end
    if S.batAimbotSetVisual then S.batAimbotSetVisual(false) end
    if S.antiBatAimbotSetVisual then S.antiBatAimbotSetVisual(false) end
    if S.tpBatSetVisual then S.tpBatSetVisual(false) end
    if S.autoLeftSetVisual then S.autoLeftSetVisual(false) end
    if S.autoRightSetVisual then S.autoRightSetVisual(false) end
    if S.setAntiFlingVisual then S.setAntiFlingVisual(false) end
    if S.bodyLockSetVisual then S.bodyLockSetVisual(false) end
    if S.setVividVisual then S.setVividVisual(false) end
    if S.setStretchVisual then S.setStretchVisual(false) end
    if S.setMedusaVisual then S.setMedusaVisual(false) end
    if S.setUnwalkVisual then S.setUnwalkVisual(false) end
    if S.setAntiLagVisual then S.setAntiLagVisual(false) end
    if S.setHideOpiumButtons2 then S.setHideOpiumButtons2(false) end
    S.refreshSpeedModeLabel()
    resetFloatingPanel()
    if updateFloatingButtons then updateFloatingButtons() end
    saveConfig()
end

local function buildConfigTab(pages)
    mkSection("Config", pages, "General")
    S.setLockUI_Visual2, _ = mkToggle("Config", pages, "Lock UI", nil, S.lockUIEnabled or false, function(on)
        S.lockUIEnabled=on; setUILock(on); saveConfig()
    end, nil)
    S.setHideOpiumButtons2, _ = mkToggle("Config", pages, "Hide Buttons", nil, S.hideOpiumButtonsEnabled or false, function(on)
        S.hideOpiumButtonsEnabled=on
        if S.floatingPanelGui then S.floatingPanelGui.Enabled=not on end
        pcall(function()
            local pg=LP:FindFirstChild("PlayerGui")
            if pg then local og=pg:FindFirstChild("OpiumGGV5_2"); if og then og.Enabled=not on end end
        end)
        saveConfig()
    end, nil)
    mkSection("Config", pages, "Background")
    local backgroundCard = mkCard("Config", pages, 158)
    backgroundCard.Name = "BackgroundImagesCard"
    backgroundCard.ClipsDescendants = true
    backgroundCard.ZIndex = 20
    local tileWidth, tileHeight, tileGap = 96, 96, 10
    local selectedStrokes = {}

    local bgHint = Instance.new("TextLabel", backgroundCard)
    bgHint.Name = "BackgroundImagesHint"
    bgHint.Size = UDim2.new(1, -20, 0, 16)
    bgHint.Position = UDim2.fromOffset(10, 5)
    bgHint.BackgroundTransparency = 1
    bgHint.Text = "BACKGROUND IMAGES   •   SWIPE ← →"
    bgHint.TextColor3 = C_HIGHLIGHT
    bgHint.Font = Enum.Font.GothamBold
    bgHint.TextSize = 8
    bgHint.TextXAlignment = Enum.TextXAlignment.Left
    bgHint.ZIndex = 24

    -- Dedicated horizontal background gallery.
    -- Use Roblox's native ScrollingFrame touch scrolling only. The previous
    -- custom touch handlers conflicted with ImageButtons and could prevent
    -- horizontal movement on mobile executors.
    local bgScroll = Instance.new("ScrollingFrame", backgroundCard)
    bgScroll.Name = "BackgroundGallery"
    bgScroll.Position = UDim2.fromOffset(8, 24)
    bgScroll.Size = UDim2.new(1, -16, 1, -32)
    bgScroll.BackgroundTransparency = 1
    bgScroll.BorderSizePixel = 0
    bgScroll.ScrollBarThickness = 0
    bgScroll.ScrollBarImageTransparency = 1
    bgScroll.Active = true
    bgScroll.Selectable = false
    bgScroll.ClipsDescendants = true
    bgScroll.ScrollingEnabled = true
    bgScroll.ScrollingDirection = Enum.ScrollingDirection.X
    bgScroll.ElasticBehavior = Enum.ElasticBehavior.Always
    bgScroll.AutomaticCanvasSize = Enum.AutomaticSize.None
    bgScroll.CanvasPosition = Vector2.new(0, 0)
    bgScroll.ZIndex = 21

    local bgLayout = Instance.new("UIListLayout", bgScroll)
    bgLayout.FillDirection = Enum.FillDirection.Horizontal
    bgLayout.SortOrder = Enum.SortOrder.LayoutOrder
    bgLayout.VerticalAlignment = Enum.VerticalAlignment.Center
    bgLayout.Padding = UDim.new(0, tileGap)

    local bgPadding = Instance.new("UIPadding", bgScroll)
    bgPadding.PaddingLeft = UDim.new(0, 3)
    bgPadding.PaddingRight = UDim.new(0, 3)

    -- Give the gallery a deterministic canvas width so every
    -- background is reachable, even before AbsoluteContentSize updates.
    local totalBackgroundWidth = (#BACKGROUND_OPTIONS * tileWidth)
        + (math.max(0, #BACKGROUND_OPTIONS - 1) * tileGap)
        + bgPadding.PaddingLeft.Offset + bgPadding.PaddingRight.Offset
    bgScroll.CanvasSize = UDim2.fromOffset(totalBackgroundWidth, 0)

    local function syncBackgroundCanvas()
        local contentWidth = (#BACKGROUND_OPTIONS * tileWidth)
            + (math.max(0, #BACKGROUND_OPTIONS - 1) * tileGap)
            + bgPadding.PaddingLeft.Offset + bgPadding.PaddingRight.Offset + 2
        local viewportWidth = bgScroll.AbsoluteSize.X
        bgScroll.CanvasSize = UDim2.fromOffset(math.max(contentWidth, viewportWidth), 0)
        -- Keep the current horizontal position valid after the viewport changes.
        local maxX = math.max(0, contentWidth - viewportWidth)
        if bgScroll.CanvasPosition.X > maxX then
            bgScroll.CanvasPosition = Vector2.new(maxX, 0)
        end
    end
    bgScroll:GetPropertyChangedSignal("AbsoluteSize"):Connect(syncBackgroundCanvas)

    local function selectBackground(assetId)
        local valid = false
        for _, optionId in ipairs(BACKGROUND_OPTIONS) do
            if assetId == optionId then valid = true; break end
        end
        if not valid then return end

        S.backgroundAssetId = assetId
        if S.backgroundImage then
            applyXypherGuiBackground(S.backgroundImage, assetId, 0.20)
        end
        for optionIndex, stroke in ipairs(selectedStrokes) do
            local selected = BACKGROUND_OPTIONS[optionIndex] == assetId
            stroke.Color = selected and C_WHITE or C_SEPARATOR_GRAY
            stroke.Thickness = selected and 3 or 1
            stroke.Transparency = selected and 0 or 0.3
        end
        saveConfig()
    end

    for index, assetId in ipairs(BACKGROUND_OPTIONS) do
        local tile = Instance.new("ImageButton", bgScroll)
        tile.Name = "BackgroundOption" .. index
        tile.Size = UDim2.fromOffset(tileWidth, tileHeight)
        tile.LayoutOrder = index
        tile.BackgroundColor3 = C_CARD
        tile.BackgroundTransparency = 0
        tile.BorderSizePixel = 0
        if assetId == XYPHER_VIDEO_BG_OPTION then
            tile.Image = ensureXypherVideoFrameAsset(1) or ""
        elseif assetId == XYPHER_UPLOADED_PHOTO_OPTION or assetId == XYPHER_UPLOADED_PHOTO_OPTION_2 or assetId == XYPHER_UPLOADED_PHOTO_OPTION_3 or assetId == XYPHER_UPLOADED_PHOTO_OPTION_4 then
            tile.Image = ensureXypherUploadedPhotoAsset(assetId) or ""
        else
            tile.Image = "rbxthumb://type=Asset&id=" .. assetId .. "&w=420&h=420"
        end
        tile.ScaleType = Enum.ScaleType.Crop
        tile.AutoButtonColor = false
        tile.Selectable = false
        tile.Active = true
        tile.ZIndex = 22
        Instance.new("UICorner", tile).CornerRadius = UDim.new(0, 10)

        local stroke = Instance.new("UIStroke", tile)
        stroke.Color = (S.backgroundAssetId == assetId) and C_WHITE or C_SEPARATOR_GRAY
        stroke.Thickness = (S.backgroundAssetId == assetId) and 3 or 1
        stroke.Transparency = (S.backgroundAssetId == assetId) and 0 or 0.3
        selectedStrokes[index] = stroke

        local number = Instance.new("TextLabel", tile)
        number.Name = "OptionNumber"
        number.AnchorPoint = Vector2.new(0.5, 1)
        number.Position = UDim2.new(0.5, 0, 1, -4)
        number.Size = UDim2.new(1, -10, 0, 22)
        number.BackgroundTransparency = 1
        number.Text = assetId == XYPHER_VIDEO_BG_OPTION and "VIDEO" or tostring(index)
        number.TextColor3 = Color3.fromRGB(255, 255, 255)
        number.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
        number.TextStrokeTransparency = 0.15
        number.Font = Enum.Font.GothamBold
        number.TextSize = 16
        number.ZIndex = 23

        tile.Activated:Connect(function()
            selectBackground(assetId)
        end)

        -- A thumbnail can fail for some image assets; use the direct asset URI as fallback.
        task.spawn(function()
            local deadline = os.clock() + 2.4
            while os.clock() < deadline and tile.Parent do
                local ok, loaded = pcall(function() return tile.IsLoaded end)
                if ok and loaded then return end
                task.wait(0.12)
            end
            if tile.Parent and not tile.IsLoaded then
                if assetId == XYPHER_UPLOADED_PHOTO_OPTION or assetId == XYPHER_UPLOADED_PHOTO_OPTION_2 or assetId == XYPHER_UPLOADED_PHOTO_OPTION_3 or assetId == XYPHER_UPLOADED_PHOTO_OPTION_4 then
                    tile.Image = ensureXypherUploadedPhotoAsset(assetId) or ""
                else
                    tile.Image = "rbxassetid://" .. assetId
                end
            end
        end)
    end

    task.defer(function()
        syncBackgroundCanvas()
        bgScroll.CanvasPosition = Vector2.new(0, 0)
    end)

    -- Extra breathing room after the gallery keeps the following toggles/cards
    -- physically separated from the image strip on small phone screens.
    rowCounts["Config"] = rowCounts["Config"] + 1
    local bgSpacer = Instance.new("Frame", pages["Config"])
    bgSpacer.Name = "BackgroundGallerySpacer"
    bgSpacer.Size = UDim2.new(1, 0, 0, 10)
    bgSpacer.BackgroundTransparency = 1
    bgSpacer.BorderSizePixel = 0
    bgSpacer.LayoutOrder = rowCounts["Config"]

    mkSection("Config", pages, "Config")
    local function addConfigManagementButton(text, callback, mode)
        local card = mkCard("Config", pages, 44)
        card.ZIndex = 2
        local button = Instance.new("TextButton", card)
        button.Name = "ConfigManagement_" .. text:gsub("%s+", "")
        button.Size = UDim2.new(1, -20, 0.82, 0)
        button.Position = UDim2.new(0, 10, 0.09, 0)
        button.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
        button.BorderSizePixel = 0
        button.Text = ""
        button.AutoButtonColor = false
        button.ZIndex = 8
        Instance.new("UICorner", button).CornerRadius = UDim.new(1, 0)

        local gradient = Instance.new("UIGradient", button)
        gradient.Rotation = 90
        if mode == "save" then
            gradient.Color = ColorSequence.new({
                ColorSequenceKeypoint.new(0.00, Color3.fromRGB(121, 121, 121)),
                ColorSequenceKeypoint.new(0.50, Color3.fromRGB(61, 61, 61)),
                ColorSequenceKeypoint.new(1.00, Color3.fromRGB(21, 21, 21)),
            })
        elseif mode == "reset" then
            gradient.Color = ColorSequence.new({
                ColorSequenceKeypoint.new(0.00, Color3.fromRGB(89, 89, 89)),
                ColorSequenceKeypoint.new(0.50, Color3.fromRGB(54, 54, 54)),
                ColorSequenceKeypoint.new(1.00, Color3.fromRGB(22, 22, 22)),
            })
        else
            gradient.Color = ColorSequence.new({
                ColorSequenceKeypoint.new(0.00, Color3.fromRGB(89, 89, 89)),
                ColorSequenceKeypoint.new(0.50, Color3.fromRGB(57, 57, 57)),
                ColorSequenceKeypoint.new(1.00, Color3.fromRGB(27, 27, 27)),
            })
        end

        local stroke = Instance.new("UIStroke", button)
        stroke.Thickness = 1.5
        stroke.Transparency = 0.35
        stroke.Color = mode == "save" and Color3.fromRGB(202, 202, 202)
            or mode == "reset" and Color3.fromRGB(172, 172, 172)
            or Color3.fromRGB(172, 172, 172)

        local label = Instance.new("TextLabel", button)
        label.Size = UDim2.new(1, 0, 1, 0)
        label.BackgroundTransparency = 1
        label.Text = text
        label.TextColor3 = Color3.fromRGB(255, 255, 255)
        label.Font = Enum.Font.GothamBlack
        label.TextSize = 13
        label.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
        label.TextStrokeTransparency = 0.55
        label.ZIndex = 9

        button.MouseEnter:Connect(function()
            TS_G:Create(button, TweenInfo.new(0.14, Enum.EasingStyle.Quad), {
                Size = UDim2.new(1, -12, 0.92, 0),
                Position = UDim2.new(0, 6, 0.04, 0),
            }):Play()
            TS_G:Create(stroke, TweenInfo.new(0.14), {Transparency = 0.05}):Play()
        end)
        button.MouseLeave:Connect(function()
            TS_G:Create(button, TweenInfo.new(0.14, Enum.EasingStyle.Quad), {
                Size = UDim2.new(1, -20, 0.82, 0),
                Position = UDim2.new(0, 10, 0.09, 0),
            }):Play()
            TS_G:Create(stroke, TweenInfo.new(0.14), {Transparency = 0.35}):Play()
        end)

        if mode == "save" then
            button.MouseButton1Click:Connect(function()
                local ok = pcall(saveConfig)
                label.Text = ok and "SAVED ✓" or "ERROR"
                task.delay(1.2, function()
                    if label and label.Parent then label.Text = text end
                end)
            end)
        elseif mode == "reset" then
            local resetDebounce = false
            button.MouseButton1Click:Connect(function()
                if resetDebounce then return end
                resetDebounce = true
                pcall(resetFloatingPanel)
                label.Text = "RESET ✓"
                task.delay(1.2, function()
                    if label and label.Parent then
                        label.Text = text
                        resetDebounce = false
                    end
                end)
            end)
        else
            local deleteState = 0
            local deleteDebounce = false
            button.MouseButton1Click:Connect(function()
                if deleteDebounce then return end
                if deleteState == 0 then
                    deleteState = 1
                    label.Text = "CONFIRM?"
                    gradient.Color = ColorSequence.new({
                        ColorSequenceKeypoint.new(0.00, Color3.fromRGB(121, 121, 121)),
                        ColorSequenceKeypoint.new(0.50, Color3.fromRGB(85, 85, 85)),
                        ColorSequenceKeypoint.new(1.00, Color3.fromRGB(40, 40, 40)),
                    })
                    task.delay(2, function()
                        if button and button.Parent and deleteState == 1 then
                            deleteState = 0
                            label.Text = text
                            gradient.Color = ColorSequence.new({
                                ColorSequenceKeypoint.new(0.00, Color3.fromRGB(89, 89, 89)),
                                ColorSequenceKeypoint.new(0.50, Color3.fromRGB(57, 57, 57)),
                                ColorSequenceKeypoint.new(1.00, Color3.fromRGB(27, 27, 27)),
                            })
                        end
                    end)
                else
                    deleteDebounce = true
                    local ok = pcall(resetConfigToDefaults)
                    label.Text = ok and "DELETED ✓" or "ERROR"
                    deleteState = 0
                    task.delay(1.5, function()
                        if label and label.Parent then
                            label.Text = text
                            gradient.Color = ColorSequence.new({
                                ColorSequenceKeypoint.new(0.00, Color3.fromRGB(89, 89, 89)),
                                ColorSequenceKeypoint.new(0.50, Color3.fromRGB(57, 57, 57)),
                                ColorSequenceKeypoint.new(1.00, Color3.fromRGB(27, 27, 27)),
                            })
                            deleteDebounce = false
                        end
                    end)
                end
            end)
        end
        return button
    end
    addConfigManagementButton("SAVE CONFIG", saveConfig, "save")
    addConfigManagementButton("RESET POSITIONS", resetFloatingPanel, "reset")
    addConfigManagementButton("DELETE SETTINGS", resetConfigToDefaults, "delete")
end -- close buildConfigTab

-- Disable health bar
pcall(function() game:GetService("StarterGui"):SetCoreGuiEnabled(Enum.CoreGuiType.Health, false) end)
LP.CharacterAdded:Connect(function()
    pcall(function() game:GetService("StarterGui"):SetCoreGuiEnabled(Enum.CoreGuiType.Health, false) end)
end) -- close LP.CharacterAdded:Connect

local function buildGui()
    S._xypherBuildReady = false
    S._xypherOpenPending = false
    -- Forward declare these before creating the independent launcher. The launcher
    -- is deliberately a separate ScreenGui so hiding/resizing Outer can never hide it.
    local showGui, hideGui

    local CoreGuiService = game:GetService("CoreGui")
    local playerGui = LP:WaitForChild("PlayerGui")
    for _, host in ipairs({CoreGuiService, playerGui}) do
        pcall(function()
            local existingMain = host:FindFirstChild("Vision")
            if existingMain then existingMain:Destroy() end
            local existingLauncher = host:FindFirstChild("XYPHER_OpenLauncher")
            if existingLauncher then existingLauncher:Destroy() end
            local existingCrosshair = host:FindFirstChild("XYPHER_CustomCrosshair")
            if existingCrosshair then existingCrosshair:Destroy() end
        end)
    end

    local gui = Instance.new("ScreenGui")
    gui.Name = "Vision"; gui.ResetOnSpawn = false
    -- Keep the dashboard above mobile buttons and the Steal Bar.
    -- The reopen launcher remains independent but sits below the dashboard.
    gui.DisplayOrder = 1000001; gui.IgnoreGuiInset = true
    gui.ZIndexBehavior = Enum.ZIndexBehavior.Global
    gui.Enabled = XYPHER_STARTUP_INTRO_COMPLETE
    local guiParentOk = pcall(function() gui.Parent = CoreGuiService end)
    if not guiParentOk or not gui.Parent then
        gui.Parent = playerGui
    end

    -- A real, independent reopen launcher. It starts visible while the dashboard
    -- is being constructed, so a later feature error cannot leave users stranded.
    local launcherGui = Instance.new("ScreenGui")
    launcherGui.Name = "XYPHER_OpenLauncher"
    launcherGui.ResetOnSpawn = false
    launcherGui.IgnoreGuiInset = true
    launcherGui.DisplayOrder = 1000000
    launcherGui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
    launcherGui.Enabled = XYPHER_STARTUP_INTRO_COMPLETE
    local launcherParentOk = pcall(function() launcherGui.Parent = gui.Parent end)
    if not launcherParentOk or not launcherGui.Parent then
        launcherGui.Parent = playerGui
    end
    S._xypherLauncherGui = launcherGui

    -- Reliable central crosshair overlay. Parent it directly to PlayerGui rather
    -- than inheriting the dashboard's parent (which may be CoreGui on executors).
    -- This keeps the reticle independent when the dashboard is hidden/minimized.
    local crosshairGui = Instance.new("ScreenGui")
    crosshairGui.Name = "XYPHER_CustomCrosshair"
    crosshairGui.ResetOnSpawn = false
    crosshairGui.IgnoreGuiInset = true
    crosshairGui.DisplayOrder = 2000000000
    crosshairGui.ZIndexBehavior = Enum.ZIndexBehavior.Global
    crosshairGui.Enabled = false
    local crosshairParentOk = pcall(function() crosshairGui.Parent = playerGui end)
    if not crosshairParentOk or not crosshairGui.Parent then
        -- Fallback for clients that restrict direct PlayerGui parenting.
        pcall(function() crosshairGui.Parent = gui.Parent end)
    end

    local crosshairRoot = Instance.new("Frame")
    crosshairRoot.Name = "CrosshairRoot"
    crosshairRoot.AnchorPoint = Vector2.new(0.5, 0.5)
    crosshairRoot.Position = UDim2.fromScale(0.5, 0.5)
    -- Use a tiny non-zero centered root so child GuiObjects reliably render on
    -- all clients/executor UI layers while their offset positions stay centered.
    crosshairRoot.Size = UDim2.fromOffset(1, 1)
    crosshairRoot.BackgroundTransparency = 1
    crosshairRoot.BorderSizePixel = 0
    crosshairRoot.Active = false
    crosshairRoot.Selectable = false
    crosshairRoot.ZIndex = 5
    crosshairRoot.Parent = crosshairGui
    S.crosshairGui = crosshairGui
    S.crosshairRoot = crosshairRoot
    S.crosshairMenuSuppressed = true

    local crosshairColorPresets = {
        {name = "White", color = Color3.fromRGB(255, 255, 255)},
        {name = "Red", color = Color3.fromRGB(255, 58, 74)},
        {name = "Cyan", color = Color3.fromRGB(65, 228, 255)},
        {name = "Lime", color = Color3.fromRGB(100, 255, 135)},
        {name = "Yellow", color = Color3.fromRGB(255, 226, 85)},
        {name = "Pink", color = Color3.fromRGB(255, 105, 205)},
    }

    local function crosshairPiece(name, x, y, width, height, rotation, color, transparency, zIndex)
        local piece = Instance.new("Frame")
        piece.Name = name
        piece.AnchorPoint = Vector2.new(0.5, 0.5)
        piece.Position = UDim2.fromOffset(x, y)
        piece.Size = UDim2.fromOffset(math.max(1, width), math.max(1, height))
        piece.BackgroundColor3 = color
        piece.BackgroundTransparency = transparency
        piece.BorderSizePixel = 0
        piece.Rotation = rotation or 0
        piece.Active = false
        piece.Selectable = false
        piece.ZIndex = zIndex or 5
        piece.Parent = crosshairRoot
        Instance.new("UICorner", piece).CornerRadius = UDim.new(1, 0)
        return piece
    end

    local function renderCustomCrosshair()
        if not crosshairGui.Parent or not crosshairRoot.Parent then return end
        for _, child in ipairs(crosshairRoot:GetChildren()) do child:Destroy() end

        local shapeIndex = math.clamp(math.floor(tonumber(S.crosshairShapeIndex) or 1), 1, 5)
        local colorIndex = math.clamp(math.floor(tonumber(S.crosshairColorIndex) or 1), 1, #crosshairColorPresets)
        local color = crosshairColorPresets[colorIndex].color
        local size = math.clamp(math.floor(tonumber(S.crosshairSize) or 8), 4, 24)
        local gap = math.clamp(math.floor(tonumber(S.crosshairGap) or 4), 0, 20)
        local thickness = math.clamp(math.floor(tonumber(S.crosshairThickness) or 2), 1, 6)
        local alpha = math.clamp((tonumber(S.crosshairTransparency) or 0) / 100, 0, 0.9)
        local outlined = S.crosshairOutlineEnabled ~= false

        local function addBar(name, x, y, width, height, rotation)
            if outlined then
                crosshairPiece(name .. "Outline", x, y, width + 2, height + 2, rotation,
                    Color3.fromRGB(0, 0, 0), 0.05, 4)
            end
            crosshairPiece(name, x, y, width, height, rotation, color, alpha, 5)
        end

        local function addRing(name, diameter)
            if outlined then
                local outline = Instance.new("Frame")
                outline.Name = name .. "Outline"
                outline.AnchorPoint = Vector2.new(0.5, 0.5)
                outline.Position = UDim2.fromOffset(0, 0)
                outline.Size = UDim2.fromOffset(diameter + 2, diameter + 2)
                outline.BackgroundTransparency = 1
                outline.BorderSizePixel = 0
                outline.Active = false
                outline.Selectable = false
                outline.ZIndex = 4
                outline.Parent = crosshairRoot
                Instance.new("UICorner", outline).CornerRadius = UDim.new(1, 0)
                local outlineStroke = Instance.new("UIStroke", outline)
                outlineStroke.Color = Color3.fromRGB(0, 0, 0)
                outlineStroke.Thickness = thickness + 2
                outlineStroke.Transparency = 0.05
            end
            local ring = Instance.new("Frame")
            ring.Name = name
            ring.AnchorPoint = Vector2.new(0.5, 0.5)
            ring.Position = UDim2.fromOffset(0, 0)
            ring.Size = UDim2.fromOffset(diameter, diameter)
            ring.BackgroundTransparency = 1
            ring.BorderSizePixel = 0
            ring.Active = false
            ring.Selectable = false
            ring.ZIndex = 5
            ring.Parent = crosshairRoot
            Instance.new("UICorner", ring).CornerRadius = UDim.new(1, 0)
            local ringStroke = Instance.new("UIStroke", ring)
            ringStroke.Color = color
            ringStroke.Thickness = thickness
            ringStroke.Transparency = alpha
        end

        if shapeIndex == 1 then -- Classic four-arm crosshair with adjustable center gap.
            addBar("CrosshairLeft", -(gap + size / 2), 0, size, thickness, 0)
            addBar("CrosshairRight", gap + size / 2, 0, size, thickness, 0)
            addBar("CrosshairTop", 0, -(gap + size / 2), thickness, size, 0)
            addBar("CrosshairBottom", 0, gap + size / 2, thickness, size, 0)
        elseif shapeIndex == 2 then -- Plus.
            addBar("CrosshairHorizontal", 0, 0, size * 2, thickness, 0)
            addBar("CrosshairVertical", 0, 0, thickness, size * 2, 0)
        elseif shapeIndex == 3 then -- Dot.
            local dotSize = math.max(3, thickness + 1)
            addBar("CrosshairDot", 0, 0, dotSize, dotSize, 0)
        elseif shapeIndex == 4 then -- Hollow circle.
            addRing("CrosshairCircle", math.max(8, size * 2))
        elseif shapeIndex == 5 then -- X.
            local diagonalSize = math.floor(size * 2.2)
            addBar("CrosshairDiagonalA", 0, 0, diagonalSize, thickness, 45)
            addBar("CrosshairDiagonalB", 0, 0, diagonalSize, thickness, -45)
        end

        if S.crosshairDotEnabled == true and shapeIndex ~= 3 then
            local dotSize = math.max(3, thickness + 1)
            addBar("CrosshairCenterDot", 0, 0, dotSize, dotSize, 0)
        end

        -- While the dashboard is open, keep the overlay out of the way. Apply
        -- both ScreenGui and root visibility so a stale child state cannot hide it.
        -- The dashboard hides the reticle while fully open. It is restored when
        -- the dashboard is closed or collapsed to its small header.
        local shouldShowCrosshair = S.crosshairEnabled == true and S.crosshairMenuSuppressed ~= true
        crosshairRoot.Visible = shouldShowCrosshair
        crosshairGui.Enabled = shouldShowCrosshair
        pcall(function() crosshairGui.DisplayOrder = math.max(2000000000, gui.DisplayOrder + 1) end)
    end
