    -- Slow synchronized pulse on the halo and two glows. It uses only three tweens
    -- per phase and stops automatically after the main panel is destroyed.
    task.spawn(function()
        while main.Parent and neonHalo.Parent do
            local glowUpInfo = TweenInfo.new(1.65, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut)
            local glowDownInfo = TweenInfo.new(1.85, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut)
            local upHalo = TS_G:Create(neonHaloStroke, glowUpInfo, {
                Color = C_HIGHLIGHT_BRIGHT, Thickness = 9, Transparency = 0.48,
            })
            local upOuter = TS_G:Create(mainGlowOuter, glowUpInfo, {
                Color = C_HIGHLIGHT, Thickness = 9, Transparency = 0.79,
            })
            local upInner = TS_G:Create(mainGlowInner, glowUpInfo, {
                Color = C_HIGHLIGHT_BRIGHT, Thickness = 4.8, Transparency = 0.59,
            })
            upHalo:Play(); upOuter:Play(); upInner:Play()
            pcall(function() upHalo.Completed:Wait() end)
            if not main.Parent then break end
            local downHalo = TS_G:Create(neonHaloStroke, glowDownInfo, {
                Color = C_HIGHLIGHT, Thickness = 6, Transparency = 0.72,
            })
            local downOuter = TS_G:Create(mainGlowOuter, glowDownInfo, {
                Color = C_HIGHLIGHT, Thickness = 7, Transparency = 0.87,
            })
            local downInner = TS_G:Create(mainGlowInner, glowDownInfo, {
                Color = C_HIGHLIGHT, Thickness = 3.5, Transparency = 0.77,
            })
            downHalo:Play(); downOuter:Play(); downInner:Play()
            pcall(function() downHalo.Completed:Wait() end)
        end
    end)

