            x = webRng:NextInteger(18, math.max(19, PANEL_W - webSize - 18))
        end
        local y = webRng:NextInteger(HEADER_H + 10, PANEL_H - TABBAR_H - webSize - 7)
        addHalloweenSpiderWeb(
            halloweenWebLayer, "ScatteredHalloweenWeb" .. tostring(webIndex),
            UDim2.fromOffset(x, y), webSize, 3,
            webRng:NextNumber(0.31, 0.45), webRng:NextInteger(0, 3)
        )
    end

