    -- Keep the mobile buttons and Steal Bar visible at all times.
    -- When the dashboard is open, place their ScreenGuis below the dashboard
    -- instead of disabling them; this lets them remain active behind the panel.
    local xypherOverlayOriginalOrders = setmetatable({}, { __mode = "k" })
    local xypherOverlayGuiNames = {
        FloatingModeMenu = true,
        StealBarMovableSmall = true,
        StealBarGuiOnly = true,
        StealProgressWindow = true,
        BylateStatusUI = true,
        K7_StatusUI = true,
        StealBarUI = true,
        VxyroStealBar = true,
    }
    local function setXypherGameplayOverlaysVisible(dashboardHidden)
        local targets = {}
        local seen = {}
        local function addScreenGuiFrom(obj)
            local current = obj
            while current and not current:IsA("ScreenGui") do current = current.Parent end
            if current and current:IsA("ScreenGui") and current ~= gui and current ~= launcherGui and not seen[current] then
                seen[current] = true
                targets[#targets + 1] = current
            end
        end
        addScreenGuiFrom(S.floatingPanelGui)
        addScreenGuiFrom(S.stealHudCard)

        -- Also find recreated HUD/mobile ScreenGuis in either UI root in case a
        -- feature rebuilt itself after its previous reference became stale.
        for _, root in ipairs({ playerGui, CoreGuiService }) do
            local okChildren, children = pcall(function() return root:GetChildren() end)
            if okChildren then
                for _, child in ipairs(children) do
                    if child:IsA("ScreenGui") and xypherOverlayGuiNames[child.Name] then
                        addScreenGuiFrom(child)
                    end
                end
            end
        end

        for _, target in ipairs(targets) do
            if target.Parent then
                if dashboardHidden then
                    -- Dashboard is closed/minimized: restore each overlay's order.
                    local original = xypherOverlayOriginalOrders[target]
                    if original ~= nil then
                        pcall(function() target.DisplayOrder = original end)
                        xypherOverlayOriginalOrders[target] = nil
                    end
                else
                    -- Dashboard is open: remember original ordering once, then
                    -- ensure it renders above each mobile/steal overlay.
                    if xypherOverlayOriginalOrders[target] == nil then
                        xypherOverlayOriginalOrders[target] = target.DisplayOrder
                    end
                    if target.DisplayOrder >= gui.DisplayOrder then
                        pcall(function() target.DisplayOrder = gui.DisplayOrder - 1 end)
                    end
                    -- Crucially, never set Enabled = false: mobile buttons and
                    -- steal progress remain visible and continue updating below the GUI.
                    if not target.Enabled then
                        -- Leave an intentionally disabled overlay disabled; do not
                        -- force unrelated user settings on or off here.
                    end
                end
            end
        end
    end
    S._xypherSetGameplayOverlaysVisible = setXypherGameplayOverlaysVisible

    closeBtn.ZIndex = 150
