    local function windowControlAction(button, action)
        local function runOnce()
            local now = os.clock()
            local last = lastWindowActionAt[button] or -math.huge
            -- InputBegan covers touch/executor input paths where Activated may
            -- not fire; Activated covers standard Roblox mouse/gamepad UI.
            -- Debouncing prevents a single press from running twice.
            if now - last < 0.24 then return end
            lastWindowActionAt[button] = now
            local ok, err = pcall(action)
            if not ok then warn("[XYPHER] Window control error: " .. tostring(err)) end
        end
        button.Activated:Connect(runOnce)
        button.InputBegan:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1
                or input.UserInputType == Enum.UserInputType.Touch then
                runOnce()
            end
        end)
    end

    local function fallbackFitScale()
        local camera = workspace.CurrentCamera
        local viewport = camera and camera.ViewportSize or Vector2.new(PANEL_W, PANEL_H)
        local fitted = math.min(1, (viewport.X - 16) / PANEL_W, (viewport.Y - 20) / PANEL_H)
        if S.IS_TOUCH_DEVICE then fitted = math.min(fitted, S.phoneGuiScale or 0.72) end
        return math.max(0.24, fitted)
    end

    local function updateWindowScale(withTween)
        local scaleObj = S.mainGuiScaleObj
        if not scaleObj then return end
        local fitted = fallbackFitScale()
        local target = dashboardMaximized and fitted or (fitted * 0.82)
        if activeDashboardScale then target = activeDashboardScale() end
        if withTween then
            if S.menuTween then pcall(function() S.menuTween:Cancel() end) end
            S.menuTween = TS_G:Create(scaleObj, TweenInfo.new(0.22, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), {Scale = target})
            S.menuTween:Play()
        else
            scaleObj.Scale = target
        end
    end

    local function setDashboardMinimized(minimized)
        dashboardMinimized = minimized == true
        S.crosshairMenuSuppressed = not dashboardMinimized
        if type(S.renderCrosshair) == "function" then pcall(S.renderCrosshair) end
        if dashboardMinimized then
            -- Remember current placement/dimensions before collapsing to header.
            savedOuterSize = UDim2.fromOffset(PANEL_W, PANEL_H)
            savedOuterPosition = outer.Position
            outer.Size = UDim2.fromOffset(PANEL_W, HEADER_H)
            outer.Position = UDim2.new(0.5, 0, 0.12, 0)
            minimizeBtn.Text = "+"
            if S._xypherLauncherGui then S._xypherLauncherGui.Enabled = true end
            if S.miniToggleButton then S.miniToggleButton.Visible = true end
            setXypherGameplayOverlaysVisible(true)
        else
            outer.Size = savedOuterSize
            outer.Position = savedOuterPosition
            minimizeBtn.Text = "−"
            if S.miniToggleButton then S.miniToggleButton.Visible = false end
            setXypherGameplayOverlaysVisible(false)
        end
        updateWindowScale(true)
    end

