    local tPad = Instance.new("UIPadding", tabScroll)
    tPad.PaddingLeft = UDim.new(0,6); tPad.PaddingRight = UDim.new(0,6)
    tPad.PaddingTop = UDim.new(0,5); tPad.PaddingBottom = UDim.new(0,5)

    -- Robust horizontal tab scrolling for touch/phone. AutomaticCanvasSize can
    -- be unreliable when children use AutomaticSize, so keep CanvasSize synced
    -- to the UIListLayout's real AbsoluteContentSize and provide an explicit
    -- swipe gesture in addition to Roblox's native ScrollingFrame handling.
    local function syncTabCanvas()
        local content = tLL.AbsoluteContentSize
        local viewport = tabScroll.AbsoluteSize
        local width = math.max(content.X + tPad.PaddingLeft.Offset + tPad.PaddingRight.Offset + 4, viewport.X)
        tabScroll.CanvasSize = UDim2.fromOffset(width, 0)
    end
    tLL:GetPropertyChangedSignal("AbsoluteContentSize"):Connect(syncTabCanvas)
    tabScroll:GetPropertyChangedSignal("AbsoluteSize"):Connect(syncTabCanvas)
    task.defer(syncTabCanvas)

    -- Explicit touch swipe so dragging across a tab moves the horizontal list
    -- instead of only activating that tab. A tap with little/no movement still
    -- activates the tab normally.
    local tabDragging = false
    local tabMoved = false
    local tabDragStartX = 0
    local tabStartCanvasX = 0
    local tabDragInput

    local function beginTabSwipe(input)
        if input.UserInputType ~= Enum.UserInputType.Touch
            and input.UserInputType ~= Enum.UserInputType.MouseButton1 then return end
        tabDragging = true
        tabMoved = false
        tabDragStartX = input.Position.X
        tabStartCanvasX = tabScroll.CanvasPosition.X
        tabDragInput = input
    end

    tabScroll.InputBegan:Connect(beginTabSwipe)
    tabScroll.InputChanged:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.Touch
            or input.UserInputType == Enum.UserInputType.MouseMovement then
            tabDragInput = input
        end
    end)

    UIS.InputChanged:Connect(function(input)
        if not tabDragging then return end
        if input ~= tabDragInput and input.UserInputType ~= Enum.UserInputType.Touch
            and input.UserInputType ~= Enum.UserInputType.MouseMovement then return end
        local dx = input.Position.X - tabDragStartX
        if math.abs(dx) >= 3 then tabMoved = true end
        local maxX = math.max(0, tabScroll.AbsoluteCanvasSize.X - tabScroll.AbsoluteSize.X)
        local nextX = math.clamp(tabStartCanvasX - dx, 0, maxX)
        tabScroll.CanvasPosition = Vector2.new(nextX, 0)
    end)

    UIS.InputEnded:Connect(function(input)
        if not tabDragging then return end
        if input.UserInputType == Enum.UserInputType.Touch
            or input.UserInputType == Enum.UserInputType.MouseButton1 then
            tabDragging = false
            tabDragInput = nil
        end
    end)

    local function switchTab(name)
        local np = pages[name]
        if not np then return end
        if activeTabName == name and activePage == np then return end
        activeTabName = name
        -- Instantly hide old page so no bleed-through
        if activePage then
            activePage.Visible = false
            activePage.Position = UDim2.fromOffset(0, 0)
        end
        -- Show new page instantly (ScrollingFrame has no GroupTransparency)
        np.Visible = true
        np.CanvasPosition = Vector2.new(0, 0)
        activePage = np
        for tName,tData in pairs(tabBtns) do
            local active = (tName == name)
            TS_G:Create(tData.lbl,TweenInfo.new(0.14),{TextColor3=active and C_WHITE or C_GREY}):Play()
            TS_G:Create(tData.ul,TweenInfo.new(0.16,Enum.EasingStyle.Quad),{BackgroundTransparency=active and 0 or 1}):Play()
        end
    end

