    -- Preserve the source page + section on every existing control so the dashboard sidebar
    -- can filter the live controls without duplicating or replacing any feature logic.
    local verticalPage = pages.Speed
    local pageOrder = {"Speed", "Main", "Move", "Config", "Keybinds"}
    for _, pageName in ipairs(pageOrder) do
        local sourcePage = pages[pageName]
        local children = {}
        for _, child in ipairs(sourcePage:GetChildren()) do
            if child:IsA("GuiObject") then table.insert(children, child) end
        end
        table.sort(children, function(a, b) return a.LayoutOrder < b.LayoutOrder end)
        local currentSection = pageName
        for _, child in ipairs(children) do
            local explicitSection = child:GetAttribute("XypherSectionTitle")
            if explicitSection then currentSection = explicitSection end
            child:SetAttribute("XypherSourceTab", pageName)
            child:SetAttribute("XypherSection", currentSection)
        end
    end

    local nextOrder = 0
    for _, child in ipairs(verticalPage:GetChildren()) do
        if child:IsA("GuiObject") then
            nextOrder += 1
            child.LayoutOrder = nextOrder
        end
    end
    for _, pageName in ipairs({"Main", "Move", "Config", "Keybinds"}) do
        local sourcePage = pages[pageName]
        for _, child in ipairs(sourcePage:GetChildren()) do
            if not child:IsA("UIListLayout") and not child:IsA("UIPadding") then
                child.Parent = verticalPage
                if child:IsA("GuiObject") then
                    nextOrder += 1
                    child.LayoutOrder = nextOrder
                end
            end
        end
        sourcePage:Destroy()
    end
