        frame.Size = size
        frame.BackgroundColor3 = background or C_CARD
        frame.BackgroundTransparency = 0.04
        frame.BorderSizePixel = 0
        frame.ZIndex = z or 10
        frame.Parent = parent
        Instance.new("UICorner", frame).CornerRadius = UDim.new(0, radius or 13)
        local stroke = Instance.new("UIStroke", frame)
        stroke.Color = C_BORDER
        stroke.Thickness = 1
        stroke.Transparency = 0.16
        return frame, stroke
    end

