        label.TextSize = textSize or 12
        label.TextXAlignment = xAlign or Enum.TextXAlignment.Left
        label.TextYAlignment = Enum.TextYAlignment.Center
        label.ZIndex = z or 12
        label.Active = false
        label.Selectable = false
        label.Parent = parent
        return label
    end

