        {name="Dark Purple", accent=Color3.fromRGB(194, 62, 255), bright=Color3.fromRGB(250, 238, 255), dark=Color3.fromRGB(20, 5, 34), border=Color3.fromRGB(132, 39, 206)},
        {name="Black & White", accent=Color3.fromRGB(248, 250, 255), bright=Color3.fromRGB(255, 255, 255), dark=Color3.fromRGB(13, 15, 21), border=Color3.fromRGB(140, 153, 176)},
        {name="Blue & White", accent=Color3.fromRGB(0, 218, 255), bright=Color3.fromRGB(222, 251, 255), dark=Color3.fromRGB(4, 20, 38), border=Color3.fromRGB(0, 143, 202)},
        {name="Pink & Purple", accent=Color3.fromRGB(255, 48, 211), bright=Color3.fromRGB(255, 230, 251), dark=Color3.fromRGB(31, 5, 36), border=Color3.fromRGB(190, 30, 151)},
        {name="Emerald Neon", accent=Color3.fromRGB(0, 255, 164), bright=Color3.fromRGB(224, 255, 243), dark=Color3.fromRGB(3, 25, 21), border=Color3.fromRGB(0, 154, 105)},
        {name="Crimson Neon", accent=Color3.fromRGB(255, 54, 87), bright=Color3.fromRGB(255, 229, 234), dark=Color3.fromRGB(30, 5, 12), border=Color3.fromRGB(188, 29, 55)},
        {name="Amber Neon", accent=Color3.fromRGB(255, 187, 40), bright=Color3.fromRGB(255, 246, 218), dark=Color3.fromRGB(30, 20, 3), border=Color3.fromRGB(178, 110, 13)},
