    local themeSwatches = {}

    -- The selected menu filters already-built controls by heading; callbacks remain unchanged.
    local sectionFilters = {
        ["Main"] = nil,
        ["Combat"] = { ["Counters"]=true, ["Steal"] = true, ["Actions"] = true },
        ["Movement"] = { ["Speed Values"]=true, ["Modes"]=true, ["Auto Path"]=true },
        ["Visual"] = { ["Visuals"]=true, ["Crosshair"]=true, ["Mobile Button Background"] = true, ["Mobile Buttons"] = true, ["Background"] = true },
        ["Player"] = { ["Display Mode"]=true, ["Player"] = true, ["Protection"] = true, ["Character / Performance"] = true },
        ["World"] = { ["Visuals"]=true, ["Background"] = true },
        ["Misc"] = { ["Utility"] = true, ["Actions"] = true, ["Keybind"] = true },
        ["Settings"] = { ["General"] = true, ["Config"] = true, ["Keybind"] = true, ["Background"] = true },
    }
    local activeNavName = "Main"
    -- Forward-declare these because remapThemeColors closes over them before
    -- their visual objects are constructed below.
    local themeFooter, themeFooterStroke, footerLine
    local function sectionIsVisible(navName, child)
        if navName == "Main" then return true end
        local filter = sectionFilters[navName]
        if not filter then return false end
        local section = child:GetAttribute("XypherSection")
        return filter[section] == true
    end

    local function paintNavigation()
        for _, entry in ipairs(navEntries) do
            local active = entry.name == activeNavName
            entry.button.BackgroundColor3 = active and activeThemeDef.dark or Color3.fromRGB(9, 9, 12)
            entry.button.BackgroundTransparency = active and 0.52 or 0.80
            entry.stroke.Color = active and activeThemeDef.accent or activeThemeDef.border
            entry.stroke.Transparency = active and 0.04 or 0.58
            entry.icon.TextColor3 = active and activeThemeDef.bright or activeThemeDef.border
            entry.label.TextColor3 = active and C_WHITE or Color3.fromRGB(190, 190, 198)
        end
    end

    local function applySectionFilter(navName)
        activeNavName = navName
        for _, child in ipairs(verticalPage:GetChildren()) do
            if child:IsA("GuiObject") then
                child.Visible = sectionIsVisible(navName, child)
            end
        end
        centerSectionTitle.Text = (navName == "Main") and "✦  AUTO FEATURES" or ("✦  " .. string.upper(navName))
        paintNavigation()
        verticalPage.CanvasPosition = Vector2.new(0, 0)
    end

    local dashboardThemeOriginals = setmetatable({}, { __mode = "k" })

    local function applyThemeToExternalXypherUIs(themeDef)
        if not themeDef then return end
        S.activeThemePalette = themeDef
        _G.XYPHER_ACTIVE_THEME = {
            name = themeDef.name, accent = themeDef.accent, bright = themeDef.bright,
            dark = themeDef.dark, border = themeDef.border,
        }

        local targets, seenTargets = {}, {}
        local function addScreen(screen)
            if not screen or not screen:IsA("ScreenGui") or screen == gui or seenTargets[screen] then return end
            local name = screen.Name:lower()
            local belongs = name == "floatingmodemenu" or name == "stealbarmovablesmall"
                or name == "xypher_openlauncher" or name:find("xypher", 1, true) ~= nil
                or name:find("vision", 1, true) ~= nil or name:find("stealbar", 1, true) ~= nil
            if belongs then
                seenTargets[screen] = true
                table.insert(targets, screen)
            end
        end
        local function scanHost(host)
            if not host then return end
            local ok, children = pcall(function() return host:GetChildren() end)
            if ok then
                for _, child in ipairs(children) do addScreen(child) end
            end
        end
        scanHost(playerGui)
        scanHost(CoreGuiService)
        pcall(function() if type(gethui) == "function" then scanHost(gethui()) end end)

        -- Observe future XYPHER/Vision overlay ScreenGuis too, so components
        -- created later by a feature inherit the currently selected palette.
        S._xypherThemeRootWatchers = S._xypherThemeRootWatchers or setmetatable({}, { __mode = "k" })
        local function watchHost(host)
            if not host or S._xypherThemeRootWatchers[host] then return end
            local okConnection, connection = pcall(function()
                return host.ChildAdded:Connect(function(child)
                    if not child or not child:IsA("ScreenGui") then return end
                    local name = child.Name:lower()
                    local belongs = name ~= "vision" and (name:find("vision", 1, true) ~= nil
                        or name:find("xypher", 1, true) ~= nil or name:find("stealbar", 1, true) ~= nil
                        or name == "floatingmodemenu")
                    if not belongs then return end
                    task.delay(0.30, function()
                        local palette = S.activeThemePalette
                        if child.Parent and palette and type(S._xypherApplyThemeToOverlays) == "function" then
                            pcall(S._xypherApplyThemeToOverlays, palette)
                        end
                    end)
                end)
            end)
            if okConnection and connection then S._xypherThemeRootWatchers[host] = connection end
        end
        watchHost(playerGui)
        watchHost(CoreGuiService)
        pcall(function() if type(gethui) == "function" then watchHost(gethui()) end end)

        local function addFromObject(obj)
            local current = obj
            while current and not current:IsA("ScreenGui") do current = current.Parent end
            addScreen(current)
        end
        addFromObject(S.floatingPanelGui)
        addFromObject(S.stealHudCard)
        addFromObject(S.miniToggleButton)

        local function seq3(a, b, c)
            return ColorSequence.new({
                ColorSequenceKeypoint.new(0, a),
                ColorSequenceKeypoint.new(0.5, b),
                ColorSequenceKeypoint.new(1, c),
            })
        end
        for _, screen in ipairs(targets) do
            local screenName = screen.Name:lower()
            local isMobile = screenName == "floatingmodemenu"
            local isSteal = screenName:find("stealbar", 1, true) ~= nil
            local isLauncher = screenName == "xypher_openlauncher"
            for _, object in ipairs(screen:GetDescendants()) do
                local name = object.Name:lower()
                local parentName = object.Parent and object.Parent.Name:lower() or ""
                if isMobile and object:GetAttribute("VisionMobileButton") == true then
                    object.BackgroundColor3 = Color3.fromRGB(5, 5, 5)
                    object:SetAttribute("XypherMobileActive", object:GetAttribute("XypherMobileActive") == true)
                    local mobileActive = object:GetAttribute("XypherMobileActive") == true
                    for _, child in ipairs(object:GetChildren()) do
                        if child:IsA("UIStroke") then
                            if child.Name == "MobileNeonBloom" then
                                child.Color = themeDef.accent
                                child.Transparency = mobileActive and 0.67 or 0.83
                                child.Thickness = mobileActive and 4 or 3
                            else
                                child.Color = mobileActive and themeDef.bright or themeDef.border
                                child.Transparency = mobileActive and 0.02 or 0.28
                                child.Thickness = mobileActive and 1.65 or 1.1
                            end
                        elseif child:IsA("UIGradient") then
                            child.Color = ColorSequence.new({
                                ColorSequenceKeypoint.new(0, themeDef.bright),
                                ColorSequenceKeypoint.new(0.32, themeDef.accent),
                                ColorSequenceKeypoint.new(0.68, themeDef.dark),
                                ColorSequenceKeypoint.new(1, Color3.fromRGB(5, 5, 5)),
                            })
                        end
                    end
                elseif isSteal and object:IsA("Frame") then
                    if name == "progressfill" then
                        object.BackgroundColor3 = themeDef.accent
                    elseif name == "statustargetdot" then
                        object.BackgroundColor3 = themeDef.bright
                    elseif name == "statusdot" or name == "targetdot" then
                        object.BackgroundColor3 = themeDef.accent
                    elseif name:find("titlewing", 1, true) or name == "headerhairline" then
                        object.BackgroundColor3 = themeDef.accent
                    elseif name == "stealprogressbar" or name == "progresstrack" or name == "statustargetouter" then
                        object.BackgroundColor3 = Color3.fromRGB(7, 7, 10)
                    end
                end

                if object:IsA("UIStroke") then
                    if isSteal then
                        if parentName:find("progressfill", 1, true) or parentName:find("titleglow", 1, true)
                            or parentName:find("panelglow", 1, true) then
                            object.Color = themeDef.accent
                        elseif parentName:find("targetinner", 1, true) then
                            object.Color = themeDef.bright
                        else
                            object.Color = themeDef.border
                        end
                    elseif isLauncher then
                        object.Color = themeDef.accent
                    elseif isMobile then
                        -- Mobile-button border strokes are handled in their own parent loop.
                    else
                        local owner = parentName
                        object.Color = (owner:find("accent", 1, true) or owner:find("glow", 1, true)
                            or owner:find("outline", 1, true) or owner:find("espbox", 1, true)) and themeDef.accent or themeDef.border
                    end
                elseif object:IsA("UIGradient") then
                    if isSteal then
                        if parentName == "progressfill" or name == "progressfillgradient" then
                            object.Color = seq3(themeDef.dark, themeDef.accent, themeDef.bright)
                        elseif parentName == "statustargetdot" or name == "statustargetdotgradient" then
                            object.Color = seq3(themeDef.bright, themeDef.accent, themeDef.dark)
                        elseif parentName:find("title", 1, true) or parentName:find("hairline", 1, true)
                            or name:find("hairline", 1, true) or name:find("wing", 1, true) then
                            object.Color = seq3(themeDef.dark, themeDef.bright, themeDef.accent)
                        elseif parentName:find("track", 1, true) or parentName:find("panel", 1, true) then
                            object.Color = seq3(Color3.fromRGB(5, 5, 8), themeDef.dark, Color3.fromRGB(8, 8, 11))
                        end
                    elseif isLauncher then
                        object.Color = seq3(themeDef.dark, themeDef.accent, themeDef.dark)
                    end
                elseif object:IsA("TextLabel") or object:IsA("TextButton") or object:IsA("TextBox") then
                    if isSteal then
                        if name == "stealstatus" or name == "pingvalue" or name == "fpsvalue" or name == "percent"
                            or name == "xyphertitleglow" then
                            object.TextColor3 = themeDef.bright
                        elseif name == "xyphertitle" then
                            object.TextColor3 = themeDef.bright
                        end
                    elseif isLauncher and name == "openguibutton" then
                        object.TextColor3 = themeDef.bright
                        object.BackgroundColor3 = themeDef.dark
                    end
                end
            end
        end

        if type(updateStealHudStatus) == "function" then pcall(updateStealHudStatus) end
    end
    S._xypherApplyThemeToOverlays = applyThemeToExternalXypherUIs

    local function remapThemeColors(themeDef)
        activeThemeDef = themeDef
        S.uiThemeName = themeDef.name
        S.activeThemePalette = themeDef
        _G.XYPHER_ACTIVE_THEME = {
            name = themeDef.name, accent = themeDef.accent, bright = themeDef.bright,
            dark = themeDef.dark, border = themeDef.border,
        }
        -- Shared colors feed existing and newly created XYPHER feature rows.
        C_BG = Color3.fromRGB(7, 8, 13)
        C_HEADER = themeDef.dark:Lerp(Color3.fromRGB(8, 9, 15), 0.68)
        C_CARD = themeDef.dark:Lerp(Color3.fromRGB(12, 13, 20), 0.80)
        C_CARD_HOV = themeDef.dark
        C_HIGHLIGHT = themeDef.accent
        C_HIGHLIGHT_BRIGHT = themeDef.bright
        C_ACCENT = themeDef.accent
        C_SHADE = themeDef.dark
        C_BORDER = themeDef.border
        C_DIM = themeDef.dark
        C_SEPARATOR_GRAY = themeDef.border
        C_CARD_ACTIVE_BG = Color3.fromRGB(
            math.floor(themeDef.dark.R * 255 * 0.5),
            math.floor(themeDef.dark.G * 255 * 0.5),
            math.floor(themeDef.dark.B * 255 * 0.5)
        )

        local function isThemeTint(color)
            local ok, hue, saturation, value = pcall(function()
                local h, sat, val = color:ToHSV()
                return h, sat, val
            end)
            -- Test saturation/value rather than a hue whitelist. This lets every
            -- palette (cyan, violet, pink, green, red and amber) remap reliably,
            -- while leaving near-black surfaces and neutral whites untouched.
            return ok and saturation >= 0.20 and value >= 0.14
        end
        local function isAccentRole(name)
            name = (name or ""):lower()
            return name:find("toggle", 1, true) or name:find("switch", 1, true)
                or name:find("fill", 1, true) or name:find("accent", 1, true)
                or name:find("selected", 1, true) or name:find("glow", 1, true)
                or name:find("underline", 1, true) or name:find("knob", 1, true)
                or name:find("active", 1, true) or name:find("highlight", 1, true)
        end

        -- Baseline snapshots make every theme switch reversible instead of
        -- comparing against a palette that was mutated by an earlier click.
        for _, object in ipairs(main:GetDescendants()) do
            local base = dashboardThemeOriginals[object]
            if not base then
                base = {}
                if object:IsA("UIStroke") then
                    base.Color = object.Color
                elseif object:IsA("TextLabel") or object:IsA("TextButton") or object:IsA("TextBox") then
                    base.TextColor3 = object.TextColor3
                    base.TextStrokeColor3 = object.TextStrokeColor3
                    base.TextStrokeTransparency = object.TextStrokeTransparency
                elseif object:IsA("Frame") then
                    base.BackgroundColor3 = object.BackgroundColor3
                    base.BackgroundTransparency = object.BackgroundTransparency
                elseif object:IsA("UIGradient") then
                    base.Color = object.Color
                end
                dashboardThemeOriginals[object] = base
            end

            if object:IsA("UIStroke") then
                local ownerName = object.Parent and object.Parent.Name or ""
                if base.Color and isThemeTint(base.Color) then
                    object.Color = (object.Thickness >= 1.4 or isAccentRole(ownerName)) and themeDef.accent or themeDef.border
                else
                    object.Color = base.Color or object.Color
                end
            elseif object:IsA("TextLabel") or object:IsA("TextButton") or object:IsA("TextBox") then
                if base.TextColor3 then
                    object.TextColor3 = isThemeTint(base.TextColor3) and themeDef.bright or base.TextColor3
                end
                if base.TextStrokeColor3 then
                    if (base.TextStrokeTransparency or object.TextStrokeTransparency) < 0.95 and isThemeTint(base.TextStrokeColor3) then
                        object.TextStrokeColor3 = themeDef.dark
                    else
                        object.TextStrokeColor3 = base.TextStrokeColor3
                    end
                end
            elseif object:IsA("Frame") then
                if base.BackgroundColor3 then
                    if (base.BackgroundTransparency or object.BackgroundTransparency) < 0.9 and isThemeTint(base.BackgroundColor3) then
                        object.BackgroundColor3 = isAccentRole(object.Name) and themeDef.accent or themeDef.dark
                    else
                        object.BackgroundColor3 = base.BackgroundColor3
                    end
                end
            elseif object:IsA("UIGradient") then
                local linkedToPalette = false
                if base.Color then
                    for _, keypoint in ipairs(base.Color.Keypoints) do
                        if isThemeTint(keypoint.Value) then
                            linkedToPalette = true
                            break
                        end
                    end
                end
                if linkedToPalette then
                    object.Color = ColorSequence.new({
                        ColorSequenceKeypoint.new(0, themeDef.dark),
                        ColorSequenceKeypoint.new(0.5, themeDef.dark:Lerp(themeDef.accent, 0.58)),
                        ColorSequenceKeypoint.new(1, themeDef.dark),
                    })
                elseif base.Color then
                    object.Color = base.Color
                end
            end
        end
        -- Pin all perimeter-glow layers to the selected palette.
        mainStroke.Color = themeDef.bright
        mainGlowInner.Color = themeDef.bright
        mainGlowOuter.Color = themeDef.accent
        neonHalo.BackgroundColor3 = themeDef.accent
        neonHaloStroke.Color = themeDef.accent
        glassSheenGradient.Color = ColorSequence.new({
            ColorSequenceKeypoint.new(0, themeDef.bright),
            ColorSequenceKeypoint.new(0.52, themeDef.border),
            ColorSequenceKeypoint.new(1, themeDef.bright),
        })
        glassSweep.BackgroundColor3 = themeDef.bright
        sidebarStroke.Color = themeDef.border
        rightRailStroke.Color = themeDef.border
        profileStroke.Color = themeDef.border
        statsStroke.Color = themeDef.border
        themeStroke.Color = themeDef.border
        themeFooterStroke.Color = themeDef.border
        welcome.BackgroundColor3 = themeDef.dark:Lerp(Color3.fromRGB(6, 6, 10), 0.78)
        welcomeBadge.BackgroundColor3 = themeDef.dark
        avatarRing.BackgroundColor3 = themeDef.dark
        headerGrad.Color = ColorSequence.new({
            ColorSequenceKeypoint.new(0, themeDef.dark),
            ColorSequenceKeypoint.new(0.5, themeDef.dark:Lerp(themeDef.accent, 0.18)),
            ColorSequenceKeypoint.new(1, themeDef.dark),
        })
        hSep.BackgroundColor3 = themeDef.accent
        hSepG.Color = ColorSequence.new({
            ColorSequenceKeypoint.new(0, themeDef.dark),
            ColorSequenceKeypoint.new(0.46, themeDef.bright),
            ColorSequenceKeypoint.new(1, themeDef.dark),
        })
        hSepGlow.BackgroundColor3 = themeDef.accent
        titleGlow.Color = themeDef.accent
        titleAccent.BackgroundColor3 = themeDef.accent
        titleAccentGradient.Color = ColorSequence.new({
            ColorSequenceKeypoint.new(0, themeDef.dark),
            ColorSequenceKeypoint.new(0.48, themeDef.accent),
            ColorSequenceKeypoint.new(1, themeDef.dark),
        })
        closeBtnStroke.Color = themeDef.border
        minimizeStroke.Color = themeDef.border
        maximizeStroke.Color = themeDef.border
        -- Keep the close control inside the selected palette instead of forcing a red tint.
        closeBtn.BackgroundColor3 = themeDef.dark:Lerp(Color3.fromRGB(8, 8, 12), 0.42)
        minimizeBtn.BackgroundColor3 = themeDef.dark:Lerp(Color3.fromRGB(8, 8, 12), 0.52)
        maximizeBtn.BackgroundColor3 = themeDef.dark:Lerp(Color3.fromRGB(8, 8, 12), 0.52)
        titleImage.TextColor3 = themeDef.bright
        titleSubtitle.TextColor3 = themeDef.bright
        welcomeStroke.Color = themeDef.border
        avatarRingStroke.Color = themeDef.accent
        welcomeIcon.TextColor3 = themeDef.bright
        welcomeTitleAccent.TextColor3 = themeDef.bright
        welcomeX.TextColor3 = themeDef.dark
        sectionUnderline.BackgroundColor3 = themeDef.accent
        themeUnderline.BackgroundColor3 = themeDef.accent
        footerLine.BackgroundColor3 = themeDef.accent

        for _, entry in ipairs(themeButtons) do
            local active = entry.name == themeDef.name
            entry.button.BackgroundColor3 = active and themeDef.dark or Color3.fromRGB(10, 10, 13)
            entry.stroke.Color = active and themeDef.accent or themeDef.border
            entry.stroke.Transparency = active and 0.08 or 0.65
            entry.dot.TextColor3 = entry.theme.accent
            entry.label.TextColor3 = active and C_WHITE or Color3.fromRGB(190, 190, 198)
            entry.swatch.BackgroundColor3 = entry.theme.accent
            entry.swatch:FindFirstChildOfClass("UIGradient").Color = ColorSequence.new({
                ColorSequenceKeypoint.new(0, entry.theme.dark),
                ColorSequenceKeypoint.new(0.5, entry.theme.accent),
                ColorSequenceKeypoint.new(1, entry.theme.bright),
            })
        end
        paintNavigation()
        if S._xypherApplyThemeToOverlays then
            pcall(S._xypherApplyThemeToOverlays, themeDef)
        end
    end

    local function selectNavigation(name)
        applySectionFilter(name)
    end

    for i, def in ipairs(navDefs) do
        local button = Instance.new("TextButton")
        button.Name = "Nav_" .. def.name
        button.Position = UDim2.fromOffset(9, 16 + (i - 1) * 43)
        button.Size = UDim2.fromOffset(SIDEBAR_W - 18, 37)
        button.BackgroundColor3 = Color3.fromRGB(9, 6, 20)
        button.BackgroundTransparency = 0.72
        button.BorderSizePixel = 0
        button.Text = ""
        button.AutoButtonColor = false
        button.ZIndex = 10
        button.Parent = sidebar
        Instance.new("UICorner", button).CornerRadius = UDim.new(0, 10)
        local stroke = Instance.new("UIStroke", button)
        stroke.Color = Color3.fromRGB(42, 29, 62)
        stroke.Thickness = 1
        stroke.Transparency = 0.48
        local navName = def.name
        local icon = makeLabel(button, "NavIcon", def.icon, UDim2.fromOffset(12, 0), UDim2.fromOffset(28, 37), 18, Color3.fromRGB(176, 168, 197), Enum.Font.GothamBold, 12, Enum.TextXAlignment.Center)
        local label = makeLabel(button, "NavLabel", navName, UDim2.fromOffset(49, 0), UDim2.new(1, -56, 1, 0), 12, Color3.fromRGB(190, 183, 209), Enum.Font.GothamMedium, 12)
        local entry = {name=navName, button=button, stroke=stroke, icon=icon, label=label}
        table.insert(navEntries, entry)
        button.Activated:Connect(function() selectNavigation(navName) end)
    end

    -- Compact XYPHER logo block at the base of the sidebar.
    local sidebarBrand = makeLabel(sidebar, "SidebarBrandMark", "X", UDim2.fromOffset(20, BODY_H - 105), UDim2.fromOffset(138, 44), 36, C_HIGHLIGHT, Enum.Font.GothamBlack, 10, Enum.TextXAlignment.Center)
    local sidebarBrandTitle = makeLabel(sidebar, "SidebarBrandTitle", "X Y P H E R", UDim2.fromOffset(20, BODY_H - 61), UDim2.fromOffset(138, 16), 9, Color3.fromRGB(199, 187, 224), Enum.Font.GothamMedium, 10, Enum.TextXAlignment.Center)
    local sidebarBrandYear = makeLabel(sidebar, "SidebarBrandYear", "E S T .   2 0 2 5", UDim2.fromOffset(20, BODY_H - 42), UDim2.fromOffset(138, 12), 7, Color3.fromRGB(118, 107, 145), Enum.Font.Gotham, 9, Enum.TextXAlignment.Center)

    for i, themeDef in ipairs(themeDefs) do
        local selectedTheme = themeDef
        local button = Instance.new("TextButton")
        button.Name = "Theme_" .. themeDef.name:gsub("[^%w]+", "")
        button.Position = UDim2.fromOffset(9, 37 + (i - 1) * 31)
        button.Size = UDim2.new(1, -18, 0, 30)
        button.BackgroundColor3 = Color3.fromRGB(10, 7, 22)
        button.BackgroundTransparency = 0.66
        button.BorderSizePixel = 0
        button.Text = ""
        button.AutoButtonColor = false
        button.ZIndex = 11
        button.Parent = themeCard
        Instance.new("UICorner", button).CornerRadius = UDim.new(0, 9)
        local stroke = Instance.new("UIStroke", button)
        stroke.Color = Color3.fromRGB(39, 28, 56)
        stroke.Thickness = 1
        stroke.Transparency = 0.65
        local dot = makeLabel(button, "ThemeRadio", "◉", UDim2.fromOffset(5, 0), UDim2.fromOffset(29, 30), 18, themeDef.accent, Enum.Font.Gotham, 13, Enum.TextXAlignment.Center)
        local label = makeLabel(button, "ThemeLabel", themeDef.name, UDim2.fromOffset(37, 0), UDim2.new(1, -76, 1, 0), 10, Color3.fromRGB(208, 207, 221), Enum.Font.GothamMedium, 12)
        local swatch = Instance.new("Frame")
        swatch.Name = "ThemeSwatch"
        swatch.AnchorPoint = Vector2.new(1, 0.5)
        swatch.Position = UDim2.new(1, -5, 0.5, 0)
        swatch.Size = UDim2.fromOffset(30, 22)
        swatch.BackgroundColor3 = themeDef.accent
        swatch.BorderSizePixel = 0
        swatch.ZIndex = 13
        swatch.Parent = button
        Instance.new("UICorner", swatch).CornerRadius = UDim.new(0, 7)
        local swatchGradient = Instance.new("UIGradient", swatch)
        swatchGradient.Color = ColorSequence.new({
            ColorSequenceKeypoint.new(0, themeDef.dark),
            ColorSequenceKeypoint.new(0.5, themeDef.accent),
            ColorSequenceKeypoint.new(1, themeDef.bright),
        })
        table.insert(themeButtons, {name=themeDef.name, theme=themeDef, button=button, stroke=stroke, dot=dot, label=label, swatch=swatch})
        button.Activated:Connect(function()
            remapThemeColors(selectedTheme)
            S.uiThemeName = selectedTheme.name
            pcall(saveConfig)
        end)
    end

    themeFooter, themeFooterStroke = makePanel(rightRail, "XypherThemeFooter", UDim2.fromOffset(8, 478), UDim2.new(1, -16, 0, 40), Color3.fromRGB(8, 5, 20), 13, 9)
    themeFooter.BackgroundTransparency = 0.56
    local footerTitle = makeLabel(themeFooter, "FooterTitle", "X Y P H E R", UDim2.fromOffset(8, 4), UDim2.new(1, -16, 0, 15), 9, Color3.fromRGB(220, 216, 238), Enum.Font.GothamMedium, 12, Enum.TextXAlignment.Center)
    local footerSubtitle = makeLabel(themeFooter, "FooterSubtitle", "S T E A L   ·   F A R M   ·   D O M I N A T E", UDim2.fromOffset(8, 21), UDim2.new(1, -16, 0, 12), 7, Color3.fromRGB(174, 168, 198), Enum.Font.Gotham, 9, Enum.TextXAlignment.Center)
    footerLine = Instance.new("Frame")
    footerLine.Name = "FooterAccent"
    footerLine.Position = UDim2.new(0.5, -20, 1, -5)
    footerLine.Size = UDim2.fromOffset(40, 2)
    footerLine.BackgroundColor3 = C_HIGHLIGHT
    footerLine.BorderSizePixel = 0
    footerLine.ZIndex = 12
    footerLine.Parent = themeFooter
    Instance.new("UICorner", footerLine).CornerRadius = UDim.new(1, 0)

    -- Live FPS and network ping; update at 2 Hz to keep phone overhead low.
    task.spawn(function()
        local previous = os.clock()
        local frames = 0
        while gui.Parent and rightRail.Parent do
            RunService.RenderStepped:Wait()
            frames += 1
            local now = os.clock()
            if now - previous >= 0.5 then
                local fps = math.floor(frames / math.max(now - previous, 0.01) + 0.5)
                frames = 0
                previous = now
                local ping = 0
                pcall(function() ping = math.floor(LP:GetNetworkPing() * 1000 + 0.5) end)
                fpsValue.Text = tostring(fps)
                pingValue.Text = tostring(ping) .. "ms"
            end
        end
    end)

    -- Responsive layout: regular size leaves breathing room; maximize fills the
    -- safe viewport. Both states are recalculated after rotation/resizing.
    local function fitDashboardScale()
        local camera = workspace.CurrentCamera
        local viewport = camera and camera.ViewportSize or Vector2.new(PANEL_W, PANEL_H)
        local scale = math.min(1, (viewport.X - 16) / PANEL_W, (viewport.Y - 20) / PANEL_H)
        if S.IS_TOUCH_DEVICE then scale = math.min(scale, S.phoneGuiScale or 0.72) end
        return math.max(0.24, scale)
    end
    activeDashboardScale = function()
        local fitted = fitDashboardScale()
        -- A visibly distinct normal size makes maximize/restore easy to notice.
        return dashboardMaximized and fitted or (fitted * 0.82)
    end
    local dashboardViewportConnection
    local function refreshDashboardFit()
        if S.mainGuiScaleObj then S.mainGuiScaleObj.Scale = activeDashboardScale() end
        S.menuOpenPosition = UDim2.fromScale(0.5, 0.5)
        if not dashboardMinimized then
            outer.Position = S.menuOpenPosition
        end
    end
    if workspace.CurrentCamera then
        dashboardViewportConnection = workspace.CurrentCamera:GetPropertyChangedSignal("ViewportSize"):Connect(refreshDashboardFit)
    end
    workspace:GetPropertyChangedSignal("CurrentCamera"):Connect(function()
        if dashboardViewportConnection then dashboardViewportConnection:Disconnect(); dashboardViewportConnection = nil end
        if workspace.CurrentCamera then
            dashboardViewportConnection = workspace.CurrentCamera:GetPropertyChangedSignal("ViewportSize"):Connect(refreshDashboardFit)
        end
        refreshDashboardFit()
    end)
    refreshDashboardFit()
    remapThemeColors(activeThemeDef)
    applySectionFilter("Main")

    -- Reliable show/hide transitions. The hide path is deliberately synchronous:
    -- it never depends on Tween.Completed, which can be cancelled by another
    -- animation or fail to run on some mobile executor UI implementations.
    local menuScale = S.mainGuiScaleObj
    local function cancelMenuTween()
        if S.menuTween then pcall(function() S.menuTween:Cancel() end) end
        if S.menuPositionTween then pcall(function() S.menuPositionTween:Cancel() end) end
    end
    showGui = function()
        if not XYPHER_STARTUP_INTRO_COMPLETE then return end
        S.menuTransitionToken = (S.menuTransitionToken or 0) + 1
        cancelMenuTween()
        S.crosshairMenuSuppressed = true
        if type(S.renderCrosshair) == "function" then pcall(S.renderCrosshair) end
        if dashboardMinimized then setDashboardMinimized(false) end
        -- setDashboardMinimized may start its own scale tween; cancel it before
        -- defining the new entrance so two tweens never fight over the same UIScale.
        cancelMenuTween()
        outer.Size = savedOuterSize
        local targetPosition = S.menuOpenPosition or UDim2.fromScale(0.5, 0.5)
        outer.Position = targetPosition
        outer.Visible = true
        setXypherGameplayOverlaysVisible(false)
        if S._xypherLauncherGui then S._xypherLauncherGui.Enabled = true end
        if S.miniToggleButton then S.miniToggleButton.Visible = false end
        S._xypherOpenPending = false
        updateWindowScale(false)
        if menuScale then
            local target = activeDashboardScale()
            menuScale.Scale = math.max(0.14, target * 0.58)
            outer.Position = UDim2.new(targetPosition.X.Scale, targetPosition.X.Offset, targetPosition.Y.Scale, targetPosition.Y.Offset + 34)
            S.menuTween = TS_G:Create(menuScale, TweenInfo.new(0.44, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {Scale = target})
            S.menuPositionTween = TS_G:Create(outer, TweenInfo.new(0.44, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), {Position = targetPosition})
            S.menuTween:Play()
            S.menuPositionTween:Play()
        end
    end
    hideGui = function()
        if not XYPHER_STARTUP_INTRO_COMPLETE then return end
        S.menuTransitionToken = (S.menuTransitionToken or 0) + 1
        local transitionToken = S.menuTransitionToken
        cancelMenuTween()
        S.crosshairMenuSuppressed = false
        if type(S.renderCrosshair) == "function" then pcall(S.renderCrosshair) end
        setXypherGameplayOverlaysVisible(true)
        if S._xypherLauncherGui then S._xypherLauncherGui.Enabled = true end
        if S.miniToggleButton then
            S.miniToggleButton.Visible = true
            S.miniToggleButton.Active = true
            S.miniToggleButton.Selectable = true
        end

        -- Shrink the dashboard smoothly before hiding it. The transition token
        -- prevents a late completion callback from hiding a dashboard reopened quickly.
        if menuScale then
            local targetPosition = S.menuOpenPosition or UDim2.fromScale(0.5, 0.5)
            local closeScale = math.max(0.14, activeDashboardScale() * 0.58)
            S.menuTween = TS_G:Create(menuScale, TweenInfo.new(0.30, Enum.EasingStyle.Quad, Enum.EasingDirection.In), {
                Scale = closeScale,
            })
            S.menuPositionTween = TS_G:Create(outer, TweenInfo.new(0.30, Enum.EasingStyle.Quad, Enum.EasingDirection.In), {
                Position = UDim2.new(targetPosition.X.Scale, targetPosition.X.Offset, targetPosition.Y.Scale, targetPosition.Y.Offset + 30),
            })
            local closeTween = S.menuTween
            closeTween:Play()
            S.menuPositionTween:Play()
            closeTween.Completed:Connect(function(playbackState)
                if playbackState ~= Enum.PlaybackState.Completed then return end
                if transitionToken ~= S.menuTransitionToken then return end
                outer.Visible = false
                outer.Position = targetPosition
                menuScale.Scale = activeDashboardScale()
            end)
        else
            outer.Visible = false
        end
        -- Apply visibility immediately; do not wait for the closing tween to finish.
        if type(S.renderCrosshair) == "function" then pcall(S.renderCrosshair) end
        -- The independent launcher remains available after the panel animation ends.
    end

    local menuClosedScale = math.max(0.14, activeDashboardScale() * 0.58)
    local initialOpenPosition = S.menuOpenPosition or UDim2.fromScale(0.5, 0.5)
    outer.Position = UDim2.new(initialOpenPosition.X.Scale, initialOpenPosition.X.Offset, initialOpenPosition.Y.Scale, initialOpenPosition.Y.Offset + 34)
    if menuScale then menuScale.Scale = menuClosedScale end
    outer.Visible = true
    S.menuTween = TS_G:Create(menuScale, TweenInfo.new(0.44, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {Scale = activeDashboardScale()})
    S.menuPositionTween = TS_G:Create(outer, TweenInfo.new(0.44, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), {Position = initialOpenPosition})
    S.menuTween:Play()
    S.menuPositionTween:Play()

    -- Button feedback is visual only; all actions stay in Activated so both
    -- mouse clicks and touchscreen taps use the same callback exactly once.
    local function styleWindowControl(button, stroke, role)
        button.Active = true
        button.Selectable = true
        button.AutoButtonColor = false
        local normalTransparency = 0.08
        local function getNormalColor()
            if role == "close" then return Color3.fromRGB(28, 9, 16) end
            return activeThemeDef.dark:Lerp(Color3.fromRGB(8, 8, 12), 0.52)
        end
        local function getHoverColor()
            if role == "close" then return Color3.fromRGB(132, 28, 49) end
            return activeThemeDef.accent
        end
        local function getHoverStroke()
            return activeThemeDef.bright
        end
        button.BackgroundColor3 = getNormalColor()
        stroke.Color = activeThemeDef.border
        stroke.Transparency = normalTransparency
        button.MouseEnter:Connect(function()
            if not button.Parent then return end
            TS_G:Create(button, TweenInfo.new(0.12, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
                BackgroundColor3 = getHoverColor(),
            }):Play()
            TS_G:Create(stroke, TweenInfo.new(0.12, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
                Color = getHoverStroke(), Transparency = 0,
            }):Play()
        end)
        button.MouseLeave:Connect(function()
            if not button.Parent then return end
            TS_G:Create(button, TweenInfo.new(0.16, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
                BackgroundColor3 = getNormalColor(),
            }):Play()
            TS_G:Create(stroke, TweenInfo.new(0.16, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
                Color = activeThemeDef.border, Transparency = normalTransparency,
            }):Play()
        end)
        button.Activated:Connect(function()
            if not button.Parent then return end
            local pressTween = TS_G:Create(button, TweenInfo.new(0.07, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
                BackgroundColor3 = getHoverColor(),
            })
            pressTween:Play()
            task.delay(0.10, function()
                if button and button.Parent then
                    TS_G:Create(button, TweenInfo.new(0.13, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
                        BackgroundColor3 = getNormalColor(),
                    }):Play()
                end
            end)
        end)
    end
    styleWindowControl(closeBtn, closeBtnStroke, "close")
    styleWindowControl(minimizeBtn, minimizeStroke, "normal")
    styleWindowControl(maximizeBtn, maximizeStroke, "normal")

    -- Launcher is hidden only after successful construction. Keep the ScreenGui
    -- enabled throughout so close/minimize can always reveal its button again.
    if S._xypherLauncherGui then S._xypherLauncherGui.Enabled = true end
    if S.miniToggleButton then S.miniToggleButton.Visible = false end
    S._xypherBuildReady = true
    if S._xypherOpenPending and showGui then
        S._xypherOpenPending = false
        task.defer(function()
            pcall(showGui)
            if S.miniToggleButton then S.miniToggleButton.Visible = false end
        end)
    end

    UIS.InputBegan:Connect(function(input, gpe)
        if input.UserInputType~=Enum.UserInputType.Keyboard and input.UserInputType~=Enum.UserInputType.Gamepad1 then return end
        local kc=input.KeyCode
        local function match(e) return kc==e.kb or (e.gp and kc==e.gp) end
        if gpe then
            if match(S.KB.GuiHide) then if outer.Visible then hideGui() else showGui() end end
            return
        end
        if match(S.KB.DropBrainrot) then task.spawn(runDropBrainrot)
        elseif match(S.KB.TPFlor) then runTPFloor()
        elseif match(S.KB.AutoLeft) then
            S.autoLeftEnabled=not S.autoLeftEnabled
            if S.autoLeftEnabled then
                if S.autoRightEnabled then S.autoRightEnabled=false; stopAutoRight(); if S.autoRightSetVisual then S.autoRightSetVisual(false) end end
                if S.batAimbotEnabled then setBatAimbot(false) end
                startAutoLeft()
            else stopAutoLeft() end
            if S.autoLeftSetVisual then S.autoLeftSetVisual(S.autoLeftEnabled) end
            S.restartMovement(); updateFloatingButtons(); saveConfig()
        elseif match(S.KB.AutoRight) then
            S.autoRightEnabled=not S.autoRightEnabled
            if S.autoRightEnabled then
                if S.autoLeftEnabled then S.autoLeftEnabled=false; stopAutoLeft(); if S.autoLeftSetVisual then S.autoLeftSetVisual(false) end end
                if S.batAimbotEnabled then setBatAimbot(false) end
                startAutoRight()
            else stopAutoRight() end
            if S.autoRightSetVisual then S.autoRightSetVisual(S.autoRightEnabled) end
            S.restartMovement(); updateFloatingButtons(); saveConfig()
        elseif match(S.KB.AutoBat) then setBatAimbot(not S.batAimbotEnabled)
        elseif match(S.KB.TpBat) then
            local enabled = not S.tpBatEnabled
            setTpBat(enabled)
            if S.tpBatSetVisual then S.tpBatSetVisual(enabled) end
            saveConfig()
        elseif match(S.KB.GuiHide) then if outer.Visible then hideGui() else showGui() end
        elseif match(S.KB.SpeedToggle) then S.toggleCarryMode(); S.restartMovement(); updateFloatingButtons(); saveConfig()
        elseif match(S.KB.LaggerToggle) then S.toggleLaggerMode(); S.restartMovement(); updateFloatingButtons(); saveConfig()
        elseif match(S.KB.InstaReset) then
            if _G.InstaReset and _G.InstaReset.Trigger then _G.InstaReset.Trigger() end
        end
    end)
end


-- ===========================
-- FLOATING BUTTON PANEL (HALLOWEEN ORANGE / BLACK)
-- ===========================
local function createFloatingButtonPanel()
    local panelGui = Instance.new("ScreenGui")
    panelGui.Name = "FloatingModeMenu"
    panelGui.DisplayOrder = 50
    panelGui.IgnoreGuiInset = true
    panelGui.ResetOnSpawn = false
    panelGui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
    panelGui.Enabled = XYPHER_STARTUP_INTRO_COMPLETE
    panelGui.Parent = LP:WaitForChild("PlayerGui")
    S.floatingPanelGui = panelGui

    local layoutFrame = Instance.new("Frame")
    layoutFrame.Name = "ButtonLayout"
    layoutFrame.AnchorPoint = Vector2.new(1, 0)
    layoutFrame.Position = UDim2.new(0.79, 0, 0, 0)
    layoutFrame.Size = UDim2.fromOffset(0, 0)
    layoutFrame.BackgroundTransparency = 1
    layoutFrame.BorderSizePixel = 0
    layoutFrame.ClipsDescendants = false
    layoutFrame.Active = false
    layoutFrame.Selectable = false
    layoutFrame.Parent = panelGui
    S.floatingPanelFrame = layoutFrame
    -- El panel principal mueve juntos sus botones; TP BAT y RESET van en una
    -- capa independiente para poder moverlos por separado.
    -- Solo esta franja superior captura el arrastre; el resto queda libre.
    local dragHandle = Instance.new("Frame")
    dragHandle.Name = "FloatingPanelDragHandle"
    dragHandle.Size = UDim2.fromOffset(0, 48)
    dragHandle.Position = UDim2.fromOffset(0, 0)
    dragHandle.BackgroundTransparency = 1
    dragHandle.BorderSizePixel = 0
    dragHandle.Active = true
    dragHandle.Parent = layoutFrame
    makeDraggable(dragHandle, true, layoutFrame)

    local freeButtonLayer = Instance.new("Frame")
    freeButtonLayer.Name = "IndependentButtonLayer"
    freeButtonLayer.AnchorPoint = Vector2.new(1, 0)
    freeButtonLayer.Position = UDim2.new(0.79, 0, 0, 0)
    freeButtonLayer.Size = UDim2.fromOffset(0, 0)
    freeButtonLayer.BackgroundTransparency = 1
    freeButtonLayer.BorderSizePixel = 0
    freeButtonLayer.ClipsDescendants = false
    freeButtonLayer.Active = false
    freeButtonLayer.Selectable = false
    freeButtonLayer.Parent = panelGui

    local selectedName = "CARRY SPD"
    local buttons = {}
    local BLACK = Color3.fromRGB(1, 1, 1)
    local WHITE = Color3.fromRGB(255, 255, 255)

    local buttonDefinitions = {
        {name = "DROP BR",       displayText = "DROP\nBR",       column = 2, row = 0},
        {name = "AUTO LEFT",     displayText = "AUTO\nLEFT",     column = 3, row = 0},
        {name = "TP BAT",        displayText = "TP\nBAT",       column = 1, row = 1}, -- visual only; intentionally no action
        {name = "BAT AIMBOT",    displayText = "BAT\nAIMBOT",   column = 2, row = 1},
        {name = "AUTO RIGHT",    displayText = "AUTO\nRIGHT",    column = 3, row = 1},
        {name = "Reset",         displayText = "RESET",         column = 1, row = 2},
        {name = "TP DOWN",       displayText = "TP\nDOWN",       column = 2, row = 2},
        {name = "CARRY SPD",     displayText = "CARRY\nSPD",     column = 3, row = 2},
        {name = "NORMAL LAGGER", displayText = "NORMAL\nLAGGER", column = 2, row = 3},
        {name = "CARRY LAGGER",  displayText = "CARRY\nLAGGER",  column = 3, row = 3},
    }

    local function applyButtonStyle(info, isSelected)
        if isSelected then
            info.button.BackgroundColor3 = WHITE
            info.button.TextColor3 = Color3.fromRGB(27, 27, 27)
            info.gradient.Enabled = true
        else
            info.button.BackgroundColor3 = BLACK
            info.button.TextColor3 = WHITE
            info.gradient.Enabled = false
        end
    end

    local pressTweenInfo = TweenInfo.new(0.09, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
    local releaseTweenInfo = TweenInfo.new(0.16, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)

    for _, definition in ipairs(buttonDefinitions) do
        local button = Instance.new("TextButton")
        button.Name = string.gsub(definition.name, "%s+", "")
        button.BackgroundColor3 = BLACK
        button.BorderSizePixel = 0
        button.AutoButtonColor = false
        button.Text = definition.displayText or definition.name
        button.TextColor3 = WHITE
        button.TextScaled = true
        button.TextWrapped = true
        button.Font = Enum.Font.GothamBold
        button.ZIndex = 2
        button.Parent = layoutFrame

        -- Keep persistent mobile size separate from the press/bounce animation.
        -- Otherwise every tap would overwrite the user's selected size.
        local mobileSizeScale = Instance.new("UIScale")
        mobileSizeScale.Name = "MobileSizeScale"
        mobileSizeScale.Scale = 1
        mobileSizeScale.Parent = button
        local infoButtonScale = mobileSizeScale

        local pressScale = Instance.new("UIScale")
        pressScale.Name = "PressAnimationScale"
        pressScale.Scale = 1
        pressScale.Parent = button
        local activeScaleTween
        local function animateScale(target, info)
            if activeScaleTween then activeScaleTween:Cancel() end
            activeScaleTween = TS_G:Create(pressScale, info, {Scale = target})
            activeScaleTween:Play()
        end
        button.InputBegan:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                animateScale(0.92, pressTweenInfo)
            end
        end)
        button.InputEnded:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                animateScale(1, releaseTweenInfo)
            end
        end)

        local corner = Instance.new("UICorner")
        corner.CornerRadius = UDim.new(0.24, 0)
        corner.Parent = button
        local textLimit = Instance.new("UITextSizeConstraint")
        textLimit.MinTextSize = 10
        textLimit.MaxTextSize = 15
        textLimit.Parent = button
        local gradient = Instance.new("UIGradient")
        gradient.Name = "SelectedGradient"
        gradient.Enabled = false
        gradient.Rotation = 90
        gradient.Color = ColorSequence.new({
            ColorSequenceKeypoint.new(0, Color3.fromRGB(255, 255, 255)),
            ColorSequenceKeypoint.new(0.56, Color3.fromRGB(225, 225, 225)),
            ColorSequenceKeypoint.new(1, Color3.fromRGB(79, 79, 79)),
        })
        gradient.Parent = button

        local isFreeButton = definition.name == "TP BAT" or definition.name == "Reset"
        if isFreeButton then
            button.Parent = freeButtonLayer
        end
        local info = {
            button = button,
            buttonScale = infoButtonScale,
            gradient = gradient,
            name = definition.name,
            column = definition.column,
            row = definition.row,
            independent = isFreeButton,
            userMoved = false,
            _dragging = false,
            _dragMoved = false,
        }
        table.insert(buttons, info)

        -- Mobile buttons are individually draggable whenever Lock UI is OFF.
        -- This is independent from the button's Activated action, so dragging
        -- cannot accidentally execute the feature underneath the finger.
        hit.Active = true
        local dragInput, dragStart, startPos
        local dragging, moved = false, false
        local function beginMobileDrag(input)
            if S.lockUIEnabled then return end
            if input.UserInputType == Enum.UserInputType.MouseButton1
                or input.UserInputType == Enum.UserInputType.Touch then
                dragging = true
                moved = false
                info._dragging = true
                info._dragMoved = false
                dragStart = input.Position
                startPos = button.Position
            end
        end
        local function updateMobileDrag(input)
            if S.lockUIEnabled then
                dragging = false
                moved = false
                info._dragging = false
                return
            end
            if not dragging or not dragStart or not startPos then return end
            if input.UserInputType == Enum.UserInputType.MouseMovement
                or input.UserInputType == Enum.UserInputType.Touch then
                local delta = input.Position - dragStart
                if delta.Magnitude > 5 then
                    moved = true
                    info._dragMoved = true
                    info.userMoved = true
                    button.Position = UDim2.new(
                        startPos.X.Scale, startPos.X.Offset + delta.X,
                        startPos.Y.Scale, startPos.Y.Offset + delta.Y
                    )
                end
            end
        end
        local function endMobileDrag(input)
            if input.UserInputType ~= Enum.UserInputType.MouseButton1
                and input.UserInputType ~= Enum.UserInputType.Touch then return end
            local didMove = moved
            dragging = false
            moved = false
            info._dragging = false
            if didMove then
                if isFreeButton then
                    S.floatingFreeButtonPositions[definition.name] = {
                        X = button.Position.X.Offset,
                        Y = button.Position.Y.Offset,
                    }
                else
                    S.mobileButtonPositions[definition.name] = {
                        X = button.Position.X.Offset,
                        Y = button.Position.Y.Offset,
                    }
                end
                saveConfig()
                task.delay(0.15, function()
                    if info and info.button and info.button.Parent then
                        info._dragMoved = false
                    end
                end)
            else
                info._dragMoved = false
                S._floatingPanelDragging = false
            end
        end
        hit.InputBegan:Connect(beginMobileDrag)
        hit.InputChanged:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseMovement
                or input.UserInputType == Enum.UserInputType.Touch then
                dragInput = input
            end
        end)
        UIS.InputChanged:Connect(function(input)
            if input == dragInput then updateMobileDrag(input) end
        end)
        UIS.InputEnded:Connect(endMobileDrag)

        if isFreeButton then
            local saved = S.floatingFreeButtonPositions[definition.name]
            if type(saved) == "table" and type(saved.X) == "number" and type(saved.Y) == "number" then
                button.Position = UDim2.fromOffset(saved.X, saved.Y)
                info.userMoved = true
            end
        else
            local saved = S.mobileButtonPositions[definition.name]
            if type(saved) == "table" and type(saved.X) == "number" and type(saved.Y) == "number" then
                button.Position = UDim2.fromOffset(saved.X, saved.Y)
                info.userMoved = true
            end
        end

        button.Activated:Connect(function()
            if info.name == "TP DOWN" then return end
            -- Los botones de velocidad controlan su propia luz después de cambiar
            -- el modo. No aplicar aquí el estilo genérico, porque este evento
            -- puede ejecutarse después del handler de acción y volver a encender
            -- Carry/Lagger al apagarlos con el segundo toque.
            local isModeButton = info.name == "CARRY SPD"
                or info.name == "NORMAL LAGGER"
                or info.name == "CARRY LAGGER"
                or info.name == "BAT AIMBOT"
                or info.name == "TP BAT"
            if isModeButton then return end
            selectedName = info.name
            for _, item in ipairs(buttons) do applyButtonStyle(item, item.name == selectedName) end
        end)
    end

    local function find(name)
        for _, info in ipairs(buttons) do
            if info.name == name then return info end
        end
    end
    local function flash(info, duration)
        if not info then return end
        applyButtonStyle(info, true)
        task.delay(duration or 0.35, function()
            if info.button and info.button.Parent then applyButtonStyle(info, false) end
        end)
    end
    local function canPress()
        -- Lock UI only controls dragging; it must never disable mobile button actions.
        return not S._floatingPanelDragging
    end

    local drop = find("DROP BR")
    local autoLeft = find("AUTO LEFT")
    local tpBat = find("TP BAT")
    local bat = find("BAT AIMBOT")
    S.tpBatSetVisual = function(active)
        if tpBat and tpBat.button and tpBat.button.Parent then applyButtonStyle(tpBat, active == true) end
    end
    local autoRight = find("AUTO RIGHT")
    local reset = find("Reset")
    local tpDown = find("TP DOWN")
    local carry = find("CARRY SPD")
    local normalLagger = find("NORMAL LAGGER")
    local carryLagger = find("CARRY LAGGER")

    local function connectAction(info, action)
        info.button.Activated:Connect(function()
            -- A touch that moved the button is a drag, not a button click.
            if info._dragMoved then return end
            if canPress() then action() end
        end)
    end
    connectAction(drop, function() flash(drop, 0.5); task.spawn(runDropBrainrot) end)
    connectAction(tpBat, function()
        -- TP BAT usa la logica completa: primer toque ON, segundo OFF.
        local enabled = not S.tpBatEnabled
        setTpBat(enabled)
        if S.tpBatSetVisual then S.tpBatSetVisual(enabled) else applyButtonStyle(tpBat, enabled) end
        saveConfig()
    end)
    connectAction(bat, function()
        local on = not S.batAimbotEnabled
        if on then
            if S.autoLeftEnabled then S.autoLeftEnabled = false; stopAutoLeft(); if S.autoLeftSetVisual then S.autoLeftSetVisual(false) end end
            if S.autoRightEnabled then S.autoRightEnabled = false; stopAutoRight(); if S.autoRightSetVisual then S.autoRightSetVisual(false) end end
        end
        setBatAimbot(on)
        -- BAT AIMBOT controla su propia luz: primer toque ON, segundo toque OFF.
        applyButtonStyle(bat, on)
        updateFloatingButtons()
    end)
    connectAction(autoLeft, function()
        local on = not S.autoLeftEnabled
        if on then
            if S.autoRightEnabled then S.autoRightEnabled = false; stopAutoRight() end
            if S.batAimbotEnabled then setBatAimbot(false) end
            S.autoLeftEnabled = true; startAutoLeft()
        else S.autoLeftEnabled = false; stopAutoLeft() end
        if S.autoLeftSetVisual then S.autoLeftSetVisual(on) end
        S.restartMovement(); updateFloatingButtons(); saveConfig()
    end)
    connectAction(autoRight, function()
        local on = not S.autoRightEnabled
        if on then
            if S.autoLeftEnabled then S.autoLeftEnabled = false; stopAutoLeft() end
            if S.batAimbotEnabled then setBatAimbot(false) end
            S.autoRightEnabled = true; startAutoRight()
        else S.autoRightEnabled = false; stopAutoRight() end
        if S.autoRightSetVisual then S.autoRightSetVisual(on) end
        S.restartMovement(); updateFloatingButtons(); saveConfig()
    end)
    connectAction(reset, function() flash(reset, 0.5); if _G.InstaReset and _G.InstaReset.Trigger then _G.InstaReset.Trigger() end end)
    connectAction(tpDown, function()
        applyButtonStyle(tpDown, true)
        runTPFloor()
        task.delay(0.45, function()
            if tpDown and tpDown.button and tpDown.button.Parent then applyButtonStyle(tpDown, false) end
        end)
    end)
    local function refreshLaggerButtons()
        applyButtonStyle(normalLagger, S.laggerMode == 1 and not S.speedMode)
        applyButtonStyle(carryLagger, S.laggerMode == 2 and not S.speedMode)
    end

    -- Deja los tres botones de velocidad apagados y vuelve siempre a S.NS.
    -- Esto se usa al dar el segundo toque al botón que ya está activo.
    local function returnToNormalSpeed()
        S.setNormalSpeedMode()
        S.restartMovement()
        updateFloatingButtons()
        applyButtonStyle(carry, false)
        applyButtonStyle(normalLagger, false)
        applyButtonStyle(carryLagger, false)
        saveConfig()
    end

    connectAction(carry, function()
        -- Segundo toque en Carry: apagar Carry y volver a Normal Speed.
        if S.speedMode and S.laggerMode == 0 then
            returnToNormalSpeed()
            return
        end

        -- Primer toque (o cambio desde un modo Lagger): activar Carry.
        S.setCarrySpeedMode()
        S.restartMovement()
        updateFloatingButtons()
        refreshLaggerButtons()
        applyButtonStyle(normalLagger, false)
        applyButtonStyle(carryLagger, false)
        saveConfig()
    end)

    local function setLaggerSpeedMode(mode)
        -- Segundo toque en el mismo botón Lagger: apagarlo y volver a Normal.
        if S.laggerMode == mode and not S.speedMode then
            returnToNormalSpeed()
            return
        end

        -- Primer toque, o cambio entre Normal Lagger y Carry Lagger.
        S.speedMode = false
        S.laggerMode = mode
        S.refreshSpeedModeLabel()
        S.applySpeedVelocityNow()
        S.restartMovement()
        updateFloatingButtons()
        refreshLaggerButtons()
        saveConfig()
    end

    connectAction(normalLagger, function() setLaggerSpeedMode(1) end) -- S.LS: Lagger Normal Speed
    connectAction(carryLagger, function() setLaggerSpeedMode(2) end) -- S.LCS: Lagger Carry Speed

    S.dropBrainrotSetVisual = function(active) applyButtonStyle(drop, active) end
    S.dropBrainrotFloatVisual = S.dropBrainrotSetVisual
    -- Reset remains highlighted only while its action is running; respawn clears it.
    LP.CharacterAdded:Connect(function()
        task.defer(function()
            if reset and reset.button and reset.button.Parent then applyButtonStyle(reset, false) end
            if drop and drop.button and drop.button.Parent then applyButtonStyle(drop, false) end
        end)
    end)
    S._btnAAL, S._bsAAL, S._l1AAL, S._l2AAL = autoLeft.button, nil, nil, nil
    S._btnAAR, S._bsAAR, S._l1AAR, S._l2AAR = autoRight.button, nil, nil, nil
    S._btnBAT, S._bsBAT, S._l1BAT, S._l2BAT = bat.button, nil, nil, nil
    S._setPButtonActive = function(button, _, _, _, active)
        for _, info in ipairs(buttons) do
            if info.button == button then
                applyButtonStyle(info, active)
                return
            end
        end
    end
    S._floatingButtons = {
        lagger = normalLagger.button,
        l2Lagger = {Text = ""},
        carry = carry.button,
        autoLeft = autoLeft.button,
        autoRight = autoRight.button,
        bat = bat.button,
    }

    local function updateLayout()
        local camera = workspace.CurrentCamera
        if not camera then return end
        local viewport = camera.ViewportSize
        local isLandscape = viewport.X > viewport.Y
        local sizeFactor = isLandscape and 0.16 or 0.18
        local buttonSize = math.floor(math.min(viewport.Y * sizeFactor, viewport.X * 0.24))
        local gap = math.max(8, math.floor(buttonSize * 0.14))
        local pitch = buttonSize + gap
        -- No reposicionar aquí: el usuario puede haber guardado o movido el panel.
        local firstRowY = math.floor(viewport.Y * (isLandscape and 0.18 or 0.205))
        -- Las capas solo cubren el rectángulo de los botones; no toda la pantalla.
        local groupHeight = firstRowY + buttonSize * 4 + gap * 3 + gap
        local groupWidth = buttonSize * 4 + gap * 3
        layoutFrame.Size = UDim2.fromOffset(groupWidth, groupHeight)
        freeButtonLayer.Size = UDim2.fromOffset(groupWidth, groupHeight)
        dragHandle.Size = UDim2.fromOffset(groupWidth, math.max(48, firstRowY))
        local scale = math.clamp(tonumber(S.mobileButtonScale) or 1.0, 0.50, 2.00)
        for _, info in ipairs(buttons) do
            -- Apply the user's size directly to the real button dimensions.
            -- The press animation keeps its own UIScale, so tapping cannot
            -- overwrite the chosen size.
            info.baseButtonWidth = buttonSize
            info.baseButtonHeight = buttonSize
            info.button.Size = UDim2.fromOffset(
                math.max(24, math.floor(buttonSize * scale + 0.5)),
                math.max(24, math.floor(buttonSize * scale + 0.5))
            )
            if not info.userMoved then
                info.button.Position = UDim2.fromOffset(info.column * pitch, firstRowY + info.row * pitch)
            end
        end
    end
    local cameraConnection
    local function bindCamera()
        if cameraConnection then cameraConnection:Disconnect() end
        local camera = workspace.CurrentCamera
        if camera then
            cameraConnection = camera:GetPropertyChangedSignal("ViewportSize"):Connect(updateLayout)
            updateLayout()
        end
    end
    workspace:GetPropertyChangedSignal("CurrentCamera"):Connect(bindCamera)
    bindCamera()
    -- Apply any saved individual positions after the first layout pass.
    for _, info in ipairs(buttons) do
        if not info.independent then
            local saved = S.mobileButtonPositions[info.name]
            if type(saved) == "table" and type(saved.X) == "number" and type(saved.Y) == "number" then
                info.button.Position = UDim2.fromOffset(saved.X, saved.Y)
                info.userMoved = true
            end
        end
    end

    S._floatingButtonInfos = buttons
    S._floatingFreeButtonLayer = freeButtonLayer
    S._floatingUpdateLayout = updateLayout
    if S._savedFloatingPanelPos then
        local pos = S._savedFloatingPanelPos
        layoutFrame.Position = UDim2.new(pos.XS or 0.79, pos.X or 0, pos.YS or 0, pos.Y or 0)
    end
    for _, info in ipairs(buttons) do applyButtonStyle(info, false) end
    applyButtonStyle(carry, S.speedMode and S.laggerMode == 0)
    applyButtonStyle(normalLagger, S.laggerMode == 1 and not S.speedMode)
    applyButtonStyle(carryLagger, S.laggerMode == 2 and not S.speedMode)
    applyButtonStyle(autoLeft, S.autoLeftEnabled)
    applyButtonStyle(autoRight, S.autoRightEnabled)
    applyButtonStyle(bat, S.batAimbotEnabled)
    applyButtonStyle(tpBat, S.tpBatEnabled)
end

-- ===========================
-- MOBILE BUTTON SIZE CONTROL
-- ===========================
S.setMobileButtonScale = function(scale)
    scale = tonumber(scale) or 1.0
    scale = math.clamp(scale, 0.50, 2.00)
    scale = math.floor(scale * 100 + 0.5) / 100
    S.mobileButtonScale = scale

    local touched = 0

    -- The replacement mobile UI has a parent UIScale just like the supplied
    -- Mobile_Button_UI_Only file. Use it as a single source of truth so the
    -- button, its text, gaps, and layout all scale proportionally.
    local floatingScale = S._floatingPanelScale
    if floatingScale and floatingScale.Parent then
        floatingScale.Scale = scale
        local infos = S._floatingButtonInfos
        if type(infos) == "table" then
            for _, info in ipairs(infos) do
                if info and info.button and info.button.Parent then touched += 1 end
            end
        end
        if S.mobileButtonScaleSetVisual then
            pcall(S.mobileButtonScaleSetVisual, scale)
        end
        return touched
    end

    -- Keep the label size proportional to the button size for legacy panels.
    -- The main Vision buttons use TextScaled + UITextSizeConstraint.
    local function scaleButtonText(button, multiplier)
        if not button or not button.Parent then return end
        multiplier = tonumber(multiplier) or scale

        local constraint = button:FindFirstChildOfClass("UITextSizeConstraint")
        if constraint then
            local baseMin = button:GetAttribute("VisionBaseTextMin")
            local baseMax = button:GetAttribute("VisionBaseTextMax")
            if type(baseMin) ~= "number" then baseMin = constraint.MinTextSize end
            if type(baseMax) ~= "number" then baseMax = constraint.MaxTextSize end
            button:SetAttribute("VisionBaseTextMin", baseMin)
            button:SetAttribute("VisionBaseTextMax", baseMax)
            constraint.MinTextSize = math.max(4, math.floor(baseMin * multiplier + 0.5))
            constraint.MaxTextSize = math.max(constraint.MinTextSize, math.floor(baseMax * multiplier + 0.5))
        elseif button:IsA("TextButton") or button:IsA("TextLabel") or button:IsA("TextBox") then
            local baseTextSize = button:GetAttribute("VisionBaseTextSize")
            if type(baseTextSize) ~= "number" then baseTextSize = button.TextSize end
            button:SetAttribute("VisionBaseTextSize", baseTextSize)
            button.TextSize = math.max(4, math.floor(baseTextSize * multiplier + 0.5))
        end

        -- Floating buttons have a child TextButton named TextAndTouch.
        local touch = button:FindFirstChild("TextAndTouch")
        if touch and touch:IsA("TextButton") then
            local baseTextSize = touch:GetAttribute("VisionBaseTextSize")
            if type(baseTextSize) ~= "number" then baseTextSize = touch.TextSize end
            touch:SetAttribute("VisionBaseTextSize", baseTextSize)
            touch.TextSize = math.max(4, math.floor(baseTextSize * multiplier + 0.5))
        end
    end

    -- Primary Vision mobile panel: change the actual button Size so the
    -- setting is visible and reliable on touch devices.
    local infos = S._floatingButtonInfos
    if type(infos) == "table" then
        for _, info in ipairs(infos) do
            if type(info) == "table" and info.button and info.button.Parent then
                local button = info.button
                local baseW = tonumber(info.baseButtonWidth) or tonumber(button:GetAttribute("VisionBaseWidth"))
                local baseH = tonumber(info.baseButtonHeight) or tonumber(button:GetAttribute("VisionBaseHeight"))
                if baseW and baseH then
                    button.Size = UDim2.fromOffset(
                        math.max(24, math.floor(baseW * scale + 0.5)),
                        math.max(24, math.floor(baseH * scale + 0.5))
                    )
                    scaleButtonText(button, scale)
                    touched += 1
                end
                local mobileScale = button:FindFirstChild("MobileSizeScale")
                if mobileScale and mobileScale:IsA("UIScale") then
                    -- Keep only PressAnimationScale responsible for tap bounce.
                    mobileScale.Scale = 1
                end
            end
        end
    end

    -- Re-run the layout after changing the value so the normal viewport-based
    -- button size calculation and the custom multiplier stay synchronized.
    if type(S._floatingUpdateLayout) == "function" then
        pcall(S._floatingUpdateLayout)
    end

    -- Fallback for any VisualButton_* panels that may be created by an older
    -- Vision builder. These retain their base size and get the same multiplier.
    local pg = LP:FindFirstChildOfClass("PlayerGui")
    if pg then
        for _, obj in ipairs(pg:GetDescendants()) do
            if obj:IsA("GuiObject") and obj.Name:match("^VisualButton_") then
                local baseW = obj:GetAttribute("VisionBaseWidth")
                local baseH = obj:GetAttribute("VisionBaseHeight")
                if type(baseW) ~= "number" or type(baseH) ~= "number" then
                    local size = obj.AbsoluteSize
                    baseW, baseH = size.X, size.Y
                    obj:SetAttribute("VisionBaseWidth", baseW)
                    obj:SetAttribute("VisionBaseHeight", baseH)
                end
                obj.Size = UDim2.fromOffset(
                    math.max(24, math.floor(baseW * scale + 0.5)),
                    math.max(24, math.floor(baseH * scale + 0.5))
                )
                scaleButtonText(obj, scale)
                local mobileScale = obj:FindFirstChild("MobileSizeScale")
                if mobileScale and mobileScale:IsA("UIScale") then mobileScale.Scale = 1 end
                touched += 1
            end
        end
    end

    -- Apply to any additional Vision mobile controls that were created without
    -- being registered in _floatingButtonInfos.
    local pg2 = LP:FindFirstChildOfClass("PlayerGui")
    if pg2 then
        for _, obj in ipairs(pg2:GetDescendants()) do
            if obj:IsA("TextButton") and (obj.Name == "TextAndTouch" or obj:GetAttribute("VisionMobileButton") == true) then
                scaleButtonText(obj, scale)
            end
        end
    end

    if S.mobileButtonScaleSetVisual then
        pcall(S.mobileButtonScaleSetVisual, scale)
    end
    return touched
end

S.getMobileButtonScaleMode = function()
    if S.mobileButtonScale > 1.05 then return "Large" end
    if S.mobileButtonScale < 0.95 then return "Small" end
    return "Normal"
end

-- ===========================
-- FLOATING BUTTON PANEL (Mobile_Button_UI_Only style, Vision actions wired)
-- Polished mobile buttons: subtle glass sheen, low-cost diagonal shimmer, dual neon rim.
-- ===========================
createFloatingButtonPanel = function()
    -- Refresh the live target registry each time the mobile panel is rebuilt.
    S.mobileButtonBackgroundImages = {}
    local gui = Instance.new("ScreenGui")
    gui.Name = "FloatingModeMenu"
    gui.DisplayOrder = 50
    gui.IgnoreGuiInset = true
    gui.ResetOnSpawn = false
    gui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
    gui.Parent = LP:WaitForChild("PlayerGui")
    S.floatingPanelGui = gui

    local container = Instance.new("Frame")
    container.Name = "FloatingButtons"
    container.AnchorPoint = Vector2.new(1, 0)
    container.Position = UDim2.new(1, -58, 0, 95)
    -- Layout follows Mobile_Button_UI_Only: compact two-column, rounded-square buttons.
    -- Vision keeps its existing actions and wiring; only the visual panel is replaced.
    container.Size = UDim2.fromOffset(136, 450)
    container.BackgroundTransparency = 1
    container.BorderSizePixel = 0
    container.ZIndex = 10
    container.Parent = gui
    S.floatingPanelFrame = container

    -- Match the uploaded UI's single parent scale so button size, label text,
    -- spacing, and layout scale together without overlapping each other.
    local containerScale = Instance.new("UIScale")
    containerScale.Name = "MobileButtonScale"
    containerScale.Scale = 1
    containerScale.Parent = container
    S._floatingPanelScale = containerScale

    -- Palette and grid adapted from Mobile_Button_UI_Only.lua.
    local BUTTON_BASE = Color3.fromRGB(5, 5, 5)
    local TEXT_LIGHT = Color3.fromRGB(255, 255, 255)
    local STROKE = Color3.fromRGB(121, 121, 121)
    local ACTIVE_STROKE = Color3.fromRGB(160, 160, 160)
    local byId, infos = {}, {}
    -- The source UI has eight buttons. Vision has three additional mobile actions,
    -- so they are kept and styled identically rather than silently removing features.
    local positions = {
        {"Drop", "DROP\nBR", 0, 0},
        {"AutoLeft", "AUTO\nLEFT", 68, 0},
        {"AutoBat", "BAT\nAIMBOT", 0, 78},
        {"AutoRight", "AUTO\nRIGHT", 68, 78},
        {"TPDown", "TP\nDOWN", 0, 156},
        {"CarrySpd", "CARRY\nSPD", 68, 156},
        {"LaggerNormal", "LAGGER\n1", 0, 234},
        {"LaggerCarry", "LAGGER\n2", 68, 234},
        {"InstaReset", "INSTANT\nRESET", 0, 312},
        {"BatUp", "TP\nBAT", 68, 312},
        {"AntiBatAimbot", "ANTIBAT\nAIMBOT", 0, 390},
    }
    -- Translate default offsets from the previous three-column Vision panel.
    -- Custom positions remain untouched; only old defaults are remapped.
    local legacyDefaultPositions = {
        Drop = {72, 0}, AutoLeft = {144, 0}, InstaReset = {0, 60},
        AutoBat = {72, 60}, BatUp = {0, 120}, AutoRight = {144, 60},
        TPDown = {72, 120}, CarrySpd = {144, 120}, AntiBatAimbot = {0, 180},
        LaggerCarry = {72, 180}, LaggerNormal = {144, 180},
    }
    local function style(i, active)
        if not i or not i.button or not i.button.Parent then return end
        i.active = active == true
        i.button:SetAttribute("XypherMobileActive", i.active)
        local palette = S.activeThemePalette
        i.button.BackgroundColor3 = BUTTON_BASE
        -- Re-read the shared palette whenever a feature changes state, so the
        -- button won't revert to gray after changing themes or flashing.
        i.gradient.Enabled = true
        i.gradient.Rotation = 90
        i.gradient.Color = ColorSequence.new({
            ColorSequenceKeypoint.new(0.00, palette and palette.bright or Color3.fromRGB(164, 164, 164)),
            ColorSequenceKeypoint.new(0.32, palette and palette.accent or Color3.fromRGB(138, 138, 138)),
            ColorSequenceKeypoint.new(0.66, palette and palette.dark or Color3.fromRGB(49, 49, 49)),
            ColorSequenceKeypoint.new(1.00, Color3.fromRGB(5, 5, 5)),
        })
        i.stroke.Color = i.active and (palette and palette.bright or ACTIVE_STROKE) or (palette and palette.border or STROKE)
        i.stroke.Transparency = i.active and 0.02 or 0.28
        i.stroke.Thickness = i.active and 1.65 or 1.1
        -- A second, softer rim creates a neon bloom without adding particles or per-frame work.
        if i.glowStroke and i.glowStroke.Parent then
            i.glowStroke.Color = palette and palette.accent or ACTIVE_STROKE
            i.glowStroke.Transparency = i.active and 0.67 or 0.83
            i.glowStroke.Thickness = i.active and 4 or 3
        end
        i.hit.TextColor3 = TEXT_LIGHT
        i.hit.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
        i.hit.TextStrokeTransparency = 0.25
    end
    local function flash(i, duration)
        style(i, true)
        task.delay(duration or 0.45, function()
            if i and i.button and i.button.Parent then style(i, false) end
        end)
    end
    for buttonIndex, p in ipairs(positions) do
        local button = Instance.new("Frame")
        button.Name = "VisualButton_" .. p[1]
        button:SetAttribute("VisionMobileButton", true)
        button:SetAttribute("VisionMobileButtonId", p[1])
        button:SetAttribute("VisionBaseWidth", 60)
        button:SetAttribute("VisionBaseHeight", 60)
        button.Position = UDim2.fromOffset(p[3], p[4])
        button.Size = UDim2.fromOffset(60, 60)
        button.BackgroundColor3 = BUTTON_BASE
        button.BorderSizePixel = 0
        button.ClipsDescendants = true
        button.ZIndex = 11
        button.Parent = container
        local corner = Instance.new("UICorner")
        corner.CornerRadius = UDim.new(0, 18)
        corner.Parent = button

        local photoBackground = Instance.new("ImageLabel")
        photoBackground.Name = "MobileButtonPhotoBackground"
        photoBackground.Position = UDim2.fromScale(0, 0)
        photoBackground.Size = UDim2.fromScale(1, 1)
        photoBackground.BackgroundTransparency = 1
        photoBackground.BorderSizePixel = 0
        photoBackground.Image = ""
        photoBackground.ImageTransparency = 0.0
        photoBackground.ScaleType = Enum.ScaleType.Crop
        photoBackground.Active = false
        photoBackground.Selectable = false
        photoBackground.Visible = false
        photoBackground.ZIndex = 12
        photoBackground.Parent = button
        local photoBackgroundCorner = Instance.new("UICorner")
        photoBackgroundCorner.CornerRadius = UDim.new(0, 18)
        photoBackgroundCorner.Parent = photoBackground

        local photoShade = Instance.new("Frame")
        photoShade.Name = "MobileButtonPhotoShade"
        photoShade.Position = UDim2.fromScale(0, 0)
        photoShade.Size = UDim2.fromScale(1, 1)
        photoShade.BackgroundColor3 = Color3.fromRGB(0, 0, 0)
        photoShade.BackgroundTransparency = 0.90
        photoShade.BorderSizePixel = 0
        photoShade.Active = false
        photoShade.Selectable = false
        photoShade.Visible = false
        photoShade.ZIndex = 12
        photoShade.Parent = button
        local photoShadeCorner = Instance.new("UICorner")
        photoShadeCorner.CornerRadius = UDim.new(0, 18)
        photoShadeCorner.Parent = photoShade

        S.mobileButtonBackgroundImages = S.mobileButtonBackgroundImages or {}
        table.insert(S.mobileButtonBackgroundImages, {image = photoBackground, shade = photoShade})

        -- Soft neon bloom under a crisp border; the palette is updated by style() on theme changes.
        local glowStroke = Instance.new("UIStroke")
        glowStroke.Name = "MobileNeonBloom"
        glowStroke.Color = S.activeThemePalette and S.activeThemePalette.accent or ACTIVE_STROKE
        glowStroke.Transparency = 0.83
        glowStroke.Thickness = 3
        glowStroke.Parent = button

        local stroke = Instance.new("UIStroke")
        stroke.Name = "Border"
        stroke.Color = STROKE
        stroke.Transparency = 0.28
        stroke.Thickness = 1.1
        stroke.Parent = button
        local gradient = Instance.new("UIGradient")
        gradient.Name = "SelectedGradient"
        gradient.Rotation = 90
        gradient.Color = ColorSequence.new({
            -- Orange at the top, deep orange transition, black at the bottom.
            ColorSequenceKeypoint.new(0.00, Color3.fromRGB(164, 164, 164)),
            ColorSequenceKeypoint.new(0.32, Color3.fromRGB(138, 138, 138)),
            ColorSequenceKeypoint.new(0.66, Color3.fromRGB(49, 49, 49)),
            ColorSequenceKeypoint.new(1.00, Color3.fromRGB(5, 5, 5)),
        })
        gradient.Parent = button

        -- Glass highlight band: subtle white reflection on the top third of the button.
        -- It is fully non-interactive and sits below the button's text/touch surface.
        local glassHighlight = Instance.new("Frame")
        glassHighlight.Name = "MobileGlassHighlight"
        glassHighlight.Position = UDim2.fromOffset(3, 2)
        glassHighlight.Size = UDim2.new(1, -6, 0, 22)
        glassHighlight.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
        glassHighlight.BackgroundTransparency = 0.88
        glassHighlight.BorderSizePixel = 0
        glassHighlight.Active = false
        glassHighlight.Selectable = false
        glassHighlight.ZIndex = 12
        glassHighlight.Parent = button
        Instance.new("UICorner", glassHighlight).CornerRadius = UDim.new(0, 15)
        local glassHighlightGradient = Instance.new("UIGradient")
        glassHighlightGradient.Name = "MobileGlassHighlightGradient"
        glassHighlightGradient.Rotation = 90
        glassHighlightGradient.Color = ColorSequence.new({
            ColorSequenceKeypoint.new(0, Color3.fromRGB(255, 255, 255)),
            ColorSequenceKeypoint.new(1, Color3.fromRGB(228, 228, 240)),
        })
        glassHighlightGradient.Transparency = NumberSequence.new({
            NumberSequenceKeypoint.new(0, 0.40),
            NumberSequenceKeypoint.new(0.55, 0.72),
            NumberSequenceKeypoint.new(1, 1),
        })
        glassHighlightGradient.Parent = glassHighlight

        -- One narrow diagonal sheen travels across each button. This uses a single tween
        -- per button (no RenderStepped loop), and a short stagger keeps the panel calmer.
        local glossSweep = Instance.new("Frame")
        glossSweep.Name = "MobileGlossSweep"
        glossSweep.AnchorPoint = Vector2.new(0.5, 0.5)
        glossSweep.Position = UDim2.new(-0.24, 0, 0.5, 0)
        glossSweep.Size = UDim2.new(0.27, 0, 1.45, 0)
        glossSweep.Rotation = 17
        glossSweep.BackgroundColor3 = Color3.fromRGB(255, 255, 255)
        glossSweep.BackgroundTransparency = 0.60
        glossSweep.BorderSizePixel = 0
        glossSweep.Active = false
        glossSweep.Selectable = false
        glossSweep.ZIndex = 12
        glossSweep.Parent = button
        local glossSweepGradient = Instance.new("UIGradient")
        glossSweepGradient.Name = "MobileGlossSweepGradient"
        glossSweepGradient.Rotation = 0
        glossSweepGradient.Transparency = NumberSequence.new({
            NumberSequenceKeypoint.new(0, 1),
            NumberSequenceKeypoint.new(0.48, 0.24),
            NumberSequenceKeypoint.new(1, 1),
        })
        glossSweepGradient.Parent = glossSweep
        local glossSweepTween = TS_G:Create(
            glossSweep,
            TweenInfo.new(3.2, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut, -1, true, (buttonIndex % 5) * 0.22),
            {Position = UDim2.new(1.22, 0, 0.5, 0)}
        )
        glossSweepTween:Play()

        local hit = Instance.new("TextButton")
        hit.Name = "TextAndTouch"
        hit.Size = UDim2.fromScale(1, 1)
        hit.BackgroundTransparency = 1
        hit.BorderSizePixel = 0
        hit.AutoButtonColor = false
        hit.Text = p[2]
        hit.TextColor3 = TEXT_LIGHT
        hit.TextStrokeColor3 = Color3.fromRGB(0, 0, 0)
        hit.TextStrokeTransparency = 0.18
        hit.TextSize = 11
        hit.Font = Enum.Font.GothamBlack
        hit.TextWrapped = true
        hit.TextXAlignment = Enum.TextXAlignment.Center
        hit.TextYAlignment = Enum.TextYAlignment.Center
        hit.ZIndex = 13
        hit.Parent = button
        local buttonScale = Instance.new("UIScale")
        buttonScale.Name = "PressAnimationScale"
        buttonScale.Scale = 1
        buttonScale.Parent = button
        local activeScaleTween
        local pressTween = TweenInfo.new(0.07, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)
        local bounceTween = TweenInfo.new(0.22, Enum.EasingStyle.Back, Enum.EasingDirection.Out)
        hit.InputBegan:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                if activeScaleTween then activeScaleTween:Cancel() end
                activeScaleTween = TS_G:Create(buttonScale, pressTween, {Scale = 0.88})
                activeScaleTween:Play()
            end
        end)
        hit.InputEnded:Connect(function(input)
            if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
                if activeScaleTween then activeScaleTween:Cancel() end
                activeScaleTween = TS_G:Create(buttonScale, bounceTween, {Scale = 1.08})
                activeScaleTween:Play()
                task.delay(0.18, function()
                    if buttonScale.Parent then
                        activeScaleTween = TS_G:Create(buttonScale, pressTween, {Scale = 1})
                        activeScaleTween:Play()
                    end
                end)
            end
        end)
        local mobileSizeScale = Instance.new("UIScale")
        mobileSizeScale.Name = "MobileSizeScale"
        mobileSizeScale.Scale = 1
        mobileSizeScale.Parent = button

        local i = {
            id=p[1], button=button, hit=hit, stroke=stroke, glowStroke=glowStroke,
            gradient=gradient, glassHighlight=glassHighlight, glossSweep=glossSweep,
            buttonScale=mobileSizeScale, userMoved=false,
            baseButtonWidth=60, baseButtonHeight=60,
            defaultPositionX=p[3], defaultPositionY=p[4],
            _dragging=false, _dragMoved=false,
        }
        byId[p[1]], infos[#infos+1] = i, i
        style(i, false)
    end
    local dragHandle = Instance.new("Frame")
    dragHandle.Name = "FloatingPanelDragHandle"
    dragHandle.Size = UDim2.fromOffset(136, 50)
    dragHandle.BackgroundTransparency = 1
    dragHandle.Active = true
    dragHandle.ZIndex = 1
    dragHandle.Parent = container
    makeDraggable(dragHandle, true, container)

    -- Every mobile button is independently draggable when Lock UI is OFF.
    -- This replaces the old behavior where only InstaReset and TP BAT had
    -- individual drag handlers. The button action remains intact: movement is
    -- treated as a drag and therefore does not fire the action underneath.
    -- Mobile-button drag is deliberately independent from the panel drag.
    -- Lock UI is the single gate: OFF means every button may be moved.
    local function bindMobileButtonDrag(info)
        if not info or not info.button or not info.hit then return end

        local target = info.button
        local hit = info.hit
        hit.Active = true
        hit.Selectable = false
        target.Active = true

        local dragging = false
        local dragStart = nil
        local startPosition = nil
        local moved = false

        local function isPointerInput(input)
            return input.UserInputType == Enum.UserInputType.Touch
                or input.UserInputType == Enum.UserInputType.MouseButton1
        end

        local function beginDrag(input)
            -- Lock UI OFF is the only condition required to move the button.
            if S.lockUIEnabled == true then return end
            if not isPointerInput(input) then return end

            dragging = true
            moved = false
            dragStart = input.Position
            startPosition = target.Position
            info._dragging = true
            info._dragMoved = false
        end

        local function moveDrag(input)
            if not dragging then return end
            if S.lockUIEnabled == true then
                dragging = false
                moved = false
                info._dragging = false
                info._dragMoved = false
                S._floatingPanelDragging = false
                return
            end
            if not dragStart or not startPosition then return end

            local t = input.UserInputType
            if t ~= Enum.UserInputType.Touch and t ~= Enum.UserInputType.MouseMovement then return end

            local delta = input.Position - dragStart
            if delta.Magnitude >= 2 then
                moved = true
                info._dragMoved = true
                info.userMoved = true
                S._floatingPanelDragging = true
                target.Position = UDim2.new(
                    startPosition.X.Scale, startPosition.X.Offset + delta.X,
                    startPosition.Y.Scale, startPosition.Y.Offset + delta.Y
                )
            end
        end

        local function finishDrag()
            if not dragging then return end

            local didMove = moved
            dragging = false
            moved = false
            info._dragging = false

            if didMove then
                -- All currently displayed mobile buttons belong to this same
                -- panel, so persist their positions in one consistent table.
                S.mobileButtonPositions[info.id] = {
                    XS = target.Position.X.Scale,
                    X = target.Position.X.Offset,
                    YS = target.Position.Y.Scale,
                    Y = target.Position.Y.Offset,
                }
                captureLiveMobileButtonPositions()
                saveConfig()

                -- Prevent the release from being interpreted as a click.
                info._dragMoved = true
                task.delay(0.20, function()
                    if info and info.button and info.button.Parent then
                        info._dragMoved = false
                        S._floatingPanelDragging = false
                    end
                end)
            else
                info._dragMoved = false
                S._floatingPanelDragging = false
            end
        end

        hit.InputBegan:Connect(beginDrag)

        -- Touch movement is reported through InputChanged. Mouse movement uses
        -- the same path, so both PC and phone use identical drag behavior.
        UIS.InputChanged:Connect(function(input)
            if dragging then moveDrag(input) end
        end)

        -- input.Changed is the most reliable release signal for a touch.
        hit.InputBegan:Connect(function(input)
            if not isPointerInput(input) then return end
            input.Changed:Connect(function()
                if input.UserInputState == Enum.UserInputState.End then
                    finishDrag()
                end
            end)
        end)

        UIS.InputEnded:Connect(function(input)
            if isPointerInput(input) then finishDrag() end
        end)
    end

    for _, info in ipairs(infos) do
        bindMobileButtonDrag(info)
    end

    -- Restore the floating panel itself first, then restore each button's
    -- position relative to that panel. Both levels are persisted by Save Config.
    if S._savedFloatingPanelPos then
        local pos = S._savedFloatingPanelPos
        container.Position = UDim2.new(
            tonumber(pos.XS) or 1, tonumber(pos.X) or -58,
            tonumber(pos.YS) or 0, tonumber(pos.Y) or 95
        )
    end

    -- Restore positions from Vision.json, migrating old default-grid offsets.
    for _, info in ipairs(infos) do
        local saved = S.mobileButtonPositions and S.mobileButtonPositions[info.id]
        if type(saved) == "table" then
            local xScale = tonumber(saved.XS) or 0
            local xOffset = tonumber(saved.X) or 0
            local yScale = tonumber(saved.YS) or 0
            local yOffset = tonumber(saved.Y) or 0
            local oldDefault = legacyDefaultPositions[info.id]
            local isOffsetPosition = math.abs(xScale) < 0.0001 and math.abs(yScale) < 0.0001
            local matchesOldDefault = oldDefault and isOffsetPosition
                and math.abs(xOffset - oldDefault[1]) < 1
                and math.abs(yOffset - oldDefault[2]) < 1
            local matchesNewDefault = isOffsetPosition
                and math.abs(xOffset - (info.defaultPositionX or 0)) < 1
                and math.abs(yOffset - (info.defaultPositionY or 0)) < 1

            if matchesOldDefault then
                -- Old default layout position: move to the matching new grid cell.
                info.button.Position = UDim2.fromOffset(info.defaultPositionX or 0, info.defaultPositionY or 0)
                info.userMoved = false
            else
                info.button.Position = UDim2.new(xScale, xOffset, yScale, yOffset)
                info.userMoved = not matchesNewDefault
            end
        end
    end

    -- Snapshot once after the UI is built so the in-memory state is canonical.
    S._floatingButtonInfos = infos
    captureLiveMobileButtonPositions()
    S._floatingFreeButtonLayer = container
    S._floatingUpdateLayout = function() end
    local function get(id) return byId[id] end
    local function connect(id, fn)
        get(id).hit.Activated:Connect(function()
            if not S._floatingPanelDragging then fn() end
        end)
    end
    connect("Drop", function() flash(get("Drop"), 0.5); task.spawn(runDropBrainrot) end)
    connect("InstaReset", function() flash(get("InstaReset"), 0.5); if _G.InstaReset and _G.InstaReset.Trigger then _G.InstaReset.Trigger() end end)
    connect("BatUp", function()
        local on = not S.tpBatEnabled
        setTpBat(on); style(get("BatUp"), on); saveConfig()
    end)
    connect("TPDown", function() flash(get("TPDown"), 0.45); runTPFloor() end)
    connect("AutoBat", function()
        local on = not S.batAimbotEnabled
        if on then
            if S.antiBatAimbotEnabled then
                stopAntiBatBypass()
                if S.antiBatAimbotSetVisual then pcall(S.antiBatAimbotSetVisual, false) end
            end
            if S.autoLeftEnabled then S.autoLeftEnabled=false; stopAutoLeft() end
            if S.autoRightEnabled then S.autoRightEnabled=false; stopAutoRight() end
        end
        setBatAimbot(on); style(get("AutoBat"), on); updateFloatingButtons()
    end)
    connect("AntiBatAimbot", function()
        local on = not S.antiBatAimbotEnabled
        if on then
            -- Prevent movement logic from fighting the Anti Bat logic.
            if S.batAimbotEnabled then setBatAimbot(false) end
            if S.autoLeftEnabled then S.autoLeftEnabled=false; stopAutoLeft() end
            if S.autoRightEnabled then S.autoRightEnabled=false; stopAutoRight() end
            local ok, result = pcall(startAntiBatBypass)
            on = ok and result ~= false and S.antiBatAimbotEnabled == true
            if not on then
                pcall(stopAntiBatBypass)
            end
        else
            pcall(stopAntiBatBypass)
        end
        style(get("AntiBatAimbot"), on)
        if S.antiBatAimbotSetVisual then pcall(S.antiBatAimbotSetVisual, on) end
        updateFloatingButtons()
        saveConfig()
    end)
    connect("AutoLeft", function()
        local on = not S.autoLeftEnabled
        if on then
            if S.autoRightEnabled then S.autoRightEnabled=false; stopAutoRight() end
            if S.batAimbotEnabled then setBatAimbot(false) end
            S.autoLeftEnabled=true; startAutoLeft()
        else S.autoLeftEnabled=false; stopAutoLeft() end
        if S.autoLeftSetVisual then S.autoLeftSetVisual(on) end
        S.restartMovement(); updateFloatingButtons(); saveConfig()
    end)
    connect("AutoRight", function()
        local on = not S.autoRightEnabled
        if on then
            if S.autoLeftEnabled then S.autoLeftEnabled=false; stopAutoLeft() end
            if S.batAimbotEnabled then setBatAimbot(false) end
            S.autoRightEnabled=true; startAutoRight()
        else S.autoRightEnabled=false; stopAutoRight() end
        if S.autoRightSetVisual then S.autoRightSetVisual(on) end
        S.restartMovement(); updateFloatingButtons(); saveConfig()
    end)
    local function normalSpeed()
        S.setNormalSpeedMode(); S.restartMovement(); updateFloatingButtons()
        style(get("CarrySpd"), false); style(get("LaggerCarry"), false); style(get("LaggerNormal"), false); saveConfig()
    end
    connect("CarrySpd", function()
        if S.speedMode and S.laggerMode == 0 then
            normalSpeed()
        else
            S.setCarrySpeedMode()
            S.restartMovement()
            updateFloatingButtons()
            style(get("LaggerNormal"), false)
            style(get("LaggerCarry"), false)
            saveConfig()
        end
    end)
    local function lagger(mode)
        if S.laggerMode == mode and not S.speedMode then normalSpeed(); return end
        S.speedMode=false; S.laggerMode=mode; S.refreshSpeedModeLabel(); S.applySpeedVelocityNow(); S.restartMovement(); updateFloatingButtons()
        style(get("LaggerCarry"), mode == 2); style(get("LaggerNormal"), mode == 1); saveConfig()
    end
    connect("LaggerCarry", function() lagger(2) end)
    connect("LaggerNormal", function() lagger(1) end)

    S.tpBatSetVisual = function(active) style(get("BatUp"), active) end
    S.antiBatAimbotSetVisual = function(active) style(get("AntiBatAimbot"), active) end
    S.dropBrainrotSetVisual = function(active) style(get("Drop"), active) end
    S.dropBrainrotFloatVisual = S.dropBrainrotSetVisual
    S._btnAAL, S._bsAAL, S._l1AAL, S._l2AAL = get("AutoLeft").button, nil, nil, nil
    S._btnAAR, S._bsAAR, S._l1AAR, S._l2AAR = get("AutoRight").button, nil, nil, nil
    S._btnBAT, S._bsBAT, S._l1BAT, S._l2BAT = get("AutoBat").button, nil, nil, nil
    S._setPButtonActive = function(button, _, _, _, active)
        for _, i in pairs(byId) do if i.button == button then style(i, active); return end end
    end
    S._floatingButtons = {
        lagger=get("LaggerNormal").button, l2Lagger={Text=""}, carry=get("CarrySpd").button,
        autoLeft=get("AutoLeft").button, autoRight=get("AutoRight").button, bat=get("AutoBat").button,
        antiBat=get("AntiBatAimbot").button,
    }
    style(get("BatUp"), S.tpBatEnabled)
    style(get("AutoBat"), S.batAimbotEnabled)
    style(get("AntiBatAimbot"), S.antiBatAimbotEnabled)
    style(get("AutoLeft"), S.autoLeftEnabled)
    style(get("AutoRight"), S.autoRightEnabled)
    style(get("CarrySpd"), S.speedMode and S.laggerMode == 0)
    style(get("LaggerNormal"), S.laggerMode == 1 and not S.speedMode)
    style(get("LaggerCarry"), S.laggerMode == 2 and not S.speedMode)
    pcall(S.setMobileButtonScale, S.mobileButtonScale or 1.0)
    pcall(setStealPhotoImage, S.stealPhotoAssetId)
    if type(S._xypherApplyThemeToOverlays) == "function" and S.activeThemePalette then
        pcall(S._xypherApplyThemeToOverlays, S.activeThemePalette)
    end
end

-- ── Load config then build UI ─────────────────────────────────────────────
pcall(function()
    local ok, data = pcall(function()
        if isfile and readfile and isfile(CONFIG_FILE) then return readfile(CONFIG_FILE) end
    end)
    if ok and data then
        local cfgOk, cfg = pcall(function() return HS:JSONDecode(data) end)
        if cfgOk and type(cfg)=="table" then
            if type(cfg.starbornFontEnabled) == "boolean" then
                S._restoreStarbornFont = cfg.starbornFontEnabled
            end
            if type(cfg.normalSpeed)=="number" then S.NS=cfg.normalSpeed end
            if type(cfg.backgroundAssetId)=="string" then
                for _, optionId in ipairs(BACKGROUND_OPTIONS) do
                    if cfg.backgroundAssetId == optionId then
                        S.backgroundAssetId = optionId
                        break
                    end
                end
            end
            if type(cfg.openBackgroundOptions) == "boolean" then
                S.openBackgroundOptions = cfg.openBackgroundOptions
            end
            local savedButtonPhoto = cfg.mobileButtonBackgroundAssetId or cfg.stealPhotoAssetId
            if type(savedButtonPhoto) == "string" then
                for _, optionId in ipairs(STEAL_PHOTO_OPTIONS) do
                    if savedButtonPhoto == optionId then
                        S.stealPhotoAssetId = optionId
                        break
                    end
                end
            end
            if type(cfg.carrySpeed)=="number" then S.CS=cfg.carrySpeed end
            if type(cfg.laggerSpeed)=="number" then S.LS=cfg.laggerSpeed end
            if type(cfg.laggerCarrySpeed)=="number" then S.LCS=cfg.laggerCarrySpeed end
            if type(cfg.grabRadius)=="number" then S.Steal.StealRadius=cfg.grabRadius end
            if cfg.stealDuration ~= nil then
                S.Steal.StealDuration = sanitizeStealDuration(cfg.stealDuration, S.Steal.StealDuration)
            end
            if type(cfg.mobileButtonPositions)=="table" then S.mobileButtonPositions=cfg.mobileButtonPositions end
            if type(cfg.mobileButtonScale)=="number" then S.mobileButtonScale = math.clamp(cfg.mobileButtonScale, 0.50, 2.00) end
            if type(cfg.uiThemeName) == "string" and (cfg.uiThemeName == "Dark Purple" or cfg.uiThemeName == "Black & White" or cfg.uiThemeName == "Blue & White" or cfg.uiThemeName == "Pink & Purple" or cfg.uiThemeName == "Emerald Neon" or cfg.uiThemeName == "Crimson Neon" or cfg.uiThemeName == "Amber Neon") then
                S.uiThemeName = cfg.uiThemeName
            end
            if type(cfg.crosshairEnabled) == "boolean" then S.crosshairEnabled = cfg.crosshairEnabled end
            if type(cfg.crosshairShapeIndex) == "number" then S.crosshairShapeIndex = math.clamp(math.floor(cfg.crosshairShapeIndex), 1, 5) end
            if type(cfg.crosshairColorIndex) == "number" then S.crosshairColorIndex = math.clamp(math.floor(cfg.crosshairColorIndex), 1, 6) end
            if type(cfg.crosshairSize) == "number" then S.crosshairSize = math.clamp(math.floor(cfg.crosshairSize + 0.5), 4, 24) end
            if type(cfg.crosshairGap) == "number" then S.crosshairGap = math.clamp(math.floor(cfg.crosshairGap + 0.5), 0, 20) end
            if type(cfg.crosshairThickness) == "number" then S.crosshairThickness = math.clamp(math.floor(cfg.crosshairThickness + 0.5), 1, 6) end
            if type(cfg.crosshairTransparency) == "number" then S.crosshairTransparency = math.clamp(math.floor(cfg.crosshairTransparency + 0.5), 0, 90) end
            if type(cfg.crosshairDotEnabled) == "boolean" then S.crosshairDotEnabled = cfg.crosshairDotEnabled end
            if type(cfg.crosshairOutlineEnabled) == "boolean" then S.crosshairOutlineEnabled = cfg.crosshairOutlineEnabled end
            if type(cfg.stealHudScale)=="number" then
                S.stealHudScale = math.clamp(cfg.stealHudScale, 0.50, 2.00)
            else
                S.stealHudScale = 0.55
            end
            if type(cfg.floatingFreeButtonPositions)=="table" then S.floatingFreeButtonPositions=cfg.floatingFreeButtonPositions end
            if type(cfg.lockMobileButtons)=="boolean" then S.lockMobileButtons=cfg.lockMobileButtons end
            local function rl(e,s) if type(s)=="table" then if s.kb then e.kb=Enum.KeyCode[s.kb] end; if s.gp then e.gp=Enum.KeyCode[s.gp] end end end
            -- Solo restaurar keybinds de configs ya migradas; las antiguas usaban teclas previas.
            if cfg.keybindVersion == 1 then
                rl(S.KB.DropBrainrot, cfg.dropBrainrotKey); rl(S.KB.AutoLeft, cfg.autoLeftKey)
                rl(S.KB.AutoRight, cfg.autoRightKey); rl(S.KB.AutoBat, cfg.autoBatKey)
                rl(S.KB.TpBat, cfg.tpBatKey); rl(S.KB.TPFlor, cfg.tpFloorKey); rl(S.KB.GuiHide, cfg.guiHideKey)
                rl(S.KB.SpeedToggle, cfg.speedToggleKey); rl(S.KB.LaggerToggle, cfg.laggerToggleKey)
                rl(S.KB.InstaReset, cfg.instaResetKey)
            end
            if cfg.carryMode==true then S.speedMode=true; S.setCarrySpeedMode() end
            if cfg.laggerMode == 1 then
                S.setLaggerNormalMode()
            elseif cfg.laggerMode == 2 then
                S.setLaggerCarryMode()
            end
            if cfg.antiRagdoll==true then S.antiRagdollEnabled=true; startAntiRagdoll() end
            -- Read both canonical and legacy names so existing configs are preserved.
            S.ragdollStealEnabled = (cfg.ragdollSteal == true) or (cfg.ragdollStealEnabled == true)
            S.shinyGraphicsEnabled = (cfg.shinyGraphics == true) or (cfg.shinyGraphicsEnabled == true)
            S.tpDownHeightTrigger = 20
            if type(cfg.tpDownHeightTrigger) == "number" then S.tpDownHeightTrigger = math.clamp(cfg.tpDownHeightTrigger, 1, 500) end
            -- Migrar el antiguo estado Infinite Jump a la única opción Hold Jump.
            if cfg.holdJumpEnabled==true or cfg["infiniteJump"]==true then S.holdJumpEnabled=true; startHoldJump() end
            if cfg.medusaCounter==true then
                S.medusaCounterEnabled=true
                if LP.Character then setupMedusaCounter(LP.Character) end
            end
            if cfg.batCounter==true then
                S.batCounterEnabled=true
                startBatCounter()
            end
            if cfg.batCounterV2==true then
                S.batCounterV2Enabled=true
                startBatCounterV2()
            end
            if cfg.autoStealEnabled==true then S.stealActive=true; startAutoSteal() end
            if cfg.batAimbot==true then S.batAimbotEnabled=true; startBatAimbot() end
            if cfg.antiBatAimbot==true then
                pcall(startAntiBatBypass)
                S.antiBatAimbotEnabled = true
            end
            if cfg.tpBatMode == TP_BAT_MODE_ORBIT or cfg.tpBatMode == "V3" then
                S.tpBatMode = TP_BAT_MODE_ORBIT
            elseif cfg.tpBatMode == TP_BAT_MODE_ZERO or cfg.tpBatMode == "V2 TP Bat Zero" then
                S.tpBatMode = TP_BAT_MODE_ZERO
            elseif cfg.tpBatMode == TP_BAT_MODE_VISION or cfg.tpBatMode == "V1 TP Bat Vision" then
                S.tpBatMode = TP_BAT_MODE_VISION
            else
                S.tpBatMode = TP_BAT_MODE_VISION
            end
            if S.tpBatModeSelectorLabel then S.tpBatModeSelectorLabel.Text = S.tpBatMode end
            if cfg.tpBat == true then setTpBat(true) end
            if type(cfg.batSkin) == "string" then S.setBatSkin(cfg.batSkin, false) end
            if type(cfg.displaySkin) == "string" and ({Off=true,PURPLE=true,BLUE=true,RED=true,BLACK=true,GREEN=true,WHITE=true})[cfg.displaySkin] then S.displaySkin=cfg.displaySkin end
            S.customSkinEnabled = cfg.customSkin == true and S.displaySkin ~= "Off"
            if S.customSkinEnabled and S.applyDisplaySkin then task.defer(function() pcall(S.applyDisplaySkin) end) end
            if cfg.espEnabled==true then
                S.espEnabled=true
                toggleESP(true)
                task.spawn(function()
                    task.wait(1)
                    if S.setESPVisual then S.setESPVisual(true) end
                end)
            end
            if type(cfg.stealHudPos)=="table" then
                S._savedStealHudPos = cfg.stealHudPos
                task.defer(function()
                    if S.stealHudCard and S._savedStealHudPos then
                        local pos = S._savedStealHudPos
                        local oldDefault = math.abs((tonumber(pos.X) or 0) + 150) < 2
                            and math.abs((tonumber(pos.Y) or 0) + 75) < 2
                            and math.abs((tonumber(pos.XS) or 0.5) - 0.5) < 0.001
                            and math.abs((tonumber(pos.YS) or 1) - 1) < 0.001
                        if oldDefault then
                            S.stealHudCard.Position = UDim2.new(0.5, 0, 0.5, 0)
                        else
                            S.stealHudCard.Position = UDim2.new(
                                pos.XS or 0.5, pos.X or 0,
                                pos.YS or 0.5, pos.Y or 0
                            )
                        end
                    end
                end)
            end
            if cfg.unwalkEnabled==true then S.unwalkEnabled=true; startUnwalk() end
            -- Keep the Lock UI state and its visible toggle synchronized.
            -- Older versions restored the internal flag directly, which could leave
            -- the toggle visually OFF while the mobile buttons were actually locked.
            local restoredLockUI = (cfg.lockUI == true)
            S.lockUIEnabled = restoredLockUI
            if S.setLockUI_Visual2 then
                pcall(S.setLockUI_Visual2, restoredLockUI)
            end
            pcall(setUILock, restoredLockUI)
            if cfg.fpsBoost==true then S.fpsBoostEnabled=true; applyFPSBoost() end
            S.nukeOptimizerEnabled = cfg.nukeOptimizer == true
            if S.nukeOptimizerEnabled and type(S.startNukeOptimizer) == "function" then
                local nukeRestoreOk = pcall(S.startNukeOptimizer)
                if not nukeRestoreOk then
                    if type(S.stopNukeOptimizer) == "function" then pcall(S.stopNukeOptimizer) end
                    S.nukeOptimizerEnabled = false
                end
            end
            if S.setNukeOptimizerVisual then
                pcall(S.setNukeOptimizerVisual, S.nukeOptimizerEnabled)
            end
            S.vividGraphicsEnabled = cfg.vividGraphics == true
            if S.vividGraphicsEnabled then pcall(enableVividGraphics) end
            if type(cfg.stretchFOV) == "number" then S.stretchFOV = math.clamp(cfg.stretchFOV, 70, 150) end
            S.stretchEnabled = cfg.stretchEnabled == true
            if S.stretchEnabled then pcall(enableStretch) end
            if type(cfg.skyTheme) == "string" and SKY_PRESETS[cfg.skyTheme] then
                S.skyTheme = cfg.skyTheme
                if S.skyTheme ~= "Off" then pcall(applyCustomSky, S.skyTheme) end
            else
                S.skyTheme = "Off"
            end
            if type(cfg.krobloxMode) == "string" and ({Off=true, Left=true, Right=true, Both=true})[cfg.krobloxMode] then
                S.krobloxMode = cfg.krobloxMode
                if S.krobloxMode ~= "Off" then pcall(_G._VisionApplyKroblox, S.krobloxMode) end
            else
                S.krobloxMode = "Off"
            end
            S.antiFlingEnabled = cfg.antiFling == true
            if S.antiFlingEnabled then pcall(YF.startAntiFling) end
            if type(cfg.lockEnemyRange) == "number" then S.bodyLockRange = math.clamp(math.floor(cfg.lockEnemyRange), 5, 200) end
            S.bodyLockEnabled = cfg.lockEnemy == true
            if S.bodyLockEnabled then pcall(YF.startBodyLock) end
            if type(cfg.animPack) == "string" and (cfg.animPack == "Off" or YF.ANIM_PACKS[cfg.animPack]) then
                S.currentAnimPack = cfg.animPack
            else
                S.currentAnimPack = "Off"
            end
            if S.currentAnimPack ~= "Off" then pcall(YF.startAnimPack, S.currentAnimPack) end
            S.antiLagEnabled = cfg.antiLag == true
            if S.antiLagEnabled then pcall(YF.enableAntiLag) end
            if cfg.hideOpiumButtons==true then S.hideOpiumButtonsEnabled=true end
            if type(cfg.floatingPanelPos)=="table" then
                -- El panel todavía no existe aquí; createFloatingButtonPanel lo aplica después.
                S._savedFloatingPanelPos = cfg.floatingPanelPos
            end
        end
    end
end)

-- Reconcile settings only after their UI objects and mobile-button image targets exist.
-- Previously the image pass ran before Vision.json was decoded, leaving the chosen image
-- stored in state but never applied to the floating buttons for that execution.
pcall(function()
    if type(S.setBackgroundOptionsVisible) == "function" then
        S.setBackgroundOptionsVisible(S.openBackgroundOptions ~= false)
    end
    if type(S.setOpenBackgroundVisual) == "function" then
        S.setOpenBackgroundVisual(S.openBackgroundOptions ~= false)
    end
    for optionId, setter in pairs(S.stealPhotoToggleSetters or {}) do
        if type(setter) == "function" then
            pcall(setter, optionId == S.stealPhotoAssetId)
        end
    end
    setStealPhotoImage(S.stealPhotoAssetId)
    -- The mobile-button panel is created just after the main GUI. On slower phones
    -- it may not exist yet, so wait briefly for its image targets instead of relying
    -- on a fixed delay that can race with UI construction.
    task.spawn(function()
        local deadline = os.clock() + 6
        while os.clock() < deadline do
            if S.floatingPanelGui and S.floatingPanelGui.Parent
                and #(S.mobileButtonBackgroundImages or {}) > 0 then
                pcall(setStealPhotoImage, S.stealPhotoAssetId)
                return
            end
            task.wait(0.2)
        end
        warn("[XYPHER] Mobile button background belum diterapkan: panel gambar tidak tersedia.")
    end)
end)

-- Restore the Starborn font only when the saved setting was explicitly enabled.
-- The setter performs validation and leaves the GUI usable if the font asset fails.
if S._restoreStarbornFont == true then
    task.defer(function()
        local setter = S._setStarbornFontEnabled
        local ok, result = false, false
        if type(setter) == "function" then ok, result = pcall(setter, true) end
        if ok and result == true then
            if type(S.setStarbornFontVisual) == "function" then pcall(S.setStarbornFontVisual, true) end
        else
            S.starbornFontEnabled = false
            if type(S.setStarbornFontVisual) == "function" then pcall(S.setStarbornFontVisual, false) end
            warn("[XYPHER] Starborn tidak dapat dipulihkan dari config; toggle dikembalikan ke OFF.")
        end
    end)
end

-- ── XYPHER MONOCHROME STEAL HUD ────────────────────────────────────────
-- Compact monochrome redesign: centered XYPHER title, white/gray progress rail,
-- circular emblem, right-side Ping/FPS cluster and 0% capsule.
-- Existing auto-steal logic still updates S.progressFill and S.progressPct.
local function buildStealHUD()
    if S._stealHudDragConn then
        pcall(function() S._stealHudDragConn:Disconnect() end)
        S._stealHudDragConn = nil
    end
    if S._stealHudViewportConn then
        pcall(function() S._stealHudViewportConn:Disconnect() end)
        S._stealHudViewportConn = nil
    end

    local sg = Instance.new("ScreenGui")
    sg.Name = "StealBarMovableSmall"
    sg.ResetOnSpawn = false
    sg.IgnoreGuiInset = true
    sg.DisplayOrder = 999999
    sg.ZIndexBehavior = Enum.ZIndexBehavior.Global
    sg.Enabled = XYPHER_STARTUP_INTRO_COMPLETE

    local parent
    pcall(function()
        if type(gethui) == "function" then parent = gethui() end
    end)
    if not parent then
        pcall(function() parent = game:GetService("CoreGui") end)
    end
    if not parent then parent = LP:WaitForChild("PlayerGui") end
    local parented = pcall(function() sg.Parent = parent end)
    if not parented or not sg.Parent then
        sg.Parent = LP:WaitForChild("PlayerGui")
    end

    -- Remove a previous copy if the executor re-runs this script.
    pcall(function()
        for _, child in ipairs(sg.Parent:GetChildren()) do
            if child ~= sg and child:IsA("ScreenGui") and child.Name == "StealBarMovableSmall" then
                child:Destroy()
            end
        end
    end)

    local ACCENT_GRAY = Color3.fromRGB(170, 170, 170)
    local WHITE_ACCENT = Color3.fromRGB(255, 255, 255)
    local DARK_GRAY = Color3.fromRGB(72, 72, 72)
    local LIGHT_GRAY = Color3.fromRGB(218, 218, 218)
    local WHITE = Color3.fromRGB(250, 250, 250)
    local DARK = Color3.fromRGB(5, 5, 5)
    local DARK_INNER = Color3.fromRGB(12, 12, 12)
    local MUTED = Color3.fromRGB(160, 160, 160)

    local function make(className, name, parentObject, properties)
        local object = Instance.new(className)
        object.Name = name
        for property, value in pairs(properties or {}) do
            object[property] = value
        end
        object.Parent = parentObject
        return object
    end

    local function corner(object, radius)
        return make("UICorner", object.Name .. "Corner", object, {
            CornerRadius = UDim.new(0, radius),
        })
    end

    local function stroke(object, color, thickness, transparency)
        return make("UIStroke", object.Name .. "Stroke", object, {
            Color = color,
            Thickness = thickness,
            Transparency = transparency,
            ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
        })
    end

    local function line(name, parentObject, position, size, color, transparency, rotation, zIndex)
        local item = make("Frame", name, parentObject, {
            Position = position,
            Size = size,
            Rotation = rotation or 0,
            BackgroundColor3 = color,
            BackgroundTransparency = transparency or 0,
            BorderSizePixel = 0,
            ZIndex = zIndex or 110,
            Active = false,
            Selectable = false,
        })
        corner(item, math.max(1, math.floor(math.min(size.X.Offset, size.Y.Offset) / 2)))
        return item
    end

    -- All layout values are authored on a 1050x244 canvas, then uniformly
    -- scaled to fit smaller viewports without stretching the bar itself.
    local stage = make("Frame", "XypherStealHUDRoot", sg, {
        AnchorPoint = Vector2.new(0.5, 0.5),
        Position = UDim2.new(0.5, 0, 0.5, 0),
        Size = UDim2.fromOffset(1050, 244),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        ZIndex = 100,
        Active = false,
        Selectable = false,
    })
    local uiScale = make("UIScale", "ResponsiveScale", stage, {Scale = 1})

    local function fitHud()
        local camera = Workspace.CurrentCamera
        local viewport = camera and camera.ViewportSize or Vector2.new(1280, 720)
        local fitX = math.max(0.1, (viewport.X - 16) / 1050)
        local fitY = math.max(0.1, (viewport.Y - 24) / 244)
        local responsiveScale = math.clamp(math.min(fitX, fitY), 0.32, 1)
        local requestedScale = math.clamp(tonumber(S.stealHudScale) or 0.55, 0.50, 2.00)
        local compactBase = 0.62
        uiScale.Scale = responsiveScale * requestedScale * compactBase
    end
    S.applyStealHudScale = function(value, persist)
        if value ~= nil then
            S.stealHudScale = math.floor(math.clamp(tonumber(value) or 0.55, 0.50, 2.00) * 100 + 0.5) / 100
        end
        fitHud()
        if type(S.stealHudScaleSetVisual) == "function" then
            pcall(S.stealHudScaleSetVisual, S.stealHudScale)
        end
        if persist ~= false then saveConfig() end
    end
    fitHud()
    local camera = Workspace.CurrentCamera
    if camera then
        S._stealHudViewportConn = camera:GetPropertyChangedSignal("ViewportSize"):Connect(fitHud)
    end

    -- Header hairline and the sharp, bracket-like XYPHER title treatment.
    local headerLine = make("Frame", "HeaderHairline", stage, {
        Position = UDim2.fromOffset(113, 63),
        Size = UDim2.fromOffset(824, 1),
        BackgroundColor3 = ACCENT_GRAY,
        BackgroundTransparency = 0.48,
        BorderSizePixel = 0,
        ZIndex = 103,
    })
    make("UIGradient", "HeaderHairlineGradient", headerLine, {
        Rotation = 0,
        Color = ColorSequence.new({
            ColorSequenceKeypoint.new(0, Color3.fromRGB(58, 58, 58)),
            ColorSequenceKeypoint.new(0.5, LIGHT_GRAY),
            ColorSequenceKeypoint.new(1, Color3.fromRGB(58, 58, 58)),
        }),
        Transparency = NumberSequence.new({
            NumberSequenceKeypoint.new(0, 0.35),
            NumberSequenceKeypoint.new(0.5, 0.02),
            NumberSequenceKeypoint.new(1, 0.35),
        }),
    })

    line("TitleWingLeftLong", stage, UDim2.fromOffset(266, 27), UDim2.fromOffset(75, 3), ACCENT_GRAY, 0.02, 0, 108)
    line("TitleWingLeftTip", stage, UDim2.fromOffset(250, 22), UDim2.fromOffset(34, 3), WHITE_ACCENT, 0.05, 24, 108)
    line("TitleWingLeftInner", stage, UDim2.fromOffset(326, 32), UDim2.fromOffset(20, 3), DARK_GRAY, 0.08, 0, 108)
    line("TitleWingRightLong", stage, UDim2.fromOffset(709, 27), UDim2.fromOffset(75, 3), ACCENT_GRAY, 0.02, 0, 108)
    line("TitleWingRightTip", stage, UDim2.fromOffset(766, 22), UDim2.fromOffset(34, 3), WHITE_ACCENT, 0.05, -24, 108)
    line("TitleWingRightInner", stage, UDim2.fromOffset(704, 32), UDim2.fromOffset(20, 3), DARK_GRAY, 0.08, 0, 108)

    make("TextLabel", "XypherTitleGlow", stage, {
        Position = UDim2.fromOffset(370, -2),
        Size = UDim2.fromOffset(310, 52),
        BackgroundTransparency = 1,
        Text = "XYPHER",
        TextColor3 = WHITE_ACCENT,
        TextTransparency = 0.62,
        TextStrokeColor3 = ACCENT_GRAY,
        TextStrokeTransparency = 0.48,
        Font = Enum.Font.GothamBlack,
        TextSize = 36,
        TextScaled = false,
        TextXAlignment = Enum.TextXAlignment.Center,
        TextYAlignment = Enum.TextYAlignment.Center,
        ZIndex = 109,
    })
    make("TextLabel", "XypherTitle", stage, {
        Position = UDim2.fromOffset(370, -3),
        Size = UDim2.fromOffset(310, 52),
        BackgroundTransparency = 1,
        Text = "XYPHER",
        TextColor3 = WHITE,
        TextStrokeColor3 = DARK_GRAY,
        TextStrokeTransparency = 0.42,
        Font = Enum.Font.GothamBlack,
        TextSize = 32,
        TextScaled = false,
        TextXAlignment = Enum.TextXAlignment.Center,
        TextYAlignment = Enum.TextYAlignment.Center,
        ZIndex = 110,
    })

    -- Outer panel with subtle gray edging instead of the previous unrelated
    -- image/Halloween skin; the silhouette matches the supplied screenshot.
    local panelGlow = make("Frame", "MainPanelGlow", stage, {
        Position = UDim2.fromOffset(91, 80),
        Size = UDim2.fromOffset(934, 106),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        ZIndex = 101,
    })
    corner(panelGlow, 54)
    local panelGlowStroke = stroke(panelGlow, ACCENT_GRAY, 3, 0.70)

    local panel = make("Frame", "StealProgressBar", stage, {
        Position = UDim2.fromOffset(96, 84),
        Size = UDim2.fromOffset(926, 98),
        BackgroundColor3 = DARK,
        BackgroundTransparency = 0.04,
        BorderSizePixel = 0,
        ZIndex = 102,
        Active = false,
        Selectable = false,
    })
    corner(panel, 50)
    local panelStroke = stroke(panel, Color3.fromRGB(126, 126, 126), 1.7, 0.18)
    make("UIGradient", "MainPanelGradient", panel, {
        Rotation = 0,
        Color = ColorSequence.new({
            ColorSequenceKeypoint.new(0, Color3.fromRGB(7, 7, 7)),
            ColorSequenceKeypoint.new(0.48, Color3.fromRGB(12, 12, 12)),
            ColorSequenceKeypoint.new(1, Color3.fromRGB(5, 5, 5)),
        }),
    })

    line("PanelTopGlint", stage, UDim2.fromOffset(143, 87), UDim2.fromOffset(830, 1), LIGHT_GRAY, 0.76, 0, 105)
    line("PanelBottomGlint", stage, UDim2.fromOffset(151, 178), UDim2.fromOffset(811, 1), DARK_GRAY, 0.43, 0, 105)

    -- Progress track and fill.  Keep the fill object names and references used
    -- by the existing steal engine so progress remains fully functional.
    local track = make("Frame", "ProgressTrack", stage, {
        Position = UDim2.fromOffset(151, 110),
        Size = UDim2.fromOffset(651, 48),
        BackgroundColor3 = Color3.fromRGB(8, 8, 8),
        BackgroundTransparency = 0.04,
        BorderSizePixel = 0,
        ClipsDescendants = true,
        ZIndex = 110,
        Active = false,
        Selectable = false,
    })
    corner(track, 26)
    stroke(track, Color3.fromRGB(145, 145, 145), 2.2, 0.13)
    make("UIGradient", "TrackGradient", track, {
        Rotation = 90,
        Color = ColorSequence.new({
            ColorSequenceKeypoint.new(0, Color3.fromRGB(20, 20, 20)),
            ColorSequenceKeypoint.new(0.5, Color3.fromRGB(5, 5, 5)),
            ColorSequenceKeypoint.new(1, Color3.fromRGB(20, 20, 20)),
        }),
    })

    local fill = make("Frame", "ProgressFill", track, {
        Position = UDim2.fromOffset(0, 0),
        Size = UDim2.new(0, 0, 1, 0),
        BackgroundColor3 = ACCENT_GRAY,
        BorderSizePixel = 0,
        ZIndex = 111,
        Active = false,
        Selectable = false,
    })
    corner(fill, 26)
    local fillStroke = stroke(fill, WHITE_ACCENT, 1.5, 0.48)
    make("UIGradient", "ProgressFillGradient", fill, {
        Rotation = 0,
        Color = ColorSequence.new({
            ColorSequenceKeypoint.new(0, Color3.fromRGB(105, 105, 105)),
            ColorSequenceKeypoint.new(0.43, Color3.fromRGB(155, 155, 155)),
            ColorSequenceKeypoint.new(0.78, Color3.fromRGB(205, 205, 205)),
            ColorSequenceKeypoint.new(1, Color3.fromRGB(255, 255, 255)),
        }),
    })

    local fillShine = make("Frame", "ProgressShine", fill, {
        AnchorPoint = Vector2.new(0.5, 0),
        Position = UDim2.new(-0.30, 0, 0, -3),
        Size = UDim2.new(0.20, 0, 1, 6),
        Rotation = 10,
        BackgroundColor3 = WHITE,
        BackgroundTransparency = 0.76,
        BorderSizePixel = 0,
        ZIndex = 112,
        Active = false,
        Selectable = false,
    })
    make("UIGradient", "ProgressShineGradient", fillShine, {
        Transparency = NumberSequence.new({
            NumberSequenceKeypoint.new(0, 1),
            NumberSequenceKeypoint.new(0.5, 0.25),
            NumberSequenceKeypoint.new(1, 1),
        }),
    })

    -- The status sits above the track like the reference image.
    local statusText = make("TextLabel", "StealStatus", stage, {
        Position = UDim2.fromOffset(397, 72),
        Size = UDim2.fromOffset(256, 30),
        BackgroundTransparency = 1,
        Text = (S.Steal and S.Steal.AutoStealEnabled) and ((S.Steal.isStealing and "STEALING") or "DETECT") or "OFF",
        TextColor3 = (S.Steal and S.Steal.AutoStealEnabled) and ((S.Steal.isStealing and WHITE) or WHITE_ACCENT) or MUTED,
        TextStrokeColor3 = DARK_GRAY,
        TextStrokeTransparency = 0.78,
        Font = Enum.Font.GothamMedium,
        TextSize = 19,
        TextScaled = false,
        TextXAlignment = Enum.TextXAlignment.Center,
        TextYAlignment = Enum.TextYAlignment.Center,
        ZIndex = 118,
    })
    S.stealHudStatus = statusText

    -- Right-side target ring and real-time Ping/FPS figures.
    local targetOuter = make("Frame", "StatusTargetOuter", stage, {
        Position = UDim2.fromOffset(817, 108),
        Size = UDim2.fromOffset(46, 46),
        BackgroundColor3 = Color3.fromRGB(8, 8, 8),
        BorderSizePixel = 0,
        ZIndex = 114,
        Active = false,
        Selectable = false,
    })
    corner(targetOuter, 23)
    stroke(targetOuter, Color3.fromRGB(240, 240, 240), 3.1, 0.04)
    local targetInner = make("Frame", "StatusTargetInner", stage, {
        Position = UDim2.fromOffset(824, 115),
        Size = UDim2.fromOffset(32, 32),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        ZIndex = 115,
        Active = false,
        Selectable = false,
    })
    corner(targetInner, 16)
    stroke(targetInner, ACCENT_GRAY, 1.5, 0.18)
    local targetDot = make("Frame", "StatusTargetDot", stage, {
        Position = UDim2.fromOffset(832, 123),
        Size = UDim2.fromOffset(16, 16),
        BackgroundColor3 = WHITE_ACCENT,
        BorderSizePixel = 0,
        ZIndex = 116,
        Active = false,
        Selectable = false,
    })
