    line("PercentLeftAngleA", stage, UDim2.fromOffset(382, 193), UDim2.fromOffset(34, 3), ACCENT_GRAY, 0.08, 28, 109)
    line("PercentLeftAngleB", stage, UDim2.fromOffset(407, 207), UDim2.fromOffset(26, 3), WHITE_ACCENT, 0.08, 0, 109)
    line("PercentRightOuter", stage, UDim2.fromOffset(667, 201), UDim2.fromOffset(252, 2), DARK_GRAY, 0.33, 0, 108)
    line("PercentRightAngleA", stage, UDim2.fromOffset(636, 193), UDim2.fromOffset(34, 3), ACCENT_GRAY, 0.08, -28, 109)
    line("PercentRightAngleB", stage, UDim2.fromOffset(617, 207), UDim2.fromOffset(26, 3), WHITE_ACCENT, 0.08, 0, 109)

    local percentGlow = make("Frame", "PercentCapsuleGlow", stage, {
        Position = UDim2.fromOffset(444, 186),
        Size = UDim2.fromOffset(162, 46),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
