    local percentCapsule = make("Frame", "PercentCapsule", stage, {
        Position = UDim2.fromOffset(448, 189),
        Size = UDim2.fromOffset(154, 40),
        BackgroundColor3 = Color3.fromRGB(8, 8, 8),
        BackgroundTransparency = 0.02,
        BorderSizePixel = 0,
