    local percent = make("TextLabel", "Percent", percentCapsule, {
        Size = UDim2.fromScale(1, 1),
        BackgroundTransparency = 1,
        Text = "0%",
        TextColor3 = WHITE,
        TextStrokeColor3 = DARK_GRAY,
        TextStrokeTransparency = 0.68,
        Font = Enum.Font.GothamMedium,
        TextSize = 25,
        TextXAlignment = Enum.TextXAlignment.Center,
        TextYAlignment = Enum.TextYAlignment.Center,
        ZIndex = 114,
    })

    -- Soft pulsing strokes keep the UI alive without a heavy per-frame loop.
    task.spawn(function()
        while sg.Parent and panel.Parent do
            local up = TS_G:Create(panelStroke, TweenInfo.new(1.35, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut), {
                Color = Color3.fromRGB(245, 245, 245),
                Thickness = 2.0,
                Transparency = 0.16,
            })
            up:Play()
            pcall(function() up.Completed:Wait() end)
            if not (sg.Parent and panel.Parent) then break end
            local down = TS_G:Create(panelStroke, TweenInfo.new(1.55, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut), {
                Color = Color3.fromRGB(85, 85, 85),
                Thickness = 1.25,
                Transparency = 0.40,
            })
            down:Play()
            pcall(function() down.Completed:Wait() end)
        end
    end)
    task.spawn(function()
        while sg.Parent and panelGlow.Parent do
            local up = TS_G:Create(panelGlowStroke, TweenInfo.new(1.5, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut), {
                Transparency = 0.52,
                Thickness = 3.2,
            })
            up:Play()
            pcall(function() up.Completed:Wait() end)
            if not (sg.Parent and panelGlow.Parent) then break end
            local down = TS_G:Create(panelGlowStroke, TweenInfo.new(1.5, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut), {
                Transparency = 0.78,
                Thickness = 2.1,
            })
            down:Play()
            pcall(function() down.Completed:Wait() end)
        end
    end)
    task.spawn(function()
        while sg.Parent and fillShine.Parent do
            fillShine.Position = UDim2.new(-0.25, 0, 0, -3)
            local sweep = TS_G:Create(fillShine, TweenInfo.new(1.25, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut), {
                Position = UDim2.new(1.25, 0, 0, -3),
            })
            sweep:Play()
            pcall(function() sweep.Completed:Wait() end)
            if not (sg.Parent and fillShine.Parent) then break end
            task.wait(0.65)
        end
    end)

    -- Make the full HUD draggable by mouse or touch while respecting UI lock.
    -- The transparent input surface is intentionally above the visuals only to
    -- capture drag gestures; it has no text or color and does not alter layout.
    local dragSurface = make("Frame", "DragSurface", stage, {
        Position = UDim2.fromScale(0, 0),
        Size = UDim2.fromScale(1, 1),
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        ZIndex = 150,
        Active = true,
        Selectable = false,
    })
    local dragging, dragInput, dragStart, startPosition = false, nil, nil, nil
    local moved = false
    local function updateDrag(input)
        if S.lockUIEnabled or not dragStart or not startPosition then return end
        local delta = input.Position - dragStart
        if delta.Magnitude > 2 then moved = true end
        stage.Position = UDim2.new(
            startPosition.X.Scale, startPosition.X.Offset + delta.X,
            startPosition.Y.Scale, startPosition.Y.Offset + delta.Y
        )
    end
    dragSurface.InputBegan:Connect(function(input)
        if S.lockUIEnabled then return end
        if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
            dragging = true
            moved = false
            dragStart = input.Position
            startPosition = stage.Position
            input.Changed:Connect(function()
                if input.UserInputState == Enum.UserInputState.End then
                    if moved then saveConfig() end
                    dragging = false
                    moved = false
                    dragStart = nil
                    startPosition = nil
                end
            end)
        end
    end)
    dragSurface.InputChanged:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch then
            dragInput = input
        end
    end)
    S._stealHudDragConn = UIS.InputChanged:Connect(function(input)
        if S.lockUIEnabled then
            dragging = false
            moved = false
            return
        end
        if input == dragInput and dragging then updateDrag(input) end
    end)

    -- Shorten the full HUD horizontally by 12%, centered around the title.
    -- Scale-based child dimensions remain scale-based so the progress fill is intact.
    local HUD_WIDTH_COMPACT = 0.88
    local function compactHudXAxis(parentObject)
        for _, child in ipairs(parentObject:GetChildren()) do
            if child:IsA("GuiObject") then
                local pos, size = child.Position, child.Size
                if parentObject == stage then
                    if child.Name ~= "DragSurface" then
                        child.Position = UDim2.new(
                            pos.X.Scale, 525 + (pos.X.Offset - 525) * HUD_WIDTH_COMPACT,
                            pos.Y.Scale, pos.Y.Offset
                        )
                        child.Size = UDim2.new(
                            size.X.Scale, size.X.Offset * HUD_WIDTH_COMPACT,
                            size.Y.Scale, size.Y.Offset
                        )
                    end
                else
                    child.Position = UDim2.new(
                        pos.X.Scale, pos.X.Offset * HUD_WIDTH_COMPACT,
                        pos.Y.Scale, pos.Y.Offset
                    )
                    child.Size = UDim2.new(
                        size.X.Scale, size.X.Offset * HUD_WIDTH_COMPACT,
                        size.Y.Scale, size.Y.Offset
                    )
                end
                compactHudXAxis(child)
            end
        end
    end
    compactHudXAxis(stage)

    -- Restore saved position, but migrate the old tiny bar's default bottom
    -- position to the new reference layout's center position.
    if S._savedStealHudPos then
        local pos = S._savedStealHudPos
        local oldDefault = math.abs((tonumber(pos.X) or 0) + 150) < 2
            and math.abs((tonumber(pos.Y) or 0) + 75) < 2
            and math.abs((tonumber(pos.XS) or 0.5) - 0.5) < 0.001
            and math.abs((tonumber(pos.YS) or 1) - 1) < 0.001
        if not oldDefault then
            stage.Position = UDim2.new(pos.XS or 0.5, pos.X or 0, pos.YS or 0.5, pos.Y or 0)
        else
            stage.Position = UDim2.new(0.5, 0, 0.5, 0)
        end
    end

    S.progressBarFrame = track
    S.progressFill = fill
    S.progressPct = percent
    S.stealHudCard = stage
    updateStealHudStatus()
    if type(S.stealHudScaleSetVisual) == "function" then
        pcall(S.stealHudScaleSetVisual, S.stealHudScale or 0.55)
    end
    fitHud()

    -- While Auto Steal is enabled but no target is currently being stolen,
    -- animate the cosmetic DETECT progress 0% -> 65% -> 0% smoothly and repeat.
    -- The real steal routine retains exclusive control whenever isStealing is true.
    local detectProgressValue = make("NumberValue", "DetectProgressValue", sg, {Value = 0})
    local detectTween = nil
    local detectProgressConnection = detectProgressValue:GetPropertyChangedSignal("Value"):Connect(function()
        if not sg.Parent or not S.Steal or not S.Steal.AutoStealEnabled or S.Steal.isStealing then return end
        local value = math.clamp(detectProgressValue.Value, 0, 0.65)
        if S.progressFill and S.progressFill.Parent then
            S.progressFill.Size = UDim2.new(value, 0, 1, 0)
        end
        if S.progressPct and S.progressPct.Parent then
            S.progressPct.Text = tostring(math.floor(value * 100 + 0.5)) .. "%"
        end
    end)

    local stopDetectAnimation = function()
        if detectTween then
            pcall(function() detectTween:Cancel() end)
            detectTween = nil
        end
        if detectProgressValue and detectProgressValue.Parent then
            detectProgressValue.Value = 0
        end
    end
    S._stopStealDetectAnimation = stopDetectAnimation

    task.spawn(function()
        while sg.Parent do
            if S.Steal and S.Steal.AutoStealEnabled and not S.Steal.isStealing then
                updateStealHudStatus()
                detectProgressValue.Value = 0
                local rise = TS_G:Create(detectProgressValue, TweenInfo.new(1.0, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut), {Value = 0.65})
                detectTween = rise
                rise:Play()
                rise.Completed:Wait()
                if detectTween == rise then detectTween = nil end

                if rise.PlaybackState == Enum.PlaybackState.Completed
                    and sg.Parent and S.Steal and S.Steal.AutoStealEnabled and not S.Steal.isStealing then
                    local fall = TS_G:Create(detectProgressValue, TweenInfo.new(1.0, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut), {Value = 0})
                    detectTween = fall
                    fall:Play()
                    fall.Completed:Wait()
                    if detectTween == fall then detectTween = nil end
                end
            else
                if detectTween then
                    pcall(function() detectTween:Cancel() end)
                    detectTween = nil
                end
                if not (S.Steal and S.Steal.AutoStealEnabled) then
                    detectProgressValue.Value = 0
                end
                updateStealHudStatus()
                task.wait(0.05)
            end
        end
        if detectTween then pcall(function() detectTween:Cancel() end) end
        if detectProgressConnection then detectProgressConnection:Disconnect() end
        if S._stopStealDetectAnimation == stopDetectAnimation then
            S._stopStealDetectAnimation = nil
        end
    end)

    -- Accurate FPS and network ping, refreshed twice per second.
    task.spawn(function()
        local lastTime, frameCount = os.clock(), 0
        while sg.Parent do
            RunService.RenderStepped:Wait()
            frameCount += 1
            local now = os.clock()
            if now - lastTime >= 0.5 then
                local elapsed = now - lastTime
                local fps = math.floor(frameCount / math.max(elapsed, 0.001) + 0.5)
                frameCount, lastTime = 0, now
                local ping = 0
                pcall(function() ping = math.floor(LP:GetNetworkPing() * 1000 + 0.5) end)
                if fpsValue.Parent then fpsValue.Text = tostring(fps) end
                if pingValue.Parent then pingValue.Text = tostring(ping) .. "ms" end
            end
        end
    end)
    if type(S._xypherApplyThemeToOverlays) == "function" and S.activeThemePalette then
        pcall(S._xypherApplyThemeToOverlays, S.activeThemePalette)
    end
end

interfaceLoaded = false
local function loadVisionInterface()
    if interfaceLoaded then return true end

    local mainOk, mainErr = pcall(buildGui)
    local visionExists = false
    pcall(function()
        local pg = LP and LP:FindFirstChildOfClass("PlayerGui")
        local cg = game:GetService("CoreGui")
        visionExists = (pg and pg:FindFirstChild("Vision") ~= nil) or (cg and cg:FindFirstChild("Vision") ~= nil)
    end)

    if not mainOk and not visionExists then
        interfaceLoaded = false
        warn("[Vision] Main GUI failed: " .. tostring(mainErr))
        return false, mainErr
    end

    -- Never destroy a partially created Vision GUI because an optional child failed.
    pcall(function()
        local roots = {}
        local pg = LP and LP:FindFirstChildOfClass("PlayerGui")
        if pg then roots[#roots + 1] = pg end
        local cg = game:GetService("CoreGui")
        if cg then roots[#roots + 1] = cg end
        for _, root in ipairs(roots) do
            local v = root:FindFirstChild("Vision")
            if v and v:IsA("ScreenGui") then v.Enabled = XYPHER_STARTUP_INTRO_COMPLETE end
        end
    end)

    interfaceLoaded = true

    if not S.floatingPanelGui then
        local ok, err = pcall(function()
            createFloatingButtonPanel()
            pcall(S.setMobileButtonScale, S.mobileButtonScale or 1.0)
        end)
        if not ok then warn("[Vision] Floating buttons skipped: " .. tostring(err)) end
    end

    if not S.stealHudCard then
        local ok, err = pcall(buildStealHUD)
        if not ok then warn("[Vision] Steal HUD skipped: " .. tostring(err)) end
    end
    -- buildGui opens the dashboard on startup before these overlays exist; apply layering now.
    -- The dashboard theme selector also skins the independent mobile-button,
    -- Steal Bar, launcher, and other XYPHER-owned ScreenGuis.
    if type(S._xypherApplyThemeToOverlays) == "function" and S.activeThemePalette then
        pcall(S._xypherApplyThemeToOverlays, S.activeThemePalette)
    end
    local function refreshCustomCrosshairState()
        if type(S.setCrosshairEnabledVisual) == "function" then
            pcall(S.setCrosshairEnabledVisual, S.crosshairEnabled == true)
        end
        if type(S._setCrosshairShapeLabel) == "function" then
            local shapes = {"Classic", "Plus", "Dot", "Circle", "X"}
            local index = math.clamp(math.floor(tonumber(S.crosshairShapeIndex) or 1), 1, #shapes)
            pcall(S._setCrosshairShapeLabel, "Crosshair Style: " .. shapes[index])
        end
        if type(S._setCrosshairColorLabel) == "function" then
            local colors = {"White", "Red", "Cyan", "Lime", "Yellow", "Pink"}
            local index = math.clamp(math.floor(tonumber(S.crosshairColorIndex) or 1), 1, #colors)
            pcall(S._setCrosshairColorLabel, "Crosshair Color: " .. colors[index])
        end
        if type(S.renderCrosshair) == "function" then pcall(S.renderCrosshair) end
    end
    refreshCustomCrosshairState()
    -- Config restoration is spawned asynchronously in this file; refresh again
    -- after it has had time to apply Vision.json, without a permanent polling loop.
    task.delay(0.65, refreshCustomCrosshairState)
    task.delay(1.4, refreshCustomCrosshairState)
    if S.mainMenuFrame and S.mainMenuFrame.Visible and type(S._xypherSetGameplayOverlaysVisible) == "function" then
        pcall(S._xypherSetGameplayOverlaysVisible, false)
    end

    local character = LP.Character
    if character then
        pcall(S.setupSpeedBillboard, character)
        pcall(setupVisionRagdollTimer, character)
    end
    pcall(captureLiveMobileButtonPositions)

    -- Remote code loading is disabled so the local GUI does not download/execute unknown code.
    return true
end

LP.CharacterAdded:Connect(function(char)
    task.wait(0.5)
    if interfaceLoaded then
        S.setupSpeedBillboard(char)
        setupVisionRagdollTimer(char)
    end
    if S.antiRagdollEnabled then startAntiRagdoll() end
    if S.medusaCounterEnabled then setupMedusaCounter(char) end
    if S.currentAnimPack ~= "Off" then
        task.spawn(function()
            local animate = char:WaitForChild("Animate", 5)
            if animate and LP.Character == char and S.currentAnimPack ~= "Off" then
                pcall(YF.saveOriginalAnims, char)
                pcall(YF.startAnimPack, S.currentAnimPack)
            end
        end)
    end
    if S.holdJumpEnabled and not S._youtResetInProgress then startHoldJump() end
    if S.unwalkEnabled then task.wait(1); startUnwalk() end
    S.restartMovement()
end)
if LP.Character then
    task.spawn(function()
        if interfaceLoaded then
            S.setupSpeedBillboard(LP.Character)
            setupVisionRagdollTimer(LP.Character)
        end
        if S.antiRagdollEnabled then startAntiRagdoll() end
        if S.medusaCounterEnabled then setupMedusaCounter(LP.Character) end
    end)
end

clearOldVisionInterface()

-- STARTUP ROBUST:
-- UI dibangun dalam keadaan tersembunyi; kegagalan intro akan membuka UI sebagai fallback.
local _visionInterfaceOk, _visionInterfaceErr = pcall(loadVisionInterface)
if not _visionInterfaceOk then warn("[Vision] GUI startup error: " .. tostring(_visionInterfaceErr)) end

task.delay(0.35, function()
    pcall(function()
        local roots = {}
        local pg = LP and LP:FindFirstChildOfClass("PlayerGui")
        if pg then roots[#roots + 1] = pg end
        local cg = game:GetService("CoreGui")
        if cg then roots[#roots + 1] = cg end
        for _, root in ipairs(roots) do
            local v = root:FindFirstChild("Vision")
            if v and v:IsA("ScreenGui") then v.Enabled = XYPHER_STARTUP_INTRO_COMPLETE end
        end
    end)
end)

-- Hard visibility guard: reveal Vision and gameplay overlays only after the intro gate opens.
local function forceVisionGuiVisible()
    if not XYPHER_STARTUP_INTRO_COMPLETE then return end
    pcall(function()
        local roots = {}
        local pg = LP and LP:FindFirstChildOfClass("PlayerGui")
        if pg then roots[#roots + 1] = pg end
        local okCore, cg = pcall(function() return game:GetService("CoreGui") end)
        if okCore and cg then roots[#roots + 1] = cg end
        for _, root in ipairs(roots) do
            local vision = root:FindFirstChild("Vision")
            if vision and vision:IsA("ScreenGui") then
                vision.Enabled = XYPHER_STARTUP_INTRO_COMPLETE
            end
            local mobile = root:FindFirstChild("FloatingModeMenu")
            if mobile and mobile:IsA("ScreenGui") then
                mobile.Enabled = XYPHER_STARTUP_INTRO_COMPLETE
            end
            local stealHud = root:FindFirstChild("StealBarMovableSmall")
            if stealHud and stealHud:IsA("ScreenGui") then
                stealHud.Enabled = XYPHER_STARTUP_INTRO_COMPLETE
            end
            local launcher = root:FindFirstChild("XYPHER_OpenLauncher")
            if launcher and launcher:IsA("ScreenGui") then
                launcher.Enabled = XYPHER_STARTUP_INTRO_COMPLETE
            end
        end
    end)
end

forceVisionGuiVisible()

-- Keep the fully-built interface hidden during intro; the intro has the only visible layer.
local function holdXypherUiUntilIntroFinishes()
    if XYPHER_STARTUP_INTRO_COMPLETE then return end
    pcall(function()
        if S.mainMenuFrame and S.mainMenuFrame.Parent then S.mainMenuFrame.Visible = false end
        if S.miniToggleButton and S.miniToggleButton.Parent then S.miniToggleButton.Visible = false end
        if S._xypherLauncherGui then S._xypherLauncherGui.Enabled = false end
        if S.floatingPanelGui then S.floatingPanelGui.Enabled = false end
        if S.stealHudCard then
            local node = S.stealHudCard
            while node and not node:IsA("ScreenGui") do node = node.Parent end
            if node and node:IsA("ScreenGui") then node.Enabled = false end
        end
        local pg = LP and LP:FindFirstChildOfClass("PlayerGui")
        local cg = game:GetService("CoreGui")
        for _, root in ipairs({pg, cg}) do
            if root then
                for _, child in ipairs(root:GetChildren()) do
                    if child:IsA("ScreenGui") and (child.Name == "Vision"
                        or child.Name == "XYPHER_OpenLauncher"
                        or child.Name == "FloatingModeMenu"
                        or child.Name == "StealBarMovableSmall") then
                        child.Enabled = false
                    end
                end
            end
        end
    end)
end

local function revealXypherUiAfterIntro()
    if XYPHER_STARTUP_INTRO_COMPLETE then return end
    XYPHER_STARTUP_INTRO_COMPLETE = true
    pcall(function()
        local pg = LP and LP:FindFirstChildOfClass("PlayerGui")
        local cg = game:GetService("CoreGui")
        for _, root in ipairs({cg, pg}) do
            if root then
                for _, child in ipairs(root:GetChildren()) do
                    if child:IsA("ScreenGui") and (child.Name == "Vision"
                        or child.Name == "XYPHER_OpenLauncher"
                        or child.Name == "FloatingModeMenu"
                        or child.Name == "StealBarMovableSmall") then
                        child.Enabled = true
                    end
                end
            end
        end
        if S.mainMenuFrame and S.mainMenuFrame.Parent then S.mainMenuFrame.Visible = true end
        if S._xypherLauncherGui then S._xypherLauncherGui.Enabled = true end
        if S.miniToggleButton and S.miniToggleButton.Parent then S.miniToggleButton.Visible = false end
        if S.floatingPanelGui then S.floatingPanelGui.Enabled = true end
        if S.stealHudCard then
            local node = S.stealHudCard
            while node and not node:IsA("ScreenGui") do node = node.Parent end
            if node and node:IsA("ScreenGui") then node.Enabled = true end
        end
        if type(S._xypherSetGameplayOverlaysVisible) == "function" then
            pcall(S._xypherSetGameplayOverlaysVisible, false)
        end
    end)
    forceVisionGuiVisible()

    -- The startup entrance used to finish while Vision was disabled behind the
    -- intro. Restart it only after the gate has opened so the user can actually see it.
    task.defer(function()
        local root = S.mainMenuFrame
        local scaleObj = S.mainGuiScaleObj
        if not (root and root.Parent and root.Visible and scaleObj and scaleObj.Parent) then return end
        local targetPosition = S.menuOpenPosition or root.Position
        local camera = workspace.CurrentCamera
        local viewport = camera and camera.ViewportSize or Vector2.new(PANEL_W, PANEL_H)
        local fitted = math.min(1, (viewport.X - 16) / PANEL_W, (viewport.Y - 20) / PANEL_H)
        if S.IS_TOUCH_DEVICE then fitted = math.min(fitted, S.phoneGuiScale or 0.72) end
        local targetScale = math.max(0.24, fitted) * (S.IS_TOUCH_DEVICE and 0.82 or 0.82)
        if S.menuTween then pcall(function() S.menuTween:Cancel() end) end
        if S.menuPositionTween then pcall(function() S.menuPositionTween:Cancel() end) end
        scaleObj.Scale = math.max(0.14, targetScale * 0.58)
        root.Position = UDim2.new(targetPosition.X.Scale, targetPosition.X.Offset, targetPosition.Y.Scale, targetPosition.Y.Offset + 34)
        S.menuTween = TS_G:Create(scaleObj, TweenInfo.new(0.44, Enum.EasingStyle.Back, Enum.EasingDirection.Out), {Scale = targetScale})
        S.menuPositionTween = TS_G:Create(root, TweenInfo.new(0.44, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), {Position = targetPosition})
        S.menuTween:Play()
        S.menuPositionTween:Play()
    end)
end

holdXypherUiUntilIntroFinishes()

-- Run the replacement intro only after the Vision GUI exists. It is isolated from GUI startup.
task.spawn(function()
    local ok, err = pcall(function()
        showIntro(function()
            revealXypherUiAfterIntro()
        end)
    end)
    if not ok then
        warn("[Vision] Intro dilewati karena error: " .. tostring(err))
        revealXypherUiAfterIntro()
    end
end)

-- Final failsafe: the previous version only called forceVisionGuiVisible(),
-- which returned immediately while the intro gate was false. If an executor
-- interrupts the intro callback, both the dashboard and launcher could stay hidden.
task.delay(11.5, function()
    if not XYPHER_STARTUP_INTRO_COMPLETE then
        warn("[XYPHER] Intro gate timed out; restoring GUI visibility as a failsafe.")
        pcall(revealXypherUiAfterIntro)
        -- Always complete the gate and reveal the UI if it was still blocked at
        -- timeout entry, even if an optional call inside reveal fails on an executor.
        XYPHER_STARTUP_INTRO_COMPLETE = true
        pcall(function()
            local roots = {}
            local pg = LP and LP:FindFirstChildOfClass("PlayerGui")
            if pg then roots[#roots + 1] = pg end
            local okCore, cg = pcall(function() return game:GetService("CoreGui") end)
            if okCore and cg then roots[#roots + 1] = cg end
            for _, root in ipairs(roots) do
                for _, name in ipairs({"Vision", "XYPHER_OpenLauncher", "FloatingModeMenu", "StealBarMovableSmall"}) do
                    local screen = root:FindFirstChild(name)
                    if screen and screen:IsA("ScreenGui") then screen.Enabled = true end
                end
            end
            if S.mainMenuFrame and S.mainMenuFrame.Parent then S.mainMenuFrame.Visible = true end
            if S._xypherLauncherGui then S._xypherLauncherGui.Enabled = true end
            if S.miniToggleButton and S.miniToggleButton.Parent then S.miniToggleButton.Visible = false end
            if S.floatingPanelGui then S.floatingPanelGui.Enabled = true end
            if type(S._xypherSetGameplayOverlaysVisible) == "function" then
                pcall(S._xypherSetGameplayOverlaysVisible, false)
            end
        end)
    end
    forceVisionGuiVisible()
end)

-- Input-unblock watchdog: never allow a stale intro overlay to sit above Vision.
task.delay(11.8, function()
    pcall(function()
        local roots = {}
        local pg = LP and LP:FindFirstChildOfClass("PlayerGui")
        if pg then roots[#roots + 1] = pg end
        local cg = game:GetService("CoreGui")
        if cg then roots[#roots + 1] = cg end
        for _, root in ipairs(roots) do
            local intro = root:FindFirstChild("M4LWARE_Intro")
            if intro then
                if intro:IsA("ScreenGui") then intro.Enabled = false end
                intro:Destroy()
            end
        end
    end)
end)

-- ================================================================
-- VXYRO SELECTED LOGICS — loaded AFTER Vision UI startup
-- Ragdoll Steal + Shiny Graphics. Nothing is auto-enabled.
-- ================================================================
do
    local Ragdoll = {
        Enabled = false,
        Active = false,
        Triggered = false,
        StartTime = 0,
        SavedAutoSteal = false,
        AutoStealPaused = false,
        Connection = nil,
        Delays = {normalV1=1.35, normalV2=1.50, normalV3=1.35, semiV1=1.40, semiV2=1.40},
    }

    local function ragdollStopConnection()
        if Ragdoll.Connection then
            pcall(function() Ragdoll.Connection:Disconnect() end)
            Ragdoll.Connection = nil
        end
    end

    local function ragdollReset(restoreSteal)
        if restoreSteal and Ragdoll.SavedAutoSteal and Ragdoll.AutoStealPaused then
            pcall(startAutoSteal)
        end
        Ragdoll.Active = false
        Ragdoll.Triggered = false
        Ragdoll.StartTime = 0
        Ragdoll.SavedAutoSteal = false
        Ragdoll.AutoStealPaused = false
    end

    local function ragdollDelay()
        local d = Ragdoll.Delays
        if _G._AdaptStealMode == "SEMI" then
            return (_G._AdaptSemiVersion == "V2") and d.semiV2 or d.semiV1
        end
        if _G._AdaptNormalVersion == "V3" then return d.normalV3 end
        if _G._AdaptNormalVersion == "V2" then return d.normalV2 end
        return d.normalV1
    end

    local function ragdollSet(enabled)
        enabled = enabled == true
        Ragdoll.Enabled = enabled
        if not enabled then
            ragdollStopConnection()
            ragdollReset(true)
            S.ragdollStealEnabled = false
            return false
        end

        ragdollStopConnection()
        Ragdoll.Active = false
        Ragdoll.Triggered = false
        Ragdoll.StartTime = 0
        Ragdoll.Connection = RunService.RenderStepped:Connect(function()
            if not Ragdoll.Enabled then return end
            local char = LP and LP.Character
            local hum = char and char:FindFirstChildOfClass("Humanoid")
            if not hum then return end

            local state = hum:GetState()
            local ragdolled = state == Enum.HumanoidStateType.Physics
                or state == Enum.HumanoidStateType.Ragdoll
                or state == Enum.HumanoidStateType.FallingDown

            if ragdolled and not Ragdoll.Active then
                Ragdoll.Active = true
                Ragdoll.Triggered = false
                Ragdoll.StartTime = tick()
                Ragdoll.SavedAutoSteal = S.Steal.AutoStealEnabled == true
                if Ragdoll.SavedAutoSteal then
                    Ragdoll.AutoStealPaused = true
                    pcall(stopAutoSteal)
                end
            end

            if not Ragdoll.Active then return end
            local elapsed = tick() - Ragdoll.StartTime
            local delayTime = ragdollDelay()

            if elapsed >= delayTime and not Ragdoll.Triggered then
                Ragdoll.Triggered = true
                if Ragdoll.SavedAutoSteal and Ragdoll.AutoStealPaused then
                    pcall(startAutoSteal)
                    Ragdoll.AutoStealPaused = false
                end
            elseif elapsed >= delayTime + 1.25 and not ragdolled then
                ragdollReset(false)
            end
        end)
        S.ragdollStealEnabled = true
        return true
    end

    local Shiny = {
        Enabled = false,
        Connections = {},
        Originals = {},
        EnforceConnection = nil,
        Cursor = 1,
        NextEnforceAt = 0,
    }

    local function shinyDisconnectAll()
        for i=#Shiny.Connections,1,-1 do
            local c=Shiny.Connections[i]
            Shiny.Connections[i]=nil
            if c then pcall(function() c:Disconnect() end) end
        end
    end

    local function shinyApply(instance)
        if not instance or not instance:IsA("BasePart") then return end
        if not Shiny.Originals[instance] then
            Shiny.Originals[instance] = {
                Material=instance.Material,
                Reflectance=instance.Reflectance,
                CastShadow=instance.CastShadow,
            }
        end
        pcall(function()
            instance.Material=Enum.Material.SmoothPlastic
            instance.Reflectance=1
            instance.CastShadow=false
        end)
    end

    local function shinyEffect(className,name)
        local e=Lighting:FindFirstChild(name)
        if e and not e:IsA(className) then pcall(function() e:Destroy() end); e=nil end
        if not e then
            e=Instance.new(className)
            e.Name=name
            e.Parent=Lighting
        end
        return e
    end

    local function shinySet(enabled)
        enabled = enabled == true
        Shiny.Enabled = enabled
        if not enabled then
            if Shiny.EnforceConnection then
                pcall(function() Shiny.EnforceConnection:Disconnect() end)
                Shiny.EnforceConnection=nil
            end
            shinyDisconnectAll()
            for inst,orig in pairs(Shiny.Originals) do
                if inst and inst.Parent then
                    pcall(function()
                        inst.Material=orig.Material
                        inst.Reflectance=orig.Reflectance
                        inst.CastShadow=orig.CastShadow
                    end)
                end
            end
            Shiny.Originals={}
            Shiny.Cursor=1
            for _,name in ipairs({"VisionShinyBloom","VisionShinySunRays","VisionShinyColorCorrection"}) do
                local e=Lighting:FindFirstChild(name)
                if e then pcall(function() e.Enabled=false end) end
            end
            S.shinyGraphicsEnabled=false
            return false
        end

        shinyDisconnectAll()
        table.insert(Shiny.Connections, workspace.DescendantAdded:Connect(function(inst)
            if Shiny.Enabled then shinyApply(inst) end
        end))

        -- Vxyro visual values; initial scan is chunked so enabling does not freeze mobile.
        task.spawn(function()
            local list=workspace:GetDescendants()
            for i=1,#list do
                if not Shiny.Enabled then return end
                shinyApply(list[i])
                if i%120==0 then task.wait() end
            end
        end)

        local bloom=shinyEffect("BloomEffect","VisionShinyBloom")
        bloom.Intensity=1.6; bloom.Size=5; bloom.Threshold=1; bloom.Enabled=true
        local rays=shinyEffect("SunRaysEffect","VisionShinySunRays")
        rays.Intensity=0.55; rays.Spread=1; rays.Enabled=true
        local cc=shinyEffect("ColorCorrectionEffect","VisionShinyColorCorrection")
        cc.Saturation=0.9; cc.Contrast=0.22; cc.Brightness=0.07; cc.Enabled=true

        if not Shiny.EnforceConnection then
            Shiny.EnforceConnection=RunService.Heartbeat:Connect(function()
                if not Shiny.Enabled then return end
                local now=tick()
                if Shiny.NextEnforceAt>now then return end
                Shiny.NextEnforceAt=now+0.35
                local keys={}
                for inst in pairs(Shiny.Originals) do keys[#keys+1]=inst end
                local count=#keys
                if count==0 then return end
                local startIndex=math.clamp(Shiny.Cursor,1,count)
                local budget=math.min(80,count)
                for n=0,budget-1 do
                    local idx=((startIndex+n-1)%count)+1
                    local inst=keys[idx]
                    if inst and inst.Parent then
                        pcall(function()
                            inst.Material=Enum.Material.SmoothPlastic
                            inst.Reflectance=1
                            inst.CastShadow=false
                        end)
                    end
                end
                Shiny.Cursor=((startIndex+budget-1)%count)+1
            end)
        end
        S.shinyGraphicsEnabled=true
        return true
    end

    _G.__VisionRagdollStealSet = function(enabled)
        return pcall(ragdollSet, enabled == true)
    end
    _G.__VisionShinySet = function(enabled)
        return pcall(shinySet, enabled == true)
    end
    _G.__VisionSelectedLogicCleanup = function()
        pcall(ragdollSet,false)
        pcall(shinySet,false)
    end
end

-- Restore the imported Vxyro feature states only after their setter functions exist.
-- This keeps config loading deterministic and prevents the optional logic from
-- running before the Vision UI has finished starting.
task.defer(function()
    local rag = S.ragdollStealEnabled == true
    local shiny = S.shinyGraphicsEnabled == true
    if rag and type(_G.__VisionRagdollStealSet) == "function" then
        pcall(_G.__VisionRagdollStealSet, true)
    end
    if shiny and type(_G.__VisionShinySet) == "function" then
        pcall(_G.__VisionShinySet, true)
    end
    if rag or shiny then
        pcall(saveConfig)
    end
end)

-- Extra startup fallback: optional logic errors cannot stop the already-built UI.
task.delay(0.8, function()
    if not interfaceLoaded then pcall(loadVisionInterface) end
end)
task.delay(2.5, function()
    if not interfaceLoaded then pcall(loadVisionInterface) end
end)


-- Removed appended third-party telemetry/command module: it scanned user/game data, polled remote commands, and included an intentional infinite CPU loop.
